    ingT:[["ハクレン（またはどの魚のあらでも）","頭1個か切り身500g"],["豆腐","1丁"],["生姜","5枚"],["小ねぎ","2本"]],
    sauceT:[["サラダ油","大さじ2"],["料理酒","大さじ1"],["熱湯","1.2L"],["塩、白こしょう","適量"]],
