window.ADD_I18N("en", {
 "yellow-catfish":{tip:"A small freshwater fish common in Sichuan, Jiangsu and Zhejiang, tender and free of small bones. Careful: the dorsal and pectoral fins have spines.",warn:"Never eat freshwater fish raw.",
  d:{
   "藿香黄辣丁":{n:"Sichuan yellow catfish with Korean mint (huoxiang)",h:"Fry pickled chilies, pickled ginger and chili bean paste, add water, poach the fish and finish with fresh huoxiang.",serves:"2–3",time:"30 min",
    ingT:[["Yellow catfish","500 g (about 8–10 fish)"],["Pickled chilies","6"],["Pickled ginger","1 piece"],["Garlic","4 cloves"],["Fresh huoxiang (Korean mint) or shiso","1 bunch"]],
    sauceT:[["Pixian chili bean paste","1.5 tbsp"],["Sichuan peppercorns","1 tsp"],["Shaoxing wine","1 tbsp"],["Sugar","1 tsp"],["Neutral oil","3 tbsp"],["Hot water","600 ml"]],
    steps:["Gut the fish, rub with salt to remove the slime and rinse. Mind the spines on the dorsal and pectoral fins.",
     "Chop the pickled chilies, pickled ginger and garlic; chop the huoxiang.",
     "Heat the oil and fry the bean paste until red, then add the chilies, ginger, garlic and peppercorns until fragrant.",
     "Add the hot water, wine and sugar, bring to a boil, add the fish and cook on medium 8 minutes.",
     "Just before turning off the heat, scatter plenty of chopped huoxiang over the top."],
    tips:["No huoxiang in Japan? Shiso is a good stand-in: different aroma, still delicious.","The spines really hurt; wear gloves when cleaning."]},
   "昂刺鱼汤":{n:"Yellow catfish and tofu milky soup (Jiangsu)",h:"Fry the fish briefly, add boiling water and cook into a milky broth; add tofu and salt."},
   "酸菜黄辣丁":{n:"Yellow catfish with pickled greens",h:"Fry pickled mustard greens, simmer in water for a sour broth, cook the fish 8 minutes and add Sichuan pepper."}
  }},
 "black-carp":{tip:"The largest of China's \"four domestic fish\"; it feeds on snails, so the flesh is thick. Note: Japanese \"aozakana\" means blue-backed fish, not this one.",warn:"Never eat freshwater fish raw. The gallbladder is poisonous; never eat it.",
  d:{
   "上海熏鱼":{n:"Shanghai \"smoked\" fish (bao yu)",h:"Marinate thick slices, deep-fry until dry, then soak hot in a sauce of soy sauce, sugar and five spices.",serves:"4",time:"50 min",
    ingT:[["Black carp or grass carp middle section (or mackerel / yellowtail)","600 g"],["Ginger","1 piece"],["Japanese leek","1 stalk"],["Star anise, cinnamon stick","1 each"]],
    sauceT:[["Light soy sauce","4 tbsp"],["Dark soy sauce","1 tbsp"],["Shaoxing wine","3 tbsp"],["Sugar","5 tbsp"],["Vinegar","1 tbsp"],["Water","200 ml"],["Frying oil","4 cm deep"]],
    steps:["Cut the fish into 1.5 cm slices, marinate 1 hour with 2 tbsp light soy sauce, 1 tbsp wine, leek and ginger, then pat dry.",
     "In another pot, simmer the remaining soy sauces, wine, sugar, vinegar, water, star anise and cinnamon on low 10 minutes for the sauce; let cool.",
     "Heat the oil to 180°C and fry the fish in batches 5–6 minutes until the surface is dry, firm and deep golden.",
     "While hot, soak the slices in the sauce 5 minutes, turning so both sides absorb it.",
     "Lift out and plate. Good warm or cold."],
    tips:["An intermediate dish: fry the fish dry enough and after soaking it'll be chewy outside and tender within.","In Japan, mackerel or yellowtail work well and are even richer.","Keeps 3–4 days sealed in the fridge."]},
   "青鱼秃肺":{n:"Braised black carp liver",h:"Only the liver of the black carp, red-braised with soy sauce and sugar. A signature of old Shanghai restaurants."},
   "青鱼干":{n:"Dried black carp",h:"A Jiangnan New Year food: salted and air-dried, then cut and steamed; enjoyed with Shaoxing wine."}
  }},
 hamaguri:{tip:"Hamaguri soup is eaten for Japan's Girls' Day (March 3). Purge in salt water like Manila clams.",
  d:{
   "文蛤清汤":{n:"Clear hamaguri soup (ushio-jiru)",h:"Start the clams in cold water with kombu, cook until they open and season with only salt and a little light soy sauce; add mitsuba.",serves:"2",time:"15 min (plus 2 hours purging)",
    ingT:[["Hard clams","6 (about 300 g)"],["Kombu","one 5 cm piece"],["Mitsuba or scallion","a little"]],
    sauceT:[["Water","500 ml"],["Sake","1 tbsp"],["Salt","1/3 tsp"],["Light soy sauce","a few drops"]],
    steps:["Soak the clams in 3% salt water somewhere dark for 2–3 hours to purge, then rub the shells together to clean.",
     "Put the water, kombu and clams in a pot and heat from cold on medium.",
     "Just before boiling remove the kombu and skim.",
     "As soon as the clams open, turn off the heat and add the sake, salt and a few drops of light soy sauce.",
     "Ladle into bowls and add mitsuba."],
    tips:["Starting in cold water draws the clams' flavor fully into the broth.","Turn off the heat as soon as they open; overcooked clams toughen.","A traditional soup for Japan's Girls' Day (March 3)."]},
   "烤文蛤":{n:"Grilled hamaguri (yaki-hamaguri)",h:"Cut the hinge ligament (so they don't flip), grill over charcoal until open and add a few drops of soy sauce. A specialty of Kuwana, Mie."},
   "文蛤蒸蛋":{n:"Chinese steamed egg with clams",h:"Blanch clams until open, arrange in a bowl, pour in beaten egg with the clam liquor and steam 10 minutes."}
  }},
 shijimi:{tip:"In Japan shijimi soup is said to be good for the liver and hangovers. Freezing them before cooking boosts the savory flavor (ornithine).",
  d:{
   "蚬味噌汤":{n:"Shijimi miso soup",h:"Start purged clams in cold water; when they open, turn off the heat and dissolve miso (red miso is common).",serves:"2",time:"10 min (plus 1 hour purging)",
    ingT:[["Shijimi clams","200 g"],["Scallion","1"]],
    sauceT:[["Water","400 ml"],["Miso (red miso suits best)","1.5 tbsp"],["Sake","1 tsp"]],
    steps:["Soak the clams 1 hour in 1% salt water to purge (they're freshwater clams, so keep the brine weak), then scrub the shells.",
     "Put the water and clams in a pot, heat from cold on medium and skim.",
     "When all have opened, lower the heat, add the sake and dissolve the miso in a ladle.",
     "Don't let it boil again; sprinkle with scallion and serve."],
    tips:["Freezing purged shijimi before cooking increases their savory compounds.","Don't boil hard after adding miso or the aroma fades."]},
   "台式腌蚬仔":{n:"Taiwanese soy-marinated clams",h:"Scald until just open and marinate overnight in soy sauce, garlic, chili, rice wine and sugar."},
   "蚬子汤":{n:"Jaecheop-guk (Korean clam soup)",h:"Busan / Hadong style: clear clam soup with garlic chives, seasoned only with salt."}
  }},
 awabi:{tip:"A luxury summer ingredient in Japan. \"Tokobushi\" is a small abalone relative and much cheaper. Scrub off the black slime with salt and a brush.",
  d:{
   "酒蒸鲍鱼":{n:"Sake-steamed abalone",h:"Splash abalone in the shell with sake, salt and steam 30+ minutes until tender; serve with liver sauce.",serves:"2",time:"40 min",
    ingT:[["Abalone (or small tokobushi)","2"],["Kombu","10 cm"]],
    sauceT:[["Sake","100 ml"],["Salt","as needed (for scrubbing)"],["Soy sauce","a little"]],
    steps:["Scrub the abalone flesh (the black slimy surface) hard with a brush and salt, then rinse.",
     "Slide a spoon in from the thin side of the shell to free the meat (or steam it in the shell).",
     "Lay kombu in a heatproof dish, add the abalone, pour over the sake and cover with plastic wrap or foil.",
     "Steam over boiling water for at least 30 minutes (longer is softer, up to 1 hour).",
     "Slice and drizzle with some of the steaming liquid and a few drops of soy sauce. The green liver alongside is edible too."],
    tips:["Too little steaming leaves it tough; 30 minutes is the minimum.","Tokobushi is a small, much cheaper abalone; good for practice."]},
   "鲍鱼水贝":{n:"Mizugai (abalone in chilled salt water)",h:"Cube raw abalone and float it in iced salt water with cucumber. Crunchy and refreshing."},
   "鲍鱼粥":{n:"Jeonbok-juk (abalone porridge)",h:"Slice the abalone, mash the liver, stir-fry with soaked rice in sesame oil, add water and cook into green porridge. A Jeju specialty."},
   "蚝油鲍鱼":{n:"Braised abalone in oyster sauce",h:"Score and blanch abalone, braise with oyster sauce, soy sauce and sugar, thicken and serve with broccoli."}
  }},
 sazae:{tip:"A classic of Japanese seaside barbecues. The green liver at the tip is slightly bitter, a treat for those who love it.",
  d:{
   "壶烧蝾螺":{n:"Tsuboyaki (turban shell grilled in its shell)",h:"Grill whole; when it bubbles, pour soy sauce and sake into the opening, grill 5 minutes and twist the meat out with a skewer.",serves:"2",time:"20 min",
    ingT:[["Turban shells","4"]],
    sauceT:[["Soy sauce","4 tsp"],["Sake","4 tsp"]],
    steps:["Scrub the shells with a brush.",
     "Set them opening up on a grill rack or frying pan so they stay level (a ring of scrunched foil helps).",
     "Grill on medium 5 minutes, until the opening starts bubbling.",
     "Pour 1 tsp each of soy sauce and sake into each opening and grill 3–5 more minutes.",
     "Spear the meat with a skewer or fork and twist it out, eating it with the liver at the tip."],
    tips:["The green liver at the tip is slightly bitter; fans love it most.","A toaster oven on foil for 10 minutes also works."]},
   "蝾螺刺身":{n:"Turban shell sashimi",h:"Remove the meat and slice thin; crunchy, with wasabi and soy sauce."},
   "蝾螺炊饭":{n:"Sazae rice",h:"Slice the meat and cook with rice, dashi, soy sauce and sake."},
   "白灼海螺":{n:"Chinese boiled sea snails",h:"Boil 10 minutes in water with ginger and wine, pick out the meat with a toothpick and dip in ginger vinegar or wasabi soy."}
  }}
});
// English translation T
window.ADD_I18N("en", {
 mussel:{tip:"Pull off the beard sticking out of the shell and scrub the shells. Discard any that don't open when cooked.",warn:"Shellfish toxins (paralytic shellfish poisoning) occasionally occur in spring and summer; heed harvest-area advisories.",
  d:{
   "白酒青口":{n:"Moules marinières",h:"Soften shallots in butter, add white wine and mussels, cover 4 minutes until open, add parsley and serve with fries. Belgium's national dish.",serves:"2",time:"20 min",
    ingT:[["Mussels","500 g"],["Shallot or onion","1/2"],["Garlic","2 cloves"],["Parsley","a little"],["Baguette or fries","to taste"]],
    sauceT:[["White wine","100 ml"],["Butter","20 g"],["Cream (optional)","3 tbsp"],["Black pepper","a pinch"]],
    steps:["Scrub the shells and pull the beards off toward the hinge end. Tap any open ones; discard those that don't close.",
     "Mince the onion and garlic.",
     "Melt the butter in a deep pot on medium and soften the onion and garlic 2 minutes.",
     "Add the mussels and wine, cover and steam on high 4–5 minutes, shaking the pot once.",
     "When all are open, stir in the cream, black pepper and chopped parsley.",
     "Tip into a big bowl with the broth and mop it up with bread."],
    tips:["Mussels still closed after cooking are dead; throw them away.","Frozen cooked mussels from the supermarket can go in at step 4; just heat 3 minutes."]},
   "西班牙海鲜饭":{n:"Paella de marisco",h:"In a wide pan fry tomato, red pepper and rice, add seafood stock and saffron, top with mussels, prawns and squid and cook until a crust forms."},
   "青口汤":{n:"Honghap-tang (Korean mussel soup)",h:"Boil mussels with water, garlic, scallion and green chili, seasoned only with salt. A Korean street-stall staple."},
   "葱姜炒青口":{n:"Mussels stir-fried with ginger and scallion",h:"Blanch mussels until open, then stir-fry hot with ginger, scallion, oyster sauce and wine."}
  }},
 akagai:{tip:"The flesh is red (it contains hemoglobin); a premium sushi shellfish. If it contracts when you slap it, it's fresh.",
  d:{
   "赤贝醋拌":{n:"Akagai nuta (ark shell with vinegared miso)",h:"Toss sliced ark shell and blanched scallions with vinegared miso.",serves:"2",time:"15 min",
    ingT:[["Sashimi-grade ark shell (cleaned)","4–6"],["Scallions (or wakegi)","4"],["Wakame (optional)","a little"]],
    sauceT:[["White miso","2 tbsp"],["Vinegar","1 tbsp"],["Sugar","1 tbsp"],["Japanese mustard","1/2 tsp"]],
    steps:["Cut the scallions into 4 cm lengths, blanch 30 seconds, cool and squeeze dry.",
     "Mix the miso, vinegar, sugar and mustard into a vinegared miso.",
     "Cut the ark shell into bite-sized pieces and slap them on the board; fresh flesh curls up.",
     "Put the ark shell, scallions and wakame in a bowl and toss with the miso dressing."],
    tips:["Always buy cleaned, sashimi-grade ark shell from the supermarket.","This style is called \"nuta\" and also suits cockles and squid."]},
   "赤贝寿司":{n:"Akagai nigiri",h:"Remove and butterfly the meat, score it, slap it on the board so it curls, and shape into nigiri."},
   "葱油血蚶":{n:"Blanched blood clams (Ningbo style)",h:"Dip in hot water 10 seconds until slightly open, pry apart and dip in ginger vinegar or soy sauce."}
  }},
 saruboo:{tip:"Smaller than ark shell; in Japan mostly canned as \"akagai no ajitsuke\".",warn:"This clam once caused a major hepatitis A outbreak in China; always cook it through.",
  d:{
   "甜辣毛蚶":{n:"Sweet-savory simmered ark clams",h:"Open the clams, remove the meat and simmer with soy sauce, sugar, sake and ginger until the liquid is gone.",serves:"2–3",time:"20 min",
    ingT:[["Half-crenated ark clams","300 g"],["Ginger","1 small piece"]],
    sauceT:[["Soy sauce","2 tbsp"],["Sake","2 tbsp"],["Sugar","1 tbsp"],["Mirin","1 tbsp"]],
    steps:["Scrub the shells, put them in a pot with a little water, cover and cook until they open.",
     "Remove the meat; strain the liquid and keep 3 tbsp.",
     "Bring the soy sauce, sake, sugar, mirin, shredded ginger and reserved liquid to a boil.",
     "Add the meat and simmer on medium until the liquid is gone and they're glossy."],
    tips:["Cook these clams completely; never eat them raw or half-cooked.","Once cool, keep in a box in the fridge for 3 days."]},
   "葱油毛蚶":{n:"Ark clams with scallion oil",h:"Boil, remove the meat and dress with scallion oil and soy sauce."},
   "拌毛蚶":{n:"Saekkomak muchim (Korean dressed ark clams)",h:"Boil, remove half the shell and top with a sauce of soy sauce, chili flakes, garlic, scallion and sesame oil."}
  }},
 hokkigai:{tip:"Japanese hokkigai is the Sakhalin surf clam. Chinese supermarket \"arctic surf clam\" is usually cooked-frozen Canadian clam, a different species. Raw hokkigai turns pink when cooked.",
  d:{
   "北寄贝饭":{n:"Hokki-meshi (surf clam rice)",h:"Simmer surf clam in soy sauce and sake, cook rice in the liquid and mix the clam in at the end. A Soma, Fukushima specialty.",serves:"3–4",time:"50 min",
    ingT:[["Raw surf clam meat","4 (about 150 g)"],["Rice","2 cups (360 ml)"],["Ginger","1 small piece"],["Scallion or nori","a little"]],
    sauceT:[["Soy sauce","2 tbsp"],["Sake","2 tbsp"],["Mirin","1 tbsp"],["Water","as needed"]],
    steps:["Wash the rice and drain 30 minutes.",
     "Cut the clam into 1 cm strips and shred the ginger.",
     "Bring the soy sauce, sake, mirin and ginger to a boil in a small pan, cook the clam 1 minute (it turns pink) and lift it out; keep the liquid.",
     "Cool the liquid, pour it into the rice cooker, add water to the 2-cup line and cook as usual.",
     "When done, add the clam, cover and let stand 10 minutes, then mix.",
     "Serve topped with scallion or nori."],
    tips:["Cooking the clam first and adding it back at the end keeps it from toughening.","This is \"hokki-meshi\", the famous dish of Soma, Fukushima."]},
   "北寄贝咖喱":{n:"Hokki curry",h:"A Tomakomai, Hokkaido specialty: Japanese curry made with surf clams and vegetables."},
   "北极贝刺身":{n:"Arctic surf clam sashimi",h:"Thaw cooked-frozen clams naturally and eat with wasabi and soy sauce."}
  }},
 torigai:{tip:"The black foot looks like a bird's beak; soft and sweet. Supermarket ones are almost always pre-blanched.",
  d:{
   "鸟贝醋拌":{n:"Cockle and wakame sunomono",h:"Toss cockles, wakame and cucumber in sweet vinegar (sanbaizu).",serves:"2",time:"10 min",
    ingT:[["Blanched cockles","6–8 pieces"],["Dried wakame","2 g"],["Cucumber","1/2"]],
    sauceT:[["Rice vinegar","3 tbsp"],["Sugar","1.5 tbsp"],["Soy sauce","1 tsp"],["Salt","a pinch"]],
    steps:["Soak the wakame 5 minutes and squeeze dry. Slice the cucumber thin, salt for 5 minutes and squeeze.",
     "Cut the cockles in half.",
     "Mix the vinegar, sugar and soy sauce into sanbaizu.",
     "Put everything in a bowl and toss with the dressing."],
    tips:["Supermarket cockles are pre-blanched; use as is.","Spring is cockle season."]},
   "鸟贝寿司":{n:"Torigai nigiri",h:"Open blanched cockles, shape into nigiri and brush with a little sweet sauce if you like."},
   "英式醋泡鸟蛤":{n:"Cockles in vinegar",h:"A British seaside snack: boiled cockles doused in malt vinegar and sprinkled with pepper."}
  }},
 mirugai:{tip:"Japan's prized \"hon-miru\" is a different, pricier clam; the common supermarket \"shiro-miru\" is geoduck. You eat the long siphon, blanched and peeled.",
  d:{
   "象拔蚌刺身":{n:"Geoduck sashimi",h:"Blanch the siphon 5 seconds, peel and slice thin; crisp and sweet.",serves:"2",time:"15 min",
    ingT:[["Geoduck (siphon)","1"],["Shredded daikon, shiso","to taste"]],
    sauceT:[["Soy sauce","to taste"],["Wasabi","to taste"],["Ice water","1 bowl"]],
    steps:["Slide a knife between the shell and meat to free it, and cut off the long siphon.",
     "Dip the siphon in boiling water for 5–10 seconds, then straight into ice water.",
     "The outer skin turns white and loosens; peel it off by hand.",
     "Split the siphon lengthwise, rinse out any sand and pat dry.",
     "Slice thin on the diagonal, arrange on daikon and shiso and dip in wasabi soy sauce."],
    tips:["Blanch only briefly to loosen the skin; the inside stays raw.","Use the body for congee or stir-fries."]},
   "象拔蚌两吃":{n:"Geoduck two ways",h:"Siphon sliced as sashimi, body cooked into congee. Cantonese style."},
   "西雅图象拔蚌":{n:"Geoduck crudo (Seattle style)",h:"Thin slices with citrus juice, olive oil and sea salt."}
  }}
});
// English translation U
window.ADD_I18N("en", {
 tsubugai:{tip:"Hokkaido's \"ma-tsubu\" is the best. Supermarkets often sell whelk meat already removed from the shell.",warn:"The salivary gland (abura) of some whelks contains a toxin that causes dizziness; remove the white glandular lump.",
  d:{
   "酱油煮蛾螺":{n:"Soy-simmered whelks",h:"Simmer whole whelks in soy sauce, sake, sugar and ginger and twist the meat out with a toothpick.",serves:"2",time:"25 min",
    ingT:[["Whelks in the shell","6–8"],["Ginger","1 small piece"]],
    sauceT:[["Water","200 ml"],["Soy sauce","2 tbsp"],["Sake","2 tbsp"],["Sugar","1 tbsp"],["Mirin","1 tbsp"]],
    steps:["Scrub the shells with a brush.",
     "Bring the water, soy sauce, sake, sugar, mirin and sliced ginger to a boil.",
     "Add the whelks, cover with a drop lid and simmer on medium-low 15 minutes.",
     "Turn off the heat and let them cool in the liquid to absorb flavor.",
     "Spear the meat with a toothpick and twist it out. Be sure to remove the white lump inside (the salivary gland)."],
    tips:["The salivary gland contains a toxin that causes dizziness if you eat much; always remove it.","Buying pre-cleaned meat (むき身) is safer."]},
   "蛾螺刺身":{n:"Whelk sashimi",h:"Remove the meat and gland, rub with salt to remove the slime, slice and dip in wasabi soy sauce."},
   "拌海螺面":{n:"Golbaengi muchim (spicy whelk salad with noodles)",h:"Toss canned whelks with scallion, cucumber and onion in vinegar-gochujang and serve with somen. A Korean bar snack."},
   "葱油海螺片":{n:"Whelk slices with scallion oil",h:"Remove the gland, slice thin, blanch 10 seconds, top with scallion and pour over hot oil and soy sauce."}
  }},
 baigai:{tip:"Common in Hokuriku and western Japan; smooth, spotted shell and chewy meat.",
  d:{
   "辣炒花螺":{n:"Spicy stir-fried babylon snails",h:"Blanch, then stir-fry hot with ginger, garlic, chili, soy sauce, oyster sauce and shiso.",serves:"2",time:"25 min",
    ingT:[["Babylon snails","500 g"],["Ginger, garlic","1 tbsp each (minced)"],["Dried chilies","5"],["Shiso or Thai basil","1 bunch"]],
    sauceT:[["Pixian chili bean paste","1 tbsp"],["Oyster sauce","1 tbsp"],["Soy sauce","1 tbsp"],["Shaoxing wine","1 tbsp"],["Sugar","1 tsp"],["Neutral oil","2 tbsp"]],
    steps:["Scrub the snails and blanch 3 minutes in boiling water with ginger; drain.",
     "Heat the oil, fry the ginger, garlic and chilies, then add the bean paste until the oil turns red.",
     "Add the snails with the wine, oyster sauce, soy sauce, sugar and 3 tbsp water and toss on high 3 minutes.",
     "Add the shiso, toss and serve."],
    tips:["Don't blanch too long or the meat shrinks deep into the shell and is hard to extract.","To eat, twist the meat out with a toothpick."]},
   "煮东风螺":{n:"Simmered babylon snails (bai-gai no umani)",h:"Simmer 10 minutes in soy sauce, sake, mirin and sugar; even tastier cold."},
   "白灼花螺":{n:"Boiled babylon snails",h:"Boil 5 minutes in water with ginger and wine; dip in wasabi soy sauce."}
  }},
 mategai:{tip:"When clamming in Japan, sprinkle salt into the hole and the razor clam pops out by itself. Chinese razor clams (constricted tagelus and bamboo clams) are very common.",
  d:{
   "葱油蛏子":{n:"Razor clams with scallion oil",h:"Blanch until open, top with shredded scallion and pour over hot oil and seasoned soy sauce.",serves:"2",time:"15 min (plus 1 hour purging)",
    ingT:[["Razor clams","400 g"],["Scallions","4"],["Ginger","1 small piece"]],
    sauceT:[["Seasoned soy sauce for fish (or light soy sauce)","2 tbsp"],["Shaoxing wine","1 tbsp"],["Neutral oil","3 tbsp"]],
    steps:["Soak the clams 1 hour in 3% salt water to purge, then rinse the shells.",
     "Bring water to a boil with ginger and wine, blanch the clams 30–40 seconds and lift out as soon as they open.",
     "Remove one shell half (or not) and arrange on a plate.",
     "Cover with shredded scallion and drizzle with soy sauce.",
     "Heat the oil until smoking and pour over the scallion."],
    tips:["Keep the blanching short; razor clams toughen very fast.","There's a dark sand vein on one side you can squeeze out."]},
   "辣炒蛏子":{n:"Spicy stir-fried razor clams",h:"Fry garlic, dried chili and chili bean paste, then stir-fry the clams on high until they open."},
   "西班牙铁板蛏子":{n:"Navajas a la plancha",h:"Cook whole on a griddle until open; drizzle with olive oil, garlic, parsley and lemon."},
   "黄油酱油蛏":{n:"Butter-soy razor clams",h:"Stir-fry with butter and garlic until open and finish with soy sauce."}
  }},
 tairagi:{tip:"A huge triangular shell prized for its large adductor muscle. In Cantonese cooking \"daai ji\" usually means this or scallop muscle.",
  d:{
   "江珧矶边烧":{n:"Pen shell isobe-yaki (wrapped in nori)",h:"Sear thick slices of the adductor brushed with soy sauce and eat wrapped in nori.",serves:"2",time:"10 min",
    ingT:[["Pen shell adductors (tairagi)","2"],["Nori","1 sheet"]],
    sauceT:[["Soy sauce","1 tbsp"],["Mirin","1 tsp"],["Butter","5 g"]],
    steps:["Peel off the thin membrane around the adductor and slice 1 cm thick.",
     "Mix the soy sauce and mirin.",
     "Heat the butter on medium-high and sear the slices 30–40 seconds per side.",
     "Pour in the sauce and toss quickly.",
     "Cut the nori into strips and wrap each slice to eat."],
    tips:["Best left rare in the middle (use sashimi grade).","\"Isobe-yaki\" means eaten wrapped in nori."]},
   "XO 酱炒带子":{n:"Pen shell with XO sauce",h:"Blanch slices briefly, then stir-fry hot with asparagus and XO sauce."},
   "江珧刺身":{n:"Pen shell sashimi",h:"Peel off the membrane, slice and dip in wasabi soy or salt and lemon."}
  }},
 honbinosu:{tip:"Native to North America, now abundant in Tokyo Bay and sold cheaply in supermarkets. Contains little sand.",
  d:{
   "新英格兰蛤蜊浓汤":{n:"New England clam chowder",h:"Fry bacon, onion and potato, add clam broth and meat, then simmer thick with milk and cream.",serves:"3–4",time:"40 min",
    ingT:[["Quahogs (or Manila clams)","600 g"],["Bacon","2 slices"],["Onion","1/2"],["Potatoes","2"],["Celery (optional)","1/2 stalk"]],
    sauceT:[["White wine or water","100 ml"],["Butter","20 g"],["Flour","2 tbsp"],["Milk","400 ml"],["Cream","100 ml"],["Salt and pepper","to taste"]],
    steps:["Wash the clams, put in a pot with the wine, cover and cook until they open. Remove and chop the meat; strain and keep the broth.",
     "Dice the bacon, onion and celery small and cut the potatoes into 1.5 cm cubes.",
     "Cook the bacon in the butter until it renders, then soften the onion and celery.",
     "Sprinkle in the flour and stir on low for 1 minute (don't let it brown).",
     "Gradually stir in the clam broth, add the potatoes and 200 ml water and simmer 10 minutes until the potatoes are tender.",
     "Add the milk and cream, warm on low, add the clam meat and season with salt and pepper. Don't let it boil."],
    tips:["Boiling after adding milk makes it separate; keep the heat low.","Serving with oyster crackers is the American way."]},
   "酒蒸美国帘蛤":{n:"Sake-steamed quahogs",h:"Cover with sake and garlic until open, then add butter and scallion."},
   "烤馅蛤":{n:"Stuffies (Rhode Island stuffed clams)",h:"Mix chopped clam meat with breadcrumbs, sausage and onion, pack back into the shells and bake."},
   "辣炒白蛤":{n:"Spicy stir-fried clams",h:"Fry ginger, garlic and chili, stir-fry the clams on high until open, add soy sauce and scallion."}
  }},
 tanishi:{tip:"Hardly ever sold in Japanese markets; Chinese grocers have them frozen. Keep live snails two days in clean water with a few drops of oil to purge the mud, then snip off the tail tips.",warn:"May carry rat lungworm (Angiostrongylus); always cook completely.",
  d:{
   "炒螺蛳":{n:"Spicy braised river snails",h:"Snip and wash the snails, fry ginger, garlic, chili and bean paste, then cook the snails with shiso and water for 10 minutes.",serves:"2–3",time:"30 min (plus 1 day purging)",
    ingT:[["River snails","500 g"],["Ginger, garlic","1 tbsp each (minced)"],["Dried chilies","5"],["Shiso leaves","1 bunch"]],
    sauceT:[["Pixian chili bean paste","1.5 tbsp"],["Shaoxing wine","2 tbsp"],["Soy sauce","1 tbsp"],["Sugar","1 tsp"],["Neutral oil","3 tbsp"],["Water","200 ml"]],
    steps:["Keep live snails 1–2 days in clean water with a few drops of oil to purge, changing the water daily.",
     "Snip off the tip of each shell with pliers (so you can suck the meat out) and scrub clean.",
     "Heat the oil and fry the ginger, garlic, chilies and bean paste until the oil turns red.",
     "Add the snails and toss on high 2 minutes, then add the wine, soy sauce, sugar and water.",
     "Cover and cook on medium 10 minutes to make sure they're cooked through.",
     "Add the shiso, toss and serve."],
    tips:["Cook completely; raw or half-cooked snails can carry parasites.","Frozen pre-cleaned snails skip the purging and snipping."]},
   "螺蛳粉":{n:"Luosifen (Liuzhou river snail rice noodles)",h:"Broth of river snails and pork bones with rice noodles, pickled bamboo shoots, wood ear, tofu skin, peanuts and chili oil."},
   "越南田螺粉":{n:"Bún ốc (Hanoi snail noodle soup)",h:"A tangy tomato-vinegar broth with snail meat, rice noodles and perilla. A Hanoi breakfast."}
  }}
});
