window.ADD_I18N("ja", {
 "kaki-oyster":{d:{
  "烤牡蛎":{serves:"2",time:"30分",
   ingT:[["殻付きかき（生食用か加熱用）","6個"],["ほうれん草","1/2束"],["にんにく","1かけ"],["パン粉","大さじ3"],["粉チーズ","大さじ2"],["粗塩（天板に敷く用）","適量"]],
   sauceT:[["バター","30g"],["レモン","1/2個"],["塩・こしょう","少々"],["タバスコ（お好みで）","数滴"]],
   steps:["かきの殻をたわしで洗い、かきナイフを横から差し込んで開け、上の殻を外す。身は貝柱を切って下の殻にのせたままにする。","ほうれん草を30秒ゆでて水気をしぼり、みじん切りに。にんにくもみじん切りにする。","バターを溶かし、半量でにんにくとほうれん草を炒め、塩・こしょうをする。","残りのバターとパン粉、粉チーズを混ぜる。","天板に粗塩を敷いて（かきを安定させる）かきを並べ、ほうれん草をのせて、パン粉をかぶせる。","230°Cのオーブンで8〜10分、表面がこんがりしたらレモンを搾り、タバスコをふる。"],
   tips:["殻を開けるときは手袋をし、かきをふきんで包んでから。","「加熱用」は中心まで火を通す。","アメリカ・ニューオーリンズの名物料理。"]}}},
 asari:{d:{
  "辣炒花蛤":{serves:"2",time:"15分（砂抜き2時間）",
   ingT:[["あさり","500g"],["生姜","薄切り3枚"],["にんにく","4かけ"],["鷹の爪","4本"],["小ねぎ","2本"]],
   sauceT:[["豆板醤","大さじ1"],["料理酒","大さじ1"],["醤油","小さじ1"],["砂糖","小さじ1/2"],["サラダ油","大さじ2"]],
   steps:["あさりを3%の塩水（水500ml＋塩大さじ1）に入れ、ふたをして暗くし2時間砂抜きし、殻をこすり洗いする。","生姜はせん切り、にんにくは薄切り、唐辛子はちぎり、ねぎはぶつ切りにする。","鍋を熱して油をひき、弱火で豆板醤を炒めて赤い油を出し、生姜・にんにく・唐辛子を炒めて香りを出す。","強火にしてあさりを入れて炒め、料理酒をふってふたをし、1〜2分蒸し焼きにする。","ふたを取ってほとんど開いていたら醤油と砂糖を加えて混ぜ、ねぎを散らす。開かないものは除く。"],
   tips:["口が開いたらすぐ火を止める。炒めすぎると身が縮んで硬くなる。","豆板醤が塩辛いので、塩はほぼ不要。","「砂抜き済み」のあさりなら30分つければ十分。"]},
  "蛤蜊味噌汤":{serves:"2",time:"15分（砂抜き2時間）",
   ingT:[["あさり","200g"],["小ねぎ","1本"]],
   sauceT:[["水","400ml"],["昆布（お好みで）","5cm 1枚"],["味噌","大さじ1.5"],["酒（お好みで）","大さじ1"]],
   steps:["あさりを3%の塩水で2時間砂抜きし、殻をこすり洗いする。","鍋に水・昆布・あさりを入れて中火にかける（水から入れるとうまみが出やすい）。","煮立つ直前に昆布を取り出し、アクを取って酒を加える。","あさりが全部開いたら弱火にし、味噌を溶き入れる。","煮立つ直前で火を止め、小ねぎを散らす。"],
   tips:["あさり自体がだしになるので、別にだしは不要。","あさりに塩気があるので、味噌はいつもより少なめに。","開いたらすぐ火を止めると身が縮まない。"]},
  "蛤蜊意面":{serves:"2",time:"25分",
   ingT:[["あさり","300g"],["スパゲッティ","160g"],["にんにく","2かけ"],["鷹の爪","1本"],["パセリ","少々"]],
   sauceT:[["オリーブオイル","大さじ3"],["白ワインか酒","50ml"],["塩","適量"]],
   steps:["あさりは砂抜きしてこすり洗いする。","たっぷりの湯に塩（1Lに10g）を入れ、表示時間より1分短くパスタをゆでる。","フライパンにオリーブオイル・にんにくの薄切り・唐辛子を入れ、弱火でにんにくがうっすら色づくまで炒める。","あさりを入れて白ワインを注ぎ、ふたをして中火で2〜3分、口が開くまで蒸す。","ゆでたパスタとゆで汁大さじ3を加え、強火で1分あおって汁を乳化させ、とろみをつける。","刻んだパセリを散らし、オリーブオイルを少し回しかける。"],
   tips:["パスタは1分短くゆで、最後にフライパンであさりのスープを吸わせる。","ゆで汁のでんぷんでソースにとろみがつく。","日本では「ボンゴレ・ビアンコ」。トマトを入れれば「ロッソ」。"]}}},
 unagi:{d:{
  "红烧鳗鱼":{serves:"3",time:"60分",
   ingT:[["うなぎ（活〆・生）","1尾（約500g）"],["生姜","1かけ"],["長ねぎ","1本"],["にんにく","4かけ"]],
   sauceT:[["紹興酒か料理酒","大さじ4"],["たまり醤油","大さじ1"],["醤油","大さじ2"],["氷砂糖","30g"],["サラダ油","大さじ2"],["湯","400ml"]],
   steps:["うなぎを5cm幅に切り、80°Cくらいの湯に10秒つけ、包丁の背で表面のぬめりをこそげて洗い、水気をふく。","鍋に油を熱し、うなぎを中火で表面がうっすら色づくまで焼いて取り出す。","油を残し、生姜の薄切り・ねぎ・にんにくを炒めて香りを出し、氷砂糖を入れて弱火で溶かし、泡立つまで炒める。","うなぎを戻して鍋肌から紹興酒を回し入れ、たまり醤油・醤油・湯を加える。うなぎがかぶるくらいに。","強火で煮立てて弱火にし、ふたをして40分煮る。途中でやさしく鍋をゆする。","ふたを取って強火で煮詰め、とろりとつやが出たら完成。"],
   tips:["日本では生のうなぎは少ないので、中華食材店や通販で「活〆うなぎ」を探す。","ぬめり取りは臭み消しの要。省かない。","煮ている間は返さない。皮が破れやすい。"]},
  "名古屋鳗鱼饭":{serves:"2",time:"20分",
   ingT:[["うなぎの蒲焼き（市販）","1尾"],["温かいご飯","2杯（多めに）"],["小ねぎ","2本"],["刻みのり","適量"],["わさび","少々"]],
   sauceT:[["うなぎのたれ（付属）","1袋"],["粉山椒","少々"],["だしかほうじ茶","300ml"]],
   steps:["うなぎをアルミホイルにのせて酒を少し塗り、オーブンか魚焼きグリルで3〜4分温め、1.5cm幅に切る。","温かいご飯にたれの半量を混ぜて器に盛り、うなぎを敷き詰め、残りのたれをかける。","1杯目：しゃもじでご飯を4等分し、まず1/4をそのまま食べる。","2杯目：ねぎ・のり・わさびをのせて混ぜて食べる。","3杯目：ねぎ・のり・わさびをのせ、熱いだしかお茶をかけてお茶漬けに。","最後の1杯：いちばん気に入った食べ方で。"],
   tips:["市販の蒲焼きは温める前に酒を塗ると、ふっくらする。","だしは顆粒だしを湯で溶いたものか、ほうじ茶でOK。","名古屋名物。一杯で三通りの味が楽しめる。"]},
  "伦敦鳗鱼冻":{serves:"4",time:"40分（冷やし4時間）",
   ingT:[["うなぎ（生・活〆）","500g"],["玉ねぎ","1/2個"],["ローリエ","2枚"],["パセリ","少々"]],
   sauceT:[["水","約600ml（かぶる量）"],["ワインビネガーかモルトビネガー","大さじ3"],["塩","小さじ1"],["黒こしょう（粒）","10粒"],["ゼラチン（お好みで）","5g"],["チリビネガー（つけだれ）","適量"]],
   steps:["うなぎのぬめりを取り（塩でもむか包丁の背でこそげる）、3cm幅に切る。","鍋に水・ビネガー・玉ねぎ・ローリエ・こしょう・塩を入れ、うなぎを加えて弱火で25分。ぐらぐら煮立てない。","うなぎを器か型に移し、煮汁を目の細かいこし器でこす。","皮や骨のゼラチン質で冷めると固まるが、不安ならふやかしたゼラチンを溶かし入れる。","煮汁をうなぎに注ぎ、冷ましてから冷蔵庫で4時間以上冷やし固める。","刻んだパセリを散らし、チリビネガーを添えて冷たいまま食べる。"],
   tips:["ロンドン・イーストエンドの伝統的な軽食。かなり個性的な味。","弱火で煮ると煮汁が澄む。","日本では生のうなぎは少ないので、専門店で予約を。"]}}},
 "pork-belly":{d:{
  "冲绳炖猪肉":{serves:"4",time:"3時間",
   ingT:[["豚バラブロック（皮付きなら最高）","600g"],["生姜","1かけ"],["長ねぎの青い部分","1本分"]],
   sauceT:[["泡盛か酒","200ml"],["黒糖","60g"],["醤油","大さじ4"],["ゆで汁","300ml"],["からし（添える用）","少々"]],
   steps:["豚バラをかたまりのまま鍋に入れ、かぶるくらいの水・ねぎの青い部分・生姜の薄切りを加え、煮立ったら弱火で1時間ゆでる。","肉を取り出して5cm角に切る。ゆで汁は冷まして表面の脂を取り、300ml取っておく。","鍋に肉・泡盛・黒糖・ゆで汁を入れ、アルミホイルで落とし蓋をして弱火で30分煮る。","醤油を加え、さらに弱火で1時間、途中で何度か返しながら煮る。","ふたを取ってとろりとつやが出るまで煮詰め、からしを添える。"],
   tips:["沖縄の名物。箸で切れるやわらかさになれば成功。","先にゆでて脂を落とすので、しつこくない。","圧力鍋なら、下ゆで20分、味をつけてから15分。"]},
  "韩式烤五花":{serves:"2〜3",time:"30分",
   ingT:[["豚バラ厚切り（焼肉用、1cm）","400g"],["サンチュかエゴマの葉","1株"],["にんにく","6かけ"],["青唐辛子","2本"],["キムチ","適量"],["玉ねぎ（お好みで）","1/2個"]],
   sauceT:[["サムジャン","大さじ3"],["ごま油","大さじ2"],["塩・こしょう","少々"]],
   steps:["ごま油に塩とこしょうを混ぜてつけだれ（塩ごま油）にする。","ホットプレートかフライパンを熱し（油はひかない）、豚バラを中火で焼き、脂がたくさん出たらキッチンペーパーで吸い取る。","片面がこんがりしたら裏返し、両面カリッとしたらキッチンばさみで一口大に切る。","横でにんにくの薄切り・キムチ・玉ねぎも焼く。豚の脂で焼くといちばんおいしい。","サンチュに肉をのせて塩ごま油をつけ、サムジャン・にんにく・唐辛子をのせて包み、一口で食べる。"],
   tips:["韓国では肉をはさみで切る。とても便利。","焼きキムチは隠れた名品。","最後に残った脂とキムチでチャーハンを。"]},
  "菲律宾脆皮五花":{serves:"3",time:"1.5時間（乾燥1時間）",
   ingT:[["皮付き豚バラブロック（業務スーパーなど）","600g"],["にんにく","1玉"],["ローリエ","2枚"],["黒こしょう（粒）","小さじ1"]],
   sauceT:[["塩","大さじ1"],["揚げ油","鍋底から4cm"],["酢（つけだれ）","大さじ4"],["醤油","大さじ1"],["にんにく・玉ねぎのみじん切り、唐辛子","少々"]],
   steps:["鍋に水・豚肉・にんにく・ローリエ・粒こしょう・塩を入れ、煮立ったら弱火で45分、箸が通るまでゆでる。","取り出して水気をふき、皮を上にして冷蔵庫で1時間以上（一晩でも）置き、皮をしっかり乾かす。","4cm角に切り、フォークで皮に細かい穴をたくさんあける。","油を170°Cに熱し、肉を入れて10分、皮がぷくぷくふくらんできつね色になるまで揚げる。油がはねるので油はねガードを使う。","酢・醤油・にんにく・玉ねぎ・唐辛子を混ぜてたれを作り、肉に添える。"],
   tips:["皮が乾いているほどカリッと揚がるので、乾燥は省かない。","揚げるときはバチバチはねるので、必ずガードかふたを半分かぶせて。","フィリピンでは白いご飯と酢だれで食べる。"]}}},
 "chicken-thigh":{d:{
  "三杯鸡":{serves:"2〜3",time:"30分",
   ingT:[["鶏もも肉","2枚（約500g）"],["生姜","大1かけ"],["にんにく","10かけ"],["バジル（台湾バジル）","1束"],["赤唐辛子","1本"]],
   sauceT:[["黒ごま油（またはごま油）","大さじ3"],["米酒か酒","大さじ3"],["醤油","大さじ3"],["氷砂糖か砂糖","大さじ1"]],
   steps:["鶏肉は4cm角に切り、生姜は厚めの薄切り、にんにくは皮をむいて丸ごと使う。","鍋にごま油を入れ、弱火で生姜を3分、縁が反り返って乾くまで炒め、にんにくを加えてきつね色になるまで炒める。","中火にして鶏肉を皮目から焼き、きつね色になったらさらに2分炒める。","砂糖・醤油・米酒を加えて混ぜ、ふたをして弱火で10分煮る。","ふたを取って強火にし、炒めながら煮詰め、汁気がほぼなくなってつやが出たら唐辛子とバジルを加え、ざっと混ぜて火を止める。"],
   tips:["「三杯」はもともとごま油・米酒・醤油を1杯ずつ。家では上の分量で十分。","生姜はしっかり乾くまで炒めると台湾の味になる。","バジルは最後に入れると香りが立つ。スイートバジルでも代用できる。"]},
  "日式炸鸡":{serves:"2〜3",time:"30分（漬け30分）",
   ingT:[["鶏もも肉","2枚（約500g）"],["レモン","1/4個"],["キャベツの千切り（お好みで）","適量"]],
   sauceT:[["醤油","大さじ2"],["酒","大さじ1"],["おろし生姜","小さじ1"],["おろしにんにく","小さじ1"],["片栗粉","大さじ4"],["薄力粉","大さじ2"],["揚げ油","鍋底から3cm"]],
   steps:["鶏肉の余分な脂と筋を取り、4cm角に切る。","醤油・酒・生姜・にんにくを加えてもみ込み、冷蔵庫で30分漬ける。","片栗粉と薄力粉を混ぜ、鶏肉の汁気を軽くきって粉をまぶす。","油を170°Cに熱して3分揚げ、取り出して4分休ませる（余熱で中まで火を通す）。","油を190°Cに上げ、もう一度1分揚げて、表面をカリッときつね色にする。","レモンを搾り、キャベツを添える。"],
   tips:["二度揚げが外カリ中ジューシーのコツ。","片栗粉と薄力粉を合わせると、カリッとして衣がはがれにくい。","皮で肉を包むように丸めて揚げると、よりジューシー。"]}}}
});
window.ADD_I18N("en", {
 "kaki-oyster":{d:{
  "烤牡蛎":{serves:"2",time:"30 min",
   ingT:[["Oysters in the shell (raw or cooking grade)","6"],["Spinach","1/2 bunch"],["Garlic","1 clove"],["Panko","3 tbsp"],["Grated Parmesan","2 tbsp"],["Coarse salt (to bed the tray)","as needed"]],
   sauceT:[["Butter","30g"],["Lemon","1/2"],["Salt and pepper","a little"],["Tabasco (optional)","a few drops"]],
   steps:["Scrub the shells, insert an oyster knife at the side to pry them open and remove the top shell. Cut the muscle free but leave the oyster in the bottom shell.","Blanch the spinach for 30 seconds, squeeze dry and chop. Mince the garlic.","Melt the butter and use half to cook the garlic and spinach. Season with salt and pepper.","Mix the remaining butter with the panko and Parmesan.","Spread coarse salt on a baking tray to hold the oysters steady. Top each oyster with spinach, then the crumbs.","Bake at 230°C for 8–10 minutes until golden. Squeeze over lemon and add Tabasco."],
   tips:["Wear a glove and wrap the oyster in a towel when shucking.","Cooking-grade oysters must be cooked through.","A classic from New Orleans."]}}},
 asari:{d:{
  "辣炒花蛤":{serves:"2",time:"15 min (plus 2 hours purging)",
   ingT:[["Manila clams","500g"],["Ginger","3 slices"],["Garlic","4 cloves"],["Dried red chilies","4"],["Scallions","2"]],
   sauceT:[["Doubanjiang (chili bean paste)","1 tbsp"],["Shaoxing or cooking wine","1 tbsp"],["Light soy sauce","1 tsp"],["Sugar","1/2 tsp"],["Cooking oil","2 tbsp"]],
   steps:["Soak the clams in 3% salt water (500ml water plus 1 tbsp salt), covered to keep dark, for 2 hours to purge sand. Scrub the shells.","Cut the ginger into strips, slice the garlic, snip the chilies and cut the scallions into lengths.","Heat the oil and fry the doubanjiang over low heat until the oil turns red, then add the ginger, garlic and chilies.","Turn the heat to high, add the clams and toss, splash in the wine, cover and cook 1–2 minutes.","When most have opened, stir in the soy sauce and sugar and add the scallions. Discard any that stay closed."],
   tips:["Take them off the heat as soon as they open, or the meat shrinks and toughens.","Doubanjiang is salty, so you rarely need extra salt.","Pre-purged clams (砂抜き済み) need only 30 minutes."]},
  "蛤蜊味噌汤":{serves:"2",time:"15 min (plus 2 hours purging)",
   ingT:[["Manila clams","200g"],["Scallion","1"]],
   sauceT:[["Water","400ml"],["Kombu (optional)","1 piece, 5cm"],["Miso","1.5 tbsp"],["Sake (optional)","1 tbsp"]],
   steps:["Purge the clams in 3% salt water for 2 hours and scrub the shells.","Put cold water, kombu and the clams in a pot over medium heat (starting cold draws out more flavor).","Just before it boils, remove the kombu, skim and add the sake.","When all the clams have opened, lower the heat and dissolve the miso.","Turn off the heat just before it boils and add sliced scallion."],
   tips:["The clams make their own stock, so no dashi is needed.","Use a little less miso than usual, as clams are salty.","Turning off the heat as soon as they open keeps the meat plump."]},
  "蛤蜊意面":{serves:"2",time:"25 min",
   ingT:[["Manila clams","300g"],["Spaghetti","160g"],["Garlic","2 cloves"],["Dried red chili","1"],["Parsley","a little"]],
   sauceT:[["Olive oil","3 tbsp"],["White wine or sake","50ml"],["Salt","as needed"]],
   steps:["Purge and scrub the clams.","Boil the pasta in plenty of salted water (10g salt per liter) for 1 minute less than the package says.","Put the olive oil, sliced garlic and chili in a pan and cook on low until the garlic is pale gold.","Add the clams and wine, cover and cook over medium for 2–3 minutes until they open.","Add the pasta and 3 tbsp of pasta water and toss over high heat for 1 minute until the sauce emulsifies and thickens.","Sprinkle with chopped parsley and drizzle with a little olive oil."],
   tips:["Cook the pasta 1 minute short so it finishes by soaking up the clam broth.","The starch in the pasta water thickens the sauce.","In Japan it's called vongole bianco. Add tomato and it's rosso."]}}},
 unagi:{d:{
  "红烧鳗鱼":{serves:"3",time:"60 min",
   ingT:[["Fresh eel, killed and cleaned","1 (about 500g)"],["Ginger","1 piece"],["Japanese leek (negi)","1"],["Garlic","4 cloves"]],
   sauceT:[["Shaoxing or cooking wine","4 tbsp"],["Dark soy sauce","1 tbsp"],["Light soy sauce","2 tbsp"],["Rock sugar","30g"],["Cooking oil","2 tbsp"],["Hot water","400ml"]],
   steps:["Cut the eel into 5cm pieces, dip in water at about 80°C for 10 seconds, scrape off the slime with the back of a knife, rinse and pat dry.","Heat the oil and sear the eel over medium until lightly golden. Remove.","In the remaining oil, fry the ginger slices, leek and garlic until fragrant, then add the rock sugar and stir over low heat until melted and bubbling.","Return the eel, drizzle the wine around the edge of the pan, and add both soy sauces and hot water to cover.","Bring to a boil, then cover and simmer on low for 40 minutes, gently shaking the pan now and then.","Uncover and reduce over high heat until thick and glossy."],
   tips:["Fresh eel is rare in Japan. Look for 活〆うなぎ at Chinese grocers or online.","Scraping off the slime is essential for removing fishiness.","Don't stir while it simmers. The skin tears easily."]},
  "名古屋鳗鱼饭":{serves:"2",time:"20 min",
   ingT:[["Ready-made grilled eel (kabayaki)","1"],["Hot cooked rice","2 large bowls"],["Scallions","2"],["Shredded nori","as needed"],["Wasabi","a little"]],
   sauceT:[["Eel sauce (packet included)","1 packet"],["Sansho pepper","a little"],["Dashi or roasted green tea","300ml"]],
   steps:["Put the eel on foil, brush with a little sake, warm in the oven or fish grill for 3–4 minutes and cut into 1.5cm strips.","Mix half the sauce into the hot rice, put it in bowls, cover with eel and pour over the rest of the sauce.","First serving: divide the rice into quarters with a paddle and eat one quarter plain.","Second: add scallions, nori and wasabi and mix.","Third: add scallions, nori and wasabi and pour over hot dashi or tea.","Last: eat it whichever way you liked best."],
   tips:["Brushing store-bought eel with sake before warming makes it fluffy.","Instant dashi granules in hot water or hojicha both work.","A Nagoya specialty. The fun is eating one bowl three ways."]},
  "伦敦鳗鱼冻":{serves:"4",time:"40 min (plus 4 hours chilling)",
   ingT:[["Fresh eel, killed and cleaned","500g"],["Onion","1/2"],["Bay leaves","2"],["Parsley","a little"]],
   sauceT:[["Water","about 600ml (to cover)"],["Wine or malt vinegar","3 tbsp"],["Salt","1 tsp"],["Black peppercorns","10"],["Gelatin powder (optional)","5g"],["Chili vinegar (for serving)","as needed"]],
   steps:["Remove the slime (rub with salt or scrape with a knife) and cut the eel into 3cm pieces.","Put the water, vinegar, onion, bay, peppercorns and salt in a pot, add the eel and simmer gently for 25 minutes without boiling hard.","Move the eel to a bowl or mold and strain the liquid through a fine sieve.","Gelatin from the skin and bones sets the liquid as it cools. To be safe, stir in bloomed gelatin.","Pour the liquid over the eel, cool and refrigerate at least 4 hours until set.","Sprinkle with chopped parsley and eat cold with chili vinegar."],
   tips:["A traditional snack of London's East End, with a distinctive taste.","Gentle heat keeps the jelly clear.","Fresh eel is rare in Japan. Order from a specialist shop."]}}},
 "pork-belly":{d:{
  "冲绳炖猪肉":{serves:"4",time:"3 hours",
   ingT:[["Pork belly slab (skin-on is best)","600g"],["Ginger","1 piece"],["Green part of a Japanese leek","1"]],
   sauceT:[["Awamori or sake","200ml"],["Brown (kokuto) sugar","60g"],["Soy sauce","4 tbsp"],["Cooking liquid from the pork","300ml"],["Hot mustard (to serve)","a little"]],
   steps:["Put the slab in a pot with water to cover, the leek greens and sliced ginger. Bring to a boil and simmer on low for 1 hour.","Remove and cut into 5cm cubes. Cool the cooking liquid, skim off the fat and keep 300ml.","Put the pork, awamori, sugar and liquid in a pot, cover with foil laid directly on top and simmer on low for 30 minutes.","Add the soy sauce and simmer 1 hour more, turning a few times.","Uncover and reduce until thick and glossy. Serve with a little mustard."],
   tips:["An Okinawan classic. It's right when it falls apart at the touch of a chopstick.","Boiling first removes fat so it isn't greasy.","Pressure cooker: 20 minutes for the first boil, then 15 minutes after seasoning."]},
  "韩式烤五花":{serves:"2–3",time:"30 min",
   ingT:[["Thick-cut pork belly (1cm)","400g"],["Lettuce or perilla leaves","1 head"],["Garlic","6 cloves"],["Green chilies","2"],["Kimchi","as needed"],["Onion (optional)","1/2"]],
   sauceT:[["Ssamjang","3 tbsp"],["Sesame oil","2 tbsp"],["Salt and black pepper","a little"]],
   steps:["Mix the sesame oil with salt and pepper for dipping.","Heat a griddle or frying pan (no oil) and cook the pork over medium, blotting the fat with paper towels as it renders.","When one side is golden, flip. Once both sides are crisp, cut into bite-size pieces with scissors.","Grill sliced garlic, kimchi and onion alongside. They're best cooked in the pork fat.","Put a piece of pork dipped in the sesame oil on a lettuce leaf, add ssamjang, garlic and chili, wrap and eat in one bite."],
   tips:["Koreans cut the meat with scissors. It's very handy.","Grilled kimchi is a hidden treat.","Finish by frying rice with the leftover fat and kimchi."]},
  "菲律宾脆皮五花":{serves:"3",time:"1.5 hours (plus 1 hour drying)",
   ingT:[["Skin-on pork belly slab","600g"],["Garlic","1 head"],["Bay leaves","2"],["Black peppercorns","1 tsp"]],
   sauceT:[["Salt","1 tbsp"],["Oil for frying","4cm deep"],["Vinegar (for dipping)","4 tbsp"],["Soy sauce","1 tbsp"],["Minced garlic, onion and chili","a little"]],
   steps:["Put water, the pork, garlic, bay, peppercorns and salt in a pot. Bring to a boil and simmer on low for 45 minutes until a chopstick goes in.","Remove, pat dry and refrigerate skin side up for at least 1 hour (or overnight) so the skin dries completely.","Cut into 4cm pieces and prick the skin all over with a fork.","Heat the oil to 170°C and fry 10 minutes until the skin blisters and turns golden. It spatters, so use a splatter screen.","Mix the vinegar, soy sauce, garlic, onion and chili for dipping."],
   tips:["The drier the skin, the crisper it fries, so don't skip the drying.","Always use a splatter screen or half-cover the pot. It pops a lot.","Filipinos eat it with white rice and vinegar dip."]}}},
 "chicken-thigh":{d:{
  "三杯鸡":{serves:"2–3",time:"30 min",
   ingT:[["Chicken thighs","2 (about 500g)"],["Ginger","1 large piece"],["Garlic","10 cloves"],["Thai or sweet basil","1 large handful"],["Red chili","1"]],
   sauceT:[["Black sesame oil (or sesame oil)","3 tbsp"],["Rice wine or sake","3 tbsp"],["Soy sauce","3 tbsp"],["Rock sugar or sugar","1 tbsp"]],
   steps:["Cut the chicken into 4cm pieces, slice the ginger thickly and peel the garlic, leaving the cloves whole.","Heat the sesame oil and fry the ginger over low heat for 3 minutes until the edges curl and dry, then add the garlic and fry until golden.","Turn to medium, add the chicken skin side down and brown, then stir-fry 2 more minutes.","Add the sugar, soy sauce and rice wine, toss, cover and simmer on low for 10 minutes.","Uncover, turn to high and stir until the sauce has almost gone and the chicken is glossy. Add the chili and basil, toss and turn off the heat."],
   tips:["Three cups originally meant one cup each of sesame oil, rice wine and soy. The amounts above work at home.","Frying the ginger until dry gives the Taiwanese flavor.","Add the basil last for the most aroma. Sweet basil works too."]},
  "日式炸鸡":{serves:"2–3",time:"30 min (plus 30 min marinating)",
   ingT:[["Chicken thighs","2 (about 500g)"],["Lemon","1/4"],["Shredded cabbage (optional)","as needed"]],
   sauceT:[["Soy sauce","2 tbsp"],["Sake","1 tbsp"],["Grated ginger","1 tsp"],["Grated garlic","1 tsp"],["Potato starch","4 tbsp"],["Cake flour","2 tbsp"],["Oil for frying","3cm deep"]],
   steps:["Trim excess fat and sinew from the chicken and cut into 4cm pieces.","Massage in the soy sauce, sake, ginger and garlic and refrigerate 30 minutes.","Mix the starch and flour. Drain the chicken briefly and coat it in the mix.","Fry at 170°C for 3 minutes, remove and rest 4 minutes (carryover heat cooks the center).","Raise the oil to 190°C and fry again for 1 minute until crisp and golden.","Squeeze over lemon and serve with cabbage."],
   tips:["Double frying gives a crisp outside and juicy inside.","Starch plus flour makes a crisp coating that doesn't fall off.","Wrap the skin around the meat before frying for juicier pieces."]}}}
});
// 详细菜谱翻译 05
window.ADD_I18N("ja", {
 "chicken-thigh":{d:{
  "海南鸡饭":{serves:"3",time:"1時間",
   ingT:[["骨付き鶏もも肉","2本（約600g）"],["米（できればジャスミン米）","2合（360ml）"],["生姜","大1かけ"],["にんにく","4かけ"],["小ねぎ","3本"],["きゅうり・トマト・パクチー","適量"]],
   sauceT:[["塩","小さじ1.5"],["水","1.5L"],["鶏油かサラダ油","大さじ2"],["チリソース","適量"],["シーユーダムか甘口醤油","適量"],["ごま油","小さじ1"]],
   steps:["鶏肉に塩をすり込んで15分置く。鍋に水・生姜の薄切り・ねぎを入れて沸かし、鶏肉を入れて再沸騰したらごく弱火にし、ふたをして20分（ぐらぐら煮立てない）。","鶏肉を取り出してすぐ氷水に10分つけると皮がぷりっと締まる。取り出してごま油を塗る。","米を洗って水気をきる。鍋に鶏油を熱してにんにくと生姜のみじん切りを炒め、米を加えて2分、透き通るまで炒める。","米を炊飯器に移し、水の代わりに鶏のゆで汁を入れ、塩少々を加えて普通に炊く。","生姜だれ：生姜とねぎをみじん切りにして塩を加え、熱した油をかける。","鶏肉を切ってご飯にのせ、きゅうり・トマト・パクチーを添え、チリソース・生姜だれ・甘口醤油をつけて食べる。"],
   tips:["弱火でじっくり火を通すと、しっとりジューシーに。","鶏のスープで炊くご飯が主役。鶏よりおいしいとも。","シンガポールとマレーシアの国民食。"]}}},
 beef:{d:{
  "番茄炖牛腩":{n:"牛バラのトマト煮込み（中国風）",h:"下ゆでした牛バラをトマト・玉ねぎ・生姜と弱火で1.5時間煮込み、トマトが濃いソースになったらご飯や麺と。",serves:"3〜4",time:"2時間",
   ingT:[["牛バラ（ブロック）か牛すじ","600g"],["トマト","4個（約600g）"],["玉ねぎ","1個"],["生姜","薄切り4枚"],["小ねぎ","2本"]],
   sauceT:[["料理酒","大さじ2"],["ケチャップ","大さじ2"],["醤油","大さじ2"],["砂糖","大さじ1"],["塩","小さじ1"],["サラダ油","大さじ2"],["湯","800ml"]],
   steps:["牛肉を3cm角に切って水から入れ、料理酒大さじ1を加え、沸騰したらアクを取って3分ゆで、ぬるま湯で洗う。","トマト3個はざく切り、1個は最後用に取っておく。玉ねぎはざく切り。","鍋に油を熱して玉ねぎと生姜を2分炒め、トマト3個分とケチャップを加えて中火で5分、赤いとろりとしたソースになるまで炒める。","牛肉を入れて残りの料理酒をふり、醤油・砂糖・湯を加えて強火で煮立て、弱火にしてふたをし1.5時間煮込む（圧力鍋なら30分）。","残りのトマトと塩を加えてさらに10分、汁にとろみがついたら小ねぎを散らす。"],
   tips:["トマトは2回に分けて。先に入れた分はソースに、後の分は食感を残す。","牛肉の下ゆでは水から。血やアクがしっかり出る。","煮汁は麺やご飯にかけてもおいしい。"]},
  "小炒黄牛肉":{n:"牛肉と唐辛子の炒め（湖南風）",h:"薄切り牛肉に片栗粉と醤油をもみ込み、唐辛子・セロリ・パクチーと強火で一気に炒める湖南料理。",serves:"2",time:"20分",
   ingT:[["牛もも肉か牛ヒレ（薄切りでも可）","250g"],["青唐辛子か赤唐辛子","4〜6本"],["セロリ（茎）","1本"],["パクチー","2本"],["にんにく","4かけ"],["生姜","1かけ"]],
   sauceT:[["醤油","大さじ1"],["オイスターソース","小さじ1"],["片栗粉","小さじ1"],["料理酒","小さじ1"],["塩","少々"],["サラダ油","大さじ4"]],
   steps:["牛肉を繊維に逆らって薄切りにし、醤油・オイスターソース・料理酒・片栗粉・油大さじ1をもみ込んで15分置く。","唐辛子は小口切り、セロリとパクチーはざく切り、にんにくと生姜はみじん切りにする。","鍋を煙が出るまで熱して油大さじ3を入れ、牛肉を広げて強火で20秒焼き、手早く炒めて八分通り火が通ったら取り出す。","残った油で生姜・にんにく・唐辛子を30秒炒め、セロリを加えて30秒、塩少々をふる。","牛肉を戻して強火で20秒炒め、パクチーを加えて混ぜたら完成。"],
   tips:["繊維に逆らって切ると牛肉がやわらかい。","鍋はしっかり熱く。水っぽくならず香ばしく仕上がる。","スーパーの「牛こま切れ」もそのまま使える。"]},
  "寿喜烧":{serves:"3〜4",time:"30分",
   ingT:[["すき焼き用牛肉","400g"],["焼き豆腐","1丁"],["長ねぎ","2本"],["白菜","1/8株"],["春菊","1束"],["しいたけ","4枚"],["しらたき","1袋"],["卵（生食用）","1人1個"]],
   sauceT:[["醤油","100ml"],["みりん","100ml"],["酒","50ml"],["砂糖","大さじ3"],["牛脂","1個"]],
   steps:["醤油・みりん・酒・砂糖を煮立てて割下を作る。","しらたきは2分下ゆでして臭みを抜き、食べやすく切る。豆腐は角切り、ねぎは斜め切り、白菜と春菊はざく切り、しいたけは飾り切りにする。","すき焼き鍋か厚手のフライパンを熱し、牛脂を全体に塗る。","まず牛肉を数枚広げて砂糖を少しふり、割下を少量注いで、半熟のうちに溶き卵につけて食べる（関東は野菜から煮る）。","ねぎ・豆腐・しらたき・しいたけ・白菜を並べ、割下を半分ほど注ぎ、中火で5分煮る。","牛肉と春菊を加え、煮えたものから溶き卵につけて食べる。"],
   tips:["牛肉は色が変わったらすぐ食べる。煮すぎると硬くなる。","煮汁が濃くなったら水か酒を足す。","卵は日本の生食用を。最後に残った汁でうどんを。"]},
  "韩式烤牛肉":{serves:"3",time:"20分（漬け1時間）",
   ingT:[["牛薄切り（切り落とし）","400g"],["玉ねぎ","1個"],["にんじん","1/3本"],["長ねぎ","1/2本"],["しいたけ（お好みで）","3枚"]],
   sauceT:[["醤油","大さじ4"],["すりおろし梨かりんご","大さじ3"],["砂糖","大さじ1.5"],["おろしにんにく","大さじ1"],["ごま油","大さじ1"],["白ごま","小さじ1"],["黒こしょう","少々"]],
   steps:["醤油・梨・砂糖・にんにく・ごま油・ごま・こしょうを混ぜて漬けだれにする。","牛肉を5cm幅に切ってたれにもみ込み、冷蔵庫で1時間漬ける（梨で肉がやわらかくなる）。","玉ねぎとにんじんは細切り、ねぎは斜め切り、しいたけは薄切りにする。","フライパンを熱し、玉ねぎとにんじんを1分炒め、牛肉をたれごと加える。","強火で3〜4分、肉に火が通り汁が少し煮詰まったら、ねぎを加えて混ぜ、ごまをふる。"],
   tips:["梨のすりおろしがやわらかさの秘密。りんごやパイナップルでも。","炒めすぎるとパサつく。","サンチュで包んでも、ご飯にのせても。"]},
  "红酒炖牛肉":{serves:"4",time:"3.5時間",
   ingT:[["牛肩ロースか牛すね（ブロック）","800g"],["ベーコン（ブロック）","100g"],["玉ねぎ","1個"],["にんじん","1本"],["マッシュルーム","150g"],["にんにく","2かけ"],["ペコロス（お好みで）","8個"]],
   sauceT:[["赤ワイン","500ml（1本の2/3）"],["ビーフブイヨン","200ml"],["トマトペースト","大さじ1"],["小麦粉","大さじ2"],["タイム・ローリエ","各少々"],["バター","20g"],["塩・こしょう","適量"],["オリーブオイル","大さじ2"]],
   steps:["牛肉を5cm角の大きめに切って水気をふき、塩・こしょうをして小麦粉を薄くまぶす。","厚手の鍋に油を熱し、拍子木切りのベーコンを炒めて脂を出し、取り出す。牛肉を数回に分けて入れ、強火で各面を濃い焼き色がつくまで焼き、取り出す。","鍋に玉ねぎ・にんじんの角切り・にんにくを入れて5分炒め、トマトペーストを加えて1分炒める。","牛肉とベーコンを戻して赤ワインを注ぎ、木べらで鍋底のこびりつきをこそげ、ブイヨン・タイム・ローリエを加える。","煮立ったらふたをしてごく弱火（または160°Cのオーブン）で2.5〜3時間、フォークで肉が簡単にほぐれるまで煮込む。","別のフライパンでバターでマッシュルームとペコロスをきつね色に炒め、鍋に加えて15分煮て、塩で味をととのえる。"],
   tips:["肉を焼くときは詰め込まず、一つずつしっかり焼き色を。これがうまみのもと。","赤ワインは高価でなくてよい。飲める普通のもので。","一晩置いて温め直すとさらにおいしい。マッシュポテトやパンと。"]}}},
 lamb:{d:{
  "新疆羊肉串":{serves:"3〜4",time:"30分（漬け1時間）",
   ingT:[["ラム肩肉かラムもも肉","500g"],["ラムの脂身（お好みで）","50g"],["玉ねぎ","1/2個"],["竹串","15〜20本"]],
   sauceT:[["クミンシード","大さじ1"],["クミンパウダー","大さじ1"],["一味唐辛子（粉唐辛子）","大さじ1"],["塩","小さじ1"],["サラダ油","大さじ1"],["白ごま（お好みで）","小さじ1"]],
   steps:["竹串は焦げないよう30分水につけておく。","ラムを2cm角に切り、みじん切りの玉ねぎ・クミンパウダー半量・塩・油ともみ込み、冷蔵庫で1時間漬ける。","1本に肉を4〜5切れ刺し、間に脂身を1切れはさむ。","オーブンを230°Cに予熱する（グリルやフライパンでも）。","網にのせて6分焼き、返してクミンシード・クミンパウダー・唐辛子をふり、さらに4〜5分焼く。","焼き上がりにクミンとごまをもう一度ふり、熱いうちに。"],
   tips:["脂身をはさむと香ばしく、パサつかない。","フライパンなら中火で片面3分ずつ焼き、最後にスパイスを。","スーパーの「ラム肩ロース」がぴったり。"]},
  "成吉思汗烤肉":{serves:"3",time:"30分",
   ingT:[["ラム肉スライス（ジンギスカン用）","500g"],["もやし","1袋"],["玉ねぎ","1個"],["ピーマン","2個"],["かぼちゃ（お好みで）","1/8個"],["ラードか牛脂","1個"]],
   sauceT:[["ジンギスカンのたれ（市販）","適量"],["自家製なら：醤油","大さじ4"],["すりおろしりんご","大さじ2"],["砂糖","大さじ1"],["にんにく・生姜（すりおろし）","各小さじ1"]],
   steps:["玉ねぎは1cmの輪切り、ピーマンはざく切り、かぼちゃは薄切りにする。自家製だれの材料を混ぜる。","ジンギスカン鍋（中央が盛り上がった鉄鍋）かフライパンを熱し、脂を全体に塗って、鍋のてっぺんにのせる。","鍋の縁にもやし・玉ねぎ・ピーマン・かぼちゃを並べる。","中央の盛り上がった部分でラム肉を焼くと、脂が流れて周りの野菜が肉汁を吸う。","肉の色が変わったらたれにつけて食べ、野菜もしんなりしたら一緒に。"],
   tips:["北海道名物。専用鍋がベストだが、フライパンでもできる。","たれに漬けてから焼く「味付けジンギスカン」もあり、スーパーで買える。","ラムは火が通ったところがいちばんやわらかい。一度にのせすぎない。"]},
  "希腊烤羊腿":{serves:"4",time:"3.5時間",
   ingT:[["骨付きラム肉（もも・肩）","1kg"],["じゃがいも","4個"],["玉ねぎ","1個"],["にんにく","6かけ"],["レモン","1個"],["トマト（お好みで）","2個"],["フェタチーズ（お好みで）","100g"]],
   sauceT:[["オリーブオイル","大さじ4"],["オレガノ（乾燥）","大さじ1"],["塩","小さじ2"],["黒こしょう","小さじ1"],["クッキングシートとアルミホイル","各大1枚"]],
   steps:["ラムを大きめに切り、にんにくのみじん切り・レモン汁・オリーブオイル・オレガノ・塩・こしょうをもみ込み、1時間（または一晩）漬ける。","じゃがいもは皮をむいて大きめに切り、玉ねぎはくし形、トマトはざく切りに。","大きな天板にアルミホイル、その上にクッキングシートを敷き、じゃがいも・玉ねぎ・トマト・ラムをのせ、漬け汁をかけ、フェタをのせる。","シートとホイルを上で集めてしっかり閉じ、大きな袋のようにして蒸気を逃がさない。","160°Cのオーブンで3時間焼く。","包みを開け、220°Cに上げてさらに15分、表面に焼き色をつける。"],
   tips:["「クレフティコ」は「盗んだもの」の意味。山賊が肉を封じて地中で焼いたという言い伝えから。","しっかり包むほど、肉がやわらかくジューシーに。","ラムの脂とレモン汁を吸ったじゃがいもが絶品。"]}}},
 egg:{d:{
  "日式玉子烧":{serves:"2",time:"15分",
   ingT:[["卵","3個"],["大根おろし（添える用）","少々"]],
   sauceT:[["だし","大さじ3"],["砂糖","大さじ1（関東風の甘め）"],["薄口醤油","小さじ1/2"],["塩","ひとつまみ"],["サラダ油","適量"]],
   steps:["卵を溶きほぐし（箸で白身を切るように、泡立てない）、だし・砂糖・醤油・塩を混ぜる。","卵焼き器を中火で熱し、油をしみ込ませたキッチンペーパーで全体に油を塗る。","卵液の1/4を流して全体に広げ、表面が半熟になったら、箸で奥から手前へ巻く。","巻いた卵を奥に戻し、空いたところに油を塗って卵液の1/4を流す。巻いた卵の下にも卵液を流し込む。","半熟になったらまた奥から手前へ巻く。卵液がなくなるまでくり返す。","巻きすかアルミホイルで包んで3分置いて形を整え、切り分けて大根おろしと醤油を添える。"],
   tips:["火は強すぎないように。砂糖が多いと焦げやすい。","半熟のうちに巻くと、層がしっかりくっつく。","関西の「だし巻き卵」は砂糖を控えてだしを多くし、よりふんわり。"]},
  "韩式蒸蛋":{serves:"2",time:"15分",
   ingT:[["卵","3個"],["小ねぎ","1本"],["にんじんのみじん切り（お好みで）","少々"]],
   sauceT:[["水か煮干しだし","150ml"],["アミの塩辛か塩","小さじ1/2"],["ごま油","数滴"],["白ごま","少々"]],
   steps:["卵を溶き、アミの塩辛（または塩）を混ぜる。","小さな土鍋（トゥッペギ）に水かだしを入れ、中火で沸かす。","弱火にして卵液を流し入れ、スプーンで1分混ぜ続けて、半熟のとろとろにする。","小ねぎとにんじんを散らし、ふた（ボウルを逆さにしても）をしてごく弱火で3〜4分。","卵が鍋の縁からあふれるほどふくらんだら、ふたを取ってごま油をたらし、ごまをふって鍋ごと食卓へ。"],
   tips:["韓国焼肉店の付け合わせ。雲のようにふわふわ。","混ぜてからふたをして蒸らすと、ふくらむ。","土鍋がなければ小鍋で。焦げないようごく弱火に。"]},
  "西班牙土豆饼":{serves:"3〜4",time:"45分",
   ingT:[["卵","5個"],["じゃがいも","3個（約450g）"],["玉ねぎ","1個"]],
   sauceT:[["オリーブオイル","約150ml（じゃがいもを煮る用）"],["塩","小さじ1"]],
   steps:["じゃがいもは皮をむいて3mmの薄切り、玉ねぎは薄切りにする。","20cmのフライパンにたっぷりのオリーブオイルを入れ、じゃがいもと玉ねぎ、塩の半量を加え、弱火で15〜20分、色づけずにやわらかくなるまで煮る。","穴あきおたまで取り出して油をきる（油は取っておく）。","卵を溶いて残りの塩を加え、温かいじゃがいもと玉ねぎを入れて10分なじませる。","フライパンに油大さじ1を残して中火で卵液を流し、へらで縁を中央に寄せながら2〜3分、弱火にして5分焼く。","大きな皿をかぶせて返し、フライパンに滑らせて戻して裏面を3分焼く。切り分けて、温かくても冷めてもおいしい。"],
   tips:["じゃがいもは揚げるのではなく、弱火の油で「煮る」。","中心が少し半熟だといちばんジューシー。","返すときは耐熱手袋をして、手早く。"]}}}
});
window.ADD_I18N("en", {
 "chicken-thigh":{d:{
  "海南鸡饭":{serves:"3",time:"1 hour",
   ingT:[["Bone-in chicken legs","2 (about 600g)"],["Rice (jasmine if possible)","2 rice-cooker cups (360ml)"],["Ginger","1 large piece"],["Garlic","4 cloves"],["Scallions","3"],["Cucumber, tomato and cilantro","as needed"]],
   sauceT:[["Salt","1.5 tsp"],["Water","1.5 liters"],["Chicken fat or cooking oil","2 tbsp"],["Chili sauce","as needed"],["Dark or sweet soy sauce","as needed"],["Sesame oil","1 tsp"]],
   steps:["Rub the chicken with salt and rest 15 minutes. Boil the water with sliced ginger and scallions, add the chicken, bring back to a boil, then turn to the lowest heat, cover and poach 20 minutes without boiling.","Plunge the chicken into ice water for 10 minutes to firm the skin, then brush with sesame oil.","Wash and drain the rice. Fry minced garlic and ginger in the chicken fat, add the rice and fry 2 minutes until translucent.","Put the rice in a rice cooker, use the poaching broth instead of water, add a little salt and cook as normal.","Ginger sauce: mince ginger and scallion, add salt and pour hot oil over.","Slice the chicken onto the rice with cucumber, tomato and cilantro, and dip in chili sauce, ginger sauce and dark soy."],
   tips:["Gentle poaching keeps the chicken silky and juicy.","Cooking the rice in chicken broth is the soul of the dish. The rice can outshine the chicken.","A national favorite in Singapore and Malaysia."]}}},
 beef:{d:{
  "番茄炖牛腩":{n:"Chinese tomato beef brisket stew",h:"Blanched beef brisket simmered 1.5 hours with tomatoes, onion and ginger until the tomatoes become a thick sauce. Serve with rice or noodles.",serves:"3–4",time:"2 hours",
   ingT:[["Beef brisket or short rib","600g"],["Tomatoes","4 (about 600g)"],["Onion","1"],["Ginger","4 slices"],["Scallions","2"]],
   sauceT:[["Shaoxing or cooking wine","2 tbsp"],["Ketchup","2 tbsp"],["Light soy sauce","2 tbsp"],["Sugar","1 tbsp"],["Salt","1 tsp"],["Cooking oil","2 tbsp"],["Hot water","800ml"]],
   steps:["Cut the beef into 3cm pieces, put in cold water with 1 tbsp wine, bring to a boil, skim and boil 3 minutes. Rinse in warm water.","Cut 3 tomatoes into chunks and save 1 for the end. Cut the onion into chunks.","Fry the onion and ginger in oil for 2 minutes, add the 3 tomatoes and ketchup and cook over medium for 5 minutes until thick and red.","Add the beef, the rest of the wine, soy sauce, sugar and hot water. Bring to a boil, cover and simmer on low for 1.5 hours (30 minutes in a pressure cooker).","Add the last tomato and the salt and simmer 10 more minutes until thick. Sprinkle with scallions."],
   tips:["Add tomatoes in two stages: the first become sauce, the last keep some texture.","Start the beef in cold water so the blood and scum come out fully.","The sauce is great over noodles or rice."]},
  "小炒黄牛肉":{n:"Hunan stir-fried beef with chilies",h:"Thin beef slices coated in starch and soy, stir-fried fast over high heat with chilies, celery and cilantro. A Hunan dish.",serves:"2",time:"20 min",
   ingT:[["Beef (round or tenderloin, or thin slices)","250g"],["Bird's eye or green chilies","4–6"],["Celery stalk","1"],["Cilantro","2 sprigs"],["Garlic","4 cloves"],["Ginger","1 small piece"]],
   sauceT:[["Light soy sauce","1 tbsp"],["Oyster sauce","1 tsp"],["Cornstarch","1 tsp"],["Shaoxing or cooking wine","1 tsp"],["Salt","a little"],["Cooking oil","4 tbsp"]],
   steps:["Slice the beef thinly against the grain and mix with the soy sauce, oyster sauce, wine, starch and 1 tbsp oil. Rest 15 minutes.","Slice the chilies, cut the celery and cilantro into lengths, and mince the garlic and ginger.","Heat the wok until smoking, add 3 tbsp oil, spread the beef out and sear 20 seconds on high, then stir-fry quickly until mostly cooked. Remove.","In the remaining oil, fry the ginger, garlic and chilies for 30 seconds, add the celery for 30 seconds and salt lightly.","Return the beef, toss on high for 20 seconds, add the cilantro and serve."],
   tips:["Cutting against the grain keeps the beef tender.","A very hot wok gives smoky wok hei and stops the beef going watery.","Japanese 牛こま切れ (beef scraps) work as is."]},
  "寿喜烧":{serves:"3–4",time:"30 min",
   ingT:[["Thinly sliced sukiyaki beef","400g"],["Grilled tofu","1 block"],["Japanese leeks (negi)","2"],["Napa cabbage","1/8 head"],["Garland chrysanthemum","1 bunch"],["Shiitake","4"],["Shirataki noodles","1 pack"],["Raw-safe eggs","1 per person"]],
   sauceT:[["Soy sauce","100ml"],["Mirin","100ml"],["Sake","50ml"],["Sugar","3 tbsp"],["Beef suet or oil","1 piece"]],
   steps:["Bring the soy sauce, mirin, sake and sugar to a boil to make warishita (sukiyaki sauce).","Blanch the shirataki 2 minutes to remove the smell and cut into lengths. Cube the tofu, cut the leeks diagonally, cut the cabbage and chrysanthemum into pieces, and score the shiitake.","Heat a sukiyaki pan or heavy frying pan and rub it all over with the suet.","Start with a few slices of beef, sprinkle with a little sugar and add a splash of sauce. Eat while still pink, dipped in beaten raw egg (in Tokyo they simmer the vegetables first).","Arrange the leek, tofu, shirataki, shiitake and cabbage in the pan, add sauce halfway up and simmer over medium for 5 minutes.","Add beef and chrysanthemum and eat as things cook, dipping in beaten egg."],
   tips:["Eat the beef as soon as it changes color. It toughens if overcooked.","Add a little water or sake if the broth gets too salty.","Use Japanese raw-safe eggs. Finish with udon in the leftover broth."]},
  "韩式烤牛肉":{serves:"3",time:"20 min (plus 1 hour marinating)",
   ingT:[["Thinly sliced beef","400g"],["Onion","1"],["Carrot","1/3"],["Japanese leek (negi)","1/2"],["Shiitake (optional)","3"]],
   sauceT:[["Soy sauce","4 tbsp"],["Grated Asian pear or apple","3 tbsp"],["Sugar","1.5 tbsp"],["Grated garlic","1 tbsp"],["Sesame oil","1 tbsp"],["White sesame seeds","1 tsp"],["Black pepper","a little"]],
   steps:["Mix the soy sauce, pear, sugar, garlic, sesame oil, sesame seeds and pepper into a marinade.","Cut the beef 5cm wide, massage it into the marinade and refrigerate 1 hour (the pear tenderizes it).","Slice the onion and carrot thinly, cut the leek diagonally and slice the shiitake.","Heat a frying pan and fry the onion and carrot 1 minute, then add the beef and marinade.","Stir-fry on high for 3–4 minutes until the beef is cooked and the sauce reduces a little. Add the leek, toss and sprinkle with sesame."],
   tips:["Grated pear is the secret to tender bulgogi. Apple or pineapple also work.","Don't overcook or the beef dries out.","Wrap in lettuce or serve over rice."]},
  "红酒炖牛肉":{serves:"4",time:"3.5 hours",
   ingT:[["Beef chuck or shin (in a piece)","800g"],["Thick-cut bacon","100g"],["Onion","1"],["Carrot","1"],["Mushrooms","150g"],["Garlic","2 cloves"],["Pearl onions (optional)","8"]],
   sauceT:[["Red wine","500ml (2/3 bottle)"],["Beef stock","200ml"],["Tomato paste","1 tbsp"],["Flour","2 tbsp"],["Thyme and bay leaf","a little each"],["Butter","20g"],["Salt and black pepper","as needed"],["Olive oil","2 tbsp"]],
   steps:["Cut the beef into 5cm chunks, pat dry, season and dust with flour.","Heat the oil in a heavy pot, fry the bacon lardons until the fat renders and remove. Brown the beef in batches over high heat until deep brown on every side. Remove.","Cook the chopped onion, carrot and garlic for 5 minutes, add the tomato paste and cook 1 minute.","Return the beef and bacon, pour in the wine and scrape up the browned bits with a wooden spoon. Add the stock, thyme and bay.","Bring to a boil, cover and cook on the lowest heat (or in a 160°C oven) for 2.5–3 hours until the beef pulls apart with a fork.","Brown the mushrooms and pearl onions in butter in another pan, add to the pot, simmer 15 minutes and season with salt."],
   tips:["Don't crowd the pan. Browning every piece is where the flavor comes from.","No need for expensive wine. Any drinkable bottle is fine.","Even better reheated the next day. Serve with mashed potatoes or bread."]}}},
 lamb:{d:{
  "新疆羊肉串":{serves:"3–4",time:"30 min (plus 1 hour marinating)",
   ingT:[["Lamb shoulder or leg","500g"],["Lamb fat (optional)","50g"],["Onion","1/2"],["Bamboo skewers","15–20"]],
   sauceT:[["Cumin seeds","1 tbsp"],["Ground cumin","1 tbsp"],["Chili powder","1 tbsp"],["Salt","1 tsp"],["Cooking oil","1 tbsp"],["White sesame seeds (optional)","1 tsp"]],
   steps:["Soak the skewers in water for 30 minutes so they don't burn.","Cut the lamb into 2cm pieces and mix with the chopped onion, half the ground cumin, salt and oil. Refrigerate 1 hour.","Thread 4–5 pieces onto each skewer with a piece of fat in the middle.","Preheat the oven to 230°C, or use a grill or frying pan.","Cook on a rack for 6 minutes, turn, sprinkle with cumin seeds, ground cumin and chili, and cook 4–5 minutes more.","Sprinkle with a little more cumin and sesame and eat hot."],
   tips:["A piece of fat on each skewer keeps it juicy and fragrant.","In a frying pan, cook 3 minutes per side over medium and add the spices at the end.","Japanese ラム肩ロース (lamb shoulder) is ideal."]},
  "成吉思汗烤肉":{serves:"3",time:"30 min",
   ingT:[["Sliced lamb (shoulder or leg)","500g"],["Bean sprouts","1 bag"],["Onion","1"],["Green peppers","2"],["Kabocha squash (optional)","1/8"],["Lard or beef suet","1 piece"]],
   sauceT:[["Store-bought jingisukan sauce","as needed"],["Or homemade: soy sauce","4 tbsp"],["Grated apple","2 tbsp"],["Sugar","1 tbsp"],["Grated garlic and ginger","1 tsp each"]],
   steps:["Cut the onion into 1cm rings, the peppers into pieces and the squash into thin slices. Mix the homemade sauce.","Heat a jingisukan pan (a domed iron pan) or frying pan, rub it all over with fat and set the fat on top of the dome.","Arrange the sprouts, onion, peppers and squash around the rim.","Grill the lamb on the raised center. The fat runs down so the vegetables soak up the juices.","Dip the lamb in sauce as soon as it changes color, and eat the vegetables as they soften."],
   tips:["A Hokkaido specialty. A dedicated pan is best, but a frying pan works.","Pre-marinated lamb (味付けジンギスカン) is another style, sold ready-made in supermarkets.","Lamb is most tender just cooked. Don't overload the pan."]},
  "希腊烤羊腿":{serves:"4",time:"3.5 hours",
   ingT:[["Bone-in lamb leg or shoulder pieces","1kg"],["Potatoes","4"],["Onion","1"],["Garlic","6 cloves"],["Lemon","1"],["Tomatoes (optional)","2"],["Feta (optional)","100g"]],
   sauceT:[["Olive oil","4 tbsp"],["Dried oregano","1 tbsp"],["Salt","2 tsp"],["Black pepper","1 tsp"],["Parchment paper and foil","1 large sheet each"]],
   steps:["Cut the lamb into large pieces and rub with minced garlic, lemon juice, olive oil, oregano, salt and pepper. Marinate 1 hour (or overnight).","Peel and chunk the potatoes, cut the onion into wedges and chop the tomatoes.","Line a large baking dish with foil, then parchment. Add the potatoes, onion, tomatoes and lamb, pour over the marinade and add the feta.","Gather the parchment and foil up and seal tightly into a large parcel so no steam escapes.","Bake at 160°C for 3 hours.","Open the parcel, raise the oven to 220°C and roast 15 minutes more to brown."],
   tips:["Kleftiko means stolen. Legend says bandits sealed the meat and cooked it underground.","The tighter the seal, the softer and juicier the lamb.","The potatoes soak up the lamb fat and lemon and are delicious."]}}},
 egg:{d:{
  "日式玉子烧":{serves:"2",time:"15 min",
   ingT:[["Eggs","3"],["Grated daikon (to serve)","a little"]],
   sauceT:[["Dashi","3 tbsp"],["Sugar","1 tbsp (sweet Tokyo style)"],["Light (usukuchi) soy sauce","1/2 tsp"],["Salt","a pinch"],["Cooking oil","as needed"]],
   steps:["Beat the eggs by cutting through the whites with chopsticks (don't whip in air) and mix in the dashi, sugar, soy sauce and salt.","Heat a rectangular tamagoyaki pan over medium and wipe it with an oiled paper towel.","Pour in 1/4 of the egg to cover the pan. When the top is half set, roll it from the far end toward you with chopsticks.","Push the roll back to the far end, oil the empty space and pour in another 1/4, lifting the roll so egg flows underneath.","When half set, roll toward you again. Repeat until the egg is used up.","Wrap in a bamboo mat or foil for 3 minutes to set the shape, slice and serve with grated daikon and soy sauce."],
   tips:["Keep the heat moderate. The sugar burns easily.","Roll while still half set so the layers stick together.","Kansai-style dashimaki uses less sugar and more dashi for a softer roll."]},
  "韩式蒸蛋":{serves:"2",time:"15 min",
   ingT:[["Eggs","3"],["Scallion","1"],["Minced carrot (optional)","a little"]],
   sauceT:[["Water or anchovy stock","150ml"],["Salted shrimp or salt","1/2 tsp"],["Sesame oil","a few drops"],["White sesame seeds","a little"]],
   steps:["Beat the eggs with the salted shrimp (or salt).","Bring the water or stock to a boil in a small earthenware pot (ttukbaegi) over medium.","Turn to low, pour in the eggs and stir constantly with a spoon for 1 minute until it's a half-set custard.","Sprinkle with scallion and carrot, cover (an upturned bowl works) and cook on the lowest heat for 3–4 minutes.","When it puffs up over the rim, uncover, drizzle with sesame oil, sprinkle with sesame and serve in the pot."],
   tips:["A side dish at Korean barbecue restaurants, fluffy like a cloud.","Stirring first, then covering, is what makes it puff.","Without an earthenware pot, use a small saucepan on the lowest heat so it doesn't scorch."]},
  "西班牙土豆饼":{serves:"3–4",time:"45 min",
   ingT:[["Eggs","5"],["Potatoes","3 (about 450g)"],["Onion","1"]],
   sauceT:[["Olive oil","about 150ml (for the potatoes)"],["Salt","1 tsp"]],
   steps:["Peel the potatoes and slice 3mm thick. Slice the onion.","Put plenty of olive oil in a 20cm pan, add the potatoes, onion and half the salt, and cook gently for 15–20 minutes until soft but not colored.","Lift them out with a slotted spoon and drain (keep the oil).","Beat the eggs with the rest of the salt, add the warm potatoes and onion and let sit 10 minutes.","Leave 1 tbsp oil in the pan, pour in the egg over medium heat and pull the edges toward the center for 2–3 minutes, then cook on low for 5 minutes.","Cover with a large plate, flip, slide back into the pan and cook the other side 3 minutes. Slice and serve warm or cold."],
   tips:["The potatoes are poached in oil, not fried. Keep the heat low.","A slightly runny center is the juiciest.","Wear an oven mitt and flip quickly."]}}}
});
// 详细菜谱翻译 06
window.ADD_I18N("ja", {
 daikon:{d:{
  "萝卜丝饼":{serves:"8個",time:"50分",
   ingT:[["大根","1/2本（約500g）"],["中力粉（または薄力粉＋強力粉）","250g"],["ぬるま湯","約150ml"],["干しえび（小）","大さじ2"],["小ねぎ","3本"]],
   sauceT:[["塩","小さじ1.5（大根の塩もみに小さじ1）"],["白こしょう","少々"],["ごま油","大さじ1"],["サラダ油","大さじ3"]],
   steps:["粉にぬるま湯と塩少々を加えてなめらかでやわらかい生地にこね、ふたをして20分休ませる。","大根をせん切りにし、塩小さじ1を混ぜて10分置き、しっかり水気をしぼる。","大根に干しえび・小ねぎ・白こしょう・ごま油を混ぜてあんにする。","生地を8等分して丸くのばし、あんを大さじ山盛り1のせ、肉まんのように口を閉じ、閉じ目を下にして軽く押さえる。","フライパンに油をひき、中弱火で4分、底がきつね色になるまで焼き、返してさらに4分焼く。","両面きつね色で、真ん中がふくらんだら焼き上がり。"],
   tips:["大根はしっかりしぼる。水が出ると生地が破れる。","しぼった大根の汁は生地をこねるのに使える。","冷凍餃子の皮2枚であんをはさんで焼く手抜き版も。"]},
  "鰤鱼萝卜":{serves:"3",time:"60分",
   ingT:[["ぶりのあらか切り身","400g"],["大根","1/2本（約600g）"],["生姜","1かけ"]],
   sauceT:[["米のとぎ汁（または米大さじ1）","大根の下ゆで用"],["水","500ml"],["酒","100ml"],["砂糖","大さじ3"],["みりん","大さじ2"],["醤油","大さじ4"]],
   steps:["大根は厚めに皮をむき、3cm厚さの輪切りを半分に切って面取りする。米のとぎ汁（または米大さじ1を入れた水）で15分下ゆでし、洗う。","ぶりに塩をふって15分置き、熱湯をかけて白くなったら冷水で血やうろこを洗う。","鍋に大根・ぶり・生姜の薄切り・水・酒を入れ、煮立ったらアクを取る。","砂糖とみりんを加え、アルミホイルで落とし蓋をして中弱火で15分煮る。","醤油を加えてさらに15〜20分、大根があめ色になるまで煮る。","落とし蓋を取って煮詰め、煮汁をぶりと大根にかけ、針生姜をのせる。"],
   tips:["大根を下ゆでしておくと苦みが抜け、味がしみやすい。","冬のぶりは脂がのっていて、あらは安くてだしがよく出る。","一度冷まして温め直すと、大根にさらに味がしみる。"]},
  "萝卜块泡菜":{serves:"約1kg分",time:"40分（発酵1〜2日）",
   ingT:[["大根","1本（約1kg）"],["小ねぎかにら","1束"]],
   sauceT:[["粗塩","大さじ1.5"],["砂糖","大さじ1"],["韓国唐辛子粉","大さじ4"],["魚醤（ナンプラー可）","大さじ2"],["アミの塩辛（お好みで）","大さじ1"],["おろしにんにく","大さじ2"],["おろし生姜","小さじ1"]],
   steps:["大根の皮をむき、2cm角に切る。","塩と砂糖を混ぜて30分置くと水が出てしんなりするので、水を大部分捨てる（大さじ2残す）。","唐辛子粉を加えて混ぜ、先に大根を赤く染める。","魚醤・アミの塩辛・にんにく・生姜・ざく切りのねぎを加え、手袋をしてよく混ぜる。","清潔な保存容器に入れてぎゅっと押し込み、常温で1〜2日（冬は2日）発酵させてから冷蔵する。"],
   tips:["小さな泡が出て少し酸味が出たら食べごろ。","冷蔵で2〜3週間もち、だんだん酸っぱくなる。","クッパやフライドチキンによく合う。"]}}},
 hakusai:{d:{
  "醋溜白菜":{serves:"2",time:"15分",
   ingT:[["白菜の芯の部分","1/4株分（約400g）"],["鷹の爪","3本"],["にんにく","2かけ"]],
   sauceT:[["米酢か黒酢","大さじ2"],["砂糖","大さじ1"],["醤油","大さじ1"],["塩","少々"],["片栗粉","小さじ1＋水大さじ2"],["サラダ油","大さじ2"]],
   steps:["白菜の芯を包丁を45度に寝かせてそぎ切りにする（葉は使わない）。","酢・砂糖・醤油・塩・水溶き片栗粉を器で混ぜて合わせ調味料にする。","鍋をよく熱して油をひき、唐辛子とにんにくの薄切りを炒めて香りを出す。","白菜を入れ、強火で2分、縁が透き通るまで手早く炒める。","合わせ調味料を加え、30秒炒めてとろみとつやが出たら完成。"],
   tips:["斜めに薄く切ると味がからみやすく、シャキッとする。","最後まで強火で。水っぽくならない。","残った葉はスープや鍋に。"]},
  "辣白菜泡菜":{serves:"約2kg分",time:"1.5時間（塩漬け一晩・発酵2日）",
   ingT:[["白菜","1株（約2kg）"],["大根","1/4本"],["小ねぎかにら","1束"],["梨かりんご（お好みで）","1/2個"]],
   sauceT:[["粗塩","約150g（塩漬け用）"],["白玉粉かもち粉","大さじ2"],["水","200ml"],["韓国唐辛子粉","大さじ8"],["魚醤","大さじ4"],["アミの塩辛","大さじ2"],["おろしにんにく","大さじ3"],["おろし生姜","大さじ1"],["砂糖","大さじ1"]],
   steps:["白菜は根元に切り込みを入れて手で4つ割りにし（葉が切れないように）、葉の間に塩をふる（芯の部分は多めに）。6〜8時間か一晩置き、途中で一度返す。","白菜がしんなりして曲がるようになったら、3回洗って切り口を下にし、1時間水気をきる。","白玉粉を水で溶いて弱火でのり状に煮て冷ます。","のりに唐辛子粉・魚醤・アミの塩辛・にんにく・生姜・砂糖・すりおろした梨を混ぜ、大根のせん切りとねぎを加えてヤンニョムを作る。","手袋をして、ヤンニョムを白菜の葉の間に一枚ずつ塗り込み、最後に外側の葉で全体を包む。","保存容器にぎゅっと詰め、常温で1〜2日発酵させてから冷蔵。1週間後がいちばんおいしい。"],
   tips:["上級編。初めてなら1/2株から。","のりでヤンニョムが葉にくっつき、発酵も助ける。","冷蔵で1か月以上もつ。酸っぱくなったらキムチチゲやキムチチャーハンに。"]}}},
 nasu:{d:{
  "炸茄子浸高汤":{serves:"2〜3",time:"30分（冷やし1時間）",
   ingT:[["なす","3本"],["生姜","1かけ"],["小ねぎかみょうが","少々"]],
   sauceT:[["だし","200ml"],["醤油","大さじ2"],["みりん","大さじ2"],["揚げ油","鍋底から2cm"]],
   steps:["だし・醤油・みりんを煮立て、保存容器に入れて浸し地にする。","なすのへたを取って縦4つ割りにし、皮に斜めに細かく切り込みを入れる。","なすの水気をふき（ふかないと油がはねる）、油を170°Cに熱して皮を下にして2〜3分、やわらかくなるまで揚げる。","油をきり、熱いうちにすぐ浸し地につける。","冷めたら冷蔵庫で1時間以上冷やし、おろし生姜と小ねぎを添えて冷たいまま食べる。"],
   tips:["熱いうちにつけると、なすがたっぷり味を吸う。","皮から揚げると紫色がきれいに残る。","揚げたくなければ、多めの油で焼いてもよい。"]},
  "味噌烤茄子":{serves:"2",time:"25分",
   ingT:[["米なすか普通のなす","2本"],["白ごま","少々"]],
   sauceT:[["味噌（赤か白）","大さじ2"],["砂糖","大さじ1"],["みりん","大さじ1"],["酒","大さじ1"],["サラダ油","大さじ3"]],
   steps:["味噌・砂糖・みりん・酒を小鍋に入れ、弱火で2分、つやが出るまで練って甘味噌にする。","なすを縦半分に切り、切り口に格子状の切り込みを入れる（皮まで切らない）。","フライパンに油をひき、切り口を下にして中火で4分、返してふたをし4分焼いてやわらかくする。","切り口を上にして、甘味噌をたっぷり塗る。","オーブンか魚焼きグリルで2〜3分、味噌がふつふつと少し焦げるまで焼き、ごまをふる。"],
   tips:["切り込みを入れると早く火が通り、味もしみる。","なすは油をよく吸うので、切り口に油を塗ってから焼いても。","甘味噌は豆腐やこんにゃくに塗って焼いてもおいしい。"]},
  "西西里炖菜":{serves:"4",time:"50分",
   ingT:[["なす","3本"],["セロリ","1本"],["玉ねぎ","1個"],["トマト缶","1缶（400g）"],["グリーンオリーブ","10個"],["ケッパー","大さじ1"],["松の実（お好みで）","大さじ1"],["バジル","少々"]],
   sauceT:[["オリーブオイル","大さじ6"],["赤ワインビネガーか米酢","大さじ3"],["砂糖","大さじ1.5"],["塩","適量"]],
   steps:["なすを2cm角に切り、塩をふって20分置き、水気をしぼる。","鍋にオリーブオイル大さじ4を熱し、なすを中火で全面きつね色に焼いて取り出す。","残りの油で玉ねぎとセロリを5分、しんなりするまで炒める。","トマト缶を加えて10分煮る。","なすを戻し、オリーブ・ケッパー・ビネガー・砂糖を加えて弱火で10分、甘酸っぱさのバランスを見て塩で調える。","冷まして松の実とバジルを散らす。常温で食べるのがいちばん。"],
   tips:["甘酸っぱさがシチリア風。砂糖と酢はお好みで。","翌日のほうが味がなじむので、作り置きに。","パンに添えても、パスタソースにしても。"]}}},
 tomato:{d:{
  "番茄炒蛋":{serves:"2",time:"10分",
   ingT:[["トマト","2個（約300g）"],["卵","3個"],["小ねぎ","1本"]],
   sauceT:[["塩","小さじ1/2"],["砂糖","小さじ1〜2"],["サラダ油","大さじ3"],["ケチャップ（お好みで）","大さじ1"]],
   steps:["トマトをくし形に切る（皮をむくなら、上に十字の切り込みを入れて熱湯に30秒つけるとむける）。","卵に塩ひとつまみを加えて溶く。","鍋を熱して油大さじ2をひき、卵液を流し、縁がふくらんだらへらで大きく寄せ、八分通り固まったら取り出す。","油大さじ1を足してトマトを中火で2分炒め、へらで押して汁を出す。","塩・砂糖（とケチャップ）を加え、汁が少しとろりとしたら卵を戻して混ぜ、小ねぎを散らす。"],
   tips:["卵は半熟で一度取り出し、最後に戻すとふんわり。","日本のトマトは甘めなので砂糖は控えめに。赤みが足りなければケチャップを少し。","汁をご飯にかけるのがいちばんおいしいので、煮詰めすぎない。"]},
  "卡普里沙拉":{serves:"2",time:"10分",
   ingT:[["トマト（よく熟したもの）","2個"],["モッツァレラチーズ（フレッシュ）","1個（約100g）"],["バジルの葉","8枚"]],
   sauceT:[["エキストラバージンオリーブオイル","大さじ2"],["塩","少々"],["黒こしょう","少々"],["バルサミコ酢（お好みで）","小さじ1"]],
   steps:["トマトを7mm厚さの輪切りにし、モッツァレラも同じ厚さに切る。","皿にトマト・チーズ・バジルを交互に並べる。","塩と黒こしょうをふり、オリーブオイルをかける（お好みでバルサミコ酢も）。","すぐに食べる。"],
   tips:["材料がシンプルなので、トマトとオリーブオイルは良いものを。","塩は食べる直前に。トマトから水が出てしまう。","イタリア国旗の赤・白・緑の配色。"]},
  "墨西哥莎莎酱":{serves:"4",time:"15分",
   ingT:[["トマト","2個"],["紫玉ねぎ（玉ねぎでも）","1/4個"],["ハラペーニョか青唐辛子","1本"],["パクチー","1束"],["トルティーヤチップス（添える用）","1袋"]],
   sauceT:[["ライム果汁","大さじ2"],["塩","小さじ1/2"]],
   steps:["トマトの種を取り、5mm角に切る。","玉ねぎはみじん切りにし、5分水にさらして水気をきる（辛みが抜ける）。","唐辛子は種を取ってみじん切り、パクチーは刻む。","すべてをボウルに入れ、ライム果汁と塩で和え、10分置いて味をなじませる。","トルティーヤチップスに添えるか、タコスや焼いた肉にのせる。"],
   tips:["トマトの種を取ると水っぽくならない。","辛さは唐辛子の種で調整。","その日のうちに食べるのがいちばんフレッシュ。"]}}},
 jagaimo:{d:{
  "酸辣土豆丝":{serves:"2",time:"20分",
   ingT:[["じゃがいも（メークイン）","2個（約300g）"],["鷹の爪","4本"],["ピーマン（お好みで）","1/2個"],["にんにく","2かけ"]],
   sauceT:[["米酢か黒酢","大さじ1.5"],["塩","小さじ1/2"],["砂糖","少々"],["花椒（お好みで）","10粒"],["サラダ油","大さじ2"]],
   steps:["じゃがいもの皮をむき、薄切りにしてから重ねて細いせん切りにする（スライサーでも）。","水で2〜3回、水が澄むまで洗い、さらに5分水にさらして水気をきる。","鍋をよく熱して油をひき、弱火で花椒を炒めて香りが出たら取り出し、唐辛子とにんにくの薄切りを入れる。","最大の強火にしてじゃがいもを1分手早く炒め、ピーマンのせん切りを加える。","鍋肌から酢の半量を回し入れ、塩・砂糖を加えて30秒炒め、仕上げに残りの酢を加える。"],
   tips:["でんぷんを洗い流すのがシャキシャキのコツ。","炒めるのは2分以内。少し歯ごたえが残るくらいに。","メークインはでんぷんが少なく、男爵より炒め物向き。"]}}}
});
window.ADD_I18N("en", {
 daikon:{d:{
  "萝卜丝饼":{serves:"8 cakes",time:"50 min",
   ingT:[["Daikon","1/2 (about 500g)"],["All-purpose flour","250g"],["Warm water","about 150ml"],["Small dried shrimp","2 tbsp"],["Scallions","3"]],
   sauceT:[["Salt","1.5 tsp (1 tsp for the daikon)"],["White pepper","a little"],["Sesame oil","1 tbsp"],["Cooking oil","3 tbsp"]],
   steps:["Knead the flour with warm water and a pinch of salt into a smooth, soft dough. Cover and rest 20 minutes.","Grate the daikon into fine shreds, mix with 1 tsp salt, rest 10 minutes and squeeze out as much water as you can.","Mix the daikon with the dried shrimp, scallions, white pepper and sesame oil for the filling.","Divide the dough into 8, roll each into a round, add a heaped spoonful of filling, gather and pinch closed like a bun, then press flat seam side down.","Fry in oil over medium-low for 4 minutes until golden underneath, flip and fry 4 more minutes.","They're done when both sides are golden and the middle puffs up."],
   tips:["Squeeze the daikon well, or the filling turns watery and the dough tears.","Use the daikon juice to make the dough.","Shortcut: sandwich the filling between two frozen dumpling wrappers and pan-fry."]},
  "鰤鱼萝卜":{serves:"3",time:"60 min",
   ingT:[["Yellowtail trimmings or fillets","400g"],["Daikon","1/2 (about 600g)"],["Ginger","1 piece"]],
   sauceT:[["Rice-washing water (or 1 tbsp rice)","for pre-boiling the daikon"],["Water","500ml"],["Sake","100ml"],["Sugar","3 tbsp"],["Mirin","2 tbsp"],["Soy sauce","4 tbsp"]],
   steps:["Peel the daikon thickly, cut into 3cm rounds, halve them and bevel the edges. Boil 15 minutes in rice-washing water (or water with 1 tbsp rice) and rinse.","Salt the yellowtail, rest 15 minutes, pour boiling water over until white, then rinse off blood and scales in cold water.","Put the daikon, fish, sliced ginger, water and sake in a pot, bring to a boil and skim.","Add the sugar and mirin, cover with foil laid directly on top and simmer over medium-low for 15 minutes.","Add the soy sauce and simmer 15–20 more minutes until the daikon turns deep brown.","Uncover, reduce the sauce, spoon it over the fish and daikon and top with shredded ginger."],
   tips:["Pre-boiling the daikon removes bitterness and helps it absorb flavor.","Winter yellowtail is fattiest, and trimmings (ara) are cheap and flavorful.","Cool and reheat for even more flavorful daikon."]},
  "萝卜块泡菜":{serves:"About 1kg",time:"40 min (plus 1–2 days fermenting)",
   ingT:[["Daikon","1 (about 1kg)"],["Scallions or garlic chives","1 bunch"]],
   sauceT:[["Coarse salt","1.5 tbsp"],["Sugar","1 tbsp"],["Korean chili powder","4 tbsp"],["Fish sauce","2 tbsp"],["Salted shrimp (optional)","1 tbsp"],["Grated garlic","2 tbsp"],["Grated ginger","1 tsp"]],
   steps:["Peel the daikon and cut into 2cm cubes.","Toss with the salt and sugar and rest 30 minutes. It releases water and softens. Pour off most of the liquid, keeping 2 tbsp.","Add the chili powder and mix so the daikon turns red first.","Add the fish sauce, salted shrimp, garlic, ginger and cut scallions and mix well with gloved hands.","Pack tightly into a clean jar and ferment at room temperature for 1–2 days (2 in winter), then refrigerate."],
   tips:["It's ready when small bubbles appear and it tastes slightly sour.","Keeps 2–3 weeks in the fridge, getting more sour over time.","Great with Korean rice soups and fried chicken."]}}},
 hakusai:{d:{
  "醋溜白菜":{serves:"2",time:"15 min",
   ingT:[["Napa cabbage stems","from 1/4 head (about 400g)"],["Dried red chilies","3"],["Garlic","2 cloves"]],
   sauceT:[["Rice or black vinegar","2 tbsp"],["Sugar","1 tbsp"],["Light soy sauce","1 tbsp"],["Salt","a little"],["Cornstarch","1 tsp plus 2 tbsp water"],["Cooking oil","2 tbsp"]],
   steps:["Slice the cabbage stems thinly with the knife held at 45 degrees (don't use the leaves).","Mix the vinegar, sugar, soy sauce, salt and starch slurry in a bowl.","Heat the wok very hot, add oil and fry the chilies and sliced garlic until fragrant.","Add the cabbage and stir-fry on high for 2 minutes until the edges turn translucent.","Pour in the sauce and toss 30 seconds until thick and glossy."],
   tips:["Thin diagonal slices take on flavor and stay crunchy.","Keep the heat high throughout so it doesn't go watery.","Use the leftover leaves in soup or hot pot."]},
  "辣白菜泡菜":{serves:"About 2kg",time:"1.5 hours (plus overnight salting and 2 days fermenting)",
   ingT:[["Napa cabbage","1 head (about 2kg)"],["Daikon","1/4"],["Scallions or garlic chives","1 bunch"],["Asian pear or apple (optional)","1/2"]],
   sauceT:[["Coarse salt","about 150g (for salting)"],["Glutinous rice flour","2 tbsp"],["Water","200ml"],["Korean chili powder","8 tbsp"],["Fish sauce","4 tbsp"],["Salted shrimp","2 tbsp"],["Grated garlic","3 tbsp"],["Grated ginger","1 tbsp"],["Sugar","1 tbsp"]],
   steps:["Cut into the base and pull the cabbage apart by hand into quarters (so the leaves don't tear). Sprinkle salt between every leaf, more on the thick stems. Leave 6–8 hours or overnight, turning once.","When the cabbage is soft enough to bend, rinse 3 times and drain cut side down for 1 hour.","Cook the rice flour and water over low heat into a thin paste and cool.","Mix the paste with the chili powder, fish sauce, salted shrimp, garlic, ginger, sugar and grated pear, then add shredded daikon and cut scallions to make the paste.","With gloves on, spread the paste between every leaf, then wrap each quarter in its outer leaf.","Pack tightly into a container, ferment 1–2 days at room temperature, then refrigerate. It's best after a week."],
   tips:["An advanced recipe. Try half a head the first time.","The rice paste helps the seasoning cling and aids fermentation.","Keeps over a month in the fridge. Once sour, use it for kimchi stew or kimchi fried rice."]}}},
 nasu:{d:{
  "炸茄子浸高汤":{serves:"2–3",time:"30 min (plus 1 hour chilling)",
   ingT:[["Eggplants","3"],["Ginger","1 small piece"],["Scallion or myoga","a little"]],
   sauceT:[["Dashi","200ml"],["Soy sauce","2 tbsp"],["Mirin","2 tbsp"],["Oil for frying","2cm deep"]],
   steps:["Bring the dashi, soy sauce and mirin to a boil and pour into a container as the soaking liquid.","Remove the stems, quarter the eggplants lengthwise and score the skin finely on the diagonal.","Pat dry (or the oil will spatter). Fry skin side down at 170°C for 2–3 minutes until soft.","Drain and put straight into the liquid while hot.","Cool, refrigerate at least 1 hour, and serve cold with grated ginger and scallion."],
   tips:["Soaking while hot lets the eggplant absorb the most flavor.","Frying skin side first keeps the purple color bright.","If you'd rather not deep-fry, pan-fry in plenty of oil."]},
  "味噌烤茄子":{serves:"2",time:"25 min",
   ingT:[["Large round or regular eggplants","2"],["White sesame seeds","a little"]],
   sauceT:[["Miso (red or white)","2 tbsp"],["Sugar","1 tbsp"],["Mirin","1 tbsp"],["Sake","1 tbsp"],["Cooking oil","3 tbsp"]],
   steps:["Stir the miso, sugar, mirin and sake in a small pan over low heat for 2 minutes until glossy to make sweet miso.","Halve the eggplants lengthwise and score the cut side in a crosshatch (not through the skin).","Fry cut side down in oil over medium for 4 minutes, flip, cover and cook 4 minutes until soft.","Turn cut side up and spread with plenty of sweet miso.","Grill in the oven or fish grill for 2–3 minutes until the miso bubbles and chars a little. Sprinkle with sesame."],
   tips:["Scoring helps it cook faster and absorb flavor.","Eggplant soaks up oil, so you can brush the cut side with oil before frying instead.","Sweet miso is also great grilled on tofu or konnyaku."]},
  "西西里炖菜":{serves:"4",time:"50 min",
   ingT:[["Eggplants","3"],["Celery","1 stalk"],["Onion","1"],["Canned tomatoes","1 can (400g)"],["Green olives","10"],["Capers","1 tbsp"],["Pine nuts (optional)","1 tbsp"],["Basil","a little"]],
   sauceT:[["Olive oil","6 tbsp"],["Red wine or rice vinegar","3 tbsp"],["Sugar","1.5 tbsp"],["Salt","as needed"]],
   steps:["Cut the eggplant into 2cm cubes, salt and rest 20 minutes, then squeeze dry.","Heat 4 tbsp olive oil and brown the eggplant on all sides over medium. Remove.","Add the remaining oil and cook the onion and celery 5 minutes until soft.","Add the tomatoes and simmer 10 minutes.","Return the eggplant, add the olives, capers, vinegar and sugar, simmer on low 10 minutes, then balance the sweet and sour and salt to taste.","Cool and scatter with pine nuts and basil. Best at room temperature."],
   tips:["The sweet-sour taste is Sicilian. Adjust the sugar and vinegar to taste.","Even better the next day, so make it ahead.","Serve with bread or as a pasta sauce."]}}},
 tomato:{d:{
  "番茄炒蛋":{serves:"2",time:"10 min",
   ingT:[["Tomatoes","2 (about 300g)"],["Eggs","3"],["Scallion","1"]],
   sauceT:[["Salt","1/2 tsp"],["Sugar","1–2 tsp"],["Cooking oil","3 tbsp"],["Ketchup (optional)","1 tbsp"]],
   steps:["Cut the tomatoes into wedges (to peel, score an X on top and dip in boiling water for 30 seconds).","Beat the eggs with a pinch of salt.","Heat 2 tbsp oil, pour in the eggs, push them into large curds once the edges puff, and remove when about 80% set.","Add 1 tbsp oil and fry the tomatoes over medium for 2 minutes, pressing them to release juice.","Add salt, sugar (and ketchup). When the juice thickens a little, return the eggs, toss and sprinkle with scallion."],
   tips:["Take the eggs out half cooked and add them back at the end so they stay soft.","Japanese tomatoes are sweet, so use less sugar. Add a little ketchup if they aren't very red.","The juice is best over rice, so don't reduce it too far."]},
  "卡普里沙拉":{serves:"2",time:"10 min",
   ingT:[["Ripe tomatoes","2"],["Fresh mozzarella","1 ball (about 100g)"],["Basil leaves","8"]],
   sauceT:[["Extra virgin olive oil","2 tbsp"],["Salt","a little"],["Black pepper","a little"],["Balsamic vinegar (optional)","1 tsp"]],
   steps:["Slice the tomatoes 7mm thick and the mozzarella the same.","Alternate tomato, mozzarella and basil on a plate.","Season with salt and pepper and drizzle with olive oil (and a little balsamic if you like).","Eat right away."],
   tips:["With so few ingredients, use good tomatoes and olive oil.","Salt just before eating, or the tomatoes go watery.","Red, white and green, like the Italian flag."]},
  "墨西哥莎莎酱":{serves:"4",time:"15 min",
   ingT:[["Tomatoes","2"],["Red onion (or regular onion)","1/4"],["Jalapeño or green chili","1"],["Cilantro","1 bunch"],["Tortilla chips (to serve)","1 bag"]],
   sauceT:[["Lime juice","2 tbsp"],["Salt","1/2 tsp"]],
   steps:["Seed the tomatoes and cut into 5mm dice.","Finely chop the onion, soak in water 5 minutes and drain to tame the bite.","Seed and finely chop the chili, and chop the cilantro.","Mix everything with the lime juice and salt and rest 10 minutes.","Serve with tortilla chips or spoon over tacos and grilled meat."],
   tips:["Seeding the tomatoes keeps it from getting watery.","Adjust the heat with the chili seeds.","Freshest eaten the same day."]}}},
 jagaimo:{d:{
  "酸辣土豆丝":{serves:"2",time:"20 min",
   ingT:[["Potatoes (waxy, like May Queen)","2 (about 300g)"],["Dried red chilies","4"],["Green pepper (optional)","1/2"],["Garlic","2 cloves"]],
   sauceT:[["Rice or black vinegar","1.5 tbsp"],["Salt","1/2 tsp"],["Sugar","a pinch"],["Sichuan peppercorns (optional)","10"],["Cooking oil","2 tbsp"]],
   steps:["Peel the potatoes, slice thinly, then stack and cut into fine matchsticks (or use a julienne grater).","Rinse 2–3 times until the water runs clear, soak 5 more minutes and drain.","Heat the wok very hot, add oil, fry the peppercorns on low until fragrant and remove them, then add the chilies and sliced garlic.","Turn to maximum heat, add the potatoes and stir-fry 1 minute, then add the sliced pepper.","Drizzle half the vinegar around the edge, add salt and sugar, toss 30 seconds, and add the rest of the vinegar just before serving."],
   tips:["Rinsing off the starch is the key to crunch.","Cook under 2 minutes so the potatoes stay a little crisp.","Waxy メークイン has less starch than floury 男爵 and is better for stir-frying."]}}}
});
