window.ADD_I18N("ja", {
 jagaimo:{d:{
  "可乐饼":{serves:"8個",time:"1時間",
   ingT:[["じゃがいも（男爵）","4個（約500g）"],["合いびき肉","150g"],["玉ねぎ","1/2個"],["キャベツの千切り（添える用）","適量"]],
   sauceT:[["塩・こしょう","少々"],["砂糖","小さじ1"],["醤油","小さじ1"],["小麦粉","大さじ4"],["卵","1個"],["パン粉","2カップ"],["揚げ油","鍋底から3cm"],["とんかつソース","適量"]],
   steps:["じゃがいもは皮をむいて切り、15分ゆでてやわらかくし、湯を捨てて弱火で水分を飛ばし、つぶす。","玉ねぎをみじん切りにしてひき肉と炒め、塩・こしょう・砂糖・醤油で味をつける。","炒めた肉をじゃがいもに混ぜて8等分し、小判形にまとめて冷ます（熱いと形がくずれやすい）。","小麦粉、溶き卵、パン粉の順に衣をつける。","油を180°Cに熱し、2〜3分きつね色に揚げる（中は火が通っているので衣を揚げるだけ）。","キャベツを添え、とんかつソースをかける。"],
   tips:["じゃがいもは冷ましてから衣をつけないと、揚げるときに破裂する。","高温で短時間に揚げる。","冷凍もできる。パン粉までつけて冷凍し、凍ったまま4分揚げる。"]},
  "法式焗土豆":{serves:"4",time:"1.5時間",
   ingT:[["じゃがいも（メークイン）","4個（約600g）"],["にんにく","1かけ"],["グリュイエールかピザ用チーズ（お好みで）","50g"]],
   sauceT:[["生クリーム","200ml"],["牛乳","200ml"],["塩","小さじ1"],["黒こしょう","少々"],["ナツメグ","少々"],["バター","10g"]],
   steps:["グラタン皿の内側を切ったにんにくでこすり、バターを塗る。","じゃがいもの皮をむき、2〜3mmの薄切りにする（水にさらさない。でんぷんでソースにとろみがつく）。","鍋に生クリーム・牛乳・にんにくのみじん切り・塩・こしょう・ナツメグを入れ、沸騰直前まで温める。","じゃがいもを皿に重ねて並べ、熱いクリームを注ぐ。","160°Cのオーブンで1時間、竹串がすっと通るまで焼く。最後にチーズをのせ、200°Cで10分焼いて焼き色をつける。","取り出して10分置いてから切り分ける。"],
   tips:["本来のドーフィネ風はチーズなし。チーズを入れると日本の「グラタン」に近くなる。","薄く均一に切ると、むらなく火が通る。","ローストやステーキの付け合わせにぴったり。"]}}},
 horenso:{d:{
  "蒜蓉炒菠菜":{n:"ほうれん草のにんにく炒め",h:"ほうれん草を10秒下ゆでしてえぐみを取り、強火でにんにくを香らせて手早く炒め、塩で仕上げる。",serves:"2",time:"10分",
   ingT:[["ほうれん草","1束（約250g）"],["にんにく","4かけ"]],
   sauceT:[["サラダ油","大さじ2"],["塩","小さじ1/2"],["砂糖（お好みで）","少々"]],
   steps:["ほうれん草を洗い、6cm長さに切る。根元の赤い部分は甘いので残す。","湯を沸かしてほうれん草を10秒ゆで、ざるにあげて水気をきる（えぐみとシュウ酸が抜ける）。","にんにくをみじん切りにする。鍋を熱して油をひき、弱火でにんにくをうっすら色づくまで炒めて香りを出す。","強火にしてほうれん草を入れ、30秒手早く炒め、塩と砂糖で味をつけて完成。"],
   tips:["日本のほうれん草はえぐみが強めなので、さっとゆでるとおいしい。","強火で手早く炒めると、色鮮やかで水っぽくならない。","にんにくは多めのほうが香りがいい。"]},
  "菠菜拌粉丝":{n:"ほうれん草と春雨の和え物",h:"ほうれん草と春雨をそれぞれゆで、にんにく・酢・醤油・ごま油・ラー油で和える中国北方の冷菜。",serves:"2〜3",time:"15分",
   ingT:[["ほうれん草","1束（約250g）"],["緑豆春雨","1束（約40g）"],["にんにく","3かけ"],["にんじんのせん切り（お好みで）","少々"]],
   sauceT:[["米酢か黒酢","大さじ1.5"],["醤油","大さじ1"],["砂糖","小さじ1"],["塩","少々"],["ごま油","小さじ1"],["ラー油（お好みで）","小さじ1"]],
   steps:["春雨を熱湯で3分、透き通るまでゆで、冷水にとって食べやすく切る。","同じ湯でほうれん草を30秒ゆで、冷水にとってしぼり、ざく切りにする。にんじんもさっとゆでる。","にんにくをみじん切りにし、酢・醤油・砂糖・塩・ごま油・ラー油と混ぜてたれにする。","ほうれん草・春雨・にんじんをボウルに入れ、たれで和える。"],
   tips:["ほうれん草はしっかりしぼらないと、たれが薄まる。","中国北方の家庭の冷菜。砕いたピーナッツを加えても香ばしい。","冷蔵庫で10分置くと味がなじむ。"]},
  "凉拌菠菜":{serves:"2",time:"10分",
   ingT:[["ほうれん草","1束（約200g）"],["かつお節","1袋"]],
   sauceT:[["だし","大さじ3"],["醤油","大さじ1"],["みりん（お好みで）","小さじ1"]],
   steps:["だし・醤油・みりんを混ぜる（みりんは電子レンジで20秒加熱してアルコールを飛ばすとよい）。","湯を沸かして塩少々を入れ、ほうれん草を根元から入れて10秒、全体を沈めて30秒ゆでる。","すぐに冷水にとり、冷めたら根元をそろえて手で水気をしぼる。","4cm長さに切り、もう一度軽くしぼって、浸し地に10分つける。","器に盛り、浸し地を少しかけてかつお節をのせる。"],
   tips:["ゆでたらすぐ冷水にとると、色が鮮やかに。","しっかりしぼると味が薄まらない。","日本でいちばん身近な副菜のひとつ。"]},
  "韩式菠菜":{serves:"2",time:"10分",
   ingT:[["ほうれん草","1束（約200g）"],["にんにく","1かけ"],["小ねぎ（お好みで）","1本"]],
   sauceT:[["塩","小さじ1/3"],["薄口醤油（お好みで）","小さじ1/2"],["ごま油","大さじ1"],["白ごま","大さじ1"]],
   steps:["ほうれん草を洗い、塩を入れた湯で30秒ゆでて冷水にとり、しぼって5cm長さに切る。","にんにくはすりおろし、ねぎはみじん切りにする。","ほうれん草をボウルに入れ、塩・醤油・にんにく・ねぎを加えて手で和える。","ごま油とごま（指でひねりつぶすと香りが立つ）を加えて、さらに和える。"],
   tips:["韓国の家庭のナムル。手で和えると味がよくなじむ。","ごまはたっぷりと。","冷蔵で2日もつ。ビビンバの具にも。"]},
  "奶油菠菜":{serves:"2〜3",time:"15分",
   ingT:[["ほうれん草","2束（約400g）"],["玉ねぎ","1/4個"],["にんにく","1かけ"],["粉チーズ","大さじ2"]],
   sauceT:[["バター","20g"],["生クリーム","100ml"],["塩・こしょう","少々"],["ナツメグ","少々"]],
   steps:["ほうれん草を30秒ゆでて冷水にとり、しぼって刻む。","鍋にバターを入れ、弱火で玉ねぎとにんにくのみじん切りを3分、しんなりするまで炒める。","ほうれん草を加えて1分炒め、生クリームを注いで中火で3〜4分、とろりとするまで煮る。","粉チーズ・塩・こしょう・ナツメグを加えて混ぜる。"],
   tips:["アメリカのステーキハウスの定番の付け合わせ。","クリームを少し煮詰めると口当たりがよくなる。","冷凍ほうれん草でも。解凍してしぼってから使う。"]}}},
 kabocha:{d:{
  "咸蛋黄焗南瓜":{serves:"2〜3",time:"30分",
   ingT:[["かぼちゃ","1/4個（約400g）"],["塩卵の黄身（中華食材店）","4個"],["小ねぎ（お好みで）","1本"]],
   sauceT:[["片栗粉","大さじ3"],["揚げ油","鍋底から2cm"],["バター（お好みで）","10g"],["砂糖","小さじ1"]],
   steps:["かぼちゃの種を取り、1cm角の棒状に切る（皮付きでよい）。","塩卵の黄身を器に入れて8分蒸し、スプーンでつぶして粉状にする。","かぼちゃに水を少しふってから片栗粉をまぶし、余分な粉を落とす。","油を170°Cに熱し、かぼちゃを3〜4分、外はカリッと、箸が通るまで揚げて油をきる。","鍋に油大さじ1を残し（バターを加えても）、弱火で黄身を入れ、細かい泡が立ってさらさらになるまで炒め続ける。","かぼちゃと砂糖を加え、手早く混ぜて全体に黄身をからめる。"],
   tips:["塩卵の黄身は中華食材店で。塩漬けのあひるの卵から黄身だけ使ってもよい。","黄身は弱火で炒め、細かい泡がたくさん出たらOK。","揚げたくなければ200°Cのオーブンで15分焼いても。"]},
  "泰式椰奶南瓜":{serves:"3〜4",time:"25分",
   ingT:[["かぼちゃ","1/4個（約400g）"]],
   sauceT:[["ココナッツミルク","1缶（400ml）"],["パームシュガーか三温糖","60g"],["塩","小さじ1/3"],["水","100ml"]],
   steps:["かぼちゃの種を取り、硬い皮を一部そいで2cm角に切る。","鍋にココナッツミルク（仕上げ用に大さじ3残す）・水・砂糖・塩を入れ、中火で砂糖を溶かす。","かぼちゃを入れて煮立ったら弱火にし、10〜12分、箸が通るまで煮る。","器に盛り、残しておいたココナッツミルクをかける。温かくても冷たくても。"],
   tips:["ほんの少しの塩で甘さが引き立つ。省かないで。","煮すぎるとかぼちゃがくずれる。","タイの伝統的なデザート。里いもやバナナでも作れる。"]},
  "南瓜派":{serves:"8切れ",time:"1.5時間",
   ingT:[["かぼちゃ","1/4個（皮をむいて約300g）"],["冷凍パイシート","1枚"],["卵","2個"]],
   sauceT:[["加糖練乳","150g"],["三温糖","大さじ2"],["シナモン","小さじ1"],["ジンジャーパウダー","小さじ1/2"],["ナツメグ","少々"],["塩","ひとつまみ"],["生クリーム（ホイップ、お好みで）","適量"]],
   steps:["かぼちゃの皮をむいて切り、15分蒸してやわらかくし、なめらかにつぶす（裏ごしするとさらになめらか）。","パイシートを20cmのパイ皿に敷き、フォークで穴をあけて冷蔵庫で冷やしておく。","かぼちゃに卵・練乳・三温糖・スパイス・塩を加え、なめらかになるまで混ぜる。","パイ皮に流し入れ、表面をならす。","200°Cのオーブンで15分、170°Cに下げて35〜40分、軽くゆすっても中心が揺れなくなるまで焼く。","完全に冷まして冷蔵庫で2時間冷やし、切り分けてホイップクリームを添える。"],
   tips:["日本のかぼちゃはアメリカのものより甘くほくほくなので、砂糖は控えめに。","冷まして冷やしてから切ると、きれいに切れる。","感謝祭の定番デザート。"]}}},
 renkon:{d:{
  "糯米藕":{serves:"4",time:"2.5時間（米の浸水2時間）",
   ingT:[["れんこん（太いもの）","1節（約400g）"],["もち米","100g"],["なつめ","8個"],["つまようじ","4本"]],
   sauceT:[["黒糖か三温糖","80g"],["氷砂糖","30g"],["桂花醤かはちみつ","大さじ2"],["水","れんこんがかぶる量"]],
   steps:["もち米を洗って2時間水につけ、水気をきる。","れんこんの皮をむき、片端から2cmのところを切ってふたにする。","切り口からもち米を穴に詰め、箸で押し込みながら八分目まで詰める。","切ったふたをかぶせ、つまようじで留める。","鍋に入れてかぶるくらいの水を注ぎ、なつめ・黒糖・氷砂糖を加え、強火で煮立てて弱火で2時間、途中で何度か返す。","取り出して冷まし、1cm厚さに切って、鍋の糖液と桂花醤をかける。"],
   tips:["もち米は煮るとふくらむので、詰めすぎない。","電気圧力鍋なら40分加圧でも。","冷やしてから切るときれいに切れる。冷たくてもおいしい。"]},
  "莲藕排骨汤":{serves:"3〜4",time:"2時間",
   ingT:[["豚スペアリブ","500g"],["れんこん","1節（約400g）"],["生姜","薄切り4枚"],["なつめ（お好みで）","4個"],["小ねぎ","1本"]],
   sauceT:[["料理酒","大さじ1"],["塩","小さじ1"],["白こしょう","少々"],["水","2L"]],
   steps:["スペアリブを水から入れて料理酒を加え、沸騰したらアクを取って2分ゆで、ぬるま湯で洗う。","れんこんの皮をむいて乱切りにし、変色しないよう水につける。","鍋に水・スペアリブ・生姜を入れ、強火で煮立てて弱火で40分煮る。","れんこんとなつめを加え、さらに弱火で1時間、れんこんがほっくりするまで煮る。","塩と白こしょうで味をととのえ、小ねぎを散らす。"],
   tips:["塩は最後に。肉がやわらかく煮える。","ほっくりさせたいなら太く短いれんこん、シャキッとさせたいなら細長いものを。","電気圧力鍋なら30分加圧で十分。"]}}}
});
window.ADD_I18N("en", {
 jagaimo:{d:{
  "可乐饼":{serves:"8 croquettes",time:"1 hour",
   ingT:[["Floury potatoes","4 (about 500g)"],["Mixed ground pork and beef","150g"],["Onion","1/2"],["Shredded cabbage (to serve)","as needed"]],
   sauceT:[["Salt and pepper","a little"],["Sugar","1 tsp"],["Soy sauce","1 tsp"],["Flour","4 tbsp"],["Egg","1"],["Panko","2 cups"],["Oil for frying","3cm deep"],["Tonkatsu sauce","as needed"]],
   steps:["Peel and cut the potatoes, boil 15 minutes until soft, drain, dry them out over low heat and mash.","Chop the onion and fry with the ground meat until cooked. Season with salt, pepper, sugar and soy sauce.","Mix the meat into the potatoes, divide into 8 and shape into ovals. Let cool (warm mash is hard to shape).","Coat in flour, beaten egg and panko.","Fry at 180°C for 2–3 minutes until golden (the filling is already cooked, so you're just crisping the coating).","Serve with shredded cabbage and tonkatsu sauce."],
   tips:["Cool the mash before coating, or the croquettes burst in the oil.","Fry hot and fast.","They freeze well: freeze after crumbing and fry from frozen for 4 minutes."]},
  "法式焗土豆":{serves:"4",time:"1.5 hours",
   ingT:[["Waxy potatoes","4 (about 600g)"],["Garlic","1 clove"],["Gruyère or pizza cheese (optional)","50g"]],
   sauceT:[["Heavy cream","200ml"],["Milk","200ml"],["Salt","1 tsp"],["Black pepper","a little"],["Nutmeg","a pinch"],["Butter","10g"]],
   steps:["Rub the inside of a baking dish with a cut garlic clove, then butter it.","Peel the potatoes and slice 2–3mm thick (don't soak them; the starch thickens the sauce).","Heat the cream, milk, minced garlic, salt, pepper and nutmeg until almost boiling.","Layer the potatoes in the dish and pour over the hot cream.","Bake at 160°C for 1 hour until a skewer slides in easily. Top with cheese and bake at 200°C for 10 minutes to brown.","Rest 10 minutes before cutting."],
   tips:["Classic gratin dauphinois has no cheese. With cheese it's closer to a Japanese gratin.","Thin, even slices cook evenly.","Great alongside roasts or steak."]}}},
 horenso:{d:{
  "蒜蓉炒菠菜":{n:"Garlic stir-fried spinach",h:"Blanch spinach for 10 seconds to remove bitterness, then stir-fry fast over high heat with fragrant garlic and finish with salt.",serves:"2",time:"10 min",
   ingT:[["Spinach","1 bunch (about 250g)"],["Garlic","4 cloves"]],
   sauceT:[["Cooking oil","2 tbsp"],["Salt","1/2 tsp"],["Sugar (optional)","a pinch"]],
   steps:["Wash the spinach and cut into 6cm lengths. Keep the red root ends, which are sweet.","Blanch the spinach in boiling water for 10 seconds and drain (this removes bitterness and oxalic acid).","Mince the garlic. Heat oil and fry the garlic over low heat until pale gold and fragrant.","Turn to high, add the spinach and stir-fry 30 seconds. Season with salt and sugar and serve."],
   tips:["Japanese spinach is fairly astringent, so a quick blanch helps.","High heat and speed keep it bright green and not watery.","More garlic means more flavor."]},
  "菠菜拌粉丝":{n:"Spinach and glass noodle salad",h:"Blanched spinach and glass noodles tossed with garlic, vinegar, soy sauce, sesame oil and chili oil. A northern Chinese cold dish.",serves:"2–3",time:"15 min",
   ingT:[["Spinach","1 bunch (about 250g)"],["Mung bean vermicelli","1 small bundle (about 40g)"],["Garlic","3 cloves"],["Shredded carrot (optional)","a little"]],
   sauceT:[["Rice or black vinegar","1.5 tbsp"],["Light soy sauce","1 tbsp"],["Sugar","1 tsp"],["Salt","a little"],["Sesame oil","1 tsp"],["Chili oil (optional)","1 tsp"]],
   steps:["Boil the noodles 3 minutes until clear, cool in cold water and cut into lengths.","In the same water, blanch the spinach 30 seconds, cool, squeeze dry and cut. Blanch the carrot briefly too.","Mince the garlic and mix with the vinegar, soy sauce, sugar, salt, sesame oil and chili oil.","Toss the spinach, noodles and carrot with the dressing."],
   tips:["Squeeze the spinach well so it doesn't dilute the dressing.","A home-style cold dish from northern China. Crushed peanuts add crunch.","Chill 10 minutes to let the flavors meld."]},
  "凉拌菠菜":{serves:"2",time:"10 min",
   ingT:[["Spinach","1 bunch (about 200g)"],["Bonito flakes","1 small packet"]],
   sauceT:[["Dashi","3 tbsp"],["Soy sauce","1 tbsp"],["Mirin (optional)","1 tsp"]],
   steps:["Mix the dashi, soy sauce and mirin (microwave the mirin 20 seconds first to cook off the alcohol).","Bring salted water to a boil. Dip the spinach roots in for 10 seconds, then submerge the whole bunch for 30 seconds.","Plunge into cold water. Once cool, line up the stems and squeeze out the water by hand.","Cut into 4cm lengths, squeeze lightly again and soak in the dashi mixture for 10 minutes.","Plate, spoon over a little of the liquid and top with bonito flakes."],
   tips:["Cooling right away keeps the color bright.","Squeeze well so the flavor isn't diluted.","One of the most everyday side dishes in Japan."]},
  "韩式菠菜":{serves:"2",time:"10 min",
   ingT:[["Spinach","1 bunch (about 200g)"],["Garlic","1 clove"],["Scallion (optional)","1"]],
   sauceT:[["Salt","1/3 tsp"],["Soup soy sauce (optional)","1/2 tsp"],["Sesame oil","1 tbsp"],["White sesame seeds","1 tbsp"]],
   steps:["Wash the spinach, blanch in salted boiling water for 30 seconds, cool in cold water, squeeze dry and cut into 5cm lengths.","Grate the garlic and chop the scallion.","Put the spinach in a bowl with the salt, soy sauce, garlic and scallion and mix by hand.","Add the sesame oil and sesame seeds (crush them between your fingers for more aroma) and mix again."],
   tips:["A Korean namul. Mixing by hand works the seasoning in best.","Be generous with the sesame.","Keeps 2 days in the fridge and works as a bibimbap topping."]},
  "奶油菠菜":{serves:"2–3",time:"15 min",
   ingT:[["Spinach","2 bunches (about 400g)"],["Onion","1/4"],["Garlic","1 clove"],["Grated Parmesan","2 tbsp"]],
   sauceT:[["Butter","20g"],["Heavy cream","100ml"],["Salt and black pepper","a little"],["Nutmeg","a pinch"]],
   steps:["Blanch the spinach 30 seconds, cool, squeeze dry and chop.","Melt the butter and cook the minced onion and garlic on low for 3 minutes until soft.","Add the spinach for 1 minute, pour in the cream and simmer over medium for 3–4 minutes until thick.","Stir in the Parmesan, salt, pepper and nutmeg."],
   tips:["A classic American steakhouse side.","Reduce the cream a little for a better texture.","Frozen spinach works. Thaw and squeeze it first."]}}},
 kabocha:{d:{
  "咸蛋黄焗南瓜":{serves:"2–3",time:"30 min",
   ingT:[["Kabocha squash","1/4 (about 400g)"],["Salted egg yolks","4"],["Scallion (optional)","1"]],
   sauceT:[["Potato starch","3 tbsp"],["Oil for frying","2cm deep"],["Butter (optional)","10g"],["Sugar","1 tsp"]],
   steps:["Seed the squash and cut into 1cm-thick sticks (skin on is fine).","Steam the salted yolks for 8 minutes and mash into crumbs with a spoon.","Sprinkle the squash with a little water, coat in starch and shake off the excess.","Fry at 170°C for 3–4 minutes until crisp outside and tender enough for a chopstick. Drain.","Leave 1 tbsp oil in the wok (or add butter), add the yolk crumbs over low heat and stir constantly until foamy and sandy.","Add the squash and sugar and toss quickly so every piece is coated."],
   tips:["Salted yolks are sold at Chinese grocers, or use just the yolks of salted duck eggs.","Cook the yolks over low heat. Lots of small bubbles means they're ready.","To skip frying, roast the squash at 200°C for 15 minutes."]},
  "泰式椰奶南瓜":{serves:"3–4",time:"25 min",
   ingT:[["Kabocha squash","1/4 (about 400g)"]],
   sauceT:[["Coconut milk","1 can (400ml)"],["Palm or brown sugar","60g"],["Salt","1/3 tsp"],["Water","100ml"]],
   steps:["Seed the squash, shave off some of the hard skin and cut into 2cm pieces.","Heat the coconut milk (keep 3 tbsp for topping), water, sugar and salt over medium until the sugar dissolves.","Add the squash, bring to a boil, then simmer on low for 10–12 minutes until a chopstick goes in.","Spoon into bowls and drizzle with the reserved coconut milk. Eat warm or cold."],
   tips:["A little salt brings out the sweetness. Don't skip it.","Don't overcook or the squash falls apart.","A traditional Thai dessert. Taro or banana work too."]},
  "南瓜派":{serves:"8 slices",time:"1.5 hours",
   ingT:[["Kabocha squash","1/4 (about 300g peeled)"],["Frozen pie crust or puff pastry","1 sheet"],["Eggs","2"]],
   sauceT:[["Sweetened condensed milk","150g"],["Brown sugar","2 tbsp"],["Cinnamon","1 tsp"],["Ground ginger","1/2 tsp"],["Nutmeg","a pinch"],["Salt","a pinch"],["Whipped cream (optional)","as needed"]],
   steps:["Peel and cut the squash, steam 15 minutes until soft and mash very smoothly (sieve it for an even silkier filling).","Line a 20cm pie dish with the pastry, prick with a fork and chill.","Beat the squash with the eggs, condensed milk, sugar, spices and salt until smooth.","Pour into the crust and smooth the top.","Bake at 200°C for 15 minutes, then 170°C for 35–40 minutes until the center no longer wobbles.","Cool completely, chill 2 hours, slice and serve with whipped cream."],
   tips:["Japanese kabocha is sweeter and denser than American pumpkin, so use less sugar.","Chill before slicing for clean cuts.","A Thanksgiving classic."]}}},
 renkon:{d:{
  "糯米藕":{serves:"4",time:"2.5 hours (plus 2 hours soaking)",
   ingT:[["Thick lotus root","1 segment (about 400g)"],["Glutinous rice","100g"],["Jujubes (red dates)","8"],["Toothpicks","4"]],
   sauceT:[["Brown sugar","80g"],["Rock sugar","30g"],["Osmanthus syrup or honey","2 tbsp"],["Water","to cover"]],
   steps:["Wash the glutinous rice, soak 2 hours and drain.","Peel the lotus root and cut a 2cm slice off one end to use as a lid.","Stuff the rice into the holes from the cut end, packing it with a chopstick until about 80% full.","Put the lid back and secure with toothpicks.","Put in a pot with water to cover, add the jujubes, brown sugar and rock sugar. Boil, then simmer on low for 2 hours, turning a few times.","Cool, slice 1cm thick and drizzle with some of the syrup and osmanthus."],
   tips:["Don't overfill. The rice swells as it cooks.","An electric pressure cooker takes about 40 minutes.","Chill before slicing for neat rounds. It's good cold too."]},
  "莲藕排骨汤":{serves:"3–4",time:"2 hours",
   ingT:[["Pork spare ribs","500g"],["Lotus root","1 segment (about 400g)"],["Ginger","4 slices"],["Jujubes (optional)","4"],["Scallion","1"]],
   sauceT:[["Shaoxing or cooking wine","1 tbsp"],["Salt","1 tsp"],["White pepper","a little"],["Water","2 liters"]],
   steps:["Put the ribs in cold water with the wine, bring to a boil, skim, boil 2 minutes and rinse in warm water.","Peel the lotus root, cut into chunks and keep in water so it doesn't darken.","Put the water, ribs and ginger in a pot, bring to a boil and simmer on low for 40 minutes.","Add the lotus root and jujubes and simmer 1 hour more until the lotus is soft and starchy.","Season with salt and white pepper and sprinkle with scallion."],
   tips:["Add salt at the end so the meat gets tender.","Short, fat lotus roots go soft and starchy. Long, thin ones stay crunchy.","30 minutes in an electric pressure cooker is enough."]}}}
});
