window.ADD_I18N("ja", {
 tofu:{d:{
  "凉拌豆腐":{serves:"2",time:"5分",
   ingT:[["絹ごし豆腐","1丁"],["生姜","1かけ"],["小ねぎ","1本"],["かつお節","1袋"],["大葉かみょうが（お好みで）","少々"]],
   sauceT:[["醤油","適量"]],
   steps:["豆腐をパックごと冷蔵庫でよく冷やす。","パックを開けて水を捨て、キッチンペーパーで表面を軽くふき、2つに切る。","生姜はすりおろし、ねぎは小口切り、大葉はせん切りにする。","豆腐を器に盛り、生姜・ねぎ・かつお節・大葉をのせる。","食べるときに醤油をかける。"],
   tips:["夏のいちばん簡単な一品。","ごま油＋塩＋ねぎ、またはザーサイ＋ラー油にすれば中華風の冷ややっこに。","豆腐はしっかり冷たいほうがおいしい。"]},
  "炸豆腐浇汁":{serves:"2",time:"30分",
   ingT:[["木綿豆腐","1丁"],["大根おろし","適量"],["生姜","1かけ"],["小ねぎ","1本"]],
   sauceT:[["片栗粉","大さじ3"],["揚げ油","鍋底から2cm"],["だし","150ml"],["醤油","大さじ1.5"],["みりん","大さじ1.5"]],
   steps:["豆腐をキッチンペーパーで包み、皿をのせて20分水きりし、4〜6等分に切る。","だし・醤油・みりんを煮立ててつゆを作る。","豆腐の水気をふき、片栗粉をたっぷりまぶして余分な粉を落とす。","油を170°Cに熱し、豆腐を3〜4分、表面がきつね色でカリッとするまで揚げ、油をきる。","器に盛り、熱いつゆをかけ、大根おろし・おろし生姜・小ねぎをのせる。"],
   tips:["しっかり水きりすると、揚げるときに油がはねない。","粉をつけたらすぐ揚げる。時間をおくと粉がしっとりしてしまう。","衣がつゆを吸ってとろりとするのが魅力。"]},
  "嫩豆腐汤":{serves:"2",time:"20分",
   ingT:[["純豆腐（スンドゥブ）か絹ごし豆腐","1パック（約300g）"],["あさりかえび","100g"],["豚バラ薄切り","50g"],["玉ねぎ","1/4個"],["卵","1個"],["小ねぎ","1本"]],
   sauceT:[["ごま油","大さじ1"],["韓国唐辛子粉","大さじ1〜2"],["おろしにんにく","小さじ1"],["薄口醤油","小さじ1"],["水か煮干しだし","250ml"],["塩","少々"]],
   steps:["小さな土鍋にごま油を入れ、弱火で唐辛子粉とにんにくを30秒炒めてラー油を作る（焦がさないように）。","豚肉と玉ねぎを加えて1分炒め、水を加えて煮立てる。","あさりと豆腐（スプーンで大きくすくって）を入れて3分煮る。","醤油と塩で味をととのえ、卵を割り入れる。","小ねぎを散らして鍋ごと食卓へ。食べながら卵をくずす。"],
   tips:["先にごま油で唐辛子粉を炒めると、赤く香りのよいスープになる。","白いご飯と一緒に食べるのが定番。","韓国食材店の「スンドゥブの素」を使えばさらに手軽。"]}}},
 natto:{d:{
  "纳豆煎蛋":{serves:"1〜2",time:"10分",
   ingT:[["納豆","1パック"],["卵","2個"],["小ねぎ","1本"],["ピザ用チーズ（お好みで）","20g"]],
   sauceT:[["付属のたれ","1袋"],["塩","少々"],["サラダ油かバター","大さじ1"]],
   steps:["納豆に付属のたれと小ねぎを加え、糸を引くまで30回ほど混ぜる。","卵に塩を加えて溶く。","フライパンを中火で熱して油かバターを入れ、卵液を流して箸で手早く数回混ぜる。","半熟になったら、片側に納豆（とチーズ）をのせる。","へらで反対側を折りかぶせ、30秒焼いて取り出す。"],
   tips:["加熱すると納豆のにおいがやわらぐので、納豆が苦手な人にも。","卵は半熟がいちばんやわらかい。","ケチャップでも醤油でもおいしい。"]},
  "泰北豆豉":{serves:"3〜4",time:"30分",
   ingT:[["納豆","2パック"],["エシャロット","3個"],["にんにく","4かけ"],["鷹の爪","5本"],["豚ひき肉（お好みで）","100g"],["レタス・きゅうり・もち米（添える用）","適量"]],
   sauceT:[["ナンプラー","大さじ1"],["砂糖","小さじ1"],["サラダ油","大さじ2"],["水","大さじ3"]],
   steps:["納豆はたれを入れず、スプーンで粗くつぶす（タイ北部の「トゥアナオ」も発酵豆で、納豆がいちばん近い）。","唐辛子・エシャロット・にんにくをフライパンで乾煎りして焦げ目をつけ、石臼で粗くつぶす（刻んでもよい）。","鍋に油を熱し、唐辛子ペーストを1分炒め、ひき肉を加えて火を通す。","納豆と水を加えて弱火で3分炒め、ナンプラーと砂糖で味をつける。","レタス・きゅうり・もち米を添え、ディップのようにして食べる（タイ北部のナムプリック）。"],
   tips:["炒めると納豆の糸が減り、香ばしさが増す。","タイ北部では干した発酵豆の板「トゥアナオ」を使うが、日本では手に入りにくい。","チャーハンや和え麺にも使える。"]}}},
 "kaki-fruit":{d:{
  "黄桂柿子饼":{n:"柿のおやき（西安風）",h:"よく熟した柿を小麦粉とこね、黒糖・桂花・くるみのあんを包んで両面こんがり焼く西安の屋台菓子。",serves:"8個",time:"1時間",
   ingT:[["よく熟したやわらかい柿","2個（約400g）"],["中力粉","約250g（柿の水分で調整）"],["くるみ","30g"],["白ごま","大さじ1"]],
   sauceT:[["黒糖か三温糖","40g"],["桂花醤かはちみつ","大さじ1"],["小麦粉（あん用）","大さじ1"],["サラダ油","大さじ3"]],
   steps:["柿の皮とへたを取り、スプーンでつぶしてピュレにする。","柿に粉を少しずつ加え、手につかないやわらかい生地にこね、ふたをして20分休ませる。","くるみを刻み、黒糖・桂花醤・ごま・小麦粉大さじ1と混ぜてあんにする。","生地を8等分し、手に油を塗って平らにのばし、あんを包んで口をしっかり閉じ、1.5cm厚さの円形に押さえる。","フライパンに油をひき、中弱火で4〜5分、底がきつね色になるまで焼き、返して4分焼く。"],
   tips:["とろとろに熟した柿を使う。硬い柿は渋い。","粉は柿の水分を見ながら少しずつ。やわらかめの生地がおいしい。","西安の回民街の名物。焼きたてはあんが流れ出るのでやけどに注意。"]},
  "柿饼":{serves:"約10個",time:"40分（干して3〜4週間）",
   ingT:[["渋柿（T字の枝付き）","10個"],["ひも","約3m"]],
   sauceT:[["焼酎（35度、消毒用）","100ml"]],
   steps:["へたのT字の枝を残し、ピーラーで皮をむく（へたのまわりもむく）。","熱湯に10秒くぐらせるか焼酎にくぐらせ、殺菌してカビを防ぐ。","ひもの両端にT字の枝を結び、物干し竿にかける。柿同士が触れないように。","風通しがよく日が当たり、雨のかからない軒下に干す。","1週間ほどで表面が乾いたら、数日おきに手でやさしくもむ（中がやわらかくなる）。3〜4週間で濃い茶色になり、外は乾いて中がやわらかくなったら完成。"],
   tips:["必ず渋柿を使う。干すと渋みが濃い甘みに変わる。","乾燥して寒い11〜12月に作る。","表面の白い粉は糖分で、カビではない。"]},
  "柿饼桂皮茶":{serves:"4〜6",time:"50分（冷やす時間別）",
   ingT:[["干し柿","4個"],["シナモンスティック","3本（約20g）"],["生姜","1かけ（約30g）"],["松の実","大さじ1"]],
   sauceT:[["水","1.5L"],["黒糖か三温糖","100g"],["砂糖","大さじ2"]],
   steps:["生姜は皮をむいて薄切り、シナモンは軽く洗う。","鍋2つに水750mlずつ入れ、一方に生姜、もう一方にシナモンを入れて、それぞれ弱火で30分煮る（別々に煮ると味がすっきりする）。","それぞれこして合わせ、黒糖と砂糖を加えて5分煮て、冷ましてから冷蔵庫で冷やす。","干し柿のへたを取り、切り込みを入れて種を除く。くるみを包んで巻き、輪切りにしてもよい。","飲む1〜2時間前に干し柿を冷たいスジョングァにつけてやわらかくし、器に注いで松の実を浮かべる。"],
   tips:["韓国の正月の伝統的な飲み物。冷たくして飲む。","やわらかくなった干し柿はデザートのよう。","冷蔵で1週間もつ。"]}}},
 yuzu:{d:{
  "柚子醋":{serves:"約300ml",time:"15分（一晩漬ける）",
   ingT:[["ゆず（またはすだち・レモン）","3〜4個（果汁100ml）"],["昆布","5cm 1枚"],["かつお節","5g"]],
   sauceT:[["醤油","100ml"],["みりん","50ml"],["米酢（お好みで）","大さじ2"]],
   steps:["みりんを小鍋で30秒煮立ててアルコールを飛ばし、冷ます。","ゆずを半分に切って果汁をしぼり、種をこす。","清潔な瓶にゆず果汁・醤油・みりん・酢・昆布・かつお節を入れる。","冷蔵庫で一晩置く。","翌日、キッチンペーパーを敷いたざるでこし、瓶に戻して冷蔵する。"],
   tips:["手作りのポン酢は市販品よりずっと香りが強い。","冷蔵で1〜2か月もち、時間がたつと味がまろやかになる。","鍋、餃子、焼き魚、サラダに。"]},
  "柚子胡椒":{serves:"小瓶1本分",time:"30分（熟成1週間）",
   ingT:[["青ゆず","3〜4個"],["青唐辛子","50g（約10本）"]],
   sauceT:[["塩","約15g（材料の総重量の20%）"]],
   steps:["手袋をする（唐辛子がとても辛い）。青唐辛子のへたを取り、縦に切って種を取り（辛いのが好きなら一部残す）、刻む。","ゆずの緑の皮をピーラーで薄くむき（白い部分は苦いので入れない）、刻む。","ゆずの皮と唐辛子の重さを量り、20%の塩を加える。","すべてをフードプロセッサーかすり鉢で、なめらかなペーストにする。","清潔な瓶に詰め、冷蔵庫で1週間熟成させ、味がなじんだら使える。"],
   tips:["九州の特産調味料。少量でとても香り高く辛い。","黄ゆずと赤唐辛子で作ると赤い柚子胡椒に。","鍋、焼き鳥、刺身、パスタに。冷蔵で半年もつ。"]}}},
 aji:{d:{
  "椒盐巴浪鱼":{serves:"2",time:"30分",
   ingT:[["小あじ（豆あじ）","4尾"],["にんにく","3かけ"],["赤唐辛子","1本"],["小ねぎ","2本"]],
   sauceT:[["塩","小さじ1"],["料理酒","大さじ1"],["片栗粉","大さじ4"],["花椒塩（花椒粉＋塩）","小さじ1"],["揚げ油","鍋底から3cm"]],
   steps:["あじのえらと内臓を取り、尾の両側の硬いうろこ（ぜいご）をそぎ取り、洗って水気をふく。","身に2本切り込みを入れ、塩と料理酒をまぶして15分置き、水気をふく。","片栗粉を薄くまぶす。","油を170°Cに熱して4〜5分揚げて取り出し、190°Cに上げて1分二度揚げしてカリッとさせる。","鍋に油を少し残してにんにく・唐辛子・ねぎのみじん切りを炒め、あじを入れて花椒塩をふってからめる。"],
   tips:["小あじは二度揚げすれば骨ごと食べられる。","ぜいごは必ず取る。口に刺さる。","スーパーの「豆あじ」が安くてこの料理にぴったり。"]},
  "竹荚鱼拍松":{serves:"2",time:"20分",
   ingT:[["刺身用あじ","2尾（または刺身用の身150g）"],["生姜","1かけ"],["小ねぎ","2本"],["大葉","4枚"],["みょうが（お好みで）","1個"]],
   sauceT:[["醤油","適量"],["味噌（お好みで、なめろうにする場合）","小さじ1"]],
   steps:["あじのぜいごを取って三枚におろし、骨抜きで中央の小骨を抜き、頭側から皮をはぐ。","身を細切りにしてから、包丁で粗くたたく（食感を少し残す）。","生姜はみじん切り、ねぎは小口切り、大葉とみょうがはせん切りにする。","あじに生姜・ねぎ・みょうがの半量を合わせ、さらに軽くたたく。","皿に大葉を敷いてあじを盛り、残りの薬味をのせて醤油で。味噌と一緒にたたけば千葉の「なめろう」。"],
   tips:["必ずごく新鮮な刺身用のあじを使う。","スーパーの「刺身用あじ」（おろし済み）がいちばん手軽。","残ったら焼いて「さんが焼き」に。"]}}}
});
window.ADD_I18N("en", {
 tofu:{d:{
  "凉拌豆腐":{serves:"2",time:"5 min",
   ingT:[["Silken tofu","1 block"],["Ginger","1 small piece"],["Scallion","1"],["Bonito flakes","1 small packet"],["Shiso or myoga (optional)","a little"]],
   sauceT:[["Soy sauce","as needed"]],
   steps:["Chill the tofu in its pack until very cold.","Open, drain, blot the surface gently with paper towel and cut in two.","Grate the ginger, slice the scallion and shred the shiso.","Put the tofu on a plate and top with the ginger, scallion, bonito flakes and shiso.","Pour soy sauce over when you eat."],
   tips:["The simplest summer dish.","Swap in sesame oil, salt and scallion, or zha cai and chili oil, for a Chinese version.","The tofu must be very cold."]},
  "炸豆腐浇汁":{serves:"2",time:"30 min",
   ingT:[["Firm tofu","1 block"],["Grated daikon","as needed"],["Ginger","1 small piece"],["Scallion","1"]],
   sauceT:[["Potato starch","3 tbsp"],["Oil for frying","2cm deep"],["Dashi","150ml"],["Soy sauce","1.5 tbsp"],["Mirin","1.5 tbsp"]],
   steps:["Wrap the tofu in paper towels, weigh it down with a plate for 20 minutes to drain, and cut into 4–6 pieces.","Bring the dashi, soy sauce and mirin to a boil for the sauce.","Pat the tofu dry, coat well in starch and shake off the excess.","Fry at 170°C for 3–4 minutes until golden and crisp. Drain.","Put in bowls, pour over the hot sauce and top with grated daikon, grated ginger and scallion."],
   tips:["Drain the tofu well so it doesn't spatter.","Fry right after coating or the starch turns soggy.","The charm is the coating going soft as it soaks up the broth."]},
  "嫩豆腐汤":{serves:"2",time:"20 min",
   ingT:[["Korean soft tofu or silken tofu","1 pack (about 300g)"],["Clams or shrimp","100g"],["Thin pork belly slices","50g"],["Onion","1/4"],["Egg","1"],["Scallion","1"]],
   sauceT:[["Sesame oil","1 tbsp"],["Korean chili powder","1–2 tbsp"],["Grated garlic","1 tsp"],["Soup soy sauce or light soy","1 tsp"],["Water or anchovy stock","250ml"],["Salt","a little"]],
   steps:["Fry the chili powder and garlic in sesame oil in a small earthenware pot over low heat for 30 seconds to make chili oil (don't burn it).","Add the pork and onion, fry 1 minute, then add the water and bring to a boil.","Add the clams and scoop in large spoonfuls of tofu. Cook 3 minutes.","Season with soy sauce and salt and crack in the egg.","Sprinkle with scallion and serve in the pot. Break the egg up as you eat."],
   tips:["Frying the chili powder in sesame oil first makes the soup red and fragrant.","Eat with a bowl of white rice.","Korean grocers sell ready-made sundubu base for an even quicker version."]}}},
 natto:{d:{
  "纳豆煎蛋":{serves:"1–2",time:"10 min",
   ingT:[["Natto","1 pack"],["Eggs","2"],["Scallion","1"],["Pizza cheese (optional)","20g"]],
   sauceT:[["Sauce packet from the natto","1"],["Salt","a little"],["Cooking oil or butter","1 tbsp"]],
   steps:["Mix the natto with its sauce and the scallion about 30 times until stringy.","Beat the eggs with salt.","Heat oil or butter in a frying pan over medium, pour in the eggs and stir quickly a few times with chopsticks.","When half set, put the natto (and cheese) on one side.","Fold the other half over with a spatula, cook 30 seconds and slide out."],
   tips:["Cooking softens natto's smell, so it's a good start for natto skeptics.","Keep the egg soft for the best texture.","Good with ketchup or soy sauce."]},
  "泰北豆豉":{serves:"3–4",time:"30 min",
   ingT:[["Natto","2 packs"],["Shallots","3"],["Garlic","4 cloves"],["Dried red chilies","5"],["Ground pork (optional)","100g"],["Lettuce, cucumber and sticky rice (to serve)","as needed"]],
   sauceT:[["Fish sauce","1 tbsp"],["Sugar","1 tsp"],["Cooking oil","2 tbsp"],["Water","3 tbsp"]],
   steps:["Roughly mash the natto without its sauce (northern Thai thua nao is also fermented soybeans, and natto is the closest substitute).","Dry-roast the chilies, shallots and garlic in a nonstick pan until charred, then pound into a coarse paste in a mortar (or chop finely).","Fry the paste in oil for 1 minute, then add the pork and cook through.","Add the natto and water, stir over low heat for 3 minutes, and season with fish sauce and sugar.","Serve with lettuce, cucumber and sticky rice and eat it like a dip (a northern Thai nam prik)."],
   tips:["Frying cuts natto's stringiness and deepens its aroma.","Northern Thailand uses dried fermented soybean discs (thua nao), which are hard to find in Japan.","Use it in fried rice or tossed noodles too."]}}},
 "kaki-fruit":{d:{
  "黄桂柿子饼":{n:"Xi'an persimmon cakes",h:"Very ripe persimmon kneaded with flour, filled with brown sugar, osmanthus and walnuts, and pan-fried golden on both sides. A Xi'an street snack.",serves:"8 cakes",time:"1 hour",
   ingT:[["Very ripe, soft persimmons","2 (about 400g)"],["All-purpose flour","about 250g (adjust for moisture)"],["Walnuts","30g"],["White sesame seeds","1 tbsp"]],
   sauceT:[["Brown sugar","40g"],["Osmanthus syrup or honey","1 tbsp"],["Flour (for the filling)","1 tbsp"],["Cooking oil","3 tbsp"]],
   steps:["Peel and stem the persimmons and mash with a spoon.","Add flour to the purée bit by bit and knead into a soft dough that doesn't stick. Cover and rest 20 minutes.","Chop the walnuts and mix with the sugar, osmanthus, sesame and 1 tbsp flour for the filling.","Divide the dough into 8, oil your hands, flatten each piece, wrap in a spoonful of filling, pinch closed and press into 1.5cm-thick rounds.","Fry in oil over medium-low for 4–5 minutes until golden underneath, flip and fry 4 minutes."],
   tips:["Use persimmons ripe to the point of mush. Firm ones are astringent.","Add the flour gradually depending on the fruit. A softer dough tastes better.","A snack from Xi'an's Muslim Quarter. The filling runs when hot, so mind your mouth."]},
  "柿饼":{serves:"About 10",time:"40 min (plus 3–4 weeks drying)",
   ingT:[["Astringent persimmons with a T-shaped stem","10"],["String","about 3m"]],
   sauceT:[["Shochu or vodka (35%, for sterilizing)","100ml"]],
   steps:["Keep the T-shaped twig on each stem and peel the persimmons with a peeler (including around the calyx).","Dip in boiling water for 10 seconds or in shochu to sterilize and prevent mold.","Tie a persimmon by its twig to each end of a string and hang over a pole so they don't touch.","Hang under the eaves where there's airflow and sun but no rain.","After about a week the surface dries. Gently knead them every few days to soften the inside. After 3–4 weeks they turn dark brown, dry outside and soft inside."],
   tips:["Always use astringent persimmons. Drying turns the astringency into intense sweetness.","Make them in cold, dry November–December weather.","The white powder on the surface is sugar, not mold."]},
  "柿饼桂皮茶":{serves:"4–6",time:"50 min (plus chilling)",
   ingT:[["Dried persimmons","4"],["Cinnamon sticks","3 (about 20g)"],["Ginger","1 piece (about 30g)"],["Pine nuts","1 tbsp"]],
   sauceT:[["Water","1.5 liters"],["Brown sugar","100g"],["Sugar","2 tbsp"]],
   steps:["Peel and thinly slice the ginger, and rinse the cinnamon.","Put 750ml water with the ginger in one pot and 750ml with the cinnamon in another. Simmer each on low for 30 minutes (separately gives a cleaner flavor).","Strain both and combine, add the sugars, simmer 5 minutes, cool and refrigerate.","Stem the dried persimmons, slit and remove the seeds. You can roll one around a walnut and slice it.","Soak the persimmons in the cold punch for 1–2 hours before serving to soften, then ladle into bowls and float pine nuts on top."],
   tips:["A traditional Korean New Year drink, served chilled.","The softened persimmons are like a dessert.","Keeps a week in the fridge."]}}},
 yuzu:{d:{
  "柚子醋":{serves:"About 300ml",time:"15 min (plus overnight steeping)",
   ingT:[["Yuzu (or sudachi or lemon)","3–4 (100ml juice)"],["Kombu","1 piece, 5cm"],["Bonito flakes","5g"]],
   sauceT:[["Soy sauce","100ml"],["Mirin","50ml"],["Rice vinegar (optional)","2 tbsp"]],
   steps:["Boil the mirin in a small pan for 30 seconds to cook off the alcohol and cool.","Halve and squeeze the yuzu and strain out the seeds.","Put the juice, soy sauce, mirin, vinegar, kombu and bonito flakes in a clean jar.","Refrigerate overnight.","The next day, strain through a sieve lined with paper towel and store in the fridge."],
   tips:["Homemade ponzu is far more fragrant than store-bought.","Keeps 1–2 months in the fridge and mellows over time.","Use with hot pot, dumplings, grilled fish and salads."]},
  "柚子胡椒":{serves:"1 small jar",time:"30 min (plus 1 week maturing)",
   ingT:[["Green yuzu","3–4"],["Green chilies","50g (about 10)"]],
   sauceT:[["Salt","about 15g (20% of the total weight)"]],
   steps:["Wear gloves (the chilies are hot). Stem, split and seed the chilies (leave some seeds for more heat) and chop.","Peel off just the green yuzu zest with a peeler (the white pith is bitter) and chop.","Weigh the zest and chilies and add 20% of that weight in salt.","Grind everything in a food processor or mortar into a smooth paste.","Pack into a clean jar and mature in the fridge for 1 week before using."],
   tips:["A Kyushu specialty. A tiny amount is very fragrant and hot.","Yellow yuzu with red chilies makes red yuzu kosho.","Use with hot pot, yakitori, sashimi and pasta. Keeps 6 months in the fridge."]}}},
 aji:{d:{
  "椒盐巴浪鱼":{serves:"2",time:"30 min",
   ingT:[["Small horse mackerel","4"],["Garlic","3 cloves"],["Red chili","1"],["Scallions","2"]],
   sauceT:[["Salt","1 tsp"],["Shaoxing or cooking wine","1 tbsp"],["Potato starch","4 tbsp"],["Sichuan pepper salt","1 tsp"],["Oil for frying","3cm deep"]],
   steps:["Remove the gills and guts, shave off the hard scutes along both sides of the tail, rinse and pat dry.","Score each fish twice, rub with salt and wine, rest 15 minutes and pat dry.","Coat lightly in starch.","Fry at 170°C for 4–5 minutes and remove. Raise the oil to 190°C and fry again for 1 minute until crisp.","Leave a little oil in the wok, fry minced garlic, chili and scallion, add the fish and toss with the pepper salt."],
   tips:["Double-fried small fish can be eaten bones and all.","Always remove the scutes or they'll scratch your mouth.","Japanese 豆あじ (baby horse mackerel) is cheap and perfect here."]},
  "竹荚鱼拍松":{serves:"2",time:"20 min",
   ingT:[["Sashimi-grade horse mackerel","2 (or 150g sashimi fillets)"],["Ginger","1 small piece"],["Scallions","2"],["Shiso leaves","4"],["Myoga (optional)","1"]],
   sauceT:[["Soy sauce","as needed"],["Miso (optional, for namero)","1 tsp"]],
   steps:["Remove the scutes, fillet into three pieces, pull out the pin bones with tweezers and peel off the skin from the head end.","Cut the fillets into thin strips, then chop roughly with a knife, keeping some texture.","Mince the ginger, slice the scallions and shred the shiso and myoga.","Mix the fish with half the ginger, scallion and myoga and chop lightly again.","Line a plate with shiso, add the fish, top with the rest of the garnishes and eat with soy sauce. Chop in miso to make Chiba-style namero."],
   tips:["Use only very fresh sashimi-grade fish.","Pre-filleted 刺身用あじ from the supermarket is the easiest.","Shape leftovers into patties and pan-fry them (sanga-yaki)."]}}}
});
// 详细菜谱翻译 10
window.ADD_I18N("ja", {
 aji:{d:{
  "南蛮渍":{serves:"3〜4",time:"40分（冷やし半日）",
   ingT:[["小あじ（豆あじ）","10尾（約300g）"],["玉ねぎ","1/2個"],["にんじん","1/3本"],["ピーマン","1個"],["鷹の爪","1本"]],
   sauceT:[["米酢","100ml"],["だしか水","100ml"],["醤油","大さじ3"],["砂糖","大さじ3"],["片栗粉","大さじ3"],["揚げ油","鍋底から2cm"]],
   steps:["酢・だし・醤油・砂糖・輪切りの唐辛子を煮立てて保存容器に入れ、玉ねぎ・にんじん・ピーマンのせん切りを漬ける。","小あじのえらと内臓を取り、ぜいごをそいで洗い、水気をふく。","片栗粉をまぶし、160°Cの油で6〜8分、骨までカリッとするまでじっくり揚げる。","熱いうちにすぐ南蛮酢につけ、野菜とさっと混ぜる。","冷蔵庫で半日〜1日置き、冷たいまま食べる。"],
   tips:["低温でじっくり揚げると、小あじの骨まで食べられる。","熱いうちにつけると甘酢がよくしみる。","冷蔵で3〜4日もち、日がたつほど味がなじむ。"]},
  "葡式烤竹荚鱼":{serves:"2",time:"30分",
   ingT:[["あじ（下処理済み）","2尾"],["小さいじゃがいも","4個"],["玉ねぎ","1/2個"],["ピーマン","1個"],["トマト","1個"]],
   sauceT:[["粗塩","大さじ1"],["オリーブオイル","大さじ4"],["ワインビネガーか米酢","大さじ1"],["塩・こしょう","少々"]],
   steps:["あじの水気をふき、全体に粗塩をまぶして15分置く。","じゃがいもを皮付きのまま15分ゆでてやわらかくする。","玉ねぎ・ピーマン・トマトを角切りにし、酢・オリーブオイル大さじ2・塩・こしょうで和えてサラダにする。","焼き網、魚焼きグリルか230°Cのオーブンで10〜12分、途中で一度返し、皮がパリッとするまで焼く。","皿にあじとじゃがいもを盛り、残りのオリーブオイルをかけてサラダを添える。"],
   tips:["ポルトガルでは焼き魚にもじゃがいもにもオリーブオイルをたっぷり。","粗塩をまぶすと皮がパリッとし、味もしみる。","夏に屋外で炭火焼きにするのがいちばん。"]}}},
 iwashi:{d:{
  "梅干煮沙丁鱼":{serves:"2〜3",time:"35分",
   ingT:[["真いわし","4〜6尾"],["梅干し","2個"],["生姜","1かけ"]],
   sauceT:[["水","150ml"],["酒","50ml"],["醤油","大さじ2"],["砂糖","大さじ1"],["みりん","大さじ1"]],
   steps:["いわしの頭を切り落とし、腹を少し斜めに切って指で内臓をかき出し、洗って水気をふく。","生姜はせん切りにする。","鍋に水・酒・醤油・砂糖・みりん・生姜・ちぎった梅干し（種ごと）を入れて煮立てる。","いわしを並べて入れ、アルミホイルで落とし蓋をして中弱火で15〜20分煮る。","ホイルを取り、煮汁をかけながら、汁が少し残ってつやが出るまで煮る。"],
   tips:["梅干しが臭みを取り、骨もやわらかくする。","返さない。皮が破れやすい。","冷めてもおいしいので作り置きに。"]},
  "沙丁鱼丸汤":{serves:"3",time:"40分",
   ingT:[["真いわし","4尾（身約200g）"],["大根","1/6本"],["にんじん","1/3本"],["長ねぎ","1/2本"],["生姜","1かけ"]],
   sauceT:[["味噌（つみれ用）","小さじ1"],["片栗粉","大さじ1"],["だし","800ml"],["味噌（汁用）","大さじ2.5"]],
   steps:["いわしの頭と内臓を取り、指で中骨に沿って開き（手開き）、中骨を外して皮をむく。","身を細かくたたき（フードプロセッサーでも）、生姜・ねぎのみじん切り、味噌小さじ1、片栗粉を加えて粘りが出るまで混ぜる。","大根とにんじんをいちょう切りにし、だしで8分やわらかく煮る。","スプーン2本でつみれの形にして汁に落とし、浮き上がるまで5分煮る。","弱火にして味噌を溶き入れ、ねぎを散らす。"],
   tips:["いわしは身がやわらかいので、指で骨を外せる。","つみれに味噌と生姜を入れると臭みが消える。","ごぼうを入れてもおいしい。"]},
  "葡式烤沙丁鱼":{serves:"2",time:"25分",
   ingT:[["真いわし（丸ごと、内臓付き）","6尾"],["カンパーニュかバゲット","4枚"],["ピーマン・パプリカ","各1個"],["レモン","1/2個"]],
   sauceT:[["粗塩","大さじ1"],["オリーブオイル","大さじ2"]],
   steps:["いわしを洗う。うろこも内臓も取らず（ポルトガル伝統の方法）、水気をふいて粗塩をまぶし、30分置く。","ピーマンとパプリカを丸ごと皮が黒くなるまで焼き、冷ましてから皮をむいて裂き、オリーブオイルと塩で和える。","炭火か魚焼きグリルの強火で、いわしを片面3〜4分ずつ、皮がふくれて焦げ目がつくまで焼く。","焼けたいわしをパンの上に直接のせ、脂をパンにしみ込ませる。","レモンを搾り、焼きピーマンを添える。"],
   tips:["リスボンの6月の聖アントニオ祭に欠かせない一品。","内臓を取らないのが伝統で、ほろ苦い。苦手なら取ってもよい。","魚を食べたあとの、脂を吸ったパンがいちばんおいしい。"]},
  "西西里沙丁鱼意面":{serves:"2",time:"40分",
   ingT:[["真いわし（手開き）","4尾（約200g）"],["ブカティーニかスパゲッティ","160g"],["フェンネル（球茎と葉）","1/2個"],["玉ねぎ","1/2個"],["レーズン","大さじ1"],["松の実","大さじ1"],["アンチョビ（お好みで）","2枚"],["パン粉","大さじ3"]],
   sauceT:[["オリーブオイル","大さじ5"],["サフラン（お好みで）","ひとつまみ"],["白ワイン","50ml"],["塩・こしょう","適量"]],
   steps:["パン粉をオリーブオイル大さじ1で弱火できつね色にカリッと炒めて取り出す。レーズンはぬるま湯で戻し、サフランは熱湯大さじ2につける。","フェンネルの葉は取っておき、球茎はせん切りにしてパスタ用の塩湯で5分ゆでて取り出す（湯は取っておく）。","フライパンにオリーブオイルを入れ、玉ねぎとアンチョビを5分炒め、フェンネル・レーズン・松の実を加えて2分炒める。","いわしを加えて白ワインを注ぎ、へらで身をくずし、サフラン水を加えて弱火で5分煮る。","フェンネルのゆで汁でパスタを表示より1分短くゆで、フライパンに加え、ゆで汁大さじ3を加えて和える。","刻んだフェンネルの葉と炒めたパン粉をふる（シチリアではチーズの代わりにパン粉を使う）。"],
   tips:["甘い（レーズン）・塩辛い（アンチョビ）・香り（フェンネル）がシチリアらしい組み合わせ。","フェンネルは大きめのスーパーや通販で買える。","パン粉は「貧乏人のチーズ」と呼ばれる。"]}}},
 katakuchi:{d:{
  "椒盐凤尾鱼":{serves:"2",time:"25分",
   ingT:[["かたくちいわしか小いわし","200g"],["にんにく","2かけ"],["小ねぎ","1本"]],
   sauceT:[["塩","小さじ1/2"],["料理酒","大さじ1"],["片栗粉か小麦粉","大さじ4"],["花椒塩（花椒粉＋塩）","小さじ1"],["揚げ油","鍋底から2cm"]],
   steps:["小魚の頭を指でちぎり、そのまま内臓を引き出して洗い、水気をきる。","塩と料理酒をまぶして10分置き、キッチンペーパーで水気をふく。","ポリ袋に入れて片栗粉を加えて振り、薄く粉をまぶす。","油を170°Cに熱して数回に分けて2分ずつ揚げ、全部揚げたら油温を上げて、もう一度まとめて1分二度揚げする。","鍋に油を少し残してにんにくのみじん切りを炒め、魚を入れて花椒塩とねぎをふって混ぜる。"],
   tips:["二度揚げでいちばんカリッとし、骨ごと食べられる。","一度にたくさん入れると油温が下がるので、数回に分けて。","日本では生のかたくちいわしは少ないので「小いわし」で代用するのが近い。"]},
  "小鱼干高汤":{serves:"約1L",time:"15分（30分以上浸す）",
   ingT:[["煮干し（いりこ）","20g（約15尾）"]],
   sauceT:[["水","1L"]],
   steps:["煮干しの頭を取り、身を割って黒いはらわたを取る（苦みのもと）。","鍋に入れて水を注ぎ、30分以上つける（冷蔵庫で一晩がベスト）。","中火にかけ、沸騰直前に弱火にしてアクを取り、弱火で5分煮る。","キッチンペーパーを敷いたざるでこす。","味噌汁、うどんのつゆ、煮物に。"],
   tips:["はらわたを取ると、だしが苦くならない。","煮干しを軽く乾煎りしてからつけると、香りがよくなる。","西日本の家庭でよく使うだし。冷蔵で2〜3日もつ。"]},
  "西班牙醋腌鳀鱼":{serves:"3〜4",time:"30分（漬け一晩）",
   ingT:[["生のかたくちいわしか小いわし（刺身用）","300g"],["にんにく","2かけ"],["パセリ","1束"]],
   sauceT:[["白ワインビネガーか米酢","200ml"],["水","50ml"],["塩","小さじ1"],["オリーブオイル","大さじ4"]],
   steps:["寄生虫対策のため、必ず先に48時間以上（−20°C）冷凍し、冷蔵庫で解凍する。","頭をちぎり、指で中骨に沿って開いて中骨と内臓を取り、蝶のような形に開いて洗う。","皮を下にしてバットに並べ、酢・水・塩を混ぜた液をかぶるまで注ぎ、冷蔵庫で6時間〜一晩漬ける。身が白くなる。","酢を捨て、キッチンペーパーで水気をふく。","皿に並べてオリーブオイルをかけ、にんにくとパセリのみじん切りを散らし、冷蔵庫で1時間置いてから食べる。"],
   tips:["酢では寄生虫は死なないので、冷凍は絶対に省かない。","スペインのバルの定番。パンとビールに。","オリーブオイルに漬ければ冷蔵で5日もつ。"]},
  "马来椰浆饭配炸江鱼仔":{serves:"2",time:"50分",
   ingT:[["米（ジャスミン米が理想）","1.5合（約220g）"],["小さめの煮干しかちりめんじゃこ","40g"],["ピーナッツ","40g"],["卵","2個"],["きゅうり","1/2本"],["パンダンリーフ（お好みで）","2枚"]],
   sauceT:[["ココナッツミルク","200ml"],["水","150ml"],["塩","小さじ1/2"],["生姜の薄切り","2枚"],["サンバル（市販か手作り）","大さじ4"],["砂糖","小さじ1"],["サラダ油","適量"]],
   steps:["米を洗い、ココナッツミルク・水・塩・生姜・結んだパンダンリーフを加えて炊飯器で普通に炊く。","卵を9分ゆでて固ゆでにし、殻をむいて半分に切る。きゅうりは薄切り。","鍋に2cmの油を入れ、弱火でピーナッツを3〜4分、うっすら色づくまで揚げて取り出す。続けて小魚を1〜2分、カリッと揚げる。","鍋に油大さじ1を残してサンバルを炒め、砂糖と揚げた小魚の半量を加えて炒め合わせる。","皿の中央にココナッツライスを盛り、まわりに小魚・ピーナッツ・卵・きゅうり・サンバルを並べる。"],
   tips:["マレーシアの国民的な朝ごはん。バナナの葉で包むことも多い。","小魚とピーナッツは弱火で。焦げやすい。","サンバルはKALDIやアジア食材店で買える。"]}}},
 shirasu:{d:{
  "吻仔鱼粥":{serves:"2",time:"40分",
   ingT:[["米","1/2カップ（約90g）"],["釜揚げしらす","50g"],["生姜","1かけ"],["セロリの葉か小ねぎ","少々"]],
   sauceT:[["水","1L"],["塩","小さじ1/2"],["白こしょう","少々"],["ごま油（お好みで）","数滴"]],
   steps:["米を洗い、油を数滴混ぜて15分置く（おかゆがなめらかになる）。","鍋に湯を沸かして米を入れ、再沸騰したら弱火にし、ふたを少しずらして25〜30分、ときどき混ぜて焦げつかないように煮る。","生姜は細いせん切り、セロリの葉はみじん切りにする。","とろみがついたらしらすと生姜を加えて1分煮る。","塩と白こしょうで味をととのえ、セロリの葉を散らしてごま油をたらす。"],
   tips:["釜揚げしらすには塩気があるので、味見してから調味を。","残りご飯に水を加えて10分煮る時短版もできる。","朝ごはんや食欲のないときに。"]},
  "萝卜泥拌银鱼":{serves:"2",time:"5分",
   ingT:[["釜揚げしらす","40g"],["大根","5cm"],["大葉か小ねぎ（お好みで）","少々"]],
   sauceT:[["ポン酢か醤油","適量"]],
   steps:["大根をすりおろし、ざるにのせて軽く水気をきる（しぼりすぎない）。","大根おろしを小鉢に盛る。","しらすをたっぷりのせ、小ねぎか大葉のせん切りをのせる。","食べるときにポン酢か醤油をかける。"],
   tips:["大根の葉に近い部分は甘いので、大根おろし向き。","居酒屋の定番のおつまみ。","温かいご飯にのせれば「しらす丼」。"]}}}
});
window.ADD_I18N("en", {
 aji:{d:{
  "南蛮渍":{serves:"3–4",time:"40 min (plus half a day chilling)",
   ingT:[["Small horse mackerel","10 (about 300g)"],["Onion","1/2"],["Carrot","1/3"],["Green pepper","1"],["Dried red chili","1"]],
   sauceT:[["Rice vinegar","100ml"],["Dashi or water","100ml"],["Soy sauce","3 tbsp"],["Sugar","3 tbsp"],["Potato starch","3 tbsp"],["Oil for frying","2cm deep"]],
   steps:["Boil the vinegar, dashi, soy sauce, sugar and sliced chili, pour into a container and add the thinly sliced onion, carrot and pepper.","Remove the gills and guts from the fish, shave off the scutes, rinse and pat dry.","Coat in starch and fry slowly at 160°C for 6–8 minutes until even the bones are crisp.","Put them straight into the marinade while hot and toss with the vegetables.","Refrigerate half a day to a day and eat cold."],
   tips:["Slow frying at low heat makes the bones edible.","Marinating while hot lets the fish soak up the sweet-sour flavor.","Keeps 3–4 days in the fridge and gets better each day."]},
  "葡式烤竹荚鱼":{serves:"2",time:"30 min",
   ingT:[["Whole horse mackerel, cleaned","2"],["Small potatoes","4"],["Onion","1/2"],["Green pepper","1"],["Tomato","1"]],
   sauceT:[["Coarse salt","1 tbsp"],["Olive oil","4 tbsp"],["Wine or rice vinegar","1 tbsp"],["Salt and black pepper","a little"]],
   steps:["Pat the fish dry, rub all over with coarse salt and rest 15 minutes.","Boil the potatoes in their skins for 15 minutes until tender.","Dice the onion, pepper and tomato and toss with the vinegar, 2 tbsp olive oil, salt and pepper.","Grill on a rack, under a fish grill or in a 230°C oven for 10–12 minutes, turning once, until the skin is crisp.","Plate the fish and potatoes, drizzle with the remaining olive oil and serve with the salad."],
   tips:["The Portuguese drench both grilled fish and potatoes in olive oil.","Coarse salt makes the skin crisp and seasons the fish.","Best cooked outdoors over charcoal in summer."]}}},
 iwashi:{d:{
  "梅干煮沙丁鱼":{serves:"2–3",time:"35 min",
   ingT:[["Sardines","4–6"],["Umeboshi (pickled plums)","2"],["Ginger","1 piece"]],
   sauceT:[["Water","150ml"],["Sake","50ml"],["Soy sauce","2 tbsp"],["Sugar","1 tbsp"],["Mirin","1 tbsp"]],
   steps:["Cut off the heads, slice off a little of the belly at an angle, pull out the guts with your finger, rinse and pat dry.","Cut the ginger into thin strips.","Bring the water, sake, soy sauce, sugar, mirin, ginger and torn umeboshi (pits and all) to a boil.","Lay the sardines in a row, cover with foil laid directly on top and simmer over medium-low for 15–20 minutes.","Remove the foil and spoon the liquid over until only a little glossy sauce remains."],
   tips:["Umeboshi removes fishiness and softens the bones.","Don't turn them. The skin tears easily.","Good cold, so it keeps well as a make-ahead dish."]},
  "沙丁鱼丸汤":{serves:"3",time:"40 min",
   ingT:[["Sardines","4 (about 200g flesh)"],["Daikon","1/6"],["Carrot","1/3"],["Japanese leek (negi)","1/2"],["Ginger","1 small piece"]],
   sauceT:[["Miso (for the balls)","1 tsp"],["Potato starch","1 tbsp"],["Dashi","800ml"],["Miso (for the soup)","2.5 tbsp"]],
   steps:["Remove the heads and guts, open the fish flat along the backbone with your fingers, lift out the bone and peel off the skin.","Chop the flesh into a fine paste (or use a food processor) and mix with minced ginger and leek, 1 tsp miso and the starch until sticky.","Cut the daikon and carrot into thin quarter-moons and simmer in the dashi for 8 minutes until tender.","Shape the paste into balls with two spoons, drop them into the soup and simmer 5 minutes until they float.","Turn the heat down, dissolve in the miso and sprinkle with leek."],
   tips:["Sardine flesh is soft enough to bone with your fingers.","Miso and ginger in the balls cancel any fishiness.","Burdock is a good addition."]},
  "葡式烤沙丁鱼":{serves:"2",time:"25 min",
   ingT:[["Whole sardines, ungutted","6"],["Country bread or baguette","4 slices"],["Green and red peppers","1 each"],["Lemon","1/2"]],
   sauceT:[["Coarse salt","1 tbsp"],["Olive oil","2 tbsp"]],
   steps:["Rinse the sardines. Leave the scales and guts in (the traditional Portuguese way), pat dry, rub with coarse salt and rest 30 minutes.","Roast the peppers whole until blackened, cool, peel, tear into strips and dress with olive oil and salt.","Grill the sardines over charcoal or a hot fish grill for 3–4 minutes per side until the skin blisters and chars.","Put the grilled fish straight onto the bread so the oil soaks in.","Squeeze over lemon and serve with the peppers."],
   tips:["A must at Lisbon's Saint Anthony festival in June.","Leaving the guts in is traditional and slightly bitter. Remove them if you prefer.","The oil-soaked bread left after the fish is the best part."]},
  "西西里沙丁鱼意面":{serves:"2",time:"40 min",
   ingT:[["Boned sardine fillets","4 fish (about 200g)"],["Bucatini or spaghetti","160g"],["Fennel bulb and fronds","1/2"],["Onion","1/2"],["Raisins","1 tbsp"],["Pine nuts","1 tbsp"],["Anchovies (optional)","2"],["Panko or breadcrumbs","3 tbsp"]],
   sauceT:[["Olive oil","5 tbsp"],["Saffron (optional)","a pinch"],["White wine","50ml"],["Salt and black pepper","as needed"]],
   steps:["Toast the breadcrumbs in 1 tbsp olive oil over low heat until golden and crisp. Soak the raisins in warm water and the saffron in 2 tbsp hot water.","Save the fennel fronds. Slice the bulb and boil it in the salted pasta water for 5 minutes, then remove (keep the water).","Cook the onion and anchovies in olive oil for 5 minutes, then add the fennel, raisins and pine nuts for 2 minutes.","Add the sardines and wine, break up the fish with a spatula, add the saffron water and simmer on low for 5 minutes.","Cook the pasta in the fennel water 1 minute short of the package time, add to the pan with 3 tbsp pasta water and toss.","Sprinkle with chopped fennel fronds and the toasted crumbs (Sicilians use crumbs instead of cheese)."],
   tips:["Sweet raisins, salty anchovy and fragrant fennel are a classic Sicilian combination.","Fennel is sold at larger supermarkets or online.","Toasted crumbs are called poor man's cheese."]}}},
 katakuchi:{d:{
  "椒盐凤尾鱼":{serves:"2",time:"25 min",
   ingT:[["Fresh anchovies or small sardines","200g"],["Garlic","2 cloves"],["Scallion","1"]],
   sauceT:[["Salt","1/2 tsp"],["Shaoxing or cooking wine","1 tbsp"],["Potato starch or flour","4 tbsp"],["Sichuan pepper salt","1 tsp"],["Oil for frying","2cm deep"]],
   steps:["Pinch off the heads with your fingers, pulling the guts out with them. Rinse and drain.","Toss with the salt and wine, rest 10 minutes and blot dry.","Shake in a bag with the starch so each fish gets a thin coat.","Fry at 170°C in batches for 2 minutes each. When all are done, raise the heat and fry them all again together for 1 minute.","Fry minced garlic in a little oil, add the fish and toss with the pepper salt and scallion."],
   tips:["Frying twice gives the crispest result, bones and all.","Too many at once lowers the oil temperature, so work in batches.","Fresh anchovies are rare in Japan. Small sardines (小いわし) are the closest substitute."]},
  "小鱼干高汤":{serves:"About 1 liter",time:"15 min (plus 30+ min soaking)",
   ingT:[["Dried anchovies (niboshi)","20g (about 15)"]],
   sauceT:[["Water","1 liter"]],
   steps:["Pinch off the heads, split the bodies and remove the dark guts (they're bitter).","Put them in a pot with the water and soak at least 30 minutes (overnight in the fridge is best).","Heat over medium. Just before boiling, turn to low, skim and simmer 5 minutes.","Strain through a sieve lined with paper towel.","Use for miso soup, udon broth or simmered dishes."],
   tips:["Removing the guts keeps the stock from tasting bitter.","Dry-toasting the anchovies before soaking makes the stock more fragrant.","A common stock in western Japan. Keeps 2–3 days in the fridge."]},
  "西班牙醋腌鳀鱼":{serves:"3–4",time:"30 min (plus overnight marinating)",
   ingT:[["Fresh anchovies or small sardines (sashimi grade)","300g"],["Garlic","2 cloves"],["Parsley","1 bunch"]],
   sauceT:[["White wine or rice vinegar","200ml"],["Water","50ml"],["Salt","1 tsp"],["Olive oil","4 tbsp"]],
   steps:["Freeze the fish at −20°C for at least 48 hours first to kill parasites, then thaw in the fridge.","Pinch off the heads, open the fish along the backbone with your fingers, remove the bone and guts to make butterfly fillets, and rinse.","Lay skin side down in a dish, cover with the vinegar, water and salt mixed, and refrigerate 6 hours to overnight. The flesh turns white.","Pour off the vinegar and pat dry.","Arrange on a plate, drizzle with olive oil, scatter minced garlic and parsley, and chill 1 hour before eating."],
   tips:["Vinegar does not kill parasites, so never skip the freezing.","A classic Spanish bar tapa with bread and beer.","Covered in olive oil, it keeps 5 days in the fridge."]},
  "马来椰浆饭配炸江鱼仔":{serves:"2",time:"50 min",
   ingT:[["Rice (ideally jasmine)","1.5 rice-cooker cups (about 220g)"],["Small dried anchovies (ikan bilis)","40g"],["Peanuts","40g"],["Eggs","2"],["Cucumber","1/2"],["Pandan leaves (optional)","2"]],
   sauceT:[["Coconut milk","200ml"],["Water","150ml"],["Salt","1/2 tsp"],["Ginger","2 slices"],["Sambal (store-bought or homemade)","4 tbsp"],["Sugar","1 tsp"],["Cooking oil","as needed"]],
   steps:["Wash the rice and cook in a rice cooker with the coconut milk, water, salt, ginger and knotted pandan leaves.","Hard-boil the eggs for 9 minutes, peel and halve. Slice the cucumber.","Heat 2cm of oil and fry the peanuts on low for 3–4 minutes until lightly golden. Remove, then fry the anchovies 1–2 minutes until crisp.","Leave 1 tbsp oil in the pan, fry the sambal, and stir in the sugar and half the fried anchovies.","Mound the coconut rice in the center and arrange the anchovies, peanuts, egg, cucumber and sambal around it."],
   tips:["Malaysia's national breakfast, often wrapped in a banana leaf.","Fry the anchovies and peanuts on low. They burn easily.","Sambal is sold at KALDI and Asian grocers."]}}},
 shirasu:{d:{
  "吻仔鱼粥":{serves:"2",time:"40 min",
   ingT:[["Rice","1/2 cup (about 90g)"],["Boiled whitebait (shirasu)","50g"],["Ginger","1 small piece"],["Celery leaves or scallion","a little"]],
   sauceT:[["Water","1 liter"],["Salt","1/2 tsp"],["White pepper","a little"],["Sesame oil (optional)","a few drops"]],
   steps:["Wash the rice, mix with a few drops of oil and rest 15 minutes (for a silkier porridge).","Bring the water to a boil, add the rice, return to a boil, then simmer on low with the lid ajar for 25–30 minutes, stirring now and then so it doesn't stick.","Cut the ginger into fine strips and chop the celery leaves.","When thick, add the whitebait and ginger and cook 1 minute.","Season with salt and white pepper, scatter with celery leaves and add a few drops of sesame oil."],
   tips:["Boiled shirasu is already salty, so taste before seasoning.","For a quick version, simmer leftover rice with water for 10 minutes.","Good for breakfast or when your appetite is low."]},
  "萝卜泥拌银鱼":{serves:"2",time:"5 min",
   ingT:[["Boiled whitebait (shirasu)","40g"],["Daikon","5cm piece"],["Shiso or scallion (optional)","a little"]],
   sauceT:[["Ponzu or soy sauce","as needed"]],
   steps:["Grate the daikon and let it drain lightly in a sieve (don't squeeze it too dry).","Put the grated daikon in a small bowl.","Pile the whitebait on top and add scallion or shredded shiso.","Pour over ponzu or soy sauce when eating."],
   tips:["The end of the daikon near the leaves is sweeter and best for grating.","A standard izakaya nibble.","Over hot rice it becomes shirasu-don."]}}}
});
