window.ADD_I18N("ja", {
 kasago:{d:{
  "石九公汤":{serves:"2〜3",time:"30分",
   ingT:[["かさご","2尾（約400g）"],["絹ごし豆腐","1丁"],["生姜","1かけ"],["小ねぎかパクチー","少々"]],
   sauceT:[["サラダ油","大さじ2"],["熱湯","800ml"],["料理酒","大さじ1"],["塩","小さじ1"],["白こしょう","少々"]],
   steps:["かさごのうろこ・えら・内臓を取り（背びれは硬くとげがあるので先にはさみで切る）、洗って水気をふく。","鍋を熱して油と生姜の薄切りを入れ、かさごを中火で両面うっすら色づくまで焼く。","料理酒をふり、沸騰した湯を注いで強火で10分煮立てると、スープが乳白色になる。","豆腐を切って加え、中火でさらに5分煮る。","塩と白こしょうで味をととのえ、小ねぎかパクチーを散らす。"],
   tips:["必ず熱湯を注いで強火を保つと、スープが白くなる。","背びれのとげが刺さるので、手袋かはさみを使う。","味噌汁にしてもおいしい。"]},
  "石狗公味噌汤":{serves:"3",time:"25分",
   ingT:[["かさご（小）","2尾"],["小ねぎ","2本"],["豆腐（お好みで）","1/3丁"]],
   sauceT:[["水","800ml"],["酒","大さじ2"],["味噌","大さじ3"]],
   steps:["かさごの背びれのとげを切り、うろこ・えら・内臓を取って2〜3つに切る。","熱湯をかけてから冷水で血や残ったうろこを洗う。","鍋に水とかさごを入れて中火にかけ、煮立ったらアクを取り、酒を加えて弱火で10分、うまみを出す。","豆腐を入れ、弱火にして味噌を溶き入れる。","煮立つ直前で火を止め、小ねぎを散らす。"],
   tips:["だしは不要。魚からとてもおいしいだしが出る。","かさごのとげは硬いので、扱いに注意。","海辺の民宿や居酒屋で人気の味噌汁。"]},
  "马赛鱼汤":{serves:"4",time:"1.5時間",
   ingT:[["数種の岩礁の魚（かさご・めばる・鯛など）","1kg（骨付き）"],["えびかムール貝（お好みで）","300g"],["玉ねぎ","1個"],["フェンネルかセロリ","1/2個"],["トマト","2個"],["にんにく","4かけ"],["じゃがいも","2個"],["バゲット","1/2本"]],
   sauceT:[["オリーブオイル","大さじ5"],["サフラン","ひとつまみ"],["オレンジの皮","小1片"],["タイム・ローリエ","各少々"],["塩・こしょう","適量"],["マヨネーズ＋にんにく＋カイエン（ルイユ）","大さじ4"],["水","1.5L"]],
   steps:["魚のうろこと内臓を取り、身は大きめに切り、頭と骨はスープ用に取っておく。","鍋にオリーブオイルを入れ、玉ねぎ・フェンネル・にんにくを5分炒め、トマト・骨・頭を加えて3分炒める。","水・サフラン・オレンジの皮・ハーブを加えて強火で30分煮て、ざるでこし、骨を押してエキスをしぼる。","スープを鍋に戻し、薄切りのじゃがいもを入れて10分煮る。","魚の身を入れ（身の硬いものから）、強火で8分、最後にえびとムール貝を入れて3分煮て、塩・こしょうで調える。","バゲットを薄切りにしてカリッと焼き、ルイユ（にんにくと唐辛子のマヨネーズ）を塗ってスープにひたして食べる。"],
   tips:["強火で煮るとオリーブオイルとスープが乳化して濃厚になる。","マルセイユでは先にスープを飲み、あとで魚を食べるのが伝統。","スーパーのあらでスープを取るのがいちばんお得。"]}}},
 mebaru:{d:{
  "清蒸黑鲪":{serves:"2",time:"20分",
   ingT:[["めばる（下処理済み）","1尾（約350g）"],["生姜","1かけ"],["長ねぎ","1/2本"]],
   sauceT:[["塩","少々"],["料理酒","大さじ1"],["蒸魚醤油","大さじ2"],["サラダ油","大さじ2"]],
   steps:["魚の水気をふき、両面に切り込みを入れ、塩と料理酒を少しまぶす。","皿にねぎを敷いて魚をのせ、身の上と腹に生姜の薄切りをのせる。","湯が沸いた蒸し器に入れ、強火で10分。いちばん厚いところに箸がすっと通れば完成。","汁を捨てて生姜を除き、ねぎと生姜のせん切りをのせる。","煙が出るほど熱した油をかけ、蒸魚醤油を回しかける。"],
   tips:["必ず湯が沸いてから魚を入れると、ふっくらする。","蒸し上がったらすぐ取り出す。蒸し器に置いたままだと硬くなる。","白身魚ならどれでもこの方法で。"]},
  "辣炖黑鲪":{serves:"3",time:"40分",
   ingT:[["めばるかそいなどの白身魚（丸ごと）","1尾（約400g）"],["大根","1/6本"],["木綿豆腐","1/2丁"],["春菊","1束"],["長ねぎ","1/2本"],["ズッキーニ（お好みで）","1/2本"],["青・赤唐辛子","各1本"]],
   sauceT:[["煮干しか昆布だし","1L"],["韓国唐辛子粉","大さじ2"],["コチュジャン","大さじ1"],["テンジャンか味噌","小さじ1"],["おろしにんにく","大さじ1"],["薄口醤油","大さじ1"],["酒","大さじ2"]],
   steps:["魚のうろこと内臓を取り、3〜4つに切って熱湯をかけてから洗う。","大根は薄切り、豆腐とズッキーニは角切り、ねぎと唐辛子は斜め切り、春菊はざく切りにする。","唐辛子粉・コチュジャン・テンジャン・にんにく・醤油・酒を混ぜてたれにする。","だしと大根を8分煮て、たれを溶き入れる。","魚を入れて10分、豆腐とズッキーニを加えてさらに5分煮る。","最後に春菊・ねぎ・唐辛子を入れ、30秒で火を止める。"],
   tips:["韓国の辛い魚鍋（メウンタン）。刺身を取ったあとのあらで作るのが本場流。","春菊は最後に入れて香りを残す。","すいとん（スジェビ）を入れてもおいしい。"]}}},
 suzuki:{d:{
  "冰镇鲈鱼":{serves:"2",time:"20分",
   ingT:[["刺身用すずき（さく）","150g"],["氷水","ボウル1杯"],["大葉・大根のつま","適量"]],
   sauceT:[["白味噌","大さじ2"],["酢","大さじ1"],["砂糖","大さじ1"],["からし","小さじ1/2"],["または醤油＋わさび","適量"]],
   steps:["白味噌・酢・砂糖・からしを混ぜて、からし酢味噌を作る。","すずきの皮を引き、斜めに2〜3mmの薄切りにする。","ボウルに氷水を用意し、身を入れて箸でやさしく30秒〜1分混ぜる。","身が縮んで反り返り、白くコリッとしたら引き上げ、キッチンペーパーで水気をふく。","皿に氷・大葉・つまを敷いて身を盛り、酢味噌かわさび醤油を添える。"],
   tips:["氷水で身が締まり、余分な脂が抜けて歯ごたえがよくなる。","夏の風物詩。鯉でも同じように作れる。","長くつけると味が抜けるので、1分以内に。"]},
  "盐焗海鲈":{serves:"3〜4",time:"50分",
   ingT:[["すずき（内臓のみ除去、うろこ付き）","1尾（約800g）"],["レモン","1個"],["ローズマリー・タイム","各2枝"],["にんにく","2かけ"]],
   sauceT:[["粗塩","1.5kg"],["卵白","2〜3個分"],["オリーブオイル（添える用）","適量"]],
   steps:["オーブンを200°Cに予熱する。魚を洗って水気をふき、腹にレモンの薄切り・ハーブ・つぶしたにんにくを詰める。","粗塩に卵白と少量の水を混ぜ、湿った砂のように握って固まる状態にする。","天板にクッキングシートを敷き、塩を1cm厚さに広げて魚をのせ、残りの塩で魚全体をすき間なく覆って押し固める（尾は出ていてよい）。","25〜30分焼く（500gにつき約15分）。","食卓で包丁の背で塩の殻を割り、皮をはがして（うろこも一緒に取れる）身を取り分け、オリーブオイルとレモン汁をかける。"],
   tips:["塩の殻が水分を閉じ込め、身はしっとりなのに塩辛くない。","うろこを残すのは身を守り、塩辛くならないため。","殻を割る瞬間が盛り上がるので、おもてなしに。"]}}},
 isaki:{d:{
  "豉油蒸鸡鱼":{serves:"2",time:"20分",
   ingT:[["いさき（下処理済み）","1尾（約350g）"],["生姜","1かけ"],["長ねぎ","1/2本"],["パクチー（お好みで）","1本"]],
   sauceT:[["料理酒","大さじ1"],["蒸魚醤油","大さじ3"],["砂糖","小さじ1/2"],["サラダ油","大さじ2"]],
   steps:["魚の水気をふき、両面に斜めに3本ずつ切り込みを入れ、料理酒をまぶす。","皿に生姜の薄切りとねぎを敷いて魚をのせ、切り込みにも生姜をはさむ。","湯が沸いた蒸し器に入れ、強火で10分蒸す。","汁を捨て、ねぎ・生姜のせん切りとパクチーをのせる。","蒸魚醤油に砂糖と熱湯大さじ1を混ぜて皿の縁から回しかけ、煙が出るまで熱した油をねぎにかける。"],
   tips:["いさきは初夏がいちばん脂がのる「梅雨いさき」。","醤油を少し薄めると塩辛くなりすぎず、ご飯にかけられる。","必ず湯が沸いてから魚を入れる。"]},
  "三线矶鲈刺身":{serves:"2",time:"20分",
   ingT:[["刺身用いさき（さく、皮付き）","150g"],["生姜","1かけ"],["大葉","4枚"]],
   sauceT:[["醤油","適量"],["塩（炙り用）","少々"]],
   steps:["皮を上にして網にのせ、熱湯をかけて皮を縮ませ（皮霜）、すぐ氷水にとって水気をふく。またはバーナーで皮目をあぶる（炙り）。","冷蔵庫で5分冷やし、7mm厚さに切る。","生姜をすりおろす。","皿に大葉を敷いて刺身を盛り、おろし生姜と醤油を添える。"],
   tips:["いさきは皮がおいしいので、皮霜か炙りで皮を残すのがいちばん。","梅雨時（6〜7月）がいちばん脂がのる。","皮を引いた刺身にしてわさびで食べても。"]},
  "意式香煎":{serves:"2",time:"20分",
   ingT:[["いさきの切り身（皮付き）","2枚"],["ミニトマト","8個"],["にんにく","1かけ"],["ブラックオリーブ","6個"],["ケッパー","小さじ1"],["パセリかバジル","少々"]],
   sauceT:[["塩・こしょう","少々"],["オリーブオイル","大さじ3"],["白ワイン","50ml"]],
   steps:["切り身の水気をふき、両面に塩・こしょうをふる。","フライパンにオリーブオイル大さじ2を入れて中火にし、皮を下にして入れ、へらで10秒押さえて4分、皮がパリッとするまで焼く。","返して1分焼き、取り出す。","残りのオリーブオイルとにんにくの薄切りを30秒炒め、ミニトマト・オリーブ・ケッパーを入れる。","白ワインを注いで2分、トマトがはじけ始めるまで煮て、味見して塩で調える。","ソースを皿に敷き、皮を上にして魚をのせ（皮のパリッと感を保つ）、パセリを散らす。"],
   tips:["皮を上にして盛ると、ソースで皮がふやけない。","白身魚の切り身ならどれでも作れる。","パンでソースをぬぐって食べて。"]}}},
 kawahagi:{d:{
  "马面鱼干":{serves:"2〜4（おつまみ）",time:"5分",
   ingT:[["カワハギのみりん干しかロースト","1袋（約80g）"],["マヨネーズ（お好みで）","適量"]],
   sauceT:[["七味唐辛子（お好みで）","少々"]],
   steps:["スーパーやコンビニの味付きカワハギの干物を買う（中国では「馬面魚干」「烤魚片」と呼ぶ）。","油をひかないフライパンを弱火で熱し、干物を入れて片面20〜30秒ずつ、縁が少し反ってやわらかくなり香りが立つまで焼く。","電子レンジで10〜20秒、またはトースターで1分でもよい。","熱いうちに裂いて、七味入りのマヨネーズをつけて食べる。"],
   tips:["焼きすぎると硬く苦くなる。反ってきたら火から外す。","日本では「カワハギのみりん干し」として居酒屋の定番のおつまみ。","湿気ないよう密閉袋で保存する。"]},
  "肝酱油刺身":{serves:"2",time:"25分",
   ingT:[["カワハギ（肝付き・新鮮なもの）","1尾（約300g）"],["あさつき","2本"],["大葉","2枚"]],
   sauceT:[["醤油","大さじ2"],["酒（お好みで）","小さじ1"],["塩（肝の下処理用）","少々"]],
   steps:["頭のうしろに切り込みを入れ、ざらざらした皮を手で一気にはぐ。胆のう（緑色）を破らないよう、肝をそっと取り出す。","肝に塩少々をふって10分置いて洗い、熱湯に10秒くぐらせて氷水にとる（安全で、つぶしやすくもなる）。","身を三枚におろして薄皮を取り、ふぐ刺しのように薄造りにする。","肝を包丁でたたくか裏ごししてペーストにし、醤油と酒を混ぜて「肝醤油」を作る。","刺身を盛ってあさつきを添え、刺身でねぎを巻いて肝醤油につけて食べる。"],
   tips:["肝はとても新鮮なもの、できれば活魚のものを。不安なら肝を蒸してから使う。","秋冬は肝が大きく脂がのり、「海のフォアグラ」と呼ばれる。","魚屋さんに頼めばさばいてくれることが多い。"]}}}
});
window.ADD_I18N("en", {
 kasago:{d:{
  "石九公汤":{serves:"2–3",time:"30 min",
   ingT:[["Scorpionfish","2 (about 400g)"],["Silken tofu","1 block"],["Ginger","1 piece"],["Scallion or cilantro","a little"]],
   sauceT:[["Cooking oil","2 tbsp"],["Boiling water","800ml"],["Shaoxing or cooking wine","1 tbsp"],["Salt","1 tsp"],["White pepper","a little"]],
   steps:["Scale, gill and gut the fish (snip off the hard, spiny dorsal fin first), rinse and pat dry.","Heat oil with ginger slices and fry the fish over medium until lightly golden on both sides.","Splash in the wine, pour in boiling water and boil hard for 10 minutes. The soup turns milky white.","Add cubed tofu and cook 5 minutes over medium.","Season with salt and white pepper and sprinkle with scallion or cilantro."],
   tips:["Pour in boiling water and keep the heat high, or the soup won't turn white.","The dorsal spines are sharp. Use gloves or scissors.","It also makes great miso soup."]},
  "石狗公味噌汤":{serves:"3",time:"25 min",
   ingT:[["Small scorpionfish","2"],["Scallions","2"],["Tofu (optional)","1/3 block"]],
   sauceT:[["Water","800ml"],["Sake","2 tbsp"],["Miso","3 tbsp"]],
   steps:["Snip off the dorsal spines, scale, gill and gut the fish and cut into 2–3 pieces.","Pour boiling water over, then rinse off blood and leftover scales in cold water.","Put the fish in cold water and heat over medium. When it boils, skim, add the sake and simmer on low for 10 minutes.","Add the tofu, turn the heat to low and dissolve the miso.","Turn off the heat just before it boils and add scallions."],
   tips:["No dashi needed. The fish makes a very flavorful broth.","Scorpionfish spines are hard, so handle with care.","A favorite at seaside inns and izakaya."]},
  "马赛鱼汤":{serves:"4",time:"1.5 hours",
   ingT:[["Mixed rockfish (scorpionfish, rockfish, sea bream etc.)","1kg, bone-in"],["Shrimp or mussels (optional)","300g"],["Onion","1"],["Fennel or celery","1/2"],["Tomatoes","2"],["Garlic","4 cloves"],["Potatoes","2"],["Baguette","1/2"]],
   sauceT:[["Olive oil","5 tbsp"],["Saffron","a pinch"],["Orange peel","1 small strip"],["Thyme and bay leaf","a little each"],["Salt and pepper","as needed"],["Mayonnaise with garlic and cayenne (rouille)","4 tbsp"],["Water","1.5 liters"]],
   steps:["Scale and gut the fish, cut the flesh into large pieces and keep the heads and bones for stock.","Cook the onion, fennel and garlic in olive oil for 5 minutes, then add the tomatoes, bones and heads for 3 minutes.","Add the water, saffron, orange peel and herbs, boil hard for 30 minutes, then strain, pressing the bones to extract the juices.","Return the broth to the pot and simmer sliced potatoes for 10 minutes.","Add the fish (firmest first) and boil hard for 8 minutes. Add the shrimp and mussels for the last 3 minutes and season.","Toast slices of baguette, spread with rouille and dunk them in the soup."],
   tips:["A hard boil emulsifies the olive oil into the broth and thickens it.","In Marseille, the broth is served first and the fish after.","Supermarket fish trimmings make the most economical stock."]}}},
 mebaru:{d:{
  "清蒸黑鲪":{serves:"2",time:"20 min",
   ingT:[["Whole rockfish, cleaned","1 (about 350g)"],["Ginger","1 piece"],["Japanese leek (negi)","1/2"]],
   sauceT:[["Salt","a little"],["Shaoxing or cooking wine","1 tbsp"],["Seasoned soy for fish","2 tbsp"],["Cooking oil","2 tbsp"]],
   steps:["Pat the fish dry, score both sides and rub with a little salt and wine.","Lay leek pieces on a plate, put the fish on top and add ginger slices on and inside the fish.","Steam over boiling water on high for 10 minutes. It's done when a chopstick goes easily into the thickest part.","Pour off the liquid, remove the ginger and top with shredded leek and ginger.","Pour over smoking-hot oil, then drizzle with the soy."],
   tips:["Only add the fish once the water is boiling so it stays tender.","Take it out as soon as it's done. Sitting in the steamer toughens it.","This method works for any white fish."]},
  "辣炖黑鲪":{serves:"3",time:"40 min",
   ingT:[["Whole rockfish or other white fish","1 (about 400g)"],["Daikon","1/6"],["Firm tofu","1/2 block"],["Garland chrysanthemum","1 bunch"],["Japanese leek (negi)","1/2"],["Zucchini (optional)","1/2"],["Green and red chilies","1 each"]],
   sauceT:[["Anchovy or kombu stock","1 liter"],["Korean chili powder","2 tbsp"],["Gochujang","1 tbsp"],["Doenjang or miso","1 tsp"],["Grated garlic","1 tbsp"],["Soup soy sauce","1 tbsp"],["Sake","2 tbsp"]],
   steps:["Scale and gut the fish, cut into 3–4 pieces, pour boiling water over and rinse.","Slice the daikon, cube the tofu and zucchini, cut the leek and chilies diagonally, and cut the chrysanthemum into lengths.","Mix the chili powder, gochujang, doenjang, garlic, soy sauce and sake into a paste.","Simmer the stock and daikon for 8 minutes, then dissolve in the paste.","Add the fish and simmer 10 minutes, then the tofu and zucchini for 5 more.","Finally add the chrysanthemum, leek and chilies and turn off the heat after 30 seconds."],
   tips:["Korean spicy fish stew (maeuntang). It's most authentic made with bones left from sashimi.","Add the chrysanthemum last to keep its aroma.","Hand-torn dough (sujebi) is a good addition."]}}},
 suzuki:{d:{
  "冰镇鲈鱼":{serves:"2",time:"20 min",
   ingT:[["Sashimi-grade sea bass block","150g"],["Ice water","1 large bowl"],["Shiso and shredded daikon","as needed"]],
   sauceT:[["White miso","2 tbsp"],["Vinegar","1 tbsp"],["Sugar","1 tbsp"],["Japanese mustard","1/2 tsp"],["Or soy sauce and wasabi","as needed"]],
   steps:["Mix the white miso, vinegar, sugar and mustard into a mustard-vinegar miso.","Skin the fish and slice diagonally 2–3mm thick.","Fill a bowl with ice water, add the slices and stir gently with chopsticks for 30 seconds to 1 minute.","When the slices shrink, curl and turn white and firm, lift them out and blot dry.","Arrange on ice with shiso and daikon and serve with the miso or wasabi soy."],
   tips:["The ice water firms the flesh and removes excess fat for a crisp bite.","A summer classic. Carp can be done the same way.","Don't leave them in longer than a minute or they lose flavor."]},
  "盐焗海鲈":{serves:"3–4",time:"50 min",
   ingT:[["Whole sea bass, gutted but not scaled","1 (about 800g)"],["Lemon","1"],["Rosemary and thyme","2 sprigs each"],["Garlic","2 cloves"]],
   sauceT:[["Coarse salt","1.5kg"],["Egg whites","2–3"],["Olive oil (to serve)","as needed"]],
   steps:["Preheat the oven to 200°C. Rinse and dry the fish and stuff the belly with lemon slices, herbs and crushed garlic.","Mix the salt with the egg whites and a little water until it feels like damp sand that holds together.","Line a tray with parchment, spread a 1cm layer of salt, lay the fish on it and pack the rest of the salt over it to seal completely (the tail can stick out).","Bake 25–30 minutes (about 15 minutes per 500g).","At the table, crack the crust with the back of a knife, peel off the skin (the scales come with it), lift off the flesh and dress with olive oil and lemon."],
   tips:["The crust seals in moisture, so the fish is juicy but not salty.","Leaving the scales on protects the flesh from the salt.","Cracking the crust is a showpiece for guests."]}}},
 isaki:{d:{
  "豉油蒸鸡鱼":{serves:"2",time:"20 min",
   ingT:[["Whole grunt (isaki), cleaned","1 (about 350g)"],["Ginger","1 piece"],["Japanese leek (negi)","1/2"],["Cilantro (optional)","1 sprig"]],
   sauceT:[["Shaoxing or cooking wine","1 tbsp"],["Seasoned soy for fish","3 tbsp"],["Sugar","1/2 tsp"],["Cooking oil","2 tbsp"]],
   steps:["Pat the fish dry, make 3 diagonal cuts on each side and rub with wine.","Lay ginger and leek on a plate, put the fish on top and tuck ginger into the cuts.","Steam over boiling water on high for 10 minutes.","Pour off the liquid and top with shredded leek, ginger and cilantro.","Mix the soy with the sugar and 1 tbsp hot water and pour around the plate, then pour smoking-hot oil over the leek."],
   tips:["Grunt is fattiest in early summer, called rainy-season isaki in Japan.","Diluting the soy keeps it from being too salty, so you can spoon it over rice.","Only add the fish once the water is boiling."]},
  "三线矶鲈刺身":{serves:"2",time:"20 min",
   ingT:[["Sashimi-grade grunt block, skin on","150g"],["Ginger","1 small piece"],["Shiso leaves","4"]],
   sauceT:[["Soy sauce","as needed"],["Salt (for searing)","a little"]],
   steps:["Lay the fish skin up on a rack, pour boiling water over to tighten the skin, plunge into ice water and pat dry. Or sear the skin with a torch.","Chill 5 minutes and slice 7mm thick.","Grate the ginger.","Line a plate with shiso, add the fish and serve with ginger and soy sauce."],
   tips:["Grunt skin is tasty, so scalding or searing it is the best way to keep it.","Fattiest in the rainy season (June–July).","Skinless sashimi with wasabi works too."]},
  "意式香煎":{serves:"2",time:"20 min",
   ingT:[["Grunt fillets, skin on","2"],["Cherry tomatoes","8"],["Garlic","1 clove"],["Black olives","6"],["Capers","1 tsp"],["Parsley or basil","a little"]],
   sauceT:[["Salt and black pepper","a little"],["Olive oil","3 tbsp"],["White wine","50ml"]],
   steps:["Pat the fillets dry and season both sides.","Heat 2 tbsp olive oil over medium, lay the fish skin side down, press with a spatula for 10 seconds and cook 4 minutes until crisp.","Flip, cook 1 minute and remove.","Add the remaining oil and sliced garlic for 30 seconds, then the tomatoes, olives and capers.","Pour in the wine and simmer 2 minutes until the tomatoes start to burst. Taste and salt.","Spoon the sauce onto plates, set the fish on top skin side up (to keep it crisp) and scatter with parsley."],
   tips:["Plating skin side up keeps the skin from going soggy in the sauce.","Works with any white fish fillet.","Mop up the sauce with bread."]}}},
 kawahagi:{d:{
  "马面鱼干":{serves:"2–4 (as a snack)",time:"5 min",
   ingT:[["Seasoned dried filefish","1 bag (about 80g)"],["Mayonnaise (optional)","as needed"]],
   sauceT:[["Shichimi or chili powder (optional)","a little"]],
   steps:["Buy seasoned dried filefish from a supermarket or convenience store.","Heat a dry frying pan over low heat and toast each side for 20–30 seconds until the edges curl slightly, soften and smell toasty.","Or microwave 10–20 seconds, or toast 1 minute in a toaster oven.","Tear into strips while warm and dip in mayonnaise with shichimi."],
   tips:["Overtoasting makes it hard and bitter. Take it off as soon as it curls.","In Japan it's sold as カワハギのみりん干し, a classic izakaya snack.","Store in an airtight bag to keep it from going soft."]},
  "肝酱油刺身":{serves:"2",time:"25 min",
   ingT:[["Very fresh filefish with liver","1 (about 300g)"],["Thin chives","2"],["Shiso leaves","2"]],
   sauceT:[["Soy sauce","2 tbsp"],["Sake (optional)","1 tsp"],["Salt (for the liver)","a little"]],
   steps:["Cut behind the head and peel off the rough skin in one piece. Remove the liver carefully without breaking the green gallbladder.","Salt the liver, rest 10 minutes, rinse, dip in boiling water for 10 seconds and chill in ice water (safer and easier to mash).","Fillet the fish into three pieces, remove the thin skin and slice very thinly, like fugu sashimi.","Chop the liver or press through a sieve into a paste and mix with the soy sauce and sake to make liver soy.","Arrange the sashimi with the chives. Wrap a few chives in a slice and dip in the liver soy."],
   tips:["The liver must be very fresh, ideally from a live fish. If unsure, steam it first.","In autumn and winter the liver is large and rich, called the foie gras of the sea.","Fishmongers will usually clean it for you."]}}}
});
