window.ADD_I18N("ja", {
 fugu:{d:{
  "红烧河豚":{serves:"2〜3",time:"45分",
   ingT:[["下処理済みふぐ（身欠きふぐ、骨付き）","400g"],["豚バラ肉","100g"],["生姜","1かけ"],["長ねぎ","1本"],["にんにく","4かけ"]],
   sauceT:[["ラードかサラダ油","大さじ2"],["紹興酒","大さじ3"],["醤油","大さじ2"],["たまり醤油","小さじ1"],["氷砂糖","20g"],["湯","400ml"]],
   steps:["免許を持つ専門家が処理したふぐ（スーパーや魚屋の「身欠きふぐ」）だけを使う。絶対に自分で丸ごとのふぐをさばかない。","ふぐを水から入れて1分下ゆでし、洗う。豚バラは薄切りにする。","鍋にラードを入れて豚バラを炒めて脂を出し、生姜・ねぎ・にんにくを炒めて香りを出し、氷砂糖を加えて溶かす。","ふぐを入れて紹興酒をふり、醤油・たまり醤油・湯を加える。","強火で煮立てて弱火にし、ふたをして25分、ふぐの皮がとろりとやわらかくなるまで煮る。","ふたを取って強火で煮詰め、とろりとつやが出たら完成。"],
   tips:["ふぐの肝や卵巣などは猛毒。日本では免許のある人しか処理できないので、処理済みの身だけを買う。","江蘇省揚中・靖江一帯の伝統料理。煮汁が濃厚。","ふぐの皮はゼラチン質が多く、やわらかく煮るといちばんおいしい。"]},
  "河豚刺身":{serves:"2",time:"10分",
   ingT:[["てっさ（市販品・ふぐ処理済み）","1皿"],["あさつき","3本"],["もみじおろし","適量"],["ふぐの皮（付属、お好みで）","適量"]],
   sauceT:[["ポン酢","適量"]],
   steps:["ふぐは猛毒があるので、必ず資格を持つ専門家が処理して切った市販の刺身（スーパーや通販の「てっさ」）を買う。絶対に自分でさばかない。","冷凍品は冷蔵庫でゆっくり解凍する。","あさつきを4cm長さに切り、もみじおろしと一緒に皿の中央に置く。","小皿にポン酢を入れ、もみじおろしとあさつきを少し加える。","箸で2〜3枚まとめてつまみ、あさつきを巻いてポン酢につけて食べる。"],
   tips:["日本の法律で、ふぐは免許を持つ「ふぐ調理師」しか処理できない。","身の弾力が強いので、透けるほど薄く切る。","冬が旬。山口県下関が有名。"]},
  "炸河豚":{serves:"2",time:"30分（漬け20分）",
   ingT:[["ふぐの唐揚げ用（処理済み、骨付き）","300g"],["レモンかすだち","1/2個"]],
   sauceT:[["醤油","大さじ1.5"],["酒","大さじ1"],["おろし生姜","小さじ1"],["片栗粉","大さじ4"],["揚げ油","鍋底から3cm"]],
   steps:["専門家が処理したふぐ（魚屋や通販の「ふぐの唐揚げ用」）だけを使う。","ふぐの水気をふき、醤油・酒・生姜をもみ込んで20分漬ける。","汁気をきり、片栗粉をたっぷりまぶす。","170°Cの油で4分揚げ、取り出して2分休ませ、190°Cで1分二度揚げする。","レモンを搾り、熱いうちに。"],
   tips:["ふぐの肝や卵巣などは猛毒。処理済みのものだけを買う。","骨付きの部分をかじるのがいちばん香ばしい。","鶏の唐揚げより弾力がある、ふぐ料理の人気メニュー。"]}}},
 anago:{d:{
  "红烧星鳗":{serves:"2〜3",time:"40分",
   ingT:[["生あなご（開き）","2尾（約300g）"],["生姜","1かけ"],["長ねぎ","1本"]],
   sauceT:[["紹興酒","大さじ2"],["醤油","大さじ2"],["たまり醤油","小さじ1"],["氷砂糖","20g"],["サラダ油","大さじ2"],["湯","250ml"]],
   steps:["あなごの皮を上にしてざるにのせ、熱湯をかけて包丁の背で皮のぬめりをこそげ、洗って5cm幅に切る。","鍋に油を熱し、あなごを中火で両面うっすら色づくまで焼いて取り出す。","生姜とねぎを炒めて香りを出し、氷砂糖を加えて溶かす。","あなごを戻して紹興酒をふり、醤油・たまり醤油・湯を加えて弱火で15分煮る。","ふたを取って煮詰め、鍋をゆすってあなごにたれを均一にからめる。"],
   tips:["ぬめり取りが臭み消しの要。","あなごはうなぎより身が薄いので、15分で十分。","市販の「煮あなご」をたれで温め直しても。"]},
  "煮星鳗寿司":{serves:"2",time:"50分",
   ingT:[["生あなご（開き）","2尾"],["米","1合"]],
   sauceT:[["水","300ml"],["酒","100ml"],["醤油","大さじ3"],["砂糖","大さじ2"],["みりん","大さじ2"],["すし酢","大さじ1.5"]],
   steps:["あなごの皮を上にして網にのせ、熱湯をかけて包丁の背で白いぬめりをこそげ、洗う。","鍋に水・酒・醤油・砂糖・みりんを煮立て、あなごを皮を上にして平らに入れ、アルミホイルで落とし蓋をして弱火で15〜20分。煮立たせない。","火を止め、煮汁につけたまま冷ます（味がしみてやわらかくなる）。","あなごを取り出し、煮汁をさらに弱火で15分、はちみつくらいのとろみになるまで煮詰めて「ツメ」にする。","酢飯を握り、あなごを切ってのせ、ツメを塗る。ご飯にのせて丼にしてもよい。"],
   tips:["あなごはやわらかいので、へらで支えて取り出す。","市販の「煮あなご」を使えば、ツメを作るだけ。","東京の江戸前寿司の代表。"]},
  "天妇罗星鳗":{serves:"2",time:"30分",
   ingT:[["生あなご（開き）","2尾"],["大根おろし","適量"]],
   sauceT:[["薄力粉","60g＋打ち粉少々"],["冷水","100ml"],["卵","1/2個"],["揚げ油","鍋底から3cm"],["天つゆ（だし4：醤油1：みりん1）","適量"],["塩","少々"]],
   steps:["あなごに熱湯をかけてぬめりをこそげ、水気をふき、長ければ2つに切る。","天つゆ：だし・醤油・みりんを煮立てて冷ます。","卵と冷水を混ぜ、薄力粉を加えて箸でざっと混ぜ（粉が残ってよい）、ゆるい衣を作る。","あなごに薄く打ち粉をし、衣をつける。","油を175°Cに熱し、皮を下にして2〜3分、返して1分、衣が薄いきつね色でカリッとするまで揚げる。","大根おろしと天つゆ、または塩で。"],
   tips:["衣は混ぜすぎず、冷たく。サクッと揚がる。","あなごは油に入れると丸まるので、箸で押さえてのばす。","一本揚げをご飯にのせて天つゆをかければ「穴子天丼」。"]}}},
 hamo:{d:{
  "海鳗鲞":{serves:"4",time:"30分（干す2〜3日）",
   ingT:[["はも（大、魚屋で開いてもらう）","1尾（約1kg）"],["竹串か割り箸","数本"],["生姜","1かけ"]],
   sauceT:[["粗塩","大さじ2くらい（魚の重さの3%）"],["料理酒","大さじ3"],["ラードかサラダ油（蒸すとき用）","大さじ1"]],
   steps:["魚屋に頼んで背から一枚に開いてもらい（切り離さない）、中骨を取って洗い、水気をふく。","身の両面に塩と料理酒を均一にすり込み、冷蔵庫で6時間漬ける。","竹串で身を広げ、風通しのよい涼しい場所（冬の屋外か扇風機の前）に吊るし、2〜3日、表面が乾いて押すと弾力があるまで干す。","食べるときはぶつ切りにして皿にのせ、生姜の薄切り、ラード、料理酒少々を加える。","湯が沸いた蒸し器で15分蒸し、冷めたら繊維に沿って裂いて食べる。"],
   tips:["気温10°C以下の冬だけに干す。暖かいと傷みやすい。","浙江省寧波・舟山の正月の保存食。豚バラと一緒に煮込んでも。","日本のはもは小骨が多いので、大きいものを使うと作りやすい。"]},
  "海鳗涮锅":{serves:"2〜3",time:"30分",
   ingT:[["骨切りした鱧","300g"],["玉ねぎ（淡路島産が最高）","1個"],["水菜か三つ葉","1束"],["豆腐（お好みで）","1/2丁"]],
   sauceT:[["昆布だし","1L"],["酒","50ml"],["薄口醤油","大さじ1"],["塩","少々"],["ポン酢","適量"],["梅肉（お好みで）","適量"]],
   steps:["鱧は骨がとても多いので、必ず魚屋で「骨切り」済み（1〜2mmごとに包丁を入れて小骨を断ったもの）を買い、5cm幅に切る。","玉ねぎは1cm厚さの輪切り、水菜はざく切りにする。","鍋にだし・酒・薄口醤油・塩を入れ、まず玉ねぎを5分、甘くなるまで煮る。","鱧をつまんでだしに10〜20秒くぐらせ、身が花のように開いたら食べごろ。","玉ねぎや水菜と一緒にポン酢か梅肉で食べる。"],
   tips:["骨切りはプロの技術なので、家ではおすすめしない。","夏の鱧は京都・大阪を代表する食材。秋の「名残り鱧」も脂がのっている。","最後のだしはとても濃いので、雑炊やうどんに。"]}}},
 shishamo:{d:{
  "椒盐多春鱼":{serves:"2",time:"20分",
   ingT:[["ししゃも（カラフトシシャモ）","10尾"],["にんにく","3かけ"],["赤唐辛子","1本"],["小ねぎ","1本"]],
   sauceT:[["片栗粉","大さじ3"],["花椒塩（花椒粉＋塩）","小さじ1"],["揚げ油","鍋底から2cm"]],
   steps:["ししゃもを解凍してキッチンペーパーで水気をふく（内臓は取らなくてよい）。","ポリ袋に入れて片栗粉を加えて振り、余分な粉を落とす。","油を170°Cに熱して3分揚げて取り出し、油温を上げて30秒二度揚げし、きつね色にカリッとさせる。","鍋に油を少し残し、弱火でにんにく・唐辛子・ねぎのみじん切りを炒める。","ししゃもを入れ、花椒塩をふって手早く混ぜる。"],
   tips:["スーパーの冷凍「カラフトシシャモ」はすでに塩味があるので、花椒塩は控えめに。","子持ちのメスがいちばんおいしい。","揚げたくなければ魚焼きグリルで6〜8分焼いても。"]},
  "柳叶鱼南蛮渍":{serves:"3",time:"30分（冷やし2時間）",
   ingT:[["ししゃも（カラフトシシャモ）","12尾"],["玉ねぎ","1/2個"],["にんじん","1/3本"],["ピーマン","1個"]],
   sauceT:[["米酢","80ml"],["だしか水","80ml"],["醤油","大さじ2"],["砂糖","大さじ2"],["鷹の爪","1本"],["片栗粉","大さじ3"],["揚げ油","鍋底から2cm"]],
   steps:["酢・だし・醤油・砂糖・輪切りの唐辛子を煮立てて保存容器に入れ、玉ねぎ・にんじん・ピーマンのせん切りを漬ける。","ししゃもを解凍して水気をふき、片栗粉をまぶす。","170°Cの油で3分、カリッと揚げる。","熱いうちに南蛮酢につける。","冷蔵庫で2時間以上置いて味をなじませる。"],
   tips:["ししゃもは内臓を取らず、丸ごと使える。","あじの南蛮漬けより簡単で、初心者向き。","冷蔵で3日もつ。"]}}},
 kisu:{d:{
  "椒盐沙钻":{serves:"2",time:"25分",
   ingT:[["きす（小）","8尾"],["にんにく","2かけ"],["小ねぎ","2本"],["赤唐辛子（お好みで）","1本"]],
   sauceT:[["塩","小さじ1/2"],["料理酒","大さじ1"],["片栗粉","大さじ3"],["花椒塩","小さじ1"],["揚げ油","鍋底から2cm"]],
   steps:["きすのうろこを取り、頭と内臓を除いて洗い、水気をふく。スーパーの「きす 開き」ならさらに手軽。","塩と料理酒をまぶして10分置き、水気をふく。","片栗粉を薄くまぶす。","油を170°Cに熱し、2〜3分きつね色に揚げて油をきる。","鍋に油を少し残してにんにく・唐辛子・ねぎを炒め、きすを入れて花椒塩をふって混ぜる。"],
   tips:["きすは身がやわらかいので、揚げすぎない。","皮が薄いので、粉をつけたらすぐ揚げる。時間をおくとしっとりする。","日本では天ぷらが定番だが、これは広東・香港風の食べ方。"]},
  "鱚鱼昆布腌":{serves:"2",time:"20分（冷蔵2〜3時間）",
   ingT:[["きす（刺身用・新鮮なもの）","4尾"],["昆布","2枚"],["大葉","2枚"]],
   sauceT:[["酒","大さじ2"],["塩","少々"],["わさび・醤油","適量"]],
   steps:["きすのうろこ・頭・内臓を取り、二枚におろして骨抜きで中央の骨を抜き、尾のほうから皮をはぐ。スーパーの「きす 開き」でもよい。","身にごく少量の塩をふって10分置き、水気をふく。","昆布を酒を含ませたキッチンペーパーでふいてやわらかくし、1枚に身を並べてもう1枚をかぶせ、ラップでぴったり包む。","冷蔵庫で2〜3時間置く（きすは薄いので長く置きすぎない）。","取り出して細切りにし、大葉とわさびを添え、醤油を少したらす。"],
   tips:["きすは淡白なので、昆布締めでうまみがぐっと増す。","必ずとても新鮮な魚を使う。","きすは夏が旬。天ぷらが定番だが、昆布締めはより上品な食べ方。"]}}}
});
window.ADD_I18N("en", {
 fugu:{d:{
  "红烧河豚":{serves:"2–3",time:"45 min",
   ingT:[["Professionally cleaned pufferfish pieces, bone-in","400g"],["Pork belly","100g"],["Ginger","1 piece"],["Japanese leek (negi)","1"],["Garlic","4 cloves"]],
   sauceT:[["Lard or cooking oil","2 tbsp"],["Shaoxing wine","3 tbsp"],["Light soy sauce","2 tbsp"],["Dark soy sauce","1 tsp"],["Rock sugar","20g"],["Hot water","400ml"]],
   steps:["Use only pufferfish cleaned by a licensed professional (身欠きふぐ from a Japanese fishmonger or supermarket). Never prepare a whole puffer yourself.","Blanch the fish from cold water for 1 minute and rinse. Slice the pork belly.","Fry the pork in lard to render, add the ginger, leek and garlic until fragrant, then the rock sugar until melted.","Add the fish, splash in the wine, then add both soy sauces and the hot water.","Bring to a boil, cover and simmer on low for 25 minutes until the skin is soft and gelatinous.","Uncover and reduce over high heat until thick and glossy."],
   tips:["Puffer liver and ovaries are deadly. In Japan only licensed chefs may handle them, so only buy cleaned flesh.","A traditional dish from Yangzhong and Jingjiang in Jiangsu, with a rich sauce.","Puffer skin is full of gelatin and best when braised soft."]},
  "河豚刺身":{serves:"2",time:"10 min",
   ingT:[["Ready-made pufferfish sashimi (tessa), professionally prepared","1 plate"],["Thin chives","3"],["Grated daikon with chili (momiji oroshi)","as needed"],["Puffer skin (included, optional)","as needed"]],
   sauceT:[["Ponzu","as needed"]],
   steps:["Pufferfish is highly poisonous. Always buy sashimi cleaned and sliced by a licensed professional (tessa from a supermarket or online). Never prepare it yourself.","Thaw frozen packs slowly in the fridge.","Cut the chives into 4cm lengths and place them with the momiji oroshi in the center of the plate.","Pour ponzu into small dishes and add a little momiji oroshi and chive.","Pick up 2–3 slices at once with chopsticks, wrap them around some chive and dip in ponzu."],
   tips:["By Japanese law, only licensed fugu chefs may prepare pufferfish.","The flesh is very chewy, which is why it's sliced paper-thin.","Winter is the season, and Shimonoseki in Yamaguchi is the most famous source."]},
  "炸河豚":{serves:"2",time:"30 min (plus 20 min marinating)",
   ingT:[["Professionally cleaned pufferfish pieces for frying, bone-in","300g"],["Lemon or sudachi","1/2"]],
   sauceT:[["Soy sauce","1.5 tbsp"],["Sake","1 tbsp"],["Grated ginger","1 tsp"],["Potato starch","4 tbsp"],["Oil for frying","3cm deep"]],
   steps:["Use only pufferfish cleaned by a professional (sold as ふぐの唐揚げ用 at fishmongers or online).","Pat the pieces dry, rub in the soy sauce, sake and ginger and marinate 20 minutes.","Drain and coat well in starch.","Fry at 170°C for 4 minutes, rest 2 minutes, then fry at 190°C for 1 minute.","Squeeze over lemon and eat hot."],
   tips:["Puffer liver and ovaries are deadly. Only buy cleaned fish.","Gnawing the meat off the fried bones is the best part.","Springier than fried chicken and a favorite among puffer dishes."]}}},
 anago:{d:{
  "红烧星鳗":{serves:"2–3",time:"40 min",
   ingT:[["Butterflied conger eel","2 (about 300g)"],["Ginger","1 piece"],["Japanese leek (negi)","1"]],
   sauceT:[["Shaoxing wine","2 tbsp"],["Light soy sauce","2 tbsp"],["Dark soy sauce","1 tsp"],["Rock sugar","20g"],["Cooking oil","2 tbsp"],["Hot water","250ml"]],
   steps:["Lay the eel skin up in a colander, pour boiling water over, scrape off the slime with the back of a knife, rinse and cut into 5cm pieces.","Fry the eel in oil over medium until lightly golden on both sides. Remove.","Fry the ginger and leek until fragrant and add the rock sugar to melt.","Return the eel, splash in the wine, add both soy sauces and the hot water and simmer on low for 15 minutes.","Uncover, reduce and shake the pan to coat the eel evenly."],
   tips:["Scraping off the slime is key to removing fishiness.","Conger is thinner than freshwater eel, so 15 minutes is enough.","Ready-made 煮あなご from Japanese stores can simply be reheated in the sauce."]},
  "煮星鳗寿司":{serves:"2",time:"50 min",
   ingT:[["Butterflied raw conger eel","2"],["Rice","1 rice-cooker cup"]],
   sauceT:[["Water","300ml"],["Sake","100ml"],["Soy sauce","3 tbsp"],["Sugar","2 tbsp"],["Mirin","2 tbsp"],["Sushi vinegar","1.5 tbsp"]],
   steps:["Lay the eel skin up on a rack, pour boiling water over, scrape off the white slime with the back of a knife and rinse.","Bring the water, sake, soy sauce, sugar and mirin to a boil, lay the eel in flat skin side up, cover with foil laid directly on top and simmer gently for 15–20 minutes without boiling.","Turn off the heat and let the eel cool in the liquid (it gets softer and more flavorful).","Lift out the eel. Simmer the liquid on low for 15 more minutes until it's as thick as honey. This is tsume (sweet sauce).","Shape sushi rice into nigiri, top with pieces of eel and brush with tsume. Or lay it over rice in a bowl."],
   tips:["The eel is very soft, so support it with a spatula when lifting.","With ready-made 煮あなご, you only need to make the sauce.","A signature of Tokyo-style Edomae sushi."]},
  "天妇罗星鳗":{serves:"2",time:"30 min",
   ingT:[["Butterflied raw conger eel","2"],["Grated daikon","as needed"]],
   sauceT:[["Cake flour","60g plus a little for dusting"],["Ice water","100ml"],["Egg","1/2"],["Oil for frying","3cm deep"],["Tempura dipping sauce (dashi 4: soy 1: mirin 1)","as needed"],["Salt","a little"]],
   steps:["Pour boiling water over the eel, scrape off the slime, pat dry and halve if long.","Dipping sauce: boil the dashi, soy sauce and mirin and cool.","Beat the egg with the ice water, add the flour and stir roughly with chopsticks (lumps are fine) for a thin batter.","Dust the eel lightly with flour and dip in the batter.","Fry at 175°C skin side down for 2–3 minutes, flip for 1 minute, until the batter is pale golden and crisp.","Serve with grated daikon and dipping sauce, or with salt."],
   tips:["Keep the batter cold and barely mixed for a crisp result.","The eel curls in the oil, so hold it straight with chopsticks.","Lay a whole piece over rice with sauce for anago tendon."]}}},
 hamo:{d:{
  "海鳗鲞":{serves:"4",time:"30 min (plus 2–3 days drying)",
   ingT:[["Large pike conger, gutted (ask the fishmonger to butterfly it)","1 (about 1kg)"],["Bamboo skewers or chopsticks","a few"],["Ginger","1 piece"]],
   sauceT:[["Coarse salt","about 2 tbsp (3% of the fish weight)"],["Shaoxing or cooking wine","3 tbsp"],["Lard or oil (for steaming)","1 tbsp"]],
   steps:["Have the fishmonger split the fish open from the back into one flat piece (not cut through) and remove the backbone. Rinse and pat dry.","Rub salt and wine evenly over both sides and refrigerate 6 hours.","Stretch it open with skewers and hang it somewhere cool and airy (outdoors in winter or in front of a fan) for 2–3 days, until the surface is dry and firm but springy.","To eat, cut into pieces and put on a plate with ginger slices, a little lard and wine.","Steam 15 minutes over boiling water, cool and tear into strips along the grain."],
   tips:["Only dry it in winter below 10°C. It spoils in warm weather.","A New Year preserved food from Ningbo and Zhoushan in Zhejiang. It can also be braised with pork belly.","Japanese pike conger is very bony, so a large fish is easier to work with."]},
  "海鳗涮锅":{serves:"2–3",time:"30 min",
   ingT:[["Bone-cut pike conger (hone-giri)","300g"],["Onion (Awaji onions are best)","1"],["Mizuna or mitsuba","1 bunch"],["Tofu (optional)","1/2 block"]],
   sauceT:[["Kombu dashi","1 liter"],["Sake","50ml"],["Light (usukuchi) soy sauce","1 tbsp"],["Salt","a little"],["Ponzu","as needed"],["Pickled plum paste (optional)","as needed"]],
   steps:["Pike conger is full of tiny bones, so buy it already bone-cut by the fishmonger (scored every 1–2mm to sever the bones). Cut into 5cm pieces.","Slice the onion into 1cm rings and cut the mizuna into lengths.","Put the dashi, sake, soy sauce and salt in a pot and simmer the onion first for 5 minutes until sweet.","Swish each piece of eel in the broth for 10–20 seconds. It's done when it opens like a flower.","Eat with the onion and mizuna, dipped in ponzu or plum paste."],
   tips:["Bone-cutting is a professional skill and not recommended at home.","Summer pike conger is iconic in Kyoto and Osaka, and the autumn fish (nagori hamo) is rich too.","The leftover broth is very flavorful, so finish with porridge or udon."]}}},
 shishamo:{d:{
  "椒盐多春鱼":{serves:"2",time:"20 min",
   ingT:[["Capelin (shishamo)","10"],["Garlic","3 cloves"],["Red chili","1"],["Scallion","1"]],
   sauceT:[["Potato starch","3 tbsp"],["Sichuan pepper salt","1 tsp"],["Oil for frying","2cm deep"]],
   steps:["Thaw the capelin and pat dry (no need to gut them).","Shake in a bag with the starch and tap off the excess.","Fry at 170°C for 3 minutes and remove, then raise the heat and fry again for 30 seconds until golden and crisp.","Fry the minced garlic, chili and scallion in a little oil over low heat.","Add the fish, sprinkle with pepper salt and toss quickly."],
   tips:["Frozen capelin sold in Japan is already salted, so go easy on the pepper salt.","Females full of roe are the tastiest.","To skip frying, grill them for 6–8 minutes."]},
  "柳叶鱼南蛮渍":{serves:"3",time:"30 min (plus 2 hours chilling)",
   ingT:[["Capelin (shishamo)","12"],["Onion","1/2"],["Carrot","1/3"],["Green pepper","1"]],
   sauceT:[["Rice vinegar","80ml"],["Dashi or water","80ml"],["Soy sauce","2 tbsp"],["Sugar","2 tbsp"],["Dried red chili","1"],["Potato starch","3 tbsp"],["Oil for frying","2cm deep"]],
   steps:["Boil the vinegar, dashi, soy sauce, sugar and sliced chili, pour into a container and add the thinly sliced onion, carrot and pepper.","Thaw the capelin, pat dry and coat in starch.","Fry at 170°C for 3 minutes until crisp.","Put them into the marinade while hot.","Refrigerate at least 2 hours."],
   tips:["Capelin don't need gutting and are used whole.","Easier than horse mackerel nanbanzuke and good for beginners.","Keeps 3 days in the fridge."]}}},
 kisu:{d:{
  "椒盐沙钻":{serves:"2",time:"25 min",
   ingT:[["Small Japanese whiting (kisu)","8"],["Garlic","2 cloves"],["Scallions","2"],["Red chili (optional)","1"]],
   sauceT:[["Salt","1/2 tsp"],["Shaoxing or cooking wine","1 tbsp"],["Potato starch","3 tbsp"],["Sichuan pepper salt","1 tsp"],["Oil for frying","2cm deep"]],
   steps:["Scale the fish, remove the heads and guts, rinse and pat dry. Pre-opened きす 開き from the supermarket is even easier.","Rub with salt and wine, rest 10 minutes and pat dry.","Coat lightly in starch.","Fry at 170°C for 2–3 minutes until golden and drain.","Fry minced garlic, chili and scallion in a little oil, add the fish and toss with the pepper salt."],
   tips:["Whiting is very tender, so don't overfry.","The skin is thin, so fry right after coating or it gets soggy.","In Japan it's usually tempura. This is the Cantonese and Hong Kong way."]},
  "鱚鱼昆布腌":{serves:"2",time:"20 min (plus 2–3 hours chilling)",
   ingT:[["Very fresh sashimi-grade whiting","4"],["Kombu","2 pieces"],["Shiso leaves","2"]],
   sauceT:[["Sake","2 tbsp"],["Salt","a little"],["Wasabi and soy sauce","as needed"]],
   steps:["Scale the fish, remove the heads and guts, fillet into two, pull the center bones with tweezers and peel off the skin from the tail end. Supermarket きす 開き also works.","Sprinkle very lightly with salt, rest 10 minutes and pat dry.","Wipe the kombu with sake-dampened paper towel to soften, lay the fillets on one piece, cover with the other and wrap tightly.","Refrigerate 2–3 hours (whiting is thin, so not too long).","Unwrap, cut into thin strips and serve with shiso, wasabi and a drop of soy sauce."],
   tips:["Whiting is mild, and kombu curing boosts its savoriness.","Use only very fresh fish.","Whiting is a summer fish usually made into tempura. Kombu curing is the more refined way."]}}}
});
