window.ADD_I18N("ja", {
 ayu:{d:{
  "香煎香鱼":{serves:"2",time:"20分",
   ingT:[["鮎","2〜4尾"],["レモン","1/2個"],["大葉か香菜（お好みで）","少々"]],
   sauceT:[["塩","小さじ1"],["サラダ油","大さじ2"],["白こしょう（お好みで）","少々"]],
   steps:["鮎を洗い、腹から肛門に向けて指で押してふんを出す。内臓は取らなくてよい。鮎のわたのほろ苦さが持ち味。","キッチンペーパーで水気をふき、両面に塩をして10分置き、出てきた水分をふく。","フライパンを弱火で熱して油をひき、鮎を入れて4〜5分、底面がきつね色になるまで焼く。","返してさらに4分、両面カリッと中まで火を通す。","皿に盛り、レモンを搾る。"],
   tips:["弱火でじっくり焼くと皮がくっつかず、中までしっかり火が通る。","鮎は夏が旬。養殖ものは一年中ある。","苦味が苦手なら内臓を取ってもよい。"]},
  "香鱼饭":{serves:"3〜4",time:"1時間",
   ingT:[["鮎","2〜3尾"],["米","2合（360ml）"],["生姜","1かけ"],["大葉か三つ葉","少々"]],
   sauceT:[["塩","少々"],["だし","約330ml"],["薄口醤油","大さじ1.5"],["酒","大さじ1.5"]],
   steps:["米を洗って30分ざるに上げる。","鮎に塩をふり、魚焼きグリルで両面に焼き色がつくまで焼く（中まで火が通らなくてよい）。","土鍋か炊飯器に米・薄口醤油・酒を入れ、だしを2合の目盛りまで加え、生姜のせん切りをのせる。","鮎を丸ごと米の上にのせ、普通に炊く。","炊けたら鮎を取り出し、片手で身を押さえて頭を引くと中骨がすっと抜ける。身をご飯に戻して混ぜる。","大葉のせん切りか三つ葉を散らす。"],
   tips:["鮎のわたのほろ苦さも鮎ご飯の味。一緒に混ぜてよい。","中骨は「引き抜く」と簡単に取れる。","夏の鮎の季節ならではの料理。"]},
  "香鱼甘露煮":{serves:"4（常備菜）",time:"3時間",
   ingT:[["小鮎","6尾"],["生姜","1かけ"]],
   sauceT:[["水","500ml"],["酒","100ml"],["酢","大さじ1"],["醤油","大さじ4"],["砂糖","大さじ4"],["水あめかはちみつ","大さじ2"]],
   steps:["鮎は内臓を取らずに洗って水気をふき、魚焼きグリルで両面をこんがり焼く（形を固め、臭みを取る）。","鍋底に竹の皮かオーブンシートを敷き、鮎を並べ、水・酒・酢・生姜の薄切りを加え、落とし蓋をして弱火で1時間煮る（酢で骨がやわらかくなる）。","砂糖と醤油を加え、さらに弱火で1.5時間煮る。","最後に水あめを加え、スプーンで煮汁を鮎にかけながら、とろりとつやが出るまで煮詰める。","冷めたら容器に入れる。冷蔵で1週間もつ。"],
   tips:["弱火で長時間煮るので、骨まで丸ごと食べられる。","先に焼いておくと、煮ている間に身がくずれない。","京都や岐阜の伝統的な保存食。"]}}},
 nijimasu:{d:{
  "豉汁蒸鳟鱼":{serves:"2",time:"25分",
   ingT:[["にじます（切り身か一尾）","約400g"],["豆豉（トウチ）","大さじ1"],["にんにく","3かけ"],["生姜","1かけ"],["小ねぎ","2本"],["赤唐辛子（お好みで）","1本"]],
   sauceT:[["料理酒","大さじ1"],["醤油","大さじ1"],["砂糖","小さじ1/2"],["片栗粉","小さじ1"],["サラダ油","大さじ3"]],
   steps:["にじますの水気をふき、3cm幅に切る（一尾なら両面に切り目を入れる）。料理酒をまぶす。","豆豉をさっと洗って刻み、にんにくと生姜をみじん切りにする。","油大さじ1で豆豉・にんにく・生姜を弱火で1分炒め、醤油と砂糖を加え、火を止めて片栗粉を混ぜ、豆豉だれを作る。","魚を皿に並べ、豆豉だれを均一にのせる。","湯が沸いた蒸し器で強火8分（一尾なら10分）蒸す。","小ねぎと唐辛子をのせ、熱した油をかける。"],
   tips:["豆豉は中華食材店で「トウチ」として買える。","片栗粉を少し加えると、たれが魚にからんで流れない。","鮭の切り身でも同じように蒸せる。"]},
  "盐烤虹鳟":{serves:"2",time:"30分",
   ingT:[["にじます（内臓処理済み、一尾）","2尾"],["竹串（お好みで）","2本"],["すだちかレモン","1/2個"]],
   sauceT:[["塩","大さじ1"]],
   steps:["にじますを塩でこすって表面のぬめりを取り、洗って水気をふく。","竹串を口から刺し、中骨に沿って縫うように通し、泳いでいるようなS字にする（お好みで）。","全体に塩をふり、ひれと尾には多めにつける（「化粧塩」で焦げ防止）。","魚焼きグリル、220°Cのオーブン、または炭火のそばで15〜20分、途中で返して皮がパリッとするまで焼く。","レモンを搾って食べる。"],
   tips:["川辺の釣り堀の定番。炭火でじっくり焼くのがいちばん香ばしい。","ひれの塩で焦げにくく、見た目もきれい。","魚焼きグリルなら片面6〜8分。"]},
  "烟熏鳟鱼":{serves:"4",time:"1時間（漬け4時間）",
   ingT:[["にじますのフィレ（皮付き）","2枚（約400g）"],["スモークチップ（桜かりんご）","ひとつかみ"],["クリームチーズ","100g"],["レモン","1/2個"],["ディルかチャイブ","少々"]],
   sauceT:[["塩","大さじ2"],["砂糖","大さじ1"],["黒こしょう","少々"],["ホースラディッシュ（お好みで）","小さじ1"]],
   steps:["塩・砂糖・こしょうを混ぜてフィレにすり込み、冷蔵庫で4時間漬ける。","洗って水気をふき、網にのせて冷蔵庫で1時間乾かす（表面が乾くと色がよくつく）。","古い鍋か中華鍋にアルミホイルを敷いてチップを置き、上に網をのせ、皮を下にして魚を置き、ふたをしっかり閉める。","中火で煙が出てきたら弱火にし、15〜20分、中まで火が通り表面が金褐色になるまでいぶす。","冷めたらほぐし、クリームチーズ・レモン汁・ホースラディッシュ・ディルと混ぜ、クラッカーやパンに塗る。"],
   tips:["いぶすときは換気扇を回し、鍋は必ずアルミホイルで保護する。","燻製はそのまま食べてもおいしい。冷蔵で4日もつ。","アメリカではスモークトラウトをディップ（trout dip）にすることが多い。"]}}},
 kinki:{d:{
  "喜知次一夜干":{serves:"2",time:"30分（干す一晩）",
   ingT:[["きんき（一尾）","1〜2尾"],["大根おろし","適量"]],
   sauceT:[["水","1L"],["塩","40〜50g（4〜5%の塩水）"]],
   steps:["魚屋に背開きにしてもらうか、自分で背びれに沿って腹まで切り（切り離さない）、開いて内臓とえらを取り、洗う。","4〜5%の塩水に30〜40分つける。","水気をふき、皮を下にして網にのせ、冷蔵庫でラップをせずに一晩乾かす（冬の寒い屋外なら3〜4時間）。","表面が乾き、押すと弾力があればできあがり。","魚焼きグリルの弱火で身側を5分、皮側を3〜4分焼き、大根おろしを添える。"],
   tips:["きんきは脂が多いので、弱火でじっくり焼くと脂が落ちる。","一夜干しは水分がほどよく抜け、生より甘みが増す。","北海道の高級魚。ほっけやあじでも同じように作れる。"]},
  "盐水煮喜知次":{serves:"2",time:"25分",
   ingT:[["きんき（一尾、処理済み）","1尾"],["長ねぎ","1/2本"]],
   sauceT:[["水","約800ml（魚がかぶる量）"],["塩","大さじ1（約2%の塩水）"],["ポン酢","適量"]],
   steps:["魚のうろこと内臓を取って洗い、両面に切り目を入れる。","鍋に水と塩を入れ（海水くらいの塩加減）、煮立てる。","魚を入れて中弱火で8〜10分煮ると、表面にオレンジ色の脂が浮いてくる。","取り出して深皿に入れ、煮汁を少しかける。","ポン酢につけ、白髪ねぎと一緒に食べる。煮汁に浮いた脂はスプーンですくって飲める。"],
   tips:["北海道網走の漁師の食べ方「湯煮」。塩水だけで、脂の味そのものを楽しむ。","火が強すぎると皮が破れる。","残った煮汁で茶漬けにしても。"]}}},
 hata:{d:{
  "九绘火锅":{serves:"3〜4",time:"40分",
   ingT:[["クエかハタ（皮・アラ付き）","500g"],["白菜","1/6株"],["豆腐","1丁"],["長ねぎ","1本"],["しいたけ","4枚"],["春菊","1束"]],
   sauceT:[["昆布","10cm 1枚"],["水","1.2L"],["酒","100ml"],["塩","少々"],["ポン酢","適量"],["もみじおろし","適量"],["ご飯と卵（雑炊用）","茶碗1杯＋1個"]],
   steps:["昆布を水に30分つける。","切り身とアラに塩をふって15分置き、熱湯をかけてから冷水で血合いとぬめりを洗う。","土鍋を火にかけ、沸騰直前に昆布を取り出して酒を加え、アラと切り身を入れて10分煮てアクを取る。","白菜の芯・ねぎ・しいたけ・豆腐を入れて5分煮て、白菜の葉と春菊を加える。","ポン酢ともみじおろしで食べる。皮のゼラチン質がいちばんおいしい。","食べ終わったら鍋の具をきれいにすくい、ご飯を入れて3分煮て、溶き卵を回し入れ、ねぎを散らして雑炊にする。"],
   tips:["クエは高級魚。中国でよく食べるハタでも同じようにおいしい。","アラから出るだしがとても濃く、雑炊がいちばんの楽しみ。","和歌山や九州の冬の名物。"]},
  "泰式柠檬蒸鱼":{serves:"2〜3",time:"30分",
   ingT:[["ハタかすずき（一尾）","1尾（約600g）"],["レモングラス（お好みで）","1本"],["にんにく","6かけ"],["プリッキーヌか赤唐辛子","3〜5本"],["パクチー","1束"],["ライム","3個"]],
   sauceT:[["ナンプラー","大さじ3"],["ライム果汁","大さじ4"],["砂糖","大さじ1"],["鶏ガラスープか湯","100ml"]],
   steps:["魚のうろこと内臓を取り、両面に切り目を入れ、腹にたたいたレモングラスを詰める。","にんにくと唐辛子をみじん切りにし、パクチーの根を刻む（葉は取っておく）。","にんにく・唐辛子・パクチーの根・ナンプラー・ライム汁・砂糖・熱い鶏ガラスープを混ぜて酸っぱ辛いたれを作り、味見して酸味・甘み・塩気を調える。","魚を深皿にのせ、湯が沸いた蒸し器で強火12〜15分蒸す。","蒸し上がったら皿の汁を捨て、たれを魚全体にたっぷりかけ、ライムの輪切りとパクチーの葉をのせる。"],
   tips:["タイ料理店では魚形の専用鍋を使い、下から火で保温する。","たれは「酸味＞塩気＞甘み」がタイ式のバランス。","蒸す代わりに揚げた魚にすれば、また別のタイ料理になる。"]}}},
 kurodai:{d:{
  "黑鲷刺身":{serves:"2",time:"20分",
   ingT:[["刺身用チヌ（さく、皮付き）","200g"],["大根のつま・大葉","適量"]],
   sauceT:[["醤油・わさび","適量"],["ポン酢（皮付き刺身用）","適量"]],
   steps:["皮付きで食べるなら、皮を上にして網にのせ、ふきんをかぶせて熱湯をかけ、皮が縮んだらすぐ氷水にとり（湯引き）、水気をふく。","皮なしで食べるなら、皮と身の間に包丁を入れ、皮を押さえて包丁を前に押し出して皮を引く。","皮なしは7mm厚さ、皮付きは5mmの薄切りにする（皮がかたいため）。","皿に大根のつまと大葉を敷き、刺身を盛る。","皮なしはわさび醤油、皮付きはポン酢で。"],
   tips:["黒鯛は関西で「チヌ」と呼ばれ、冬から春がおいしい。","夏の黒鯛は磯臭いことがあるので、冬のものを選ぶ。","湯引きした皮は歯ごたえがあり、風味がよい。"]},
  "意式烤鲷":{serves:"2〜3",time:"45分",
   ingT:[["黒鯛か真鯛（一尾、処理済み）","1尾（約600g）"],["じゃがいも","3個"],["レモン","1個"],["ローズマリー","2枝"],["にんにく","3かけ"],["ブラックオリーブ","10個"],["ミニトマト","8個"]],
   sauceT:[["オリーブオイル","大さじ5"],["白ワイン","50ml"],["塩・こしょう","適量"]],
   steps:["オーブンを200°Cに予熱する。じゃがいもを5mmの薄切りにし、オリーブオイル大さじ2・塩・こしょうであえて天板に広げ、先に15分焼く。","魚の水気をふき、両面に2本ずつ切り目を入れ、内外に塩・こしょうをし、腹にレモンの薄切り・ローズマリー・つぶしたにんにくを詰める。","半分焼けたじゃがいもの上に魚をのせ、周りにオリーブとミニトマトを置き、白ワインと残りのオリーブオイルをかける。","20〜25分、目が白くなり、背のいちばん厚い部分にナイフがすっと通るまで焼く。","天板ごと食卓に出し、レモンを搾る。"],
   tips:["イタリアの海辺のレストランの定番。一皿で完成。","じゃがいもを先に焼くと、魚と同時に火が通る。","魚の汁とオリーブオイルを吸ったじゃがいもがいちばんおいしい。"]}}}
});
window.ADD_I18N("en", {
 ayu:{d:{
  "香煎香鱼":{serves:"2",time:"20 min",
   ingT:[["Sweetfish (ayu)","2–4"],["Lemon","1/2"],["Shiso or cilantro (optional)","a little"]],
   sauceT:[["Salt","1 tsp"],["Cooking oil","2 tbsp"],["White pepper (optional)","a little"]],
   steps:["Rinse the fish and press along the belly toward the vent with a finger to squeeze out waste. No need to gut it, since the slightly bitter innards are part of ayu's charm.","Pat dry with paper towel, salt both sides, rest 10 minutes and wipe off the moisture.","Heat a frying pan on low, add oil and cook the fish 4–5 minutes until golden underneath.","Flip and cook another 4 minutes until crisp on both sides and cooked through.","Plate and squeeze over lemon."],
   tips:["Low, slow heat keeps the skin from sticking and cooks the fish through.","Ayu is a summer fish, and farmed ones are available year-round.","Gut the fish if you don't like the bitterness."]},
  "香鱼饭":{serves:"3–4",time:"1 hour",
   ingT:[["Sweetfish (ayu)","2–3"],["Rice","2 rice-cooker cups (360ml)"],["Ginger","1 piece"],["Shiso or mitsuba","a little"]],
   sauceT:[["Salt","a little"],["Dashi","about 330ml"],["Light (usukuchi) soy sauce","1.5 tbsp"],["Sake","1.5 tbsp"]],
   steps:["Wash the rice and drain for 30 minutes.","Salt the fish and grill until golden on both sides (it needn't be cooked through).","Put the rice, soy sauce and sake in a clay pot or rice cooker, add dashi to the 2-cup line and top with julienned ginger.","Lay the whole fish on the rice and cook as usual.","When done, lift out the fish. Hold the body with one hand and pull the head with the other, and the backbone slides out in one piece. Return the flesh to the rice and mix.","Scatter with shredded shiso or mitsuba."],
   tips:["The bitterness of the innards is part of the flavor, so you can mix them in too.","Pulling the backbone out makes deboning easy.","A special dish of the summer ayu season."]},
  "香鱼甘露煮":{serves:"4 (keeps well)",time:"3 hours",
   ingT:[["Small sweetfish (ayu)","6"],["Ginger","1 piece"]],
   sauceT:[["Water","500ml"],["Sake","100ml"],["Vinegar","1 tbsp"],["Soy sauce","4 tbsp"],["Sugar","4 tbsp"],["Starch syrup (mizuame) or honey","2 tbsp"]],
   steps:["Without gutting, rinse and dry the fish and grill until browned on both sides (this firms them and removes fishiness).","Line a pot with bamboo leaves or baking paper, lay in the fish, add the water, sake, vinegar and sliced ginger, cover with a drop lid and simmer on low 1 hour (the vinegar softens the bones).","Add the sugar and soy sauce and simmer on low another 1.5 hours.","Finally add the syrup and spoon the liquid over the fish while reducing until thick and glossy.","Cool and store in a container. Keeps 1 week in the fridge."],
   tips:["Long, gentle simmering makes the whole fish edible, bones and all.","Grilling first keeps the fish from falling apart while simmering.","A traditional preserved food from Kyoto and Gifu."]}}},
 nijimasu:{d:{
  "豉汁蒸鳟鱼":{serves:"2",time:"25 min",
   ingT:[["Rainbow trout pieces or whole fish","about 400g"],["Fermented black beans (douchi)","1 tbsp"],["Garlic","3 cloves"],["Ginger","1 piece"],["Scallions","2"],["Red chili (optional)","1"]],
   sauceT:[["Shaoxing or cooking wine","1 tbsp"],["Light soy sauce","1 tbsp"],["Sugar","1/2 tsp"],["Potato starch","1 tsp"],["Cooking oil","3 tbsp"]],
   steps:["Pat the trout dry and cut into 3cm pieces (score both sides if whole). Rub with wine.","Briefly rinse and chop the black beans, and mince the garlic and ginger.","Fry the beans, garlic and ginger in 1 tbsp oil on low for 1 minute, add the soy sauce and sugar, turn off the heat and stir in the starch to make the sauce.","Arrange the fish on a plate and spread the sauce evenly over it.","Steam over boiling water on high for 8 minutes (10 for a whole fish).","Top with scallions and chili and pour over sizzling hot oil."],
   tips:["Black beans are sold at Chinese grocers. In Japan they're called トウチ.","A little starch helps the sauce cling to the fish.","Salmon pieces can be steamed the same way."]},
  "盐烤虹鳟":{serves:"2",time:"30 min",
   ingT:[["Whole rainbow trout, gutted","2"],["Bamboo skewers (optional)","2"],["Sudachi or lemon","1/2"]],
   sauceT:[["Salt","1 tbsp"]],
   steps:["Rub the trout with salt to remove surface slime, rinse and pat dry.","Insert a skewer through the mouth and weave it along the backbone so the fish curves in an S shape as if swimming (optional).","Salt all over, heavily on the fins and tail (decorative salt that stops them burning).","Grill, roast at 220°C or cook beside charcoal for 15–20 minutes, turning once, until the skin is crisp.","Squeeze over lemon to eat."],
   tips:["A classic at riverside fishing spots, best slow-grilled over charcoal.","Salt on the fins prevents burning and looks neater.","Under a fish grill, cook 6–8 minutes per side."]},
  "烟熏鳟鱼":{serves:"4",time:"1 hour (plus 4 hours curing)",
   ingT:[["Skin-on rainbow trout fillets","2 (about 400g)"],["Cherry or apple wood smoking chips","1 handful"],["Cream cheese","100g"],["Lemon","1/2"],["Dill or chives","a little"]],
   sauceT:[["Salt","2 tbsp"],["Sugar","1 tbsp"],["Black pepper","a little"],["Horseradish (optional)","1 tsp"]],
   steps:["Mix the salt, sugar and pepper, rub over the fillets and refrigerate 4 hours.","Rinse, pat dry and air-dry on a rack in the fridge for 1 hour (a dry surface takes color better).","Line an old pot or wok with foil, add the chips, set a rack on top, lay the fish skin side down and cover tightly.","Heat on medium until smoking, then lower the heat and smoke 15–20 minutes until cooked through and golden brown.","Cool, flake and mix with the cream cheese, lemon juice, horseradish and dill. Spread on crackers or bread."],
   tips:["Run the range hood while smoking and always protect the pot with foil.","The smoked fish is great on its own and keeps 4 days in the fridge.","Americans often make smoked trout into a dip."]}}},
 kinki:{d:{
  "喜知次一夜干":{serves:"2",time:"30 min (plus drying overnight)",
   ingT:[["Whole kichiji rockfish (kinki)","1–2"],["Grated daikon","as needed"]],
   sauceT:[["Water","1 liter"],["Salt","40–50g (4–5% brine)"]],
   steps:["Have the fishmonger split it open from the back, or cut along the dorsal fin down to the belly without cutting through. Open it flat, remove the guts and gills and rinse.","Soak in 4–5% brine for 30–40 minutes.","Pat dry, lay skin side down on a rack and air-dry uncovered in the fridge overnight (or 3–4 hours outdoors on a cold winter day).","It's ready when the surface is dry and springs back when pressed.","Grill on low, flesh side 5 minutes then skin side 3–4 minutes. Serve with grated daikon."],
   tips:["Kinki is very fatty, so grill slowly to let the fat drip off.","Overnight drying removes just enough moisture and makes it sweeter than fresh.","A luxury Hokkaido fish. Atka mackerel (hokke) or horse mackerel work the same way."]},
  "盐水煮喜知次":{serves:"2",time:"25 min",
   ingT:[["Whole kichiji rockfish (kinki), cleaned","1"],["Japanese leek (negi)","1/2"]],
   sauceT:[["Water","about 800ml (to cover)"],["Salt","1 tbsp (about 2% brine)"],["Ponzu","as needed"]],
   steps:["Scale and gut the fish, rinse and score both sides.","Bring the water and salt (as salty as seawater) to a boil.","Add the fish and simmer on medium-low 8–10 minutes. A layer of orange fat will float to the surface.","Lift into a deep dish and spoon over a little of the cooking liquid.","Dip in ponzu and eat with shredded leek. Spoon up the fat in the broth and drink it."],
   tips:["This is how fishermen in Abashiri, Hokkaido eat it (yuni). Only salt water, so you taste the pure fat.","Too high a heat will split the skin.","Use the leftover broth for ochazuke."]}}},
 hata:{d:{
  "九绘火锅":{serves:"3–4",time:"40 min",
   ingT:[["Longtooth grouper (kue) or grouper, skin-on with bones","500g"],["Napa cabbage","1/6 head"],["Tofu","1 block"],["Japanese leek (negi)","1"],["Shiitake","4"],["Shungiku (edible chrysanthemum)","1 bunch"]],
   sauceT:[["Kombu","1 piece, 10cm"],["Water","1.2 liters"],["Sake","100ml"],["Salt","a little"],["Ponzu","as needed"],["Grated daikon with chili (momiji oroshi)","as needed"],["Rice and egg (for porridge)","1 bowl + 1"]],
   steps:["Soak the kombu in the water for 30 minutes.","Salt the fish pieces and bones for 15 minutes, pour boiling water over, then rinse off blood and slime in cold water.","Heat the pot, remove the kombu just before boiling, add the sake, then the bones and fish. Simmer 10 minutes, skimming.","Add the cabbage stems, leek, shiitake and tofu for 5 minutes, then the cabbage leaves and shungiku.","Eat with ponzu and momiji oroshi. The gelatinous skin is the best part.","When finished, clear out the solids, add the rice and simmer 3 minutes, drizzle in beaten egg and scatter leek for zosui porridge."],
   tips:["Kue is a luxury fish, but the grouper common in China is just as good.","The bones make a very rich broth, and the porridge is the highlight.","A winter specialty of Wakayama and Kyushu."]},
  "泰式柠檬蒸鱼":{serves:"2–3",time:"30 min",
   ingT:[["Whole grouper or sea bass","1 (about 600g)"],["Lemongrass (optional)","1 stalk"],["Garlic","6 cloves"],["Bird's eye chilies","3–5"],["Cilantro","1 bunch"],["Limes","3"]],
   sauceT:[["Fish sauce","3 tbsp"],["Lime juice","4 tbsp"],["Sugar","1 tbsp"],["Chicken stock or hot water","100ml"]],
   steps:["Scale and gut the fish, score both sides and stuff the belly with bruised lemongrass.","Mince the garlic and chilies and chop the cilantro roots (save the leaves).","Mix the garlic, chili, cilantro roots, fish sauce, lime juice, sugar and hot stock into a sour-spicy sauce. Taste and adjust.","Put the fish on a deep plate and steam on high for 12–15 minutes.","Pour off the liquid on the plate, flood the fish with the sauce and top with lime slices and cilantro leaves."],
   tips:["Thai restaurants use a fish-shaped pan kept warm over a flame.","The Thai balance is sour, then salty, then sweet.","Swap the steamed fish for fried and it becomes another Thai dish."]}}},
 kurodai:{d:{
  "黑鲷刺身":{serves:"2",time:"20 min",
   ingT:[["Sashimi-grade black sea bream block, skin-on","200g"],["Shredded daikon and shiso","as needed"]],
   sauceT:[["Soy sauce and wasabi","as needed"],["Ponzu (for skin-on sashimi)","as needed"]],
   steps:["For skin-on: lay it skin up on a rack, cover with a cloth and pour boiling water over. When the skin shrinks, plunge into ice water (yubiki) and pat dry.","For skinless: slide the knife between skin and flesh, hold the skin and push the knife forward to remove it.","Cut skinless fish 7mm thick and skin-on fish 5mm thin (the skin is chewier).","Lay daikon and shiso on a plate and arrange the slices.","Serve skinless slices with wasabi soy sauce and skin-on slices with ponzu."],
   tips:["In the Kansai region black sea bream is called chinu, and it's best from winter to spring.","Summer fish can smell of the shore, so choose winter ones.","Scalded skin is chewy and full of flavor."]},
  "意式烤鲷":{serves:"2–3",time:"45 min",
   ingT:[["Whole black or red sea bream, cleaned","1 (about 600g)"],["Potatoes","3"],["Lemon","1"],["Rosemary","2 sprigs"],["Garlic","3 cloves"],["Black olives","10"],["Cherry tomatoes","8"]],
   sauceT:[["Olive oil","5 tbsp"],["White wine","50ml"],["Salt and black pepper","as needed"]],
   steps:["Preheat the oven to 200°C. Slice the potatoes 5mm thick, toss with 2 tbsp olive oil, salt and pepper, spread in a roasting tray and roast 15 minutes first.","Pat the fish dry, make 2 cuts on each side, season inside and out and stuff the belly with lemon slices, rosemary and crushed garlic.","Lay the fish on the half-cooked potatoes, scatter olives and tomatoes around and drizzle with the wine and remaining oil.","Roast 20–25 minutes, until the eyes turn white and a knife slides easily into the thickest part of the back.","Bring the tray to the table and squeeze over lemon."],
   tips:["A classic of Italian seaside restaurants, all in one tray.","Roasting the potatoes first means they finish at the same time as the fish.","The potatoes soaked in fish juices and olive oil are the best part."]}}}
});
