window.ADD_I18N("ja", {
 itoyori:{d:{
  "香煎红三鱼":{serves:"2",time:"20分",
   ingT:[["いとより（処理済み）","2尾"],["長ねぎ","1/2本"],["生姜","1かけ"]],
   sauceT:[["塩","小さじ1/2"],["料理酒","大さじ1"],["小麦粉","大さじ2"],["サラダ油","大さじ2"],["蒸魚醤油か醤油","大さじ1.5"],["砂糖","少々"]],
   steps:["魚の水気をふき、両面に切り目を入れ、塩と料理酒をまぶして10分置き、再び水気をふく。","ねぎと生姜を細いせん切りにする。","魚に小麦粉を薄くはたく。","フライパンに油を熱し、魚を入れて中弱火で片面4分ずつ、きつね色に焼く。","皿に盛ってねぎと生姜をのせる。フライパンに醤油・砂糖・水大さじ2を入れて煮立て、魚にかける。"],
   tips:["身がやわらかいので、返すときはフライ返し2本で支える。","日本では「いとより」。皮の黄色いすじがきれい。","焼いた魚にレモンを搾るだけでもおいしい。"]},
  "法式纸包鱼":{serves:"2",time:"30分",
   ingT:[["いとよりの切り身（白身魚なら何でも）","2切れ"],["にんじん","1/3本"],["ズッキーニか長ねぎ","1/2本"],["マッシュルーム","4個"],["レモン","1/2個"],["タイムかディル","少々"]],
   sauceT:[["塩・白こしょう","少々"],["バター","20g"],["白ワイン","大さじ2"],["クッキングシート","大2枚"]],
   steps:["オーブンを200°Cに予熱する。にんじんとズッキーニを細切り、マッシュルームを薄切りにする。","魚の水気をふき、塩・こしょうをする。","クッキングシートを二つ折りにし、片側の中央に野菜を敷いて魚をのせ、バター・レモンの薄切り・ハーブをのせて白ワインをかける。","もう片側をかぶせ、ふちを少しずつ折り込んで、半月形の包みにしっかり閉じる。","天板にのせて15分焼くと、包みがふくらむ。","包みごと食卓に出し、はさみで切り開くと香りがふわっと立つ。"],
   tips:["しっかり閉じれば蒸気が逃げず、身がしっとりする。","クッキングシートがなければアルミホイルで。","日本の「ホイル焼き」も同じ。味噌ときのこを入れてもおいしい。"]}}},
 mekajiki:{d:{
  "黑椒剑鱼排":{serves:"2",time:"20分",
   ingT:[["めかじきの切り身","2切れ（約300g）"],["玉ねぎ","1/2個"],["ピーマン","1個"]],
   sauceT:[["塩","少々"],["粗挽き黒こしょう","小さじ1"],["オイスターソース","大さじ1"],["醤油","小さじ1"],["砂糖","小さじ1"],["バター","10g"],["サラダ油","大さじ1"],["水","大さじ3"]],
   steps:["めかじきの水気をふき、塩と黒こしょう少々をふる。","玉ねぎとピーマンを細切りにする。オイスターソース・醤油・砂糖・黒こしょうの半量・水を混ぜて黒こしょうだれを作る。","フライパンに油を熱し、めかじきを中火で片面2分ずつ、七分通り焼いて取り出す。","バターを入れ、玉ねぎとピーマンを1分炒める。","たれを入れて煮立て、めかじきを戻して両面に30秒からめる。"],
   tips:["めかじきは脂が少なく、焼きすぎるとぱさつく。中が少しピンクくらいがベスト。","台湾では「旗魚」と呼ばれ、弁当屋の定番。","日本のスーパーでは一年中あり、値段も手ごろ。"]},
  "西西里剑鱼卷":{serves:"2〜3",time:"40分",
   ingT:[["めかじき（薄切り）","300g（約8枚）"],["パン粉","大さじ4"],["粉チーズ","大さじ2"],["松の実","大さじ1"],["レーズン","大さじ1"],["パセリ","少々"],["ローリエ・玉ねぎ（串用）","各8枚"],["竹串","4本"]],
   sauceT:[["オリーブオイル","大さじ4"],["レモン","1/2個"],["塩・黒こしょう","少々"]],
   steps:["めかじきをラップではさみ、めん棒でたたいて3mm厚さにのばし、塩・こしょうをする。","パン粉をオリーブオイル大さじ1できつね色に炒め、冷めたら粉チーズ・松の実・もどして刻んだレーズン・パセリのみじん切り・レモンの皮を加え、オリーブオイル大さじ1でしっとりした具にする。","めかじき1枚に具をスプーン1杯のせて巻く。","竹串に、巻いたもの・ローリエ・玉ねぎ・巻いたもの…の順に刺す。","オリーブオイルを塗ってパン粉をまぶし、220°Cのオーブンかフライパンの中火で10〜12分、途中で返して焼く。","レモンを搾る。"],
   tips:["シチリア・メッシーナの名物。甘み・塩気・香ばしさの組み合わせ。","日本のめかじきの切り身は厚めなので、自分で横に薄く切ってからたたく。","竹串がなければつまようじで留めても。"]},
  "烤剑鱼排":{serves:"2",time:"20分",
   ingT:[["めかじき（厚切り2cm以上）","2切れ（約400g）"],["レモン","1/2個"],["バジル（ジェノベーゼ用）","1束（約30g）"],["にんにく","1かけ"],["松の実かくるみ","大さじ1"]],
   sauceT:[["オリーブオイル","大さじ5"],["粉チーズ","大さじ1"],["塩・黒こしょう","適量"]],
   steps:["ジェノベーゼ：バジル・にんにく・松の実・粉チーズ・オリーブオイル大さじ4・塩少々をフードプロセッサーでペーストにする。","めかじきの水気をふき、オリーブオイル大さじ1を塗り、塩と黒こしょうをふる。","グリルパンかフライパンを強火で煙が出るまで熱し、めかじきを入れて片面3分ずつ、格子の焼き目をつける。","中がまだ少しピンクのうちに火から下ろし、3分休ませる。","ジェノベーゼをかけ、レモンを搾る。"],
   tips:["めかじきは脂が少ないので、強火で短時間に焼かないとぱさつく。","厚切りのほうがジューシーに焼ける。","サルサ（トマト・玉ねぎ・唐辛子・パクチー）も定番の組み合わせ。"]}}},
 shiira:{d:{
  "台湾鬼头刀鱼排":{serves:"2",time:"20分",
   ingT:[["しいらの切り身","2切れ（約300g）"],["にんにく","3かけ"],["小ねぎ","1本"],["レモン","1/4個"]],
   sauceT:[["塩","小さじ1/2"],["白こしょう","少々"],["小麦粉","大さじ2"],["サラダ油","大さじ2"],["台湾醤油膏か醤油","大さじ2"],["砂糖","小さじ1"]],
   steps:["切り身の水気をふき、塩と白こしょうで10分置き、再び水気をふいて小麦粉を薄くはたく。","にんにくをみじん切りにし、醤油膏・砂糖・湯冷まし大さじ1と混ぜて、にんにく醤油を作る。","フライパンに油を熱し、中火で片面3分ずつ、きつね色に中まで焼く。","皿に盛って小ねぎを散らし、にんにく醤油とレモンを添える。"],
   tips:["しいらは身がやや乾きやすいので、小麦粉で水分を閉じ込める。","日本では「しいら」。安くて夏から秋によく出回る。","棒状に切ってフライにしても。"]},
  "鲯鳅黄油煎":{serves:"2",time:"20分",
   ingT:[["しいら（切り身）","2切れ"],["レモン","1/2個"],["パセリ","少々"]],
   sauceT:[["塩・こしょう","少々"],["小麦粉","大さじ2"],["オリーブオイル","大さじ1"],["バター","20g"],["醤油（お好みで）","小さじ1"]],
   steps:["切り身の水気をふき、塩・こしょうをして5分置き、再び水気をふく。","小麦粉を薄くまぶし、余分をはたく。","フライパンにオリーブオイルとバターの半量を入れ、中火で3分きつね色に焼き、返して2〜3分焼く。","残りのバターを入れ、溶けたらスプーンで魚にかける。鍋肌から醤油を少したらしてもよい（和風）。","皿に盛り、レモンを搾ってパセリを散らす。"],
   tips:["しいらは白身で淡白、ムニエルにぴったり。","醤油を少し加えれば、洋食屋の「バター醤油」味に。","ハワイでは「マヒマヒ」と呼ばれ、人気の魚。"]}}},
 gindara:{d:{
  "清蒸银鳕鱼":{serves:"2",time:"15分",
   ingT:[["銀だらの切り身","2切れ（約250g）"],["生姜","1かけ"],["長ねぎ","1/2本"]],
   sauceT:[["料理酒","大さじ1"],["蒸魚醤油","大さじ2"],["サラダ油","大さじ2"]],
   steps:["銀だらを解凍して水気をふき、料理酒をまぶす。","皿に生姜の薄切りを敷いて魚をのせ、上に生姜のせん切りをのせる。","湯が沸いた蒸し器で強火6〜7分蒸す。","皿の汁を捨て、白髪ねぎをのせる。","煙が出るまで熱した油をかけ、蒸魚醤油を回しかける。"],
   tips:["銀だらは脂が多いので、蒸し時間は短めのほうがなめらか。","日本のスーパーの銀だらは冷凍が多いので、冷蔵庫でゆっくり解凍する。","味付き（西京漬け）の銀だらは清蒸には向かない。"]},
  "味噌银鳕":{serves:"2",time:"20分（漬け2〜3日）",
   ingT:[["銀だら（生・切り身）","2切れ（約250g）"],["はじかみ（お好みで）","2本"]],
   sauceT:[["西京味噌（白味噌）","150g"],["酒","大さじ3"],["みりん","大さじ3"],["砂糖","大さじ2"]],
   steps:["酒とみりんを小鍋で20秒煮立ててアルコールを飛ばし、火を止めて砂糖を溶かし、白味噌を加えて混ぜ、冷ます。","銀だらの水気をふき、塩少々をして15分置き、再び水気をふく。","味噌床で魚を完全に包み、保存袋に入れるかガーゼで包んで、冷蔵庫で2〜3日漬ける。","取り出して指かキッチンペーパーで味噌をきれいにぬぐう（残ると焦げる）。","220°Cのオーブンか魚焼きグリルで10〜12分、表面がキャラメル状に濃い焼き色がつくまで焼く。"],
   tips:["ニューヨークのNobuの名物（Black cod miso）だが、もとは日本の「西京焼き」。","味噌はしっかりぬぐわないと、すぐ黒く焦げる。","スーパーの「銀だら西京漬け」なら焼くだけ。"]}}},
 anko:{d:{
  "红烧老头鱼":{serves:"3",time:"40分",
   ingT:[["あんこう（切り身・あら、皮と骨付き）","500g"],["豚バラ薄切り","80g"],["長ねぎ","1本"],["生姜","4枚"],["にんにく","5かけ"],["鷹の爪（お好みで）","2本"]],
   sauceT:[["中国みそ（黄豆醤）か豆板醤","大さじ1.5"],["料理酒","大さじ2"],["醤油","大さじ1"],["砂糖","小さじ1"],["酢","小さじ1"],["サラダ油","大さじ2"],["水","400ml"]],
   steps:["あんこうを熱湯で1分ゆで、冷水でぬめりと血を洗い流す。","鍋に油を熱し、豚バラを脂が出て軽く焦げるまで炒める。","ねぎのぶつ切り・生姜・にんにく・鷹の爪・みそを入れ、弱火で1分炒めて香りを出す。","あんこうを入れ、料理酒と酢を回しかけ、醤油・砂糖・水を加える。","強火で煮立ててから中弱火で20分煮込み、途中で煮汁を魚にかける。","煮汁が半分くらいになり、少しとろみがついたら完成。"],
   tips:["あんこうは水分が多いので、水は多く入れなくてよい。","皮と骨のゼラチン質がいちばんおいしいので捨てない。","中国東北や山東では「老頭魚」「蛤蟆魚」と呼ばれ、冬が旬。"]},
  "鮟鱇肝":{serves:"4",time:"1時間（漬け1時間）",
   ingT:[["あん肝（生）","300g"],["あさつき","3本"],["もみじおろし","適量"]],
   sauceT:[["塩","大さじ1"],["酒","100ml"],["ポン酢","適量"],["ラップ・アルミホイル","各大1枚"]],
   steps:["あん肝に塩をして30分置き、洗ってから酒に30分つける（臭み取り）。","つまようじかピンセットで表面と中の血管や筋を取り、血を押し出す（ここで臭みが決まる）。","水気をふいてラップにのせ、直径5cmくらいの筒状に巻いて両端をねじり、さらにアルミホイルで包む。","湯が沸いた蒸し器で、中火で30分蒸す。","冷めたら冷蔵庫で2時間冷やし固め、1.5cm厚さに切り、ポン酢・もみじおろし・あさつきを添える。"],
   tips:["「海のフォアグラ」と呼ばれ、冬がいちばん脂がのる。","血管取りは根気よく。きれいにするほど臭みがない。","スーパーには蒸した「あん肝」もあり、切るだけで食べられる。"]},
  "西班牙鮟鱇炖饭":{serves:"3〜4",time:"50分",
   ingT:[["あんこう（切り身）","400g"],["米（洗わない）","1.5合（約220g）"],["えび（殻付き）","6尾"],["玉ねぎ","1/2個"],["赤パプリカ","1/2個"],["にんにく","2かけ"],["トマト","1個"]],
   sauceT:[["オリーブオイル","大さじ4"],["サフラン","ひとつまみ"],["パプリカパウダー","小さじ1"],["魚のスープ（または水＋顆粒だし）","1L"],["白ワイン","50ml"],["塩","適量"]],
   steps:["サフランを熱い魚のスープ100mlにつける。あんこうに塩をふる。","深めの鍋にオリーブオイルを熱し、あんこうとえびの表面を焼いて取り出す。","同じ鍋で玉ねぎ・パプリカ・にんにくを5分炒め、すりおろしたトマトとパプリカパウダーを加えて2分炒める。","米を加えて1分炒め、白ワインを注ぎ、スープとサフラン水を加え、煮立ったら中火で10分煮る（ときどき混ぜる）。","あんこうとえびを戻して6〜8分、米に火が通りつつスープが残る（おじやくらい）状態にし、塩で味を調える。"],
   tips:["「アロス・カルドソ」はスープ入りのスペインの米料理で、パエリアとおじやの中間。","あんこうは身が締まっていて、長く煮てもくずれない。","米が汁を吸い続けるので、できたらすぐ食べる。"]}}}
});
window.ADD_I18N("en", {
 itoyori:{d:{
  "香煎红三鱼":{serves:"2",time:"20 min",
   ingT:[["Golden threadfin bream (itoyori), cleaned","2"],["Japanese leek (negi)","1/2"],["Ginger","1 piece"]],
   sauceT:[["Salt","1/2 tsp"],["Shaoxing or cooking wine","1 tbsp"],["Flour","2 tbsp"],["Cooking oil","2 tbsp"],["Seasoned soy sauce for fish or light soy sauce","1.5 tbsp"],["Sugar","a little"]],
   steps:["Pat the fish dry, score both sides, rub with salt and wine, rest 10 minutes and pat dry again.","Cut the leek and ginger into fine shreds.","Dust the fish lightly with flour.","Heat oil in a frying pan and cook the fish on medium-low 4 minutes per side until golden.","Plate and top with the leek and ginger. Boil the soy sauce, sugar and 2 tbsp water in the pan and pour over the fish."],
   tips:["The flesh is delicate, so use two spatulas to flip it.","Called itoyori in Japan, with pretty yellow stripes on the skin.","Simply squeezing lemon over the fried fish is also delicious."]},
  "法式纸包鱼":{serves:"2",time:"30 min",
   ingT:[["Threadfin bream fillets (or any white fish)","2"],["Carrot","1/3"],["Zucchini or Japanese leek","1/2"],["Button mushrooms","4"],["Lemon","1/2"],["Thyme or dill","a little"]],
   sauceT:[["Salt and white pepper","a little"],["Butter","20g"],["White wine","2 tbsp"],["Baking paper","2 large sheets"]],
   steps:["Preheat the oven to 200°C. Julienne the carrot and zucchini and slice the mushrooms.","Pat the fish dry and season with salt and pepper.","Fold a sheet of baking paper in half. In the middle of one half, lay the vegetables, then the fish, topped with butter, lemon slices and herbs. Drizzle with wine.","Fold over the other half and crimp the edges in small folds to seal into a half-moon parcel.","Bake on a tray for 15 minutes. The parcel will puff up.","Serve in the parcel and cut it open with scissors at the table to release the aroma."],
   tips:["Seal it tightly so the steam stays in and the fish stays moist.","Foil works if you have no baking paper.","Japan's hoiru-yaki is the same idea. Miso and mushrooms are great inside."]}}},
 mekajiki:{d:{
  "黑椒剑鱼排":{serves:"2",time:"20 min",
   ingT:[["Swordfish steaks","2 (about 300g)"],["Onion","1/2"],["Green pepper","1"]],
   sauceT:[["Salt","a little"],["Coarse black pepper","1 tsp"],["Oyster sauce","1 tbsp"],["Light soy sauce","1 tsp"],["Sugar","1 tsp"],["Butter","10g"],["Cooking oil","1 tbsp"],["Water","3 tbsp"]],
   steps:["Pat the swordfish dry and season with a little salt and black pepper.","Slice the onion and pepper. Mix the oyster sauce, soy sauce, sugar, half the black pepper and the water into a pepper sauce.","Heat oil in a frying pan and cook the fish on medium 2 minutes per side until about 70% done. Remove.","Add the butter and stir-fry the onion and pepper for 1 minute.","Pour in the sauce, bring to a boil, return the fish and coat both sides for 30 seconds."],
   tips:["Swordfish is lean and dries out if overcooked, so leave it slightly pink in the middle.","In Taiwan it's a staple of lunchbox shops.","Japanese supermarkets sell it year-round at a good price."]},
  "西西里剑鱼卷":{serves:"2–3",time:"40 min",
   ingT:[["Thinly sliced swordfish","300g (about 8 slices)"],["Breadcrumbs","4 tbsp"],["Grated Parmesan","2 tbsp"],["Pine nuts","1 tbsp"],["Raisins","1 tbsp"],["Parsley","a little"],["Bay leaves and onion pieces (for skewering)","8 each"],["Bamboo skewers","4"]],
   sauceT:[["Olive oil","4 tbsp"],["Lemon","1/2"],["Salt and black pepper","a little"]],
   steps:["Place the swordfish between plastic wrap and pound with a rolling pin to 3mm thick. Season with salt and pepper.","Toast the breadcrumbs in 1 tbsp olive oil until golden. Once cool, add the Parmesan, pine nuts, soaked and chopped raisins, chopped parsley and lemon zest, plus 1 tbsp olive oil for a moist filling.","Put a spoonful of filling on each slice and roll up.","Thread onto skewers: roll, bay leaf, onion, roll, and so on.","Brush with olive oil, sprinkle with breadcrumbs and cook at 220°C in the oven or in a pan on medium for 10–12 minutes, turning halfway.","Squeeze over lemon."],
   tips:["A famous dish from Messina, Sicily, combining sweet, salty and savory.","Japanese swordfish steaks are thick, so slice them horizontally before pounding.","Toothpicks work instead of skewers."]},
  "烤剑鱼排":{serves:"2",time:"20 min",
   ingT:[["Thick swordfish steaks (2cm or more)","2 (about 400g)"],["Lemon","1/2"],["Basil (for pesto)","1 bunch (about 30g)"],["Garlic","1 clove"],["Pine nuts or walnuts","1 tbsp"]],
   sauceT:[["Olive oil","5 tbsp"],["Grated Parmesan","1 tbsp"],["Salt and black pepper","as needed"]],
   steps:["Pesto: blend the basil, garlic, pine nuts, Parmesan, 4 tbsp olive oil and a pinch of salt.","Pat the fish dry, brush with 1 tbsp olive oil and season with salt and pepper.","Heat a grill pan or frying pan on high until smoking, add the fish and cook 3 minutes per side to get grill marks.","Take it off the heat while still slightly pink inside and rest 3 minutes.","Spoon over the pesto and squeeze over lemon."],
   tips:["Swordfish is lean, so cook it hot and fast or it dries out.","Thick steaks stay juicier than thin ones.","Salsa (tomato, onion, chili and cilantro) is another classic pairing."]}}},
 shiira:{d:{
  "台湾鬼头刀鱼排":{serves:"2",time:"20 min",
   ingT:[["Mahi-mahi fillets","2 (about 300g)"],["Garlic","3 cloves"],["Scallion","1"],["Lemon","1/4"]],
   sauceT:[["Salt","1/2 tsp"],["White pepper","a little"],["Flour","2 tbsp"],["Cooking oil","2 tbsp"],["Taiwanese thick soy paste or light soy sauce","2 tbsp"],["Sugar","1 tsp"]],
   steps:["Pat the fish dry, season with salt and white pepper for 10 minutes, pat dry again and dust lightly with flour.","Mince the garlic and mix with the soy paste, sugar and 1 tbsp cooled boiled water for garlic soy sauce.","Heat oil in a frying pan and cook the fish on medium 3 minutes per side until golden and cooked through.","Plate, scatter with scallion and serve with the garlic soy sauce and lemon."],
   tips:["Mahi-mahi is a little dry, and the flour seals in moisture.","Called shiira in Japan. Cheap and common from summer to autumn.","It can also be cut into strips and fried."]},
  "鲯鳅黄油煎":{serves:"2",time:"20 min",
   ingT:[["Mahi-mahi fillets","2"],["Lemon","1/2"],["Parsley","a little"]],
   sauceT:[["Salt and pepper","a little"],["Flour","2 tbsp"],["Olive oil","1 tbsp"],["Butter","20g"],["Soy sauce (optional)","1 tsp"]],
   steps:["Pat the fish dry, season with salt and pepper, rest 5 minutes and pat dry again.","Coat thinly with flour and shake off the excess.","Heat the olive oil and half the butter on medium, cook 3 minutes until golden, flip and cook 2–3 minutes more.","Add the remaining butter and spoon it over the fish as it melts. A splash of soy sauce around the pan edge gives it a Japanese twist.","Plate, squeeze over lemon and sprinkle with parsley."],
   tips:["Mahi-mahi is white and mild, perfect for meunière.","A little soy sauce makes the butter-soy flavor of Japanese yoshoku diners.","In Hawaii it's called mahi-mahi and is very popular."]}}},
 gindara:{d:{
  "清蒸银鳕鱼":{serves:"2",time:"15 min",
   ingT:[["Sablefish (black cod) pieces","2 (about 250g)"],["Ginger","1 piece"],["Japanese leek (negi)","1/2"]],
   sauceT:[["Shaoxing or cooking wine","1 tbsp"],["Seasoned soy sauce for fish","2 tbsp"],["Cooking oil","2 tbsp"]],
   steps:["Thaw the fish, pat dry and rub with wine.","Lay ginger slices on a plate, put the fish on top and scatter with shredded ginger.","Steam over boiling water on high for 6–7 minutes.","Pour off the liquid and top with shredded leek.","Pour over smoking-hot oil, then drizzle with the soy sauce."],
   tips:["Sablefish is very fatty, so a shorter steam keeps it silky.","It's often sold frozen in Japan. Thaw slowly in the fridge.","Pre-marinated saikyo-zuke sablefish isn't suitable for steaming."]},
  "味噌银鳕":{serves:"2",time:"20 min (plus 2–3 days marinating)",
   ingT:[["Raw sablefish (black cod) pieces","2 (about 250g)"],["Pickled ginger shoots (optional)","2"]],
   sauceT:[["Saikyo white miso","150g"],["Sake","3 tbsp"],["Mirin","3 tbsp"],["Sugar","2 tbsp"]],
   steps:["Boil the sake and mirin in a small pan for 20 seconds to cook off the alcohol, turn off the heat, dissolve the sugar, stir in the miso and cool.","Pat the fish dry, salt lightly for 15 minutes and pat dry again.","Coat the fish completely in the miso, put in a zip bag or wrap in cheesecloth and refrigerate 2–3 days.","Wipe off all the miso with fingers or paper towel (any left will burn).","Roast at 220°C or under a fish grill for 10–12 minutes until caramelized with dark brown spots."],
   tips:["Nobu's signature black cod miso in New York comes from Japan's saikyo-yaki.","Wipe off the miso thoroughly or it burns black quickly.","Supermarket 銀だら西京漬け only needs grilling."]}}},
 anko:{d:{
  "红烧老头鱼":{serves:"3",time:"40 min",
   ingT:[["Monkfish pieces, skin and bone-in","500g"],["Thin-sliced pork belly","80g"],["Japanese leek (negi)","1"],["Ginger","4 slices"],["Garlic","5 cloves"],["Dried red chilies (optional)","2"]],
   sauceT:[["Chinese soybean paste or doubanjiang","1.5 tbsp"],["Shaoxing or cooking wine","2 tbsp"],["Light soy sauce","1 tbsp"],["Sugar","1 tsp"],["Rice vinegar","1 tsp"],["Cooking oil","2 tbsp"],["Water","400ml"]],
   steps:["Blanch the monkfish in boiling water for 1 minute and rinse off the slime and scum in cold water.","Fry the pork in oil until the fat renders and it browns slightly.","Add the leek, ginger, garlic, chilies and bean paste and fry on low for 1 minute until fragrant.","Add the fish, splash in the wine and vinegar, then add the soy sauce, sugar and water.","Bring to a boil, then simmer on medium-low for 20 minutes, spooning the sauce over the fish.","It's done when the sauce has reduced by half and thickened slightly."],
   tips:["Monkfish releases a lot of water, so don't add too much.","The gelatinous skin and bones are the best part, so don't throw them out.","In northeast China and Shandong it's called old man fish or toad fish, best in winter."]},
  "鮟鱇肝":{serves:"4",time:"1 hour (plus 1 hour soaking)",
   ingT:[["Fresh monkfish liver","300g"],["Thin chives","3"],["Grated daikon with chili (momiji oroshi)","as needed"]],
   sauceT:[["Salt","1 tbsp"],["Sake","100ml"],["Ponzu","as needed"],["Plastic wrap and foil","1 large sheet each"]],
   steps:["Salt the liver for 30 minutes, rinse and soak in sake for 30 minutes (to remove odor).","Pick out the blood vessels and sinew on the surface and inside with a toothpick or tweezers, and press out the blood. This step decides whether it smells fishy.","Pat dry, lay on plastic wrap, roll into a log about 5cm across, twist the ends tight and wrap again in foil.","Steam over boiling water on medium for 30 minutes.","Cool, chill 2 hours to set, cut into 1.5cm slices and serve with ponzu, momiji oroshi and chives."],
   tips:["Called the foie gras of the sea, and richest in winter.","Be patient removing the vessels. The cleaner, the less fishy.","Supermarkets also sell steamed ankimo ready to slice."]},
  "西班牙鮟鱇炖饭":{serves:"3–4",time:"50 min",
   ingT:[["Monkfish pieces","400g"],["Rice (unwashed)","1.5 rice-cooker cups (about 220g)"],["Shell-on shrimp","6"],["Onion","1/2"],["Red bell pepper","1/2"],["Garlic","2 cloves"],["Tomato","1"]],
   sauceT:[["Olive oil","4 tbsp"],["Saffron","a pinch"],["Paprika","1 tsp"],["Fish stock (or water plus stock granules)","1 liter"],["White wine","50ml"],["Salt","as needed"]],
   steps:["Soak the saffron in 100ml hot stock. Salt the monkfish.","Heat olive oil in a deep pan, sear the monkfish and shrimp and set aside.","In the same pan, fry the onion, pepper and garlic for 5 minutes, then add grated tomato and paprika for 2 minutes.","Add the rice and stir 1 minute, pour in the wine, then the stock and saffron water. Bring to a boil and simmer on medium for 10 minutes, stirring now and then.","Return the fish and shrimp and cook 6–8 minutes more, until the rice is done but still soupy like porridge. Season with salt."],
   tips:["Arroz caldoso is a soupy Spanish rice, between paella and porridge.","Monkfish is firm and won't fall apart with long cooking.","The rice keeps absorbing liquid, so eat right away."]}}}
});
