window.ADD_I18N("ja", {
 bora:{d:{
  "鲻鱼冰镇":{serves:"2",time:"20分",
   ingT:[["刺身用ボラ（寒ボラ、さく）","200g"],["氷水","ボウル1杯"],["大葉・大根のつま","適量"]],
   sauceT:[["白味噌","大さじ2"],["酢","大さじ1"],["砂糖","大さじ1"],["からし","小さじ1/2"]],
   steps:["冬にきれいな海でとれたボラ（寒ボラ）だけを使う。夏や河口のボラはにおいがあることがある。","白味噌・酢・砂糖・からしを混ぜて、からし酢味噌を作る。","皮を引き、包丁を斜めに入れて2〜3mmの薄切りにする。","氷水に入れて30秒〜1分かき混ぜ、身が縮んでコリッとしたら引き上げて水気をふく。","氷と大葉の上に盛り、酢味噌で食べる。"],
   tips:["冬のボラは身がきれいで甘く、「寒ボラ」と呼ばれる。","氷水で洗うと余分な脂とにおいが抜ける。","ボラの卵巣がからすみになる。"]},
  "地中海烤鲻鱼":{serves:"2",time:"35分",
   ingT:[["ボラ（下処理済み）","1尾（約600g）"],["レモン","1個"],["にんにく","2かけ"],["パセリ","少々"]],
   sauceT:[["オリーブオイル","大さじ4"],["オレガノ","小さじ1"],["粗塩","小さじ1"],["黒こしょう","少々"]],
   steps:["魚の水気をふき、両面に3本ずつ切り目を入れ、粗塩とこしょうをすり込み、腹にレモンの薄切りを詰める。","オリーブオイル・レモン汁・にんにくのみじん切り・オレガノを混ぜたマリネ液を魚に塗り、15分置く。","焼き網に油を塗り（くっつき防止）、炭火か220°Cのオーブンで片面8〜10分、皮がパリッとするまで焼く。","焼いている途中で2回マリネ液を塗る。","パセリを散らし、レモンを搾る。"],
   tips:["地中海沿岸でよく見る焼き魚。シンプルだが香りがよい。","焼き網はしっかり熱して油を塗ると、皮がくっつかない。","冬の外海のボラを選べばにおいがない。"]}}},
 koi:{d:{
  "鲤鱼味噌汤":{serves:"4",time:"3時間",
   ingT:[["鯉（輪切り・鱗付き、3cm幅）","1尾（約1kg）"],["ごぼう","1本"],["生姜","1かけ"],["長ねぎ","1本"]],
   sauceT:[["酒","200ml"],["水","1.2L"],["赤味噌","大さじ5"],["砂糖","大さじ1"],["粉山椒","少々"]],
   steps:["魚屋に頼んで鯉をうろこ付きのまま輪切りにしてもらい、苦玉（緑色の胆のう。つぶれるととても苦い）を取ってもらう。","ごぼうは皮をこそげて薄切りにして水にさらし、生姜はせん切りにする。","鍋に鯉・酒・水を入れて煮立て、アクを取り、生姜とごぼうを加えて弱火で1時間煮る。","味噌の半量と砂糖を溶き入れ、落とし蓋をしてごく弱火でさらに1.5〜2時間、骨とうろこがやわらかくなるまで煮る。","最後に残りの味噌で味を調え、ねぎを入れて2分煮て、粉山椒をふる。"],
   tips:["長野や山形など内陸の伝統料理。うろこも骨も食べられる。","苦玉は必ず取る。魚屋に頼むのがいちばん安全。","圧力鍋なら40分に短縮できる。"]},
  "波兰圣诞鲤鱼":{serves:"3〜4",time:"40分（漬け1時間）",
   ingT:[["鯉の切り身（白身魚でも）","4切れ（約600g）"],["レモン","1/2個"],["ポテトサラダ（付け合わせ）","適量"]],
   sauceT:[["塩・黒こしょう","適量"],["小麦粉","大さじ4"],["卵（お好みで）","1個"],["パン粉（お好みで）","大さじ4"],["バター","30g"],["サラダ油","大さじ2"]],
   steps:["鯉に塩・こしょう・レモン汁をふり、冷蔵庫で1時間置く（泥臭さを取る）。","水気をふいて小麦粉をまぶす（カリッとさせたければ溶き卵とパン粉もつける）。","フライパンに油とバターを入れ、中火でバターが泡立つまで熱する。","魚を入れて片面5〜6分ずつ、きつね色に中まで焼く。","レモンを搾り、ポテトサラダを添える。"],
   tips:["ポーランドやチェコではクリスマスイブに肉を食べず、鯉のフライがメイン。","鯉にはY字形の小骨が多いので、食べるときに注意。","レモン汁に漬けると淡水魚の泥臭さが消える。"]}}},
 sogyo:{d:{
  "水煮鱼":{serves:"3〜4",time:"45分",
   ingT:[["白身魚の切り身（たら・鯛など）","500g"],["大豆もやし","200g"],["卵白","1個分"],["にんにく","5かけ"],["生姜","1かけ"],["長ねぎ","1/2本"]],
   sauceT:[["郫県豆板醤","大さじ2"],["火鍋の素（お好みで）","30g"],["鷹の爪","15本"],["花椒","大さじ1"],["片栗粉","大さじ1"],["塩・料理酒","各少々"],["サラダ油","大さじ6"],["水","600ml"]],
   steps:["魚を斜めに5mm厚さのそぎ切りにし、塩・料理酒・卵白・片栗粉をもみ込んで15分置く。","鍋に油大さじ2を熱してもやしを1分炒め、塩をして大きな器の底に敷く。","油大さじ2を足し、弱火で豆板醤と火鍋の素を炒めて赤い油を出し、生姜・にんにくのみじん切りとねぎを炒め、水を加えて煮立てる。","魚を1枚ずつ入れて箸でそっとほぐし、1〜2分、白くなるまで煮て、汁ごと器に移す。","魚の上に鷹の爪のぶつ切り・花椒・にんにくのみじん切りをのせる。","残りの油大さじ2（多めでも）を煙が出るまで熱し、唐辛子の上にかけて「ジュッ」と音を立てる。"],
   tips:["下味の衣をつけると、身がなめらかでくずれない。","最後にかける油は十分熱く。唐辛子と花椒の香りが立つ。","日本には草魚がないので、たら・鯛・バサの切り身で十分おいしい。"]},
  "西湖醋鱼":{serves:"2〜3",time:"35分",
   ingT:[["すずき（草魚の代わり）","1尾（約700g）"],["生姜","1かけ"],["長ねぎ","1本"]],
   sauceT:[["紹興酒","大さじ2"],["醤油","大さじ3"],["砂糖","大さじ3"],["黒酢（鎮江香醋）","大さじ3"],["片栗粉","大さじ1＋水大さじ3"],["水","約2L（ゆで用）"]],
   steps:["魚のうろこと内臓を取り、腹から中骨に沿って、つながった二枚（骨付きと骨なし）に開き、骨付き側の身の厚い部分に斜めに切り目を入れる。","大鍋に水・生姜の薄切り・ねぎを入れて煮立て、魚を皮を上にして入れ、ふたをして火を止め、3分置く。","再び火をつけ、軽く煮立ったら穴あきへらでそっと引き上げ、水気をきって皿に盛る。","ゆで汁200mlを小鍋に取り、紹興酒・醤油・砂糖を加えて煮立てる。","水溶き片栗粉で濃いめのとろみをつけ、最後に黒酢を混ぜて魚にかける。","生姜のみじん切りを散らす。"],
   tips:["魚は「煮る」のではなく、余熱で火を通すので身がやわらかい。","酢は最後に入れると酸味と香りが残る。","杭州の名物で甘酢味。日本ではすずきで代用できる。"]}}},
 hakuren:{d:{
  "湖北鱼丸":{serves:"4",time:"1時間",
   ingT:[["白身魚（たら・すずきなど）","1尾（身約300g）"],["卵白","1個分"],["生姜","1かけ"],["小ねぎ","2本"]],
   sauceT:[["塩","小さじ1"],["片栗粉","大さじ2"],["ラード（お好みで）","大さじ1"],["氷水","約150ml"],["白こしょう","少々"]],
   steps:["生姜とねぎをたたき、氷水に10分つけてねぎ生姜水を作る。","魚の皮と骨を取り、スプーンで身をこそげ、小骨を取り除き、包丁でごく細かくたたく（フードプロセッサーでも）。","すり身をボウルに入れ、ねぎ生姜水を4〜5回に分けて加え、そのつど一方向に力強く混ぜて吸わせる。","塩を加えてさらに5分混ぜると粘りが出る。卵白・片栗粉・ラードを加えて混ぜる。","鍋に水を張り、すり身を手に取って親指と人さし指の間から丸く絞り出し、スプーンですくって水に落とす。","全部入れたら弱火でゆっくり加熱し、沸騰直前に浮いてきたら完成。ぐらぐら煮立てない。"],
   tips:["塩を入れてから練るのが弾力を出すポイント。","水から入れて弱火でゆっくり煮ると、白くやわらかく仕上がる。","ゆでた魚団子は冷凍でき、スープや鍋に使える。"]},
  "红烧鲢鱼":{serves:"3",time:"35分",
   ingT:[["白身魚の切り身（ぶり・さわらでも可）","600g"],["生姜","4枚"],["長ねぎ","1本"],["にんにく","4かけ"]],
   sauceT:[["料理酒","大さじ2"],["醤油","大さじ2"],["たまり醤油","小さじ1"],["砂糖","大さじ1"],["酢","大さじ1"],["サラダ油","大さじ3"],["水","300ml"]],
   steps:["魚の水気をふき、料理酒と塩少々で10分置き、再び水気をふく。","鍋に油を熱し、魚を中火で両面きつね色に焼いて取り出す。","残った油でねぎ・生姜・にんにくを炒める。","魚を戻し、鍋肌から酢を回し入れ、醤油・たまり醤油・砂糖・水を加える。","ふたをして中弱火で15分煮て、ふたを取って煮詰める。"],
   tips:["鰱魚は小骨が多いので大きめに切って煮る。食べるときは注意。","酢で淡水魚の泥臭さが消える。","日本では鰱魚が手に入らないので、鯉やぶりの切り身で代用。"]}}},
 kokuren:{d:{
  "砂锅鱼头":{serves:"3〜4",time:"50分",
   ingT:[["鯛のかぶとなど大きな魚の頭（半割り）","1個（約1kg）"],["絹ごし豆腐","1丁"],["たけのこ水煮","100g"],["しいたけ","4枚"],["生姜","1かけ"],["小ねぎ","2本"]],
   sauceT:[["サラダ油","大さじ3"],["料理酒","大さじ2"],["熱湯","1.5L"],["塩","小さじ1"],["白こしょう","少々"]],
   steps:["魚の頭を洗い、えらと黒い膜を取って水気をふく。","鍋に油を熱して生姜の薄切りを入れ、頭の切り口を下にして3分きつね色に焼き、返して2分焼く。","料理酒をふり、熱湯を注いで強火で10分ぐらぐら煮ると、スープが白くなる。","土鍋に移し、たけのこの薄切りとしいたけを入れて中火で20分煮る。","豆腐を加えてさらに10分煮て、塩と白こしょうで調え、小ねぎを散らす。"],
   tips:["熱湯を注いで強火で煮るのが、スープを白くするコツ。","日本では花鰱の頭は手に入らないので、鯛のかぶとやぶりの頭で。","残ったスープに春雨や麺を入れても。"]},
  "天麻鱼头汤":{serves:"3〜4",time:"1.5時間",
   ingT:[["魚の頭（鯛・ぶりなど、半割り）","1個（約800g）"],["天麻（漢方店・中華食材店）","15g"],["クコの実","大さじ1"],["なつめ","4個"],["生姜","4枚"]],
   sauceT:[["サラダ油","大さじ2"],["料理酒","大さじ1"],["熱湯","1.5L"],["塩","小さじ1"]],
   steps:["天麻を洗い、30分水につける。","魚の頭のえらを取って洗い、水気をふく。鍋に油と生姜を入れ、頭を両面きつね色に焼く。","料理酒をふり、熱湯を注いで強火で10分煮る。","土鍋か煮込み鍋に移し、天麻（つけ汁ごと）となつめを加えて弱火で1時間煮る。","クコの実を加えて5分煮て、塩で調える。"],
   tips:["広東の「老火湯」。天麻は昔から養生に使われてきた。","天麻は中華食材店か通販で買える。","調味料は控えめにして、素材の味を楽しむ。"]}}},
 funa:{d:{
  "酥鲫鱼":{serves:"4",time:"3.5時間",
   ingT:[["小ぶな（10cmくらい）","500g"],["長ねぎ","3本"],["生姜","1かけ"]],
   sauceT:[["揚げ油","鍋底から3cm"],["酢","100ml"],["醤油","大さじ4"],["たまり醤油","大さじ1"],["砂糖","大さじ4"],["紹興酒","大さじ4"],["ごま油","大さじ1"],["水","400ml"]],
   steps:["小ぶなのうろこ・えら・内臓を取って洗い、水気をふく。","油を180°Cに熱し、魚を何回かに分けて5〜6分、表面がかたくカリッとなるまで揚げる。","土鍋の底にねぎのぶつ切りと生姜の薄切りを敷き、魚をすき間なく並べ、さらにねぎをのせる。","酢・醤油・たまり醤油・砂糖・紹興酒・水を混ぜて注ぎ、魚がかぶるようにする。","強火で煮立ててからごく弱火にし、ふたをして3時間煮る（圧力鍋なら40分）。途中で動かさない。","ふたを取ってごま油をたらし、冷めたら冷蔵庫で冷やし、冷たいまま食べる。骨までやわらかく食べられる。"],
   tips:["しっかり揚げてから煮ると骨がやわらかくなる。","酢が骨をやわらかくするので欠かせない。","日本でも湖のある地域では小ぶなが売られている。小あじでも代用できる。"]},
  "鲫鱼寿司":{serves:"長く楽しめる量",time:"1時間（発酵1〜2年）",
   ingT:[["子持ちのニゴロブナ","5尾"],["ご飯","約2kg"],["粗塩","約1kg"],["樽・重石","1組"]],
   sauceT:[["酒","少々"]],
   steps:["春：ふなのうろこを取り、えらから内臓を抜き（卵は残す）、えらと腹に塩を詰め、樽に塩と魚を交互に重ね、重石をして夏まで漬ける。","夏（7月）：ふなを取り出し、塩を洗い流して半日干す。","ご飯を冷まし、魚の腹にご飯を詰め、樽にご飯と魚を交互に重ねて押し固め、酒を少しふり、ふたをして重石をのせる。","ふたの上に水を張って空気を遮断し、涼しい場所で年末か翌年まで発酵させる。","取り出してご飯をぬぐい（ご飯も食べられる）、薄切りにしてそのまま、またはご飯にのせて熱いお茶をかけてお茶漬けに。"],
   tips:["滋賀県琵琶湖の伝統発酵食品で、日本の寿司の原型。味もにおいもとても強い。","作るのに1年以上かかるので、初めてなら市販の「鮒寿司」を味わってみるのがおすすめ。","昔からおなかによいとされ、薄切りを酒の肴にする。"]}}}
});
window.ADD_I18N("en", {
 bora:{d:{
  "鲻鱼冰镇":{serves:"2",time:"20 min",
   ingT:[["Winter sashimi-grade grey mullet block (kan-bora)","200g"],["Ice water","1 large bowl"],["Shiso and shredded daikon","as needed"]],
   sauceT:[["White miso","2 tbsp"],["Vinegar","1 tbsp"],["Sugar","1 tbsp"],["Japanese mustard (karashi)","1/2 tsp"]],
   steps:["Only use mullet caught in clean seas in winter (kan-bora). Summer or estuary mullet can smell off.","Mix the miso, vinegar, sugar and mustard into a mustard-vinegar miso.","Skin the fish and slice diagonally 2–3mm thin.","Stir the slices in ice water for 30 seconds to 1 minute until they shrink and turn crisp, then lift out and pat dry.","Arrange on ice and shiso and eat with the vinegar miso."],
   tips:["Winter mullet is clean and sweet, called kan-bora.","Washing in ice water removes excess fat and odor.","Mullet ovaries are made into karasumi (bottarga)."]},
  "地中海烤鲻鱼":{serves:"2",time:"35 min",
   ingT:[["Whole grey mullet, cleaned","1 (about 600g)"],["Lemon","1"],["Garlic","2 cloves"],["Parsley","a little"]],
   sauceT:[["Olive oil","4 tbsp"],["Dried oregano","1 tsp"],["Coarse salt","1 tsp"],["Black pepper","a little"]],
   steps:["Pat the fish dry, make 3 cuts on each side, rub with coarse salt and pepper and stuff the belly with lemon slices.","Mix the olive oil, lemon juice, minced garlic and oregano, brush over the fish and rest 15 minutes.","Oil the grill grate (to prevent sticking) and cook over charcoal or at 220°C for 8–10 minutes per side until the skin is crisp.","Baste twice with the marinade while grilling.","Sprinkle with parsley and squeeze over lemon."],
   tips:["A common grilled fish along the Mediterranean, simple but fragrant.","Heat and oil the grate well so the skin doesn't stick.","Choose winter, open-sea mullet to avoid any odor."]}}},
 koi:{d:{
  "鲤鱼味噌汤":{serves:"4",time:"3 hours",
   ingT:[["Carp, cut into 3cm scale-on rounds","1 (about 1kg)"],["Burdock root","1"],["Ginger","1 piece"],["Japanese leek (negi)","1"]],
   sauceT:[["Sake","200ml"],["Water","1.2 liters"],["Red miso","5 tbsp"],["Sugar","1 tbsp"],["Sansho pepper","a little"]],
   steps:["Ask the fishmonger to cut the carp into scale-on rounds and remove the gallbladder (it's green and very bitter if broken).","Scrape and thinly slice the burdock and soak in water. Julienne the ginger.","Bring the carp, sake and water to a boil, skim, add the ginger and burdock and simmer on low for 1 hour.","Dissolve in half the miso and the sugar, cover with a drop lid and simmer on the lowest heat 1.5–2 hours more, until the bones and scales soften.","Season with the remaining miso, add the leek for 2 minutes and sprinkle with sansho."],
   tips:["A traditional dish of inland areas like Nagano and Yamagata. The scales and bones are edible.","Always remove the gallbladder. Having the fishmonger do it is safest.","A pressure cooker cuts the time to 40 minutes."]},
  "波兰圣诞鲤鱼":{serves:"3–4",time:"40 min (plus 1 hour marinating)",
   ingT:[["Carp pieces (or any white fish)","4 (about 600g)"],["Lemon","1/2"],["Potato salad (to serve)","as needed"]],
   sauceT:[["Salt and black pepper","as needed"],["Flour","4 tbsp"],["Egg (optional)","1"],["Breadcrumbs (optional)","4 tbsp"],["Butter","30g"],["Cooking oil","2 tbsp"]],
   steps:["Season the carp with salt, pepper and lemon juice and refrigerate 1 hour (to remove the muddy taste).","Pat dry and coat in flour (for extra crunch, dip in egg and breadcrumbs too).","Heat the oil and butter on medium until the butter foams.","Fry the fish 5–6 minutes per side until golden and cooked through.","Squeeze over lemon and serve with potato salad."],
   tips:["In Poland and the Czech Republic no meat is eaten on Christmas Eve, and fried carp is the main dish.","Carp has many Y-shaped bones, so eat carefully.","Lemon juice removes the muddy taste of freshwater fish."]}}},
 sogyo:{d:{
  "水煮鱼":{serves:"3–4",time:"45 min",
   ingT:[["White fish fillets (cod, sea bream, etc.)","500g"],["Soybean sprouts","200g"],["Egg white","1"],["Garlic","5 cloves"],["Ginger","1 piece"],["Japanese leek (negi)","1/2"]],
   sauceT:[["Pixian doubanjiang","2 tbsp"],["Hot pot base (optional)","30g"],["Dried red chilies","15"],["Sichuan peppercorns","1 tbsp"],["Potato starch","1 tbsp"],["Salt and Shaoxing wine","a little each"],["Cooking oil","6 tbsp"],["Water","600ml"]],
   steps:["Slice the fish diagonally 5mm thick and massage with salt, wine, egg white and starch. Rest 15 minutes.","Stir-fry the sprouts in 2 tbsp oil for 1 minute, salt and spread in the bottom of a large bowl.","Add 2 more tbsp oil and fry the doubanjiang and hot pot base on low until the oil turns red. Add minced ginger and garlic and the leek, then the water, and bring to a boil.","Add the fish one slice at a time, gently separating with chopsticks, and cook 1–2 minutes until white. Pour everything into the bowl.","Top the fish with cut chilies, Sichuan peppercorns and minced garlic.","Heat the remaining 2 tbsp oil (or more) until smoking and pour over the chilies so they sizzle."],
   tips:["The starch coating keeps the fish silky and intact.","The final oil must be very hot to release the chili and pepper aroma.","There's no grass carp in Japan, but cod, sea bream or basa work well."]},
  "西湖醋鱼":{serves:"2–3",time:"35 min",
   ingT:[["Sea bass (instead of grass carp)","1 (about 700g)"],["Ginger","1 piece"],["Japanese leek (negi)","1"]],
   sauceT:[["Shaoxing wine","2 tbsp"],["Soy sauce","3 tbsp"],["Sugar","3 tbsp"],["Chinkiang black vinegar","3 tbsp"],["Potato starch","1 tbsp + 3 tbsp water"],["Water","about 2 liters (for poaching)"]],
   steps:["Scale and gut the fish and split it from the belly along the backbone into two joined halves (one with bone, one without). Score the thick part of the bone side diagonally.","Boil water with sliced ginger and leek in a large pot, add the fish skin side up, cover, turn off the heat and leave 3 minutes.","Turn the heat back on, and when it barely simmers, carefully lift out the fish with a slotted spatula, drain and place on a plate.","Put 200ml of the poaching liquid in a small pan with the wine, soy sauce and sugar and bring to a boil.","Thicken well with the starch slurry, stir in the vinegar last and pour over the fish.","Sprinkle with minced ginger."],
   tips:["The fish is poached in residual heat rather than boiled, so it stays tender.","Add the vinegar last to keep its tang and aroma.","A famous sweet-and-sour dish from Hangzhou. In Japan use sea bass."]}}},
 hakuren:{d:{
  "湖北鱼丸":{serves:"4",time:"1 hour",
   ingT:[["White fish (cod, sea bass, etc.)","1 (about 300g flesh)"],["Egg white","1"],["Ginger","1 piece"],["Scallions","2"]],
   sauceT:[["Salt","1 tsp"],["Potato starch","2 tbsp"],["Lard (optional)","1 tbsp"],["Ice water","about 150ml"],["White pepper","a little"]],
   steps:["Crush the ginger and scallions and soak in ice water for 10 minutes to make scallion-ginger water.","Remove the skin and bones, scrape the flesh off with a spoon, pick out any small bones and chop very finely with a knife (or use a food processor).","Put the paste in a bowl and add the scallion-ginger water in 4–5 parts, stirring hard in one direction each time until absorbed.","Add the salt and keep beating 5 minutes until sticky and elastic, then mix in the egg white, starch and lard.","Fill a pot with cold water. Take a handful of paste and squeeze a ball out between thumb and forefinger, scoop it off with a spoon and drop into the water.","When all are in, heat slowly on low. The balls are done when they float just before boiling. Don't let it boil hard."],
   tips:["Beating after adding salt is the key to springy fish balls.","Starting in cold water over low heat keeps them white and tender.","Cooked fish balls freeze well for soups and hot pot."]},
  "红烧鲢鱼":{serves:"3",time:"35 min",
   ingT:[["White fish pieces (yellowtail or Spanish mackerel also fine)","600g"],["Ginger","4 slices"],["Japanese leek (negi)","1"],["Garlic","4 cloves"]],
   sauceT:[["Shaoxing or cooking wine","2 tbsp"],["Light soy sauce","2 tbsp"],["Dark soy sauce","1 tsp"],["Sugar","1 tbsp"],["Rice vinegar","1 tbsp"],["Cooking oil","3 tbsp"],["Water","300ml"]],
   steps:["Pat the fish dry, marinate with wine and a little salt for 10 minutes and pat dry again.","Heat oil and fry the fish on medium until golden on both sides. Remove.","Fry the leek, ginger and garlic in the remaining oil.","Return the fish, pour vinegar around the pan edge and add both soy sauces, sugar and water.","Cover and simmer on medium-low 15 minutes, then uncover and reduce."],
   tips:["Silver carp is bony, so braise it in large pieces and eat carefully.","Vinegar removes the muddy taste of freshwater fish.","Silver carp isn't sold in Japan. Use carp or yellowtail."]}}},
 kokuren:{d:{
  "砂锅鱼头":{serves:"3–4",time:"50 min",
   ingT:[["Large fish head, halved (e.g. sea bream)","1 (about 1kg)"],["Silken tofu","1 block"],["Boiled bamboo shoots","100g"],["Shiitake","4"],["Ginger","1 piece"],["Scallions","2"]],
   sauceT:[["Cooking oil","3 tbsp"],["Shaoxing or cooking wine","2 tbsp"],["Boiling water","1.5 liters"],["Salt","1 tsp"],["White pepper","a little"]],
   steps:["Rinse the head, remove the gills and black membrane and pat dry.","Heat oil with ginger slices and fry the head cut side down 3 minutes until golden, then 2 minutes on the other side.","Splash in the wine, pour in the boiling water and boil hard on high for 10 minutes until the broth turns white.","Transfer to a clay pot, add sliced bamboo shoots and shiitake and simmer on medium for 20 minutes.","Add cubed tofu for 10 more minutes, season with salt and white pepper and scatter with scallions."],
   tips:["Boiling water and high heat are what make the broth milky.","Bighead carp heads aren't sold in Japan, so use sea bream or yellowtail heads.","Add glass noodles or noodles to the leftover broth."]},
  "天麻鱼头汤":{serves:"3–4",time:"1.5 hours",
   ingT:[["Fish head, halved (sea bream, yellowtail, etc.)","1 (about 800g)"],["Gastrodia root slices (tianma, from herbal or Chinese shops)","15g"],["Goji berries","1 tbsp"],["Jujubes","4"],["Ginger","4 slices"]],
   sauceT:[["Cooking oil","2 tbsp"],["Shaoxing or cooking wine","1 tbsp"],["Boiling water","1.5 liters"],["Salt","1 tsp"]],
   steps:["Rinse the gastrodia and soak in water for 30 minutes.","Remove the gills, rinse and dry the head. Fry it with oil and ginger until golden on both sides.","Splash in the wine, add the boiling water and boil on high for 10 minutes.","Transfer to a stockpot or clay pot, add the gastrodia (with its soaking water) and jujubes and simmer on low for 1 hour.","Add the goji for 5 minutes and season with salt."],
   tips:["A Cantonese slow-cooked soup. Gastrodia has long been used for wellbeing.","Gastrodia is sold at Chinese grocers or online.","Keep the seasoning light to taste the ingredients."]}}},
 funa:{d:{
  "酥鲫鱼":{serves:"4",time:"3.5 hours",
   ingT:[["Small crucian carp (about 10cm)","500g"],["Japanese leeks (negi)","3"],["Ginger","1 piece"]],
   sauceT:[["Oil for frying","3cm deep"],["Rice vinegar","100ml"],["Light soy sauce","4 tbsp"],["Dark soy sauce","1 tbsp"],["Sugar","4 tbsp"],["Shaoxing wine","4 tbsp"],["Sesame oil","1 tbsp"],["Water","400ml"]],
   steps:["Scale, gill and gut the fish, rinse and pat dry.","Heat oil to 180°C and fry in batches for 5–6 minutes until the skin is hard and crisp.","Line a clay pot with leek pieces and ginger slices, pack the fish snugly on top and cover with more leek.","Mix the vinegar, both soy sauces, sugar, wine and water and pour in to cover the fish.","Bring to a boil, then cover and cook on the lowest heat for 3 hours (40 minutes in a pressure cooker). Don't stir.","Uncover, drizzle with sesame oil, cool and chill. Eat cold. The bones are soft enough to eat."],
   tips:["Frying thoroughly before braising makes the bones crumbly.","The vinegar softens the bones, so don't skip it.","Small crucian carp (kobuna) are sold in Japanese lake regions. Small horse mackerel also work."]},
  "鲫鱼寿司":{serves:"lasts a long time",time:"1 hour (plus 1–2 years fermenting)",
   ingT:[["Nigorobuna crucian carp with roe","5"],["Cooked rice","about 2kg"],["Coarse salt","about 1kg"],["Barrel and weight","1 set"]],
   sauceT:[["Sake","a little"]],
   steps:["Spring: scale the fish, pull the guts out through the gills (keep the roe), pack the gills and belly with salt, layer salt and fish in a barrel and weigh down until summer.","Summer (July): take out the fish, rinse off the salt and air-dry for half a day.","Cool the rice, stuff the bellies with it, layer rice and fish in the barrel, press firmly, sprinkle with a little sake, cover and weigh down.","Pour a little water on the lid to seal out air and ferment in a cool place until year's end or the following year.","Remove, wipe off the rice (it's edible too) and slice thin to eat as is, or on rice with hot tea poured over."],
   tips:["A traditional fermented food from Lake Biwa in Shiga and the ancestor of sushi. Very strong in taste and smell.","It takes over a year, so first try ready-made funazushi.","Traditionally considered good for digestion, and eaten thinly sliced with sake."]}}}
});
