window.ADD_I18N("ja", {
 "mandarin-fish":{d:{
  "松鼠鳜鱼":{serves:"3〜4",time:"60分",
   ingT:[["鱖魚かすずき・鯛（一尾）","1尾（約700g）"],["松の実（お好みで）","大さじ1"],["グリーンピース（お好みで）","大さじ1"]],
   sauceT:[["塩・料理酒","各少々"],["片栗粉","約100g（まぶす用）"],["ケチャップ","大さじ5"],["砂糖","大さじ3"],["酢","大さじ3"],["塩","少々"],["水溶き片栗粉","片栗粉大さじ1＋水大さじ3"],["水","100ml"],["揚げ油","鍋底から5cm"]],
   steps:["魚のうろこと内臓を取り、頭を切り落とす。背から中骨に沿って身を2枚におろし（尾の部分はつなげたまま）、中骨と腹骨を切り取る。","皮を下にして、まず斜めに、次にまっすぐ包丁を入れて格子状の切り目を入れる。皮まで届くが破らない深さに。塩と料理酒をまぶして10分置く。","身と頭に片栗粉をまんべんなくまぶし、切り目の間にもつけ、余分をはたく。","油を180°Cに熱し、尾を持って身を外側に反らせ、まず身に油をかけて形を固めてから全体を入れ、4〜5分きつね色にカリッと揚げる。頭も揚げる。","皿に魚と頭を並べて魚の形にする。","鍋に油を少し残し、ケチャップ・砂糖・酢・塩・水を煮立て、水溶き片栗粉で濃いとろみをつけ、松の実とグリーンピースを加え、熱いうちに魚にかける（ジュージュー音がする）。"],
   tips:["切り目が細かいほど、リスの毛のように見える。","蘇州の名物で難易度は高め。初めてなら切り身に切り目を入れた簡単版で。","甘酢あんは揚げたてにかけると、音も食感もいちばんよい。"]},
  "臭鳜鱼":{serves:"3",time:"40分（漬け5〜7日）",
   ingT:[["鱖魚かすずき（一尾）","1尾（約600g）"],["豚バラ肉","80g"],["たけのこ水煮","80g"],["にんにく","5かけ"],["生姜","1かけ"],["赤唐辛子","3本"],["小ねぎ","2本"]],
   sauceT:[["塩","約15g（魚の重さの2.5%）"],["サラダ油","大さじ3"],["料理酒","大さじ2"],["醤油","大さじ2"],["たまり醤油","小さじ1"],["砂糖","小さじ1"],["水","300ml"]],
   steps:["うろこ・えら・内臓を取り、水で洗わずにキッチンペーパーでふく。全体と腹の中に塩をすり込む。","保存袋に入れて空気を抜き、重しをのせて冷蔵（0〜5°C）で5〜7日漬け、毎日裏返す。身がにんにくの房のようにほぐれ、独特のにおいが出れば成功。","取り出して洗い、水気をふいて両面に切り目を入れる。","鍋に油を熱し、魚を中火で両面焼いて取り出す。","豚バラを炒めて脂を出し、生姜・にんにく・唐辛子・たけのこを炒め、魚を戻して料理酒をふり、醤油・たまり醤油・砂糖・水を加える。","中弱火で15分煮て、煮詰めたら小ねぎを散らす。"],
   tips:["安徽・徽州の名物。においは臭いが食べるとおいしい。","漬けるときは必ず冷蔵。ぬめりが出たり緑色になったら食べない。","初めてなら3〜4日漬けにすると、においが穏やか。"]}}},
 "large-croaker":{d:{
  "雪菜大汤黄鱼":{serves:"3",time:"30分",
   ingT:[["いしもち・ぐち（一尾、処理済み）","1尾（約500g）"],["雪菜（中華食材店）か高菜漬け","100g"],["たけのこ水煮","50g"],["生姜","4枚"],["小ねぎ","2本"]],
   sauceT:[["ラードかサラダ油","大さじ3"],["紹興酒","大さじ2"],["熱湯","1L"],["塩","少々"],["白こしょう","少々"]],
   steps:["魚の水気をふき、両面に切り目を入れる。雪菜は洗って絞り、刻む。たけのこは薄切りにする。","鍋を熱してラードと生姜を入れ、魚を中火で両面きつね色に焼く。","紹興酒をふり、熱湯を注いで強火で8分ぐらぐら煮ると、スープが白くなる。","雪菜とたけのこを加えてさらに5分煮る。","味見してから塩を加え（雪菜自体がしょっぱい）、白こしょうと小ねぎを散らす。"],
   tips:["熱湯と強火がスープを白くするポイント。","雪菜は塩辛いので、塩は最後に。","寧波の名物。日本では「いしもち」で代用できる。"]},
  "烤黄鱼干":{serves:"2",time:"20分",
   ingT:[["グルビ（韓国の干しイシモチ）","2尾"],["ご飯","2杯"]],
   sauceT:[["サラダ油","大さじ2"],["ごま油（お好みで）","小さじ1"]],
   steps:["グルビのひれをはさみで切り、表面の塩をさっと洗い流してキッチンペーパーでふく。","フライパンに油とごま油を入れ、中弱火で熱する。","魚を入れ、ふたをして（油がはねる）片面4〜5分ずつ、きつね色に焼く。","魚焼きグリルか200°Cのオーブンで12分焼いてもよい。","ご飯と一緒に、身をほぐしながら食べる。"],
   tips:["韓国全羅南道・霊光のグルビが最も有名で、高級なご飯のおかず。","グルビはすでに塩辛いので味付けは不要。","伝統的な食べ方：緑茶につけて冷やし、身をほぐして緑茶漬けにする（ポリグルビ）。"]}}},
 "small-croaker":{d:{
  "家常烧黄鱼":{serves:"2〜3",time:"30分",
   ingT:[["キグチか小さめのいしもち","6尾（約400g）"],["豚バラ薄切り","50g"],["にんにく","6かけ"],["生姜","3枚"],["小ねぎ","2本"]],
   sauceT:[["小麦粉","大さじ2"],["料理酒","大さじ1"],["醤油","大さじ2"],["たまり醤油","小さじ1"],["砂糖","大さじ1"],["酢","小さじ1"],["サラダ油","大さじ3"],["水","250ml"]],
   steps:["うろこを取り、えらから箸を入れてねじって内臓を取り、洗って水気をふき、小麦粉を薄くまぶす。","鍋に油を熱し、魚を中火で両面きつね色に焼いて取り出す。","豚バラを炒めて脂を出し、丸ごとのにんにくと生姜を炒めて香りを出す。","魚を戻し、料理酒と酢を回しかけ、醤油・たまり醤油・砂糖・水を加える。","中弱火で10分煮て、強火で煮詰め、小ねぎを散らす。"],
   tips:["えらから箸で内臓を取ると、腹が破れず形がきれい。","煮汁をご飯にかけるのがいちばんおいしいので、煮詰めすぎない。","丸ごと煮たにんにくもやわらかくておいしい。"]},
  "煎黄花鱼":{serves:"2",time:"20分（干す半日）",
   ingT:[["キグチか小さめのいしもち","4尾"],["ご飯","2杯"]],
   sauceT:[["粗塩","小さじ1"],["サラダ油","大さじ3"],["小麦粉（お好みで）","大さじ1"]],
   steps:["うろこを取り、えらから内臓をねじり出し（腹は開かない）、洗う。","全体に塩をして網にのせ、冷蔵庫で半日（または一晩）乾かす。","水気をふき、小麦粉を薄くはたく（くっつきにくい）。","フライパンに油を熱し、中火で片面4分ずつ、きつね色にカリッと焼く。","ご飯と一緒に食べる。"],
   tips:["韓国の家庭の焼き魚（センソングイ）。キムチとご飯と一緒に。","干すと身が締まり、焼いてもくずれにくい。","焼いている間は何度も返さない。"]}}},
 managatsuo:{d:{
  "西京烧鲳鱼":{serves:"2",time:"20分（漬け2日）",
   ingT:[["マナガツオ（切り身）","2切れ"],["はじかみ（お好みで）","2本"]],
   sauceT:[["西京味噌","150g"],["酒","大さじ2"],["みりん","大さじ2"],["砂糖","大さじ1"],["塩","少々"]],
   steps:["切り身に塩少々をふって20分置き、水気をふく。","酒とみりんを煮立ててアルコールを飛ばし、砂糖と白味噌を混ぜて冷ます。","切り身をガーゼで包んでから味噌床で包み（ガーゼなしで直接塗ってもよい）、冷蔵庫で2日漬ける。","取り出して味噌をきれいにぬぐう。","魚焼きグリルの弱火で8〜10分、一度返して表面が金褐色になるまで焼く。"],
   tips:["マナガツオは身がやわらかく脂もほどよく、西京焼きにぴったり。","味噌はしっかりぬぐい、弱火でじっくり焼かないと焦げやすい。","京都の料亭ではマナガツオの西京焼きがよく出る。"]},
  "印度香料煎鲳鱼":{serves:"2",time:"30分（漬け20分）",
   ingT:[["マナガツオ（一尾、処理済み）","2尾（1尾約300g）"],["レモン","1個"],["玉ねぎ・パクチー（添え）","適量"]],
   sauceT:[["ターメリック","小さじ1/2"],["チリパウダー","小さじ1"],["しょうが・にんにくのすりおろし","各小さじ1"],["塩","小さじ1/2"],["米粉（またはセモリナ粉）","大さじ4"],["サラダ油","大さじ4"]],
   steps:["マナガツオの両面に3本ずつ切り目を入れる。","ターメリック・チリパウダー・しょうが・にんにく・塩・レモン汁を混ぜてペーストにし、魚と切り目に塗り、20分漬ける。","両面に米粉を押しつけるようにまぶす。","フライパンに油を熱し、中火で片面4〜5分ずつ、きつね色にカリッと焼く。","玉ねぎの輪切り・パクチー・くし形のレモンを添える。"],
   tips:["インド・ムンバイやゴアの海辺の定番「ポンフレット・フライ」。","米粉で皮が特にカリッとする。","辛さはチリパウダーで調整。"]}}},
 tilapia:{d:{
  "泰式炸鱼配青芒":{serves:"2〜3",time:"40分",
   ingT:[["ティラピア（イズミダイ、一尾、処理済み）","1尾（約600g）"],["青マンゴー（または青りんご）","1個"],["エシャロット","2個"],["プリッキーヌ","2〜3本"],["パクチー","1束"],["ピーナッツ","大さじ2"]],
   sauceT:[["片栗粉","大さじ3"],["塩","少々"],["揚げ油","鍋底から4cm"],["ナンプラー","大さじ2"],["ライム果汁","大さじ2"],["パームシュガーか砂糖","大さじ1"]],
   steps:["魚の水気をふき、両面に斜めに4本ずつ切り目を入れて塩をし、片栗粉を薄くまぶす。","油を180°Cに熱し、魚を丸ごと10〜12分、一度返して、ひれまで食べられるほどカリッと揚げる。","青マンゴーは皮をむいて細切り、エシャロットは薄切り、唐辛子は刻み、パクチーはざく切りにする。","ナンプラー・ライム汁・砂糖を混ぜ、マンゴー・エシャロット・唐辛子・パクチーをあえて青マンゴーサラダにする。","揚げた魚を皿に盛り、サラダをのせ、砕いたピーナッツを散らす。"],
   tips:["タイ料理店の人気メニュー。外はカリッと中はふんわり、酸っぱ辛いサラダと。","日本で青マンゴーがなければ、青りんごか青パパイヤで。","揚げる前に魚の水気をしっかりふかないと油がはねる。"]},
  "墨西哥炸鱼":{serves:"2",time:"30分",
   ingT:[["ティラピア（一尾、処理済み）","2尾（小）"],["ライム","2個"],["トルティーヤ","4枚"],["レタス・トマト・アボカド（添え）","適量"]],
   sauceT:[["塩","小さじ1"],["ガーリックパウダー（お好みで）","小さじ1/2"],["小麦粉","大さじ3"],["揚げ油","鍋底から3cm"],["ホットソース","適量"]],
   steps:["魚の両面に3本ずつ切り目を入れ、ライムを搾り、塩とガーリックパウダーをすり込んで15分置く。","水気をふき、小麦粉を薄くはたく。","油を180°Cに熱し、魚を丸ごと6〜8分、返しながらきつね色にカリッと揚げる。","ご飯・サラダ・アボカド・温めたトルティーヤを添える。","ライムを搾りホットソースをかけ、身をほぐしてトルティーヤに包んで食べる。"],
   tips:["メキシコの海辺の家庭料理「モハラ・フリタ」。","皮までおいしく食べられるよう、カリッと揚げる。","サルサ（トマト・玉ねぎ・パクチー）を添えても。"]}}},
 namazu:{d:{
  "美国南方炸鲶鱼":{serves:"2〜3",time:"40分（漬け30分）",
   ingT:[["なまずのフィレ（白身魚でも）","4枚（約400g）"],["レモン","1/2個"]],
   sauceT:[["バターミルク（牛乳＋レモン汁大さじ1）","200ml"],["ホットソース","小さじ1"],["コーンミール","100g"],["小麦粉","大さじ3"],["ケイジャンスパイスかパプリカ","小さじ1"],["塩・こしょう","適量"],["揚げ油","鍋底から3cm"],["タルタルソース","適量"]],
   steps:["バターミルクにホットソースを混ぜ、フィレをつけて冷蔵庫で30分置く（臭みが取れ、やわらかくなる）。","コーンミール・小麦粉・スパイス・塩・こしょうを混ぜる。","フィレを取り出して軽く汁気をきり、粉に押しつけてしっかりまぶす。","油を175°Cに熱し、4〜5分きつね色にカリッと揚げる。","タルタルソースとレモンを添える。定番の付け合わせはコーンブレッドとコールスロー。"],
   tips:["アメリカ南部のソウルフード。コーンミールのつぶつぶ感が特徴。","日本ではコーンフレークを砕いて代用できる。","牛乳につけると淡水魚の泥臭さが消える。"]},
  "越南焦糖焖鱼":{serves:"3",time:"45分",
   ingT:[["なまずかさばの切り身","500g"],["エシャロット","3個"],["にんにく","3かけ"],["赤唐辛子","2本"],["小ねぎ","2本"]],
   sauceT:[["砂糖（カラメル用）","大さじ3"],["ナンプラー","大さじ3"],["ココナッツウォーターか水","200ml"],["粗挽き黒こしょう","小さじ1"],["サラダ油","大さじ1"]],
   steps:["切り身をナンプラー・にんにくとエシャロットのみじん切りの半量・砂糖小さじ1で20分漬ける。","土鍋か小鍋に砂糖と水大さじ2を入れ、中火で混ぜずに、濃い琥珀色のカラメルになるまで煮る（約5分）。","すぐに油と残りのにんにく・エシャロットを入れて30秒炒め、魚（漬け汁ごと）を入れ、両面を返してカラメルをからめる。","ココナッツウォーターを加えて煮立て、弱火にしてふたをし、25〜30分煮る。途中で一度返す。","ふたを取ってとろりとつやが出るまで煮詰め、黒こしょうをたっぷりふり、唐辛子と小ねぎを散らし、ご飯と一緒に。"],
   tips:["カラメルは濃い色まで、でも焦がさない（苦くなる）。紅茶色になったら具を入れる。","ベトナムの家庭料理「カー・コー・ト」。伝統的には土鍋で作る。","煮汁は甘辛いので、白いご飯は必須。"]}}}
});
window.ADD_I18N("en", {
 "mandarin-fish":{d:{
  "松鼠鳜鱼":{serves:"3–4",time:"60 min",
   ingT:[["Whole mandarin fish, sea bass or sea bream","1 (about 700g)"],["Pine nuts (optional)","1 tbsp"],["Green peas (optional)","1 tbsp"]],
   sauceT:[["Salt and Shaoxing wine","a little each"],["Potato starch","about 100g (for coating)"],["Ketchup","5 tbsp"],["Sugar","3 tbsp"],["White vinegar","3 tbsp"],["Salt","a little"],["Starch slurry","1 tbsp starch + 3 tbsp water"],["Water","100ml"],["Oil for frying","5cm deep"]],
   steps:["Scale and gut the fish and cut off the head. Cut the two fillets off the backbone from the back, leaving them joined at the tail, and trim away the backbone and belly bones.","Lay the fillets skin down and score in a diamond pattern, first diagonally then straight, cutting down to but not through the skin. Rub with salt and wine and rest 10 minutes.","Coat the fillets and head evenly with starch, getting it into the cuts, and shake off the excess.","Heat oil to 180°C. Hold the tail so the flesh curls outward, ladle oil over to set the shape, then lower the whole fish in and fry 4–5 minutes until golden and crisp. Fry the head too.","Arrange the fish and head on a plate in the shape of a fish.","With a little oil left in the pan, boil the ketchup, sugar, vinegar, salt and water, thicken with the slurry, add the pine nuts and peas and pour over the fish while hot (it will sizzle)."],
   tips:["The finer the scoring, the more it looks like squirrel fur.","A famous Suzhou dish and fairly difficult. Try a simplified version with scored fillets first.","Pour the sauce right after frying for the sizzle and best texture."]},
  "臭鳜鱼":{serves:"3",time:"40 min (plus 5–7 days curing)",
   ingT:[["Whole mandarin fish or sea bass","1 (about 600g)"],["Pork belly","80g"],["Boiled bamboo shoots","80g"],["Garlic","5 cloves"],["Ginger","1 piece"],["Red chilies","3"],["Scallions","2"]],
   sauceT:[["Salt","about 15g (2.5% of the fish weight)"],["Cooking oil","3 tbsp"],["Shaoxing or cooking wine","2 tbsp"],["Light soy sauce","2 tbsp"],["Dark soy sauce","1 tsp"],["Sugar","1 tsp"],["Water","300ml"]],
   steps:["Scale, gill and gut the fish. Don't rinse it, just wipe dry with paper towel. Rub salt all over and inside.","Seal in a zip bag with the air pressed out, weigh down and cure in the fridge (0–5°C) for 5–7 days, turning daily. It's ready when the flesh separates into flakes like garlic cloves and has a distinctive smell.","Rinse, pat dry and score both sides.","Fry the fish in oil on medium until golden on both sides. Remove.","Fry the sliced pork until the fat renders, add the ginger, garlic, chilies and bamboo, return the fish, splash in the wine and add both soy sauces, sugar and water.","Simmer on medium-low 15 minutes, reduce and scatter with scallions."],
   tips:["A famous Huizhou dish from Anhui that smells pungent but tastes wonderful.","Always cure it in the fridge. Discard if it turns slimy or greenish.","For a first try, cure it 3–4 days for a milder smell."]}}},
 "large-croaker":{d:{
  "雪菜大汤黄鱼":{serves:"3",time:"30 min",
   ingT:[["Whole yellow croaker or white croaker (ishimochi), cleaned","1 (about 500g)"],["Pickled mustard greens (xuecai) or takana pickles","100g"],["Boiled bamboo shoots","50g"],["Ginger","4 slices"],["Scallions","2"]],
   sauceT:[["Lard or cooking oil","3 tbsp"],["Shaoxing wine","2 tbsp"],["Boiling water","1 liter"],["Salt","a little"],["White pepper","a little"]],
   steps:["Pat the fish dry and score both sides. Rinse, squeeze and chop the pickled greens, and slice the bamboo.","Heat lard with the ginger and fry the fish on medium until golden on both sides.","Splash in the wine, add the boiling water and boil hard on high for 8 minutes until the broth turns milky.","Add the pickled greens and bamboo and simmer 5 more minutes.","Taste before salting (the pickles are salty), then add white pepper and scallions."],
   tips:["Boiling water plus high heat is what turns the broth white.","The pickles are salty, so season last.","A famous Ningbo dish. In Japan use ishimochi."]},
  "烤黄鱼干":{serves:"2",time:"20 min",
   ingT:[["Korean dried yellow croaker (gulbi)","2"],["Steamed rice","2 bowls"]],
   sauceT:[["Cooking oil","2 tbsp"],["Sesame oil (optional)","1 tsp"]],
   steps:["Snip off the fins, rinse off the surface salt and pat dry with paper towel.","Heat the oil and sesame oil in a frying pan on medium-low.","Add the fish, cover (it spatters) and cook 4–5 minutes per side until golden.","Or grill or roast at 200°C for 12 minutes.","Pick the flesh off and eat with rice."],
   tips:["Gulbi from Yeonggwang in South Jeolla is the most famous, a prized side dish for rice.","It's already salty, so no seasoning is needed.","The traditional way is to soak it in green tea, chill and eat the flaked flesh with green tea over rice (bori-gulbi)."]}}},
 "small-croaker":{d:{
  "家常烧黄鱼":{serves:"2–3",time:"30 min",
   ingT:[["Small yellow croaker or small white croaker","6 (about 400g)"],["Thin-sliced pork belly","50g"],["Garlic","6 cloves"],["Ginger","3 slices"],["Scallions","2"]],
   sauceT:[["Flour","2 tbsp"],["Shaoxing or cooking wine","1 tbsp"],["Light soy sauce","2 tbsp"],["Dark soy sauce","1 tsp"],["Sugar","1 tbsp"],["Rice vinegar","1 tsp"],["Cooking oil","3 tbsp"],["Water","250ml"]],
   steps:["Scale the fish, twist out the guts with chopsticks through the gills, rinse, pat dry and dust lightly with flour.","Fry the fish in oil on medium until golden on both sides. Remove.","Fry the pork until the fat renders, then add the whole garlic cloves and ginger until fragrant.","Return the fish, splash in the wine and vinegar and add both soy sauces, sugar and water.","Simmer on medium-low 10 minutes, reduce on high and scatter with scallions."],
   tips:["Removing the guts through the gills keeps the belly intact and the fish neat.","The sauce over rice is the best part, so don't reduce it too far.","The braised whole garlic cloves are delicious too."]},
  "煎黄花鱼":{serves:"2",time:"20 min (plus half a day drying)",
   ingT:[["Small yellow croaker or small white croaker","4"],["Steamed rice","2 bowls"]],
   sauceT:[["Coarse salt","1 tsp"],["Cooking oil","3 tbsp"],["Flour (optional)","1 tbsp"]],
   steps:["Scale the fish, twist out the guts through the gills (without opening the belly) and rinse.","Salt all over and air-dry on a rack in the fridge for half a day (or overnight).","Pat dry and dust lightly with flour (it prevents sticking).","Fry in oil on medium 4 minutes per side until golden and crisp.","Eat with rice."],
   tips:["A Korean home-style grilled fish (saengseon-gui), with kimchi and rice.","Drying firms the flesh so it doesn't break when frying.","Don't flip it too often."]}}},
 managatsuo:{d:{
  "西京烧鲳鱼":{serves:"2",time:"20 min (plus 2 days marinating)",
   ingT:[["Pomfret pieces","2"],["Pickled ginger shoots (optional)","2"]],
   sauceT:[["Saikyo white miso","150g"],["Sake","2 tbsp"],["Mirin","2 tbsp"],["Sugar","1 tbsp"],["Salt","a little"]],
   steps:["Sprinkle the fish lightly with salt, rest 20 minutes and pat dry.","Boil the sake and mirin to cook off the alcohol, mix in the sugar and miso and cool.","Wrap the fish in cheesecloth, then cover in the miso (or spread it directly) and refrigerate 2 days.","Remove and wipe off all the miso.","Grill on low for 8–10 minutes, turning once, until golden brown."],
   tips:["Pomfret is tender with moderate fat, ideal for saikyo-yaki.","Wipe off the miso and grill gently or it burns easily.","Kyoto ryotei restaurants often serve pomfret this way."]},
  "印度香料煎鲳鱼":{serves:"2",time:"30 min (plus 20 min marinating)",
   ingT:[["Whole pomfret, cleaned","2 (about 300g each)"],["Lemon","1"],["Onion rings and cilantro (to serve)","as needed"]],
   sauceT:[["Ground turmeric","1/2 tsp"],["Chili powder","1 tsp"],["Ginger and garlic paste","1 tsp each"],["Salt","1/2 tsp"],["Rice flour (or semolina)","4 tbsp"],["Cooking oil","4 tbsp"]],
   steps:["Make 3 cuts on each side of the fish.","Mix the turmeric, chili, ginger-garlic paste, salt and lemon juice into a paste, rub over the fish and into the cuts and marinate 20 minutes.","Press rice flour onto both sides.","Fry in oil on medium 4–5 minutes per side until golden and crisp.","Serve with onion rings, cilantro and lemon wedges."],
   tips:["A coastal classic in Mumbai and Goa called pomfret fry.","Rice flour makes the crust especially crisp.","Adjust the heat with the chili powder."]}}},
 tilapia:{d:{
  "泰式炸鱼配青芒":{serves:"2–3",time:"40 min",
   ingT:[["Whole tilapia, cleaned","1 (about 600g)"],["Green mango (or green apple)","1"],["Shallots","2"],["Bird's eye chilies","2–3"],["Cilantro","1 bunch"],["Roasted peanuts","2 tbsp"]],
   sauceT:[["Potato starch","3 tbsp"],["Salt","a little"],["Oil for frying","4cm deep"],["Fish sauce","2 tbsp"],["Lime juice","2 tbsp"],["Palm sugar or sugar","1 tbsp"]],
   steps:["Pat the fish dry, make 4 diagonal cuts on each side, salt and dust lightly with starch.","Heat oil to 180°C and fry the whole fish 10–12 minutes, turning once, until very crisp (even the fins are edible).","Peel and shred the mango, thinly slice the shallots, chop the chilies and cut the cilantro.","Mix the fish sauce, lime juice and sugar and toss with the mango, shallot, chili and cilantro.","Plate the fish, pile the salad on top and scatter with crushed peanuts."],
   tips:["A favorite in Thai restaurants: crisp outside, tender inside, with a sour-spicy salad.","Without green mango, use green apple or green papaya.","Dry the fish well before frying or the oil will spatter."]},
  "墨西哥炸鱼":{serves:"2",time:"30 min",
   ingT:[["Whole tilapia, cleaned","2 small"],["Limes","2"],["Corn tortillas","4"],["Lettuce, tomato and avocado (to serve)","as needed"]],
   sauceT:[["Salt","1 tsp"],["Garlic powder (optional)","1/2 tsp"],["Flour","3 tbsp"],["Oil for frying","3cm deep"],["Hot sauce","as needed"]],
   steps:["Make 3 cuts on each side, squeeze over lime, rub with salt and garlic powder and rest 15 minutes.","Pat dry and dust lightly with flour.","Heat oil to 180°C and fry the whole fish 6–8 minutes, turning, until golden and crisp.","Serve with rice, salad, avocado and warm tortillas.","Squeeze over lime, add hot sauce, and pull off the flesh to wrap in tortillas."],
   tips:["A home-style dish from Mexico's coast called mojarra frita.","Fry it very crisp so even the skin is tasty.","Salsa (tomato, onion and cilantro) goes well too."]}}},
 namazu:{d:{
  "美国南方炸鲶鱼":{serves:"2–3",time:"40 min (plus 30 min soaking)",
   ingT:[["Catfish fillets (or any white fish)","4 (about 400g)"],["Lemon","1/2"]],
   sauceT:[["Buttermilk (or milk + 1 tbsp lemon juice)","200ml"],["Hot sauce","1 tsp"],["Coarse cornmeal","100g"],["Flour","3 tbsp"],["Cajun seasoning or paprika","1 tsp"],["Salt and black pepper","as needed"],["Oil for frying","3cm deep"],["Tartar sauce","as needed"]],
   steps:["Mix the buttermilk and hot sauce and soak the fillets in the fridge for 30 minutes (removes odor and tenderizes).","Mix the cornmeal, flour, spices, salt and pepper.","Lift out the fillets, let them drip briefly and press firmly into the coating.","Fry at 175°C for 4–5 minutes until golden and crisp.","Serve with tartar sauce and lemon. Traditional sides are cornbread and coleslaw."],
   tips:["Southern soul food, with cornmeal's gritty crunch as its hallmark.","In Japan, crushed cornflakes can stand in for cornmeal.","Soaking in milk removes the muddy taste of freshwater fish."]},
  "越南焦糖焖鱼":{serves:"3",time:"45 min",
   ingT:[["Catfish or mackerel pieces","500g"],["Shallots","3"],["Garlic","3 cloves"],["Red chilies","2"],["Scallions","2"]],
   sauceT:[["Sugar (for caramel)","3 tbsp"],["Fish sauce","3 tbsp"],["Coconut water or water","200ml"],["Coarse black pepper","1 tsp"],["Cooking oil","1 tbsp"]],
   steps:["Marinate the fish with the fish sauce, half the minced garlic and shallot and 1 tsp sugar for 20 minutes.","Put the sugar and 2 tbsp water in a clay pot or small pan and cook on medium without stirring until it turns a deep amber caramel (about 5 minutes).","Immediately add the oil and remaining garlic and shallot for 30 seconds, then the fish with its marinade, turning to coat in caramel.","Add the coconut water, bring to a boil, cover and simmer on low 25–30 minutes, turning once.","Uncover and reduce until thick and glossy. Finish with plenty of black pepper, chili and scallions, and serve with rice."],
   tips:["Take the caramel dark but not burnt (it turns bitter). Add the rest when it's the color of black tea.","A Vietnamese home dish, cá kho tộ, traditionally made in a clay pot.","The sauce is salty-sweet, so plain rice is a must."]}}}
});
