window.ADD_I18N("ja", {
 "black-carp":{d:{
  "青鱼干":{serves:"6",time:"30分（漬けと干し7〜10日）",
   ingT:[["大きな青魚（ぶり・さば）","1尾（約2kg）"],["生姜","1かけ"],["ひも","1本"]],
   sauceT:[["粗塩","約60g（魚の重さの3%）"],["花椒","大さじ1"],["焼酎か紹興酒","大さじ3"],["砂糖","大さじ1"]],
   steps:["魚を背から開いて一枚にし、内臓と黒い膜を取り、キッチンペーパーでふく。水で洗いすぎない。","花椒と塩を弱火でから炒りして香りを出し、冷めたら砂糖を混ぜ、魚の両面に均一にすり込み、焼酎をふる。","保存袋に入れて重しをのせ、冷蔵庫で3日漬け、毎日裏返す。","取り出して水気をふき、竹串で広げて、涼しく風通しのよい場所に5〜7日吊るし、表面がかたく乾くまで干す。","食べるときはぶつ切りにし、生姜の薄切りと紹興酒少々をのせ、湯が沸いた蒸し器で20分蒸す。冷たくても温かくても、紹興酒と一緒に。"],
   tips:["冬（気温10°C以下）に作る。暖かいと傷みやすい。","江南地方の正月の伝統的な保存食。","干し上がったら切り分けて冷凍保存できる。"]}}},
 hamaguri:{d:{
  "文蛤蒸蛋":{serves:"2〜3",time:"25分",
   ingT:[["はまぐりかあさり","8個（約200g）"],["卵","3個"],["小ねぎ","1本"]],
   sauceT:[["ぬるま湯（貝の汁を含む）","約270ml（卵液の1.5倍）"],["塩","少々"],["醤油","小さじ1"],["ごま油","数滴"]],
   steps:["はまぐりの砂抜きをして、殻をこすり洗いする。","鍋に水300mlとはまぐりを入れ、口が開いたらすぐ取り出す。煮汁は目の細かいざるでこし、人肌に冷ます。","卵を溶き、1.5倍量の貝の汁（足りなければぬるま湯）と塩少々を混ぜ、ざるでこして泡を取る。","はまぐりを深皿に並べ、卵液を注ぎ、ラップか皿でふたをする。","湯が沸いた蒸し器に入れ、中弱火で10〜12分、卵液が固まり中央が軽くゆれる程度まで蒸す。","醤油とごま油をかけ、小ねぎを散らす。"],
   tips:["卵液をこし、ラップをして中弱火で蒸すと、表面が鏡のようになめらかになる。","貝の汁にうまみがあるので、塩はほとんどいらない。","はまぐりは口が開いたらすぐ取り出すと、蒸してもかたくならない。"]},
  "烤文蛤":{serves:"2",time:"20分（砂抜き別）",
   ingT:[["はまぐり（大）","6個"],["すだち（お好みで）","1/2個"]],
   sauceT:[["醤油","数滴"],["酒（お好みで）","少々"]],
   steps:["はまぐりを2時間砂抜きし、殻をこすり洗いする。","はまぐりの背（2枚の殻のつなぎ目）にある黒いじん帯を小さなナイフで切る（焼いたときに殻がひっくり返らず、汁がこぼれない）。","炭火、焼き網、またはフライパンを中火で熱し、はまぐりをのせる。","3〜5分で殻が開いたら、醤油と酒を数滴たらし、さらに30秒焼く。","汁ごと食べ、すだちを少し搾る。"],
   tips:["三重県桑名の名物。「その手は桑名の焼き蛤」ということわざもある。","じん帯を切るのがポイント。切らないと殻が開いたときに汁が全部こぼれる。","汁がとてもおいしいので、必ず飲む。"]}}},
 shijimi:{d:{
  "台式腌蚬仔":{serves:"4（ご飯のおかず）",time:"20分（漬け一晩）",
   ingT:[["しじみ","300g"],["にんにく","6かけ"],["赤唐辛子","2本"],["生姜（お好みで）","1かけ"]],
   sauceT:[["醤油","100ml"],["米酒か酒","50ml"],["砂糖","大さじ1"],["酢","小さじ1"],["湯冷まし","50ml"]],
   steps:["しじみを3時間砂抜きしてこすり洗いし、冷凍庫で一晩凍らせる（凍らせると口が開きやすく、うまみも増す）。","にんにくをつぶし、唐辛子を輪切りにする。醤油・米酒・砂糖・酢・湯冷ましを混ぜて漬け汁を作り、にんにくと唐辛子を加える。","湯を沸かして火を止め、凍ったしじみを入れて1〜2分つけ、口がわずかに開いたらすぐ引き上げる。","すぐに漬け汁に入れ、ふたをして冷蔵庫で一晩漬ける。","翌日から食べられる。冷蔵で2日以内に食べきる。"],
   tips:["しじみは少し開く程度に。火が通りすぎると身が縮んで食感が変わる。","この台湾料理のしじみは半生なので、とても新鮮で信頼できるものを使う。おなかが弱い人は長めに湯につける。","漬け汁をご飯にかけてもおいしい。"]},
  "蚬子汤":{serves:"3",time:"20分（砂抜き別）",
   ingT:[["しじみ","400g"],["にら","1/2束"],["長ねぎ（お好みで）","少々"]],
   sauceT:[["水","1L"],["塩","小さじ1"],["おろしにんにく（お好みで）","小さじ1/2"]],
   steps:["しじみを1%の塩水に3時間つけて砂抜きし、こすり洗いする。","鍋に水としじみを入れて中火にかけ、ゆっくり温めてうまみを出す。","沸騰したらアクを取り、しじみがすべて開いてスープが乳白色になるまで煮る。","塩（とにんにく）で味を調える。","ざく切りのにらを入れ、30秒煮て火を止める。"],
   tips:["韓国・釜山や河東の「チェチョプクク」。昔から二日酔いのスープ。","水から煮ると、しじみのうまみがしっかり出る。","身を取り出し、スープだけをご飯と一緒に飲んでもよい。"]}}},
 awabi:{d:{
  "蚝油鲍鱼":{serves:"2",time:"30分",
   ingT:[["活あわびかとこぶし","4個（1個約60g）"],["ブロッコリー","1/2株"],["生姜","2枚"],["にんにく","2かけ"]],
   sauceT:[["オイスターソース","大さじ2"],["醤油","小さじ1"],["砂糖","小さじ1"],["料理酒","大さじ1"],["水","100ml"],["水溶き片栗粉","片栗粉小さじ1＋水大さじ2"],["サラダ油","大さじ1"]],
   steps:["あわびのふちの黒い膜をブラシでこすり洗いし、スプーンを殻に沿わせて身を取り出し、内臓を除いて表面に格子の切り目を入れる。","料理酒を入れた熱湯にあわびを30秒通して取り出す。ブロッコリーは小房に分け、塩ゆで1分して皿に並べる。","鍋に油を熱して生姜とにんにくを炒め、オイスターソース・醤油・砂糖・水を加えて煮立てる。","あわびを入れ、弱火で3〜5分煮る。","水溶き片栗粉でとろみをつけ、あわびを殻に戻すかブロッコリーの中央に盛り、たれをかける。"],
   tips:["あわびは加熱時間が短いほどやわらかい。煮すぎるとかたくなる。","日本の「とこぶし」は小さなあわびで、ずっと安い。作り方は同じ。","内臓（肝）は取っておいて、別に炒めても。"]},
  "鲍鱼水贝":{serves:"2",time:"20分",
   ingT:[["活あわび","1個（約200g）"],["きゅうり","1本"],["氷","ボウル1杯"],["大葉か芽もの（お好みで）","少々"]],
   sauceT:[["塩","小さじ1くらい（約1%の氷塩水）"],["湯冷まし","500ml"],["わさび・醤油（お好みで）","適量"]],
   steps:["あわびに塩をふり、ブラシで身のふちと裏を強くこすって黒いぬめりを取り、洗い流す。","木べらかしゃもじを殻と身の薄い側に差し込み、貝柱をはがして身を取り出し、内臓（肝は別に食べられる）と口（かたい部分）を取る。","身を1.5cm角に切り、きゅうりも同じ大きさに切る。","湯冷ましに塩と氷を加えて氷塩水を作り、あわびときゅうりを入れて5分つける。","氷水ごとガラスの器に盛り、そのまま（わさび醤油をつけても）食べる。"],
   tips:["夏の料理。角切りの生あわびのコリコリした食感を楽しむ。","氷塩水につけると身が締まり、さらにコリッとする。","千葉・房総などの伝統的な食べ方。"]},
  "鲍鱼粥":{serves:"3",time:"50分（米の浸水1時間）",
   ingT:[["活あわび（肝付き）","2個（1個約100g）"],["米","1カップ（約180g）"],["小ねぎ・ごま・のり（添え）","少々"]],
   sauceT:[["ごま油","大さじ2"],["水","1.2L"],["塩か薄口醤油","適量"]],
   steps:["米を洗って1時間水につけ、水気をきる。","あわびをこすり洗いして身を取り出し、緑色の肝を分け（口は取る）、身を薄切りにし、肝は刻むかつぶす。","鍋にごま油を熱し、肝を1分炒め、身を加えてさらに1分炒める。","米を加え、2分炒めて米粒を半透明にする。","水を加えて煮立て、弱火で30分、焦げつかないようときどき混ぜながら、米粒が花開くまで煮る。","塩か薄口醤油で調え、小ねぎ・ごま・のりを散らす。"],
   tips:["あわびの肝が決め手。粥がきれいな薄緑色になり、味も濃くなる。","済州島の名物で、韓国の滋養粥。","冷凍あわびでもよいが、肝付きのものを。"]}}},
 sazae:{d:{
  "白灼海螺":{serves:"2",time:"20分",
   ingT:[["さざえ","4〜6個"],["生姜","1かけ"],["小ねぎ","1本"]],
   sauceT:[["料理酒","大さじ1"],["塩","小さじ1"],["しょうが酢（しょうがのみじん切り＋黒酢）","適量"],["わさび醤油","適量"]],
   steps:["さざえの殻をこすり洗いし、きれいな水に30分つける。","鍋に水・生姜の薄切り・ねぎ・料理酒・塩を入れ、さざえを入れて火にかける。","沸騰したら中火で8〜10分ゆでる。","取り出し、つまようじを口に刺して回しながら身を引き出す（尾の緑色のわたは食べられる。少し苦い）。","薄切りにし、しょうが酢かわさび醤油で食べる。"],
   tips:["水からゆっくりゆでると、身を引き出しやすい。","口のかたいふたは食べられないので取る。","日本の居酒屋では「つぼ焼き」が定番。殻ごと火にかけて焼いてもおいしい。"]},
  "蝾螺刺身":{serves:"2",time:"20分",
   ingT:[["活さざえ","2〜3個"],["大葉・大根のつま","適量"]],
   sauceT:[["醤油・わさび","適量"]],
   steps:["さざえの口を上にして10分置き、ふたが少し開くのを待つ。","ふたと殻の間に小さなナイフを差し込み、殻の内側に沿って一周させて貝柱を切り、指でふたをつまんで回しながら身を丸ごと引き出す。","ふた（かたい部分）と尾のわた（緑色。別にゆでて食べられる）を切り離し、口のかたい歯を取る。","身を塩でもみ洗いして流し、3mmの薄切りにする。","きれいに洗った殻に戻すか大葉の上に盛り、わさび醤油で食べる。"],
   tips:["さざえの刺身はとてもコリコリして、ほのかに磯の苦みがある。","引き出せないときは、殻ごと冷凍庫で20分凍らせ、熱湯に10秒つけるとよい。","わたはゆでると少し苦く、酒好きにはたまらない。"]},
  "蝾螺炊饭":{serves:"3〜4",time:"1時間",
   ingT:[["さざえ","4個"],["米","2合（360ml）"],["生姜","1かけ"],["三つ葉","少々"]],
   sauceT:[["だし","約340ml"],["薄口醤油","大さじ1.5"],["酒","大さじ2"],["みりん","大さじ1"]],
   steps:["米を洗って30分ざるに上げる。","さざえを熱湯で3分ゆで、取り出してつまようじで回しながら身を引き出し、ふたと口を取る。わたは取っても残してもよい。","身を薄切りにする。","炊飯器に米・薄口醤油・酒・みりんを入れ、だしを2合の目盛りまで加え、生姜のせん切りとさざえをのせて普通に炊く。","炊けたら10分蒸らして混ぜ、三つ葉を散らす。"],
   tips:["ゆでると身を取り出しやすい。","身を一緒に炊くと、ご飯に磯の香りが広がる。","わたを少し残すと、風味が増すがほろ苦くなる。"]}}},
 mussel:{d:{
  "葱姜炒青口":{serves:"2〜3",time:"20分",
   ingT:[["ムール貝","500g"],["生姜","1かけ"],["長ねぎ","1本"],["にんにく","3かけ"],["赤唐辛子（お好みで）","1本"]],
   sauceT:[["料理酒","大さじ2"],["オイスターソース","大さじ1"],["醤油","小さじ1"],["砂糖","小さじ1/2"],["サラダ油","大さじ2"]],
   steps:["ムール貝の殻をこすり洗いし、はみ出ている足糸（ひげ）を手で引き抜いて洗う。","生姜は薄切り、ねぎはぶつ切り、にんにくはつぶす。","鍋に油を熱し、強火で生姜・ねぎの白い部分・にんにく・唐辛子を炒める。","ムール貝を入れて料理酒をふり、ふたをして2分蒸し焼きにする。","ふたを取り、ほとんど開いたらオイスターソース・醤油・砂糖・ねぎの青い部分を加え、強火で1分炒め合わせる。"],
   tips:["開かないムール貝は死んでいる可能性があるので、取り除いて食べない。","足糸は殻のとがった方向に引くと抜きやすい。","日本のスーパーでは冷凍のハーフシェルのムール貝が多い。解凍してそのまま2分炒めればよい。"]}}}
});
window.ADD_I18N("en", {
 "black-carp":{d:{
  "青鱼干":{serves:"6",time:"30 min (plus 7–10 days curing and drying)",
   ingT:[["Black carp or a large yellowtail or mackerel","1 (about 2kg)"],["Ginger","1 piece"],["String","1 length"]],
   sauceT:[["Coarse salt","about 60g (3% of the fish weight)"],["Sichuan peppercorns","1 tbsp"],["Baijiu, shochu or Shaoxing wine","3 tbsp"],["Sugar","1 tbsp"]],
   steps:["Split the fish open from the back into one flat piece, remove the guts and black membrane and wipe dry with paper towel without washing too much.","Toast the peppercorns and salt in a dry pan on low until fragrant, cool, add the sugar and rub evenly over both sides. Sprinkle with the liquor.","Seal in a zip bag, weigh down and refrigerate 3 days, turning daily.","Pat dry, stretch open with skewers and hang in a cool, airy place for 5–7 days until the surface is hard and dry.","To eat, cut into pieces, top with ginger slices and a little Shaoxing wine and steam 20 minutes. Eat hot or cold, with rice wine."],
   tips:["Make it in winter (below 10°C). It spoils in warm weather.","A traditional New Year preserved food of the Jiangnan region.","Once dried, cut into portions and freeze."]}}},
 hamaguri:{d:{
  "文蛤蒸蛋":{serves:"2–3",time:"25 min",
   ingT:[["Hard clams (hamaguri) or littleneck clams","8 (about 200g)"],["Eggs","3"],["Scallion","1"]],
   sauceT:[["Warm water (including clam juice)","about 270ml (1.5× the egg)"],["Salt","a little"],["Light soy sauce","1 tsp"],["Sesame oil","a few drops"]],
   steps:["Purge the clams of sand and scrub the shells.","Put the clams in 300ml water and lift them out the moment they open. Strain the liquid through a fine sieve and cool to lukewarm.","Beat the eggs with 1.5 times their volume of clam juice (top up with warm water) and a pinch of salt. Strain and skim off the foam.","Arrange the clams in a deep dish, pour in the egg and cover with plastic wrap or a plate.","Steam over boiling water on medium-low 10–12 minutes, until set but still trembling slightly in the center.","Drizzle with soy sauce and sesame oil and scatter with scallion."],
   tips:["Straining, covering and steaming on medium-low gives a mirror-smooth surface.","The clam juice is so savory that you need little salt.","Pull the clams as soon as they open so they don't toughen during steaming."]},
  "烤文蛤":{serves:"2",time:"20 min (plus purging)",
   ingT:[["Large hard clams (hamaguri)","6"],["Sudachi (optional)","1/2"]],
   sauceT:[["Soy sauce","a few drops"],["Sake (optional)","a little"]],
   steps:["Purge the clams for 2 hours and scrub the shells.","Find the black ligament at the back where the two shells join and cut it with a small knife (so the shell doesn't flip and spill the juice when grilling).","Heat charcoal, a grill rack or a frying pan on medium and set the clams on it.","When they open after 3–5 minutes, add a few drops of soy sauce and sake and grill 30 seconds more.","Eat with the juices and a squeeze of sudachi."],
   tips:["A specialty of Kuwana in Mie, even featured in a Japanese pun.","Cutting the ligament is key, or all the juice spills when the shell opens.","The juice is delicious, so be sure to drink it."]}}},
 shijimi:{d:{
  "台式腌蚬仔":{serves:"4 (as a side for rice)",time:"20 min (plus marinating overnight)",
   ingT:[["Freshwater clams (shijimi)","300g"],["Garlic","6 cloves"],["Red chilies","2"],["Ginger (optional)","1 piece"]],
   sauceT:[["Soy sauce","100ml"],["Rice wine or sake","50ml"],["Sugar","1 tbsp"],["Vinegar","1 tsp"],["Cooled boiled water","50ml"]],
   steps:["Purge the clams for 3 hours, scrub and freeze overnight (frozen clams open more easily and taste sweeter).","Crush the garlic and slice the chilies. Mix the soy sauce, rice wine, sugar, vinegar and water and add the garlic and chilies.","Boil a pot of water, turn off the heat, add the frozen clams and leave 1–2 minutes. Lift out as soon as they open slightly.","Put them straight into the marinade, cover and refrigerate overnight.","Ready the next day. Eat within 2 days."],
   tips:["The clams should only just open. Overcooked, the meat shrinks and the texture is wrong.","The clams in this Taiwanese dish are half-raw, so use very fresh clams from a trusted source. If you have a sensitive stomach, soak them longer.","The marinade is great over rice."]},
  "蚬子汤":{serves:"3",time:"20 min (plus purging)",
   ingT:[["Freshwater clams (shijimi)","400g"],["Garlic chives","1/2 bunch"],["Japanese leek (optional)","a little"]],
   sauceT:[["Water","1 liter"],["Salt","1 tsp"],["Grated garlic (optional)","1/2 tsp"]],
   steps:["Purge the clams in 1% salt water for 3 hours and scrub.","Put the clams in cold water and heat slowly on medium to draw out their flavor.","When it boils, skim and cook until all the clams open and the broth turns milky.","Season with salt (and garlic).","Add the cut chives, cook 30 seconds and turn off the heat."],
   tips:["Jaecheop-guk from Busan and Hadong in Korea, traditionally a hangover soup.","Starting in cold water brings out the most flavor.","You can pick out the meat and just drink the clear broth with rice."]}}},
 awabi:{d:{
  "蚝油鲍鱼":{serves:"2",time:"30 min",
   ingT:[["Live abalone or small abalone (tokobushi)","4 (about 60g each)"],["Broccoli","1/2 head"],["Ginger","2 slices"],["Garlic","2 cloves"]],
   sauceT:[["Oyster sauce","2 tbsp"],["Light soy sauce","1 tsp"],["Sugar","1 tsp"],["Shaoxing or cooking wine","1 tbsp"],["Water","100ml"],["Starch slurry","1 tsp starch + 2 tbsp water"],["Cooking oil","1 tbsp"]],
   steps:["Scrub the black film off the edge of the abalone, run a spoon along the shell to remove the meat, discard the innards and score the surface in a crosshatch.","Dip the abalone in boiling water with wine for 30 seconds. Cut the broccoli into florets, blanch in salted water 1 minute and arrange on a plate.","Fry the ginger and garlic in oil, add the oyster sauce, soy sauce, sugar and water and bring to a boil.","Add the abalone and simmer on low 3–5 minutes.","Thicken with the slurry, return the abalone to their shells or place among the broccoli and pour over the sauce."],
   tips:["Short cooking keeps abalone tender. Too long and it toughens.","Tokobushi in Japan is a small, much cheaper abalone cooked the same way.","Save the liver to stir-fry separately."]},
  "鲍鱼水贝":{serves:"2",time:"20 min",
   ingT:[["Live abalone","1 (about 200g)"],["Cucumber","1"],["Ice","1 bowl"],["Shiso or sprouts (optional)","a little"]],
   sauceT:[["Salt","about 1 tsp (about 1% iced brine)"],["Cooled boiled water","500ml"],["Wasabi and soy sauce (optional)","as needed"]],
   steps:["Sprinkle the abalone with salt and scrub the edges and underside hard with a brush to remove the black slime. Rinse.","Insert a wooden spatula or rice paddle between the shell and the thin side of the meat, pry off the muscle and remove the meat. Discard the innards (the liver can be eaten separately) and the hard mouth.","Cut the meat into 1.5cm cubes and the cucumber to the same size.","Make iced brine with the water, salt and ice and soak the abalone and cucumber for 5 minutes.","Serve in a glass bowl with the ice water and eat as is (or with wasabi soy sauce)."],
   tips:["A summer dish enjoyed for the crunch of raw cubed abalone.","Iced brine firms the meat and makes it crunchier.","A traditional preparation from the Boso Peninsula in Chiba."]},
  "鲍鱼粥":{serves:"3",time:"50 min (plus 1 hour soaking the rice)",
   ingT:[["Live abalone with liver","2 (about 100g each)"],["Rice","1 cup (about 180g)"],["Scallion, sesame and seaweed (to serve)","a little"]],
   sauceT:[["Sesame oil","2 tbsp"],["Water","1.2 liters"],["Salt or soup soy sauce","as needed"]],
   steps:["Wash the rice, soak 1 hour and drain.","Scrub the abalone, remove the meat and separate the green liver (discard the mouth). Slice the meat thinly and chop or mash the liver.","Fry the liver in sesame oil for 1 minute, then the sliced meat for 1 minute.","Add the rice and stir-fry 2 minutes until translucent.","Add the water, bring to a boil and simmer on low 30 minutes, stirring often so it doesn't stick, until the grains burst.","Season with salt or soup soy sauce and top with scallion, sesame and seaweed."],
   tips:["The liver is the soul of the dish, turning the porridge a pretty pale green and deepening the flavor.","A Jeju Island specialty and a restorative Korean porridge.","Frozen abalone works, but get ones with the liver."]}}},
 sazae:{d:{
  "白灼海螺":{serves:"2",time:"20 min",
   ingT:[["Turban shells (sazae)","4–6"],["Ginger","1 piece"],["Scallion","1"]],
   sauceT:[["Shaoxing or cooking wine","1 tbsp"],["Salt","1 tsp"],["Ginger vinegar (minced ginger + black vinegar)","as needed"],["Wasabi soy sauce","as needed"]],
   steps:["Scrub the shells and soak in clean water for 30 minutes.","Put cold water, ginger slices, scallion, wine and salt in a pot, add the shells and turn on the heat.","Once boiling, cook on medium 8–10 minutes.","Lift out, stick a toothpick into the opening and twist to pull out the meat (the green tail innards are edible and a little bitter).","Slice and dip in ginger vinegar or wasabi soy sauce."],
   tips:["Starting in cold water and heating slowly makes the meat easier to pull out.","The hard trapdoor at the opening is inedible, so remove it.","Japanese izakaya often serve tsuboyaki, grilled in the shell over a flame."]},
  "蝾螺刺身":{serves:"2",time:"20 min",
   ingT:[["Live turban shells (sazae)","2–3"],["Shiso and shredded daikon","as needed"]],
   sauceT:[["Soy sauce and wasabi","as needed"]],
   steps:["Set the shells opening up for 10 minutes until the trapdoor opens slightly.","Slide a small knife between the trapdoor and shell, run it around the inside to cut the muscle, then grip the trapdoor and twist the whole body out.","Cut off the trapdoor (hard part) and the tail innards (green, can be boiled separately) and remove the hard teeth at the mouth.","Rub the meat with salt, rinse and slice 3mm thin.","Return to the cleaned shell or arrange on shiso and serve with wasabi soy sauce."],
   tips:["Turban shell sashimi is very crunchy with a faint briny bitterness.","If it won't come out, freeze the shell 20 minutes and dip in boiling water for 10 seconds.","The innards are a little bitter when cooked, a favorite with drinkers."]},
  "蝾螺炊饭":{serves:"3–4",time:"1 hour",
   ingT:[["Turban shells (sazae)","4"],["Rice","2 rice-cooker cups (360ml)"],["Ginger","1 piece"],["Mitsuba","a little"]],
   sauceT:[["Dashi","about 340ml"],["Light (usukuchi) soy sauce","1.5 tbsp"],["Sake","2 tbsp"],["Mirin","1 tbsp"]],
   steps:["Wash the rice and drain for 30 minutes.","Boil the shells for 3 minutes, then twist out the meat with a toothpick and remove the trapdoor and mouth. Keep or discard the innards.","Slice the meat thinly.","Put the rice, soy sauce, sake and mirin in a rice cooker, add dashi to the 2-cup line, top with julienned ginger and the turban meat and cook as usual.","Rest 10 minutes, mix and scatter with mitsuba."],
   tips:["Boiling first makes the meat easier to remove.","Cooking the meat with the rice fills it with a taste of the sea.","Keeping some innards adds flavor and a slight bitterness."]}}},
 mussel:{d:{
  "葱姜炒青口":{serves:"2–3",time:"20 min",
   ingT:[["Mussels","500g"],["Ginger","1 piece"],["Japanese leek (negi)","1"],["Garlic","3 cloves"],["Red chili (optional)","1"]],
   sauceT:[["Shaoxing or cooking wine","2 tbsp"],["Oyster sauce","1 tbsp"],["Light soy sauce","1 tsp"],["Sugar","1/2 tsp"],["Cooking oil","2 tbsp"]],
   steps:["Scrub the mussels and pull off the protruding beards by hand. Rinse.","Slice the ginger, cut the leek into lengths and crush the garlic.","Fry the ginger, white part of the leek, garlic and chili in oil on high.","Add the mussels, splash in the wine, cover and steam 2 minutes.","When most have opened, add the oyster sauce, soy sauce, sugar and green part of the leek and toss on high for 1 minute."],
   tips:["Mussels that don't open may be dead, so discard them.","Pull the beard toward the pointed end of the shell to remove it easily.","Japanese supermarkets often sell frozen half-shell mussels. Thaw and stir-fry for 2 minutes."]}}}
});
