window.ADD_I18N("ja", {
 mussel:{d:{
  "西班牙海鲜饭":{serves:"3〜4",time:"1時間",
   ingT:[["米（洗わない）","2合（約300g）"],["ムール貝","300g"],["有頭えび","8尾"],["いか","1杯"],["トマト","1個"],["赤パプリカ","1/2個"],["玉ねぎ","1/2個"],["にんにく","2かけ"],["レモン","1個"]],
   sauceT:[["オリーブオイル","大さじ5"],["サフラン","ひとつまみ（約0.2g）"],["パプリカパウダー","小さじ1"],["魚のスープ（または水＋顆粒だし）","700ml"],["白ワイン","50ml"],["塩","小さじ1"]],
   steps:["サフランを熱い魚のスープにつけて色を出す。ムール貝は殻を洗って足糸を取り、いかは輪切りにする。","パエリア鍋（または26cmのフライパン）にオリーブオイルを熱し、えびを両面赤くなるまで焼いて取り出し、いかを1分炒めて取り出す。","同じ鍋で玉ねぎ・にんにく・パプリカを5分炒め、すりおろしたトマトとパプリカパウダーを加えてとろりとするまで炒める。","米を加えて1分、油がなじむまで炒め、白ワインを注ぎ、熱いスープと塩を加えて、へらで米を平らにならす。以後は混ぜない。","強火で5分煮てから中弱火にし、いか・えび・ムール貝を米の上に並べ、12〜15分、汁気がなくなるまで炊く。","最後に強火で1分、パチパチと音がして鍋底におこげ（ソカラット）ができたら火を止め、ふきんをかぶせて5分蒸らし、くし形のレモンを添える。"],
   tips:["米は洗わず、スープを入れたら混ぜない。これがリゾットとの最大の違い。","鍋底のおこげがいちばんおいしい。","サフランがなければターメリックで色は出せるが、香りは違う。"]},
  "青口汤":{serves:"3",time:"20分",
   ingT:[["ムール貝","700g"],["にんにく","4かけ"],["長ねぎ","1/2本"],["青唐辛子","2本"]],
   sauceT:[["水","1L"],["酒","大さじ2"],["塩","適量"]],
   steps:["ムール貝の殻をこすり洗いし、足糸を取る。","にんにくは薄切り、ねぎと唐辛子は斜め切りにする。","鍋に水・ムール貝・にんにく・酒を入れ、強火で煮立てる。","アクを取り、3〜4分、ムール貝がすべて開くまで煮る。","ねぎと唐辛子を加え、塩で味を調える（ムール貝自体に塩気があるので先に味見）。"],
   tips:["韓国の屋台（ポジャンマチャ）で無料で出てくる、うまみたっぷりの酒の肴スープ。","塩だけで味付けし、ムール貝そのものの味を楽しむ。","開かないムール貝は食べない。"]}}},
 akagai:{d:{
  "葱油血蚶":{serves:"2",time:"15分",
   ingT:[["赤貝かサルボウ（殻付き）","300g"],["小ねぎ","3本"],["生姜","1かけ"]],
   sauceT:[["サラダ油","大さじ2"],["醤油","大さじ1.5"],["黒酢","大さじ1"],["砂糖","小さじ1/2"]],
   steps:["殻をこすり洗いし、塩水に1時間つけて砂抜きする。","湯を沸かして火を止め、30秒ほど待ち（約90°C）、貝を入れて10〜15秒ゆでて取り出す。","手か小さなナイフで殻を開き、身の付いた片側の殻ごと皿に並べる（身の中の赤い汁がこの貝の特徴）。","生姜をみじん切りにして黒酢と混ぜ、しょうが酢を作る。小ねぎの小口切りを身にのせる。","煙が出るまで熱した油をねぎにかけ、醤油と砂糖を混ぜたたれをかけ、しょうが酢を添える。"],
   tips:["寧波では半生で食べるので、とても新鮮で信頼できるものを使う。心配なら長めにゆでる。","ゆで時間は短いほど身がやわらかい。","日本の赤貝は主に刺身用。殻付きの小さなサルボウのほうが中国の血蚶に近い。"]},
  "赤贝寿司":{serves:"2",time:"30分",
   ingT:[["活赤貝（殻付き）","4個"],["米","1合"],["大葉（お好みで）","2枚"]],
   sauceT:[["塩","少々"],["酢","大さじ2"],["すし酢","大さじ1.5"],["醤油・わさび","適量"]],
   steps:["酢飯を作り、うちわであおいで冷ます。","切れ味の鈍いナイフを赤貝のすき間から差し込み、両側の貝柱を切って殻を開け、身を取り出す。","オレンジ色の「身」とひもを分け、身は横から切り開いて一枚に（蝶のように）し、わたを取って塩でもみ洗いし、酢水でさっと洗う。","身の外側に斜めに数本切り目を入れ、まな板にのせて手のひらで「パン」とたたくと身が反り返る（新鮮な証拠）。","握り寿司にする（ほかの握りの要領で）。ひもは軍艦巻きか酢の物に。"],
   tips:["たたくと身が縮んで反り返るのは新鮮な証拠で、寿司屋の見せ場でもある。","スーパーには開いた「赤貝 刺身用」もあり、より手軽。","冬から春がいちばんおいしい。"]}}},
 saruboo:{d:{
  "葱油毛蚶":{serves:"2",time:"20分",
   ingT:[["サルボウ","400g"],["小ねぎ","3本"],["生姜","1かけ"]],
   sauceT:[["料理酒","大さじ1"],["サラダ油","大さじ2"],["醤油","大さじ1.5"],["砂糖","小さじ1/2"],["ごま油","数滴"]],
   steps:["サルボウをこすり洗いし、塩水に2時間つけて砂抜きする。","鍋に水・生姜の薄切り・料理酒を煮立て、サルボウを入れて2〜3分、すべて開いたら取り出す。","身を取り出して皿に並べる（殻を半分残してもよい）。","小ねぎの小口切りをのせ、煙が出るまで熱した油をかける。","醤油と砂糖を混ぜたたれとごま油数滴をかけ、混ぜて食べる。"],
   tips:["サルボウは必ず火を通して食べる。","ゆで汁はこしてスープのだしに使える。","日本では有明海周辺でよくとれ、スーパーにもときどき並ぶ。"]},
  "拌毛蚶":{serves:"2〜3",time:"30分（砂抜き別）",
   ingT:[["サルボウか赤貝","500g"],["小ねぎ","2本"],["青唐辛子・赤唐辛子","各1本"]],
   sauceT:[["醤油","大さじ2"],["韓国唐辛子粉","大さじ1"],["おろしにんにく","小さじ1"],["砂糖","小さじ1"],["ごま油","大さじ1"],["白ごま","小さじ1"],["酒","大さじ1"]],
   steps:["サルボウを2時間砂抜きし、こすり洗いする。","鍋に水と酒を煮立て、サルボウを入れてお玉で一方向にかき混ぜながら（身が片側の殻に均一に残る）、2〜3分、口が開くまでゆでる。","取り出し、身のない側の殻をはずして皿に並べる。","醤油・唐辛子粉・にんにく・砂糖・ごま油・ごま・小ねぎ・刻んだ唐辛子を混ぜてたれを作る。","小さじでたれを一つずつのせる。"],
   tips:["韓国全羅南道・筏橋（ボルギョ）の名物「コマクムチム」。","一方向に混ぜながらゆでると、身が同じ側の殻にくっつく。","ご飯に混ぜて「コマクビビンバ」にしても。"]}}},
 hokkigai:{d:{
  "北极贝刺身":{serves:"2",time:"10分（解凍別）",
   ingT:[["ほっき貝（ボイル・刺身用）","150g"],["大根のつまか大葉","適量"]],
   sauceT:[["醤油","適量"],["わさび","適量"]],
   steps:["冷蔵庫で3〜4時間かけて自然解凍する（急ぐときは袋ごと冷水に20分つける）。","キッチンペーパーで表面の水気をふく。","皿に大根のつまと大葉を敷き、ほっき貝を盛る。","わさび醤油で食べる。"],
   tips:["中国で売られる「北極貝」はほとんどがカナダ産のボイル冷凍品で、赤い色はゆでた色。","お湯や電子レンジで解凍すると食感が悪くなる。","解凍したらその日のうちに食べる。"]},
  "北寄贝咖喱":{serves:"4",time:"45分",
   ingT:[["ほっき貝（むき身、生）","4〜6個（約200g）"],["玉ねぎ","2個"],["じゃがいも","2個"],["にんじん","1本"],["温かいご飯","4杯"]],
   sauceT:[["カレールウ","1/2箱（約100g）"],["水","700ml"],["サラダ油","大さじ1"],["バター（お好みで）","10g"]],
   steps:["ほっき貝を開き、黒いわたを取って洗い、食べやすく切る。","玉ねぎは薄切り、じゃがいもとにんじんは乱切りにする。","鍋に油を熱して玉ねぎを薄いきつね色まで炒め、じゃがいもとにんじんを加えて2分炒める。","水を加えて煮立ててアクを取り、弱火で15分、野菜がやわらかくなるまで煮る。","火を止めてルウを溶かし、再び弱火でとろみがつくまで煮る。","最後にほっき貝とバターを入れて2分（身の色が赤く変われば十分）煮て、ご飯にかける。"],
   tips:["北海道苫小牧はほっき貝の水揚げ日本一で、これはご当地名物。","貝は最後に入れる。煮すぎるとかたくなる。","生のほっき貝は加熱すると灰色からピンク色に変わる。"]}}},
 torigai:{d:{
  "鸟贝寿司":{serves:"2",time:"25分",
   ingT:[["トリガイ（ボイル・開き）","6枚"],["米","1合"]],
   sauceT:[["すし酢","大さじ1.5"],["わさび","少々"],["ツメ（お好みで）","少々"],["酢（お好みで）","少々"]],
   steps:["酢飯を作り、あおいで冷ます。","トリガイはふつうゆでて開いた状態で売られている。冷水でさっと洗って水気をふき、酢にくぐらせてもよい。","手に手酢をつけ、15gくらいの酢飯を軽く握る。","トリガイを左手に（黒い面を下に）のせ、わさびを少し塗って酢飯をのせて握り、返して形を整え、トリガイが翼のように酢飯をおおうようにする。","ツメを塗るか、醤油をつけて食べる。"],
   tips:["トリガイの黒い部分が特徴なので、こすり落とさない。","春がトリガイの季節。京都・舞鶴の「丹後とり貝」が有名。","刺身や酢の物にしても。"]},
  "英式醋泡鸟蛤":{serves:"2",time:"20分",
   ingT:[["トリガイ（殻付き）かあさり","500g"]],
   sauceT:[["モルトビネガー（または米酢）","大さじ4"],["白こしょう","少々"],["塩","小さじ1"]],
   steps:["貝を2時間砂抜きし、こすり洗いする。","鍋に少量の水（2cm）と塩を入れて煮立て、貝を入れてふたをし、3分蒸して口を開かせる。","身を取り出して冷ます。","小さな紙コップか器に入れ、モルトビネガーをかけて白こしょうをふる。","つまようじで刺して食べる。"],
   tips:["イギリスの海辺のリゾートの伝統的なおやつで、ウナギのゼリー寄せやフィッシュ・アンド・チップスと並ぶ定番。","日本では小さめのあさりやトリガイで作れる。","モルトビネガーは輸入食品店で買える。"]}}},
 mirugai:{d:{
  "象拔蚌两吃":{serves:"3〜4",time:"40分",
   ingT:[["活みる貝か白みる貝","1個（約800g）"],["米","1/2カップ（約90g）"],["生姜","1かけ"],["小ねぎ","2本"],["氷","ボウル1杯"]],
   sauceT:[["わさび醤油","適量"],["塩","小さじ1/2"],["白こしょう","少々"],["ごま油","数滴"]],
   steps:["小さなナイフを殻に沿わせて身を切り離し、水管（長い部分）と胴に分ける。","水管を熱湯に10秒通してすぐ氷水にとり、外側の茶色い皮をむく。","水管を縦に切り開いて洗い、斜めに薄切りにして氷の上に並べ、わさび醤油で食べる（一品目：刺身）。","胴はわたを取って洗い、小さな角切りにする。","米を水1Lで白がゆに煮て（約30分）、貝の角切りと生姜のせん切りを入れて2分煮る（二品目：おかゆ）。","塩と白こしょうで調え、小ねぎを散らしてごま油をたらす。"],
   tips:["みる貝は高価なので必ず活きたものを。水管をつつくと縮むものが新鮮。","水管は10秒ゆでるだけで皮がむけ、身は生のまま。","胴の部分はセロリと一緒にさっと炒めてもよい。"]},
  "西雅图象拔蚌":{serves:"2〜3",time:"30分",
   ingT:[["活白みる貝かみる貝","1個（約800g）"],["ライム・オレンジ","各1/2個"],["青唐辛子かハラペーニョ","1本"],["チャイブかパクチー","少々"],["氷水","ボウル1杯"]],
   sauceT:[["エキストラバージンオリーブオイル","大さじ2"],["マルドンの塩（フレーク塩）","少々"]],
   steps:["小さなナイフを殻に沿わせて身を切り離し、水管と胴に分ける。","水管を熱湯に10秒通してすぐ氷水にとり、外側の茶色い皮をむく。","水管を切り開いて洗い、斜めに2mmの薄切りにし、氷水に1分つけてパリッとさせ、水気をふく。","冷やした皿に並べ、ライムとオレンジを搾り、オリーブオイルをかける。","唐辛子の輪切り・チャイブ・フレーク塩を散らし、すぐに食べる。"],
   tips:["アメリカ北西部（シアトル）はみる貝の主産地で、多くは中国に輸出される。","コリッと甘い食感に、酸味と油を合わせるとさっぱりする。","胴の部分はさっと炒めるかスープに。"]}}}
});
window.ADD_I18N("en", {
 mussel:{d:{
  "西班牙海鲜饭":{serves:"3–4",time:"1 hour",
   ingT:[["Rice (unwashed)","2 rice-cooker cups (about 300g)"],["Mussels","300g"],["Head-on shrimp","8"],["Squid","1"],["Tomato","1"],["Red bell pepper","1/2"],["Onion","1/2"],["Garlic","2 cloves"],["Lemon","1"]],
   sauceT:[["Olive oil","5 tbsp"],["Saffron","a pinch (about 0.2g)"],["Paprika","1 tsp"],["Fish stock (or water plus stock granules)","700ml"],["White wine","50ml"],["Salt","1 tsp"]],
   steps:["Soak the saffron in the hot stock to release its color. Scrub and debeard the mussels and cut the squid into rings.","Heat olive oil in a paella pan (or a 26cm frying pan), sear the shrimp until red on both sides and remove. Fry the squid 1 minute and remove.","In the same pan, fry the onion, garlic and pepper for 5 minutes, then add grated tomato and paprika and cook until thick.","Add the rice and stir 1 minute to coat in oil, pour in the wine, then the hot stock and salt. Spread the rice flat with a spoon and don't stir again.","Cook on high 5 minutes, then medium-low. Arrange the squid, shrimp and mussels on top and cook 12–15 minutes until the liquid is absorbed.","Finish on high for 1 minute until it crackles and a crust (socarrat) forms on the bottom. Turn off the heat, cover with a cloth for 5 minutes and serve with lemon wedges."],
   tips:["Don't wash the rice and don't stir after adding the stock. That's the big difference from risotto.","The crust on the bottom is the best part.","Turmeric can replace saffron for color, though not for aroma."]},
  "青口汤":{serves:"3",time:"20 min",
   ingT:[["Mussels","700g"],["Garlic","4 cloves"],["Japanese leek (negi)","1/2"],["Green chilies","2"]],
   sauceT:[["Water","1 liter"],["Sake","2 tbsp"],["Salt","as needed"]],
   steps:["Scrub and debeard the mussels.","Slice the garlic and cut the leek and chilies diagonally.","Bring the water, mussels, garlic and sake to a boil on high.","Skim and cook 3–4 minutes until all the mussels open.","Add the leek and chilies and season with salt (taste first, as the mussels are salty)."],
   tips:["A free, savory drinking soup served at Korean street tents (pojangmacha).","Seasoned only with salt, so you taste the pure mussel flavor.","Don't eat mussels that stay closed."]}}},
 akagai:{d:{
  "葱油血蚶":{serves:"2",time:"15 min",
   ingT:[["Blood clams or ark shells, in the shell","300g"],["Scallions","3"],["Ginger","1 piece"]],
   sauceT:[["Cooking oil","2 tbsp"],["Light soy sauce","1.5 tbsp"],["Black vinegar","1 tbsp"],["Sugar","1/2 tsp"]],
   steps:["Scrub the shells and soak in salt water for 1 hour to purge.","Boil water, turn off the heat, wait about 30 seconds (about 90°C), add the clams for 10–15 seconds and lift out.","Pry the shells open by hand or with a small knife and arrange the half-shells with meat on a plate (the red juice inside is the hallmark of blood clams).","Mince the ginger and mix with the vinegar. Scatter chopped scallions over the clams.","Pour smoking-hot oil over the scallions, drizzle with soy sauce mixed with the sugar and serve with the ginger vinegar."],
   tips:["In Ningbo blood clams are eaten half-raw, so use very fresh, reliable ones. Blanch longer if unsure.","Keep the blanching short for tender meat.","Japanese akagai is mostly for sashimi. The smaller shell-on saruboo is closer to Chinese blood clams."]},
  "赤贝寿司":{serves:"2",time:"30 min",
   ingT:[["Live ark shells (akagai), in the shell","4"],["Rice","1 rice-cooker cup"],["Shiso (optional)","2 leaves"]],
   sauceT:[["Salt","a little"],["Vinegar","2 tbsp"],["Sushi vinegar","1.5 tbsp"],["Soy sauce and wasabi","as needed"]],
   steps:["Make sushi rice and fan it cool.","Insert a blunt knife into the gap, cut the muscles on both sides, open the shell and remove the meat.","Separate the orange body from the mantle fringe (himo). Butterfly the body from the side, remove the innards, rub with salt and rinse in vinegared water.","Score the outside diagonally, lay it on the board and slap it with your palm. It will curl up (a sign of freshness).","Shape into nigiri (as for other sushi). Use the fringe for gunkan rolls or vinegared salad."],
   tips:["The curl after a slap proves freshness and is a sushi-bar showpiece.","Supermarkets sell pre-opened akagai for sashimi, which is easier.","Best from winter to spring."]}}},
 saruboo:{d:{
  "葱油毛蚶":{serves:"2",time:"20 min",
   ingT:[["Ark shells (saruboo)","400g"],["Scallions","3"],["Ginger","1 piece"]],
   sauceT:[["Shaoxing or cooking wine","1 tbsp"],["Cooking oil","2 tbsp"],["Light soy sauce","1.5 tbsp"],["Sugar","1/2 tsp"],["Sesame oil","a few drops"]],
   steps:["Scrub the clams and soak in salt water for 2 hours to purge.","Boil water with ginger slices and wine, add the clams and cook 2–3 minutes until all open. Lift out.","Remove the meat and arrange on a plate (or leave on the half-shell).","Scatter with chopped scallions and pour over smoking-hot oil.","Drizzle with the soy sauce mixed with sugar and a few drops of sesame oil, then toss."],
   tips:["Always cook ark shells through.","Strain the cooking liquid for soup stock.","Common around the Ariake Sea in Japan and sometimes in supermarkets."]},
  "拌毛蚶":{serves:"2–3",time:"30 min (plus purging)",
   ingT:[["Ark shells or blood clams","500g"],["Scallions","2"],["Green and red chilies","1 each"]],
   sauceT:[["Soy sauce","2 tbsp"],["Korean chili flakes","1 tbsp"],["Grated garlic","1 tsp"],["Sugar","1 tsp"],["Sesame oil","1 tbsp"],["White sesame","1 tsp"],["Sake","1 tbsp"]],
   steps:["Purge the clams for 2 hours and scrub.","Boil water with the sake, add the clams and stir in one direction with a ladle (so the meat stays on one shell), cooking 2–3 minutes until they open.","Lift out, remove the empty half-shells and arrange on a plate.","Mix the soy sauce, chili flakes, garlic, sugar, sesame oil, sesame seeds, scallions and chopped chilies.","Spoon a little sauce onto each clam."],
   tips:["A specialty (kkomak-muchim) of Beolgyo in South Jeolla, Korea.","Stirring in one direction makes the meat stick to the same half-shell.","Mix into rice for kkomak bibimbap."]}}},
 hokkigai:{d:{
  "北极贝刺身":{serves:"2",time:"10 min (plus thawing)",
   ingT:[["Cooked frozen surf clam (sashimi grade)","150g"],["Shredded daikon or shiso","as needed"]],
   sauceT:[["Soy sauce","as needed"],["Wasabi","as needed"]],
   steps:["Thaw in the fridge for 3–4 hours (in a hurry, soak the sealed bag in cold water for 20 minutes).","Blot dry with paper towel.","Lay daikon and shiso on a plate and arrange the clams.","Eat with wasabi soy sauce."],
   tips:["The 'arctic surf clam' sold in China is mostly cooked frozen clam from Canada. The red color comes from cooking.","Thawing in hot water or the microwave ruins the texture.","Eat the same day once thawed."]},
  "北寄贝咖喱":{serves:"4",time:"45 min",
   ingT:[["Raw shucked surf clams (hokkigai)","4–6 (about 200g)"],["Onions","2"],["Potatoes","2"],["Carrot","1"],["Hot rice","4 bowls"]],
   sauceT:[["Japanese curry roux","1/2 box (about 100g)"],["Water","700ml"],["Cooking oil","1 tbsp"],["Butter (optional)","10g"]],
   steps:["Open the clams, remove the black innards, rinse and cut into bite-size pieces.","Slice the onions and cut the potatoes and carrot into chunks.","Fry the onions in oil until light golden, add the potatoes and carrot and fry 2 minutes.","Add the water, bring to a boil, skim and simmer on low 15 minutes until the vegetables are soft.","Turn off the heat, dissolve the roux, then simmer on low until thick.","Finally add the clams and butter for 2 minutes (until the meat turns pink) and serve over rice."],
   tips:["Tomakomai in Hokkaido lands the most surf clams in Japan, and this is its local specialty.","Add the clams last, as they toughen if overcooked.","Raw surf clam turns from grey to pink when cooked."]}}},
 torigai:{d:{
  "鸟贝寿司":{serves:"2",time:"25 min",
   ingT:[["Cooked butterflied Japanese cockle (torigai)","6 pieces"],["Rice","1 rice-cooker cup"]],
   sauceT:[["Sushi vinegar","1.5 tbsp"],["Wasabi","a little"],["Sweet sushi sauce (tsume, optional)","a little"],["Vinegar (optional)","a little"]],
   steps:["Make sushi rice and fan it cool.","Torigai is usually sold already blanched and butterflied. Rinse briefly in cold water, pat dry and dip in vinegar if you like.","Wet your hands with vinegared water and shape about 15g of rice.","Lay the cockle on your left hand (dark side down), dab on wasabi, add the rice, press, flip and shape so the cockle drapes over the rice like a wing.","Brush with tsume or dip in soy sauce."],
   tips:["The dark part is torigai's hallmark, so don't scrape it off.","Spring is the season, and Tango torigai from Maizuru, Kyoto is famous.","It's also good as sashimi or in a vinegared salad."]},
  "英式醋泡鸟蛤":{serves:"2",time:"20 min",
   ingT:[["Cockles or small clams, in the shell","500g"]],
   sauceT:[["Malt vinegar (or rice vinegar)","4 tbsp"],["White pepper","a little"],["Salt","1 tsp"]],
   steps:["Purge the cockles for 2 hours and scrub.","Bring a little water (2cm) with the salt to a boil, add the cockles, cover and steam 3 minutes until they open.","Pick out the meat and cool.","Put in small paper cups or bowls, douse with malt vinegar and sprinkle with white pepper.","Eat with a toothpick."],
   tips:["A traditional British seaside snack, as classic as jellied eels or fish and chips.","Small clams or torigai work in Japan.","Malt vinegar is sold at import grocers."]}}},
 mirugai:{d:{
  "象拔蚌两吃":{serves:"3–4",time:"40 min",
   ingT:[["Live geoduck","1 (about 800g)"],["Rice","1/2 cup (about 90g)"],["Ginger","1 piece"],["Scallions","2"],["Ice","1 bowl"]],
   sauceT:[["Wasabi soy sauce","as needed"],["Salt","1/2 tsp"],["White pepper","a little"],["Sesame oil","a few drops"]],
   steps:["Run a small knife along the shell to cut out the meat and separate the siphon (the long part) from the body.","Dip the siphon in boiling water for 10 seconds, plunge into ice water and peel off the brown outer skin.","Split the siphon lengthwise, rinse, slice thinly on the diagonal and arrange on ice. Eat with wasabi soy sauce (course one: sashimi).","Remove the innards from the body, rinse and dice.","Simmer the rice in 1 liter water into plain congee (about 30 minutes), then add the diced body and shredded ginger for 2 minutes (course two: congee).","Season with salt and white pepper, scatter with scallions and add sesame oil."],
   tips:["Geoduck is expensive, so buy it live. The freshest siphons retract when touched.","A 10-second dip lets you peel the skin while the flesh stays raw.","The body can also be stir-fried quickly with celery."]},
  "西雅图象拔蚌":{serves:"2–3",time:"30 min",
   ingT:[["Live geoduck","1 (about 800g)"],["Lime and orange","1/2 each"],["Green chili or jalapeño","1"],["Chives or cilantro","a little"],["Ice water","1 bowl"]],
   sauceT:[["Extra virgin olive oil","2 tbsp"],["Flaky sea salt","a little"]],
   steps:["Run a small knife along the shell to cut out the meat and separate the siphon from the body.","Dip the siphon in boiling water for 10 seconds, plunge into ice water and peel off the brown skin.","Split and rinse the siphon, slice diagonally 2mm thin, crisp in ice water for 1 minute and pat dry.","Arrange on a chilled plate, squeeze over lime and orange and drizzle with olive oil.","Scatter with sliced chili, chives and flaky salt and eat right away."],
   tips:["The American Northwest (Seattle) is the main geoduck region, and most is exported to China.","Its sweet crunch is brightened by acid and oil.","Stir-fry the body or use it in soup."]}}}
});
