window.ADD_I18N("ja", {
 tsubugai:{d:{
  "葱油海螺片":{serves:"2",time:"20分",
   ingT:[["つぶ貝（むき身）","200g"],["小ねぎ","3本"],["生姜","1かけ"],["赤唐辛子（お好みで）","1本"]],
   sauceT:[["サラダ油","大さじ2"],["醤油","大さじ1.5"],["砂糖","小さじ1/2"],["料理酒","大さじ1"]],
   steps:["つぶ貝を塩でもんでぬめりを取る。身を切り開き、中央の黄白色の唾液腺（アブラ）を必ず取り除く（めまいを起こす成分を含む）。","身を斜めに薄切りにする。","料理酒を入れた熱湯に10〜15秒通し、くるっと丸まったら引き上げて氷水にとり、水気をきって皿に並べる。","白髪ねぎ・生姜のせん切り・唐辛子のせん切りをのせる。","煙が出るまで熱した油をねぎにかけ、醤油と砂糖を混ぜたたれをかける。"],
   tips:["唾液腺（アブラ）を取らないと、めまいや吐き気を起こす。いちばん大事な工程。","ゆで時間はごく短く。コリッとやわらかく仕上がる。","日本のスーパーの「つぶ貝 刺身用」は多くが処理済み。"]},
  "蛾螺刺身":{serves:"2",time:"20分",
   ingT:[["活つぶ貝か刺身用つぶ","2個"],["大葉・大根のつま","適量"]],
   sauceT:[["塩","小さじ1"],["醤油・わさび","適量"]],
   steps:["かなづちで殻を割るか、20分冷凍してから熱湯に10秒つけて身を引き出す。","わたを切り離し、身を切り開いて中央の黄白色の唾液腺（アブラ）を完全に取り除く（めまいを起こす成分を含む）。","身に塩をふり、強くもんでぬめりを取り、洗い流す。","3mmの薄切りにするか、表面に細かく切り目を入れてそぎ切りにする。","大葉と大根のつまの上に盛り、わさび醤油で。"],
   tips:["唾液腺（アブラ）を取らないとめまいや吐き気を起こす。いちばん大事な工程。","北海道の真つぶがいちばんおいしく、コリコリした食感。","スーパーの「つぶ貝 刺身用」はふつう処理済み。"]},
  "拌海螺面":{serves:"2〜3",time:"20分",
   ingT:[["つぶ貝の缶詰（ゴルベンイ缶）","1缶（約230g）"],["そうめん","2束（約100g）"],["長ねぎ","1/2本"],["きゅうり","1/2本"],["玉ねぎ","1/4個"],["にんじん","少々"]],
   sauceT:[["コチュジャン","大さじ2"],["韓国唐辛子粉","大さじ1"],["酢","大さじ2"],["砂糖","大さじ1"],["おろしにんにく","小さじ1"],["ごま油","大さじ1"],["白ごま","小さじ1"]],
   steps:["つぶ貝の汁気をきり（缶汁は大さじ1をたれに加えてよい）、大きいものは半分に切る。","ねぎは細いせん切りにして水にさらし、きゅうり・玉ねぎ・にんじんもせん切りにする。","コチュジャン・唐辛子粉・酢・砂糖・にんにく・ごま油・ごまを混ぜてたれを作る。","そうめんをゆでて冷水で洗い、水気を絞って小さく丸めて皿に盛る。","つぶ貝と野菜をたれであえ、そうめんの横に盛り、そうめんと混ぜながら食べる。"],
   tips:["韓国のビアホールの定番おつまみ「ゴルベンイムチム」。","つぶ貝の缶詰は韓国食材店や通販で買える。","甘酸っぱ辛い味。唐辛子はお好みで加減する。"]}}},
 baigai:{d:{
  "白灼花螺":{serves:"2",time:"20分",
   ingT:[["ばい貝","400g"],["生姜","1かけ"],["小ねぎ","2本"]],
   sauceT:[["料理酒","大さじ1"],["塩","小さじ1"],["わさび醤油","適量"],["ねぎ生姜醤油（お好みで）","適量"]],
   steps:["ばい貝の殻をこすり洗いし、きれいな水に30分つける。","鍋に水・生姜の薄切り・ねぎ・料理酒・塩を入れて煮立てる。","ばい貝を入れ、再び沸騰したら中火で5分ゆでる。","取り出し、つまようじを刺して回しながら身を引き出す。","わさび醤油かねぎ生姜醤油で食べる。"],
   tips:["ゆですぎると身がかたくなる。","日本では「ばい貝」。北陸ではよく甘辛く煮る。","身の先のわたも食べられ、ほのかに甘い。"]},
  "煮东风螺":{serves:"3",time:"25分",
   ingT:[["ばい貝","500g"],["生姜","1かけ"]],
   sauceT:[["水","200ml"],["酒","100ml"],["醤油","大さじ3"],["みりん","大さじ2"],["砂糖","大さじ1"]],
   steps:["ばい貝の殻をブラシでこすり洗いし、水に30分つける。","熱湯で1分下ゆでし、湯を捨てる（臭みとぬめりを取る）。","鍋に水・酒・醤油・みりん・砂糖・生姜の薄切りを入れて煮立て、ばい貝を入れる。","中弱火で10分煮て火を止め、煮汁につけたまま冷まして味をしみ込ませる。","つまようじで回しながら身を引き出して食べる。"],
   tips:["北陸や山陰でよく食べる酒の肴「旨煮」。","煮汁につけたまま冷ますと、味がよくしみる。","煮すぎると身がかたくなるので、10分で十分。"]}}},
 mategai:{d:{
  "辣炒蛏子":{serves:"2",time:"20分（砂抜き2時間）",
   ingT:[["まてがい（中華食材店ではアゲマキも可）","400g"],["にんにく","4かけ"],["鷹の爪","4本"],["生姜","3枚"],["小ねぎ","2本"]],
   sauceT:[["郫県豆板醤","大さじ1"],["料理酒","大さじ1"],["醤油","小さじ1"],["砂糖","小さじ1/2"],["サラダ油","大さじ2"]],
   steps:["まてがいを3%の塩水に2時間つけて砂抜きし、殻をやさしくこすり洗いする。","湯を沸かしてまてがいを30秒ゆで、殻が開いたら引き上げ、身のふちの黒い線（砂袋）を取る。殻付きのままでもよい。","鍋に油を入れ、弱火で豆板醤を炒めて赤い油を出し、生姜・にんにく・鷹の爪を炒める。","強火にしてまてがいを入れ、料理酒をふり、醤油と砂糖を加えて1分手早く炒める。","小ねぎを散らして仕上げる。"],
   tips:["先にゆでてから炒めると水が出ず、砂も取りやすい。","強火で手早く炒めると身がやわらかい。","有明海の「アゲマキ」が中国の蟶子にいちばん近い。"]},
  "西班牙铁板蛏子":{serves:"2",time:"15分（砂抜き別）",
   ingT:[["マテ貝","10本"],["にんにく","2かけ"],["パセリ","少々"],["レモン","1/2個"]],
   sauceT:[["オリーブオイル","大さじ3"],["粗塩","少々"]],
   steps:["マテ貝を立てて3%の塩水に1〜2時間つけて砂抜きし、洗う。","にんにくとパセリをみじん切りにし、オリーブオイルと混ぜる。","鉄板かフライパンを強火でよく熱し、油を少し塗ってマテ貝を寝かせて並べる。","1〜2分で殻が開いたら返し、さらに30秒焼く。","皿に盛り、にんにくパセリオイルをかけ、粗塩をふってレモンを搾る。"],
   tips:["スペイン・ガリシアの定番「ナバハス」。navajaは「折りたたみナイフ」の意味。","強火で短時間焼くと身がやわらかい。","砂抜きのときは貝を立てておくと砂を吐きやすい。"]},
  "黄油酱油蛏":{serves:"2",time:"15分（砂抜き別）",
   ingT:[["マテ貝","300g"],["にんにく","1かけ"],["小ねぎ","1本"]],
   sauceT:[["バター","15g"],["酒","大さじ2"],["醤油","大さじ1"]],
   steps:["マテ貝を砂抜きしてから洗う。","フライパンにバターとにんにくのみじん切りを入れ、弱火で香りを出す。","マテ貝を入れて酒をふり、ふたをして中火で2分、口が開くまで蒸し焼きにする。","鍋肌から醤油を回し入れ、全体を混ぜる。","皿に盛り、小ねぎを散らす。"],
   tips:["バターと醤油は日本人がいちばん好きな貝の味付け。","汁はご飯にかけたり、パンにつけたりしても。","九州・有明海の「アゲマキ」も同じように作れる。"]}}},
 tairagi:{d:{
  "XO 酱炒带子":{serves:"2",time:"15分",
   ingT:[["たいらぎの貝柱（または帆立貝柱）","200g"],["アスパラガス","4本"],["にんにく","2かけ"],["赤パプリカ（お好みで）","1/4個"]],
   sauceT:[["XO醤","大さじ2"],["料理酒","大さじ1"],["塩","少々"],["片栗粉","小さじ1"],["サラダ油","大さじ2"]],
   steps:["貝柱を横半分に切って水気をふき、塩少々と片栗粉をもみ込む。","アスパラは根元のかたい部分を落として斜め切り、パプリカは細切りにする。","油と塩少々を入れた熱湯でアスパラを30秒ゆでて取り出し、貝柱を10秒通して取り出す。","鍋に油を熱し、にんにくのみじん切りとXO醤を20秒炒めて香りを出す。","アスパラ・パプリカ・貝柱を入れ、料理酒をふって強火で30秒手早く炒める。"],
   tips:["貝柱は湯通ししてから炒めると水が出ず、なめらかに仕上がる。","XO醤自体に塩気があるので、塩はほぼ不要。","たいらぎの貝柱は冬に出回る。帆立貝柱でも代用できる。"]},
  "江珧刺身":{serves:"2",time:"15分",
   ingT:[["たいらぎの貝柱（刺身用）","2個"],["大葉・大根のつま","適量"],["レモンかすだち","1/2個"]],
   sauceT:[["醤油・わさび","適量"],["塩","少々"]],
   steps:["貝柱の表面の薄い膜を指か小さなナイフではがす。","冷水でさっと洗い、キッチンペーパーで水気をふく。","横に5mm厚さの輪切り、または角切りにする。","大葉と大根のつまの上に盛る。","わさび醤油で、または塩をふってレモンを搾って食べる。"],
   tips:["たいらぎの貝柱は帆立よりコリッとして、甘みは上品。","塩とレモンがいちばん貝柱の甘みを引き立てる。","冬から春が旬。九州の有明海や瀬戸内海が産地。"]}}},
 honbinosu:{d:{
  "辣炒白蛤":{serves:"2〜3",time:"20分",
   ingT:[["ホンビノス貝","500g"],["生姜","3枚"],["にんにく","4かけ"],["鷹の爪か生の赤唐辛子","4本"],["小ねぎ","2本"]],
   sauceT:[["料理酒","大さじ1"],["醤油","大さじ1"],["オイスターソース","小さじ1"],["砂糖","小さじ1/2"],["サラダ油","大さじ2"]],
   steps:["ホンビノス貝の殻をこすり洗いし、塩水に1時間つける（砂はふつう少ない）。","鍋に油を熱し、生姜・にんにく・唐辛子を炒める。","貝を入れて料理酒をふり、ふたをして中強火で3〜4分蒸し焼きにする。","ふたを取ってほとんど開いていたら、醤油・オイスターソース・砂糖を加えて30秒炒める。","小ねぎを散らして仕上げ、開かなかった貝は取り除く。"],
   tips:["ホンビノス貝は殻が厚いので、普通のあさりより1〜2分長く蒸す。","汁がおいしいので、麺にからめても。","東京湾のホンビノス貝は安くて大きく、炒め物にぴったり。"]},
  "酒蒸美国帘蛤":{serves:"2",time:"15分",
   ingT:[["ホンビノス貝","500g"],["にんにく","1かけ"],["小ねぎ","2本"]],
   sauceT:[["酒","100ml"],["バター","10g"],["醤油（お好みで）","数滴"]],
   steps:["殻をこすり洗いする（砂は少ないので、塩水に30分つければ十分）。","フライパンか深鍋に貝・にんにくの薄切り・酒を入れ、ふたをする。","中強火で4〜5分、殻がすべて開くまで蒸す。","バターを溶かし、醤油を数滴たらし、小ねぎを散らす。","汁ごと食べる。汁はご飯にかけたり、うどんを煮たりしても。"],
   tips:["北米原産の大型の貝で、東京湾で大量に増え、値段が安い。","殻が厚いので、普通のあさりより少し長めに蒸す。","身が多くかみごたえがあり、スープがとてもおいしい。"]}}}
});
window.ADD_I18N("en", {
 tsubugai:{d:{
  "葱油海螺片":{serves:"2",time:"20 min",
   ingT:[["Whelk meat (tsubugai)","200g"],["Scallions","3"],["Ginger","1 piece"],["Red chili (optional)","1"]],
   sauceT:[["Cooking oil","2 tbsp"],["Light soy sauce","1.5 tbsp"],["Sugar","1/2 tsp"],["Shaoxing or cooking wine","1 tbsp"]],
   steps:["Rub the whelk with salt to remove slime. Cut it open and always remove the yellowish-white salivary gland in the middle (it contains a substance that causes dizziness).","Slice thinly on the diagonal.","Dip in boiling water with wine for 10–15 seconds until the slices curl, then plunge into ice water, drain and arrange on a plate.","Top with shredded scallion, ginger and chili.","Pour smoking-hot oil over the scallions, then drizzle with soy sauce mixed with the sugar."],
   tips:["Leaving the gland (abura) in can cause dizziness and nausea. This is the most important step.","Keep the blanching very short for crisp, tender slices.","Sashimi-grade tsubugai in Japanese supermarkets is usually already cleaned."]},
  "蛾螺刺身":{serves:"2",time:"20 min",
   ingT:[["Live whelks or sashimi-grade whelk meat","2"],["Shiso and shredded daikon","as needed"]],
   sauceT:[["Salt","1 tsp"],["Soy sauce and wasabi","as needed"]],
   steps:["Crack the shell with a hammer, or freeze for 20 minutes and dip in boiling water for 10 seconds, then pull out the meat.","Cut off the innards, open the meat and completely remove the yellowish-white salivary gland (abura), which causes dizziness.","Rub the meat hard with salt to remove the slime and rinse.","Slice 3mm thin, or score the surface finely and cut into pieces.","Arrange on shiso and daikon and serve with wasabi soy sauce."],
   tips:["Leaving the gland in can cause dizziness and nausea. This is the most important step.","Hokkaido's ma-tsubu is the tastiest, with a crunchy texture.","Sashimi-grade tsubugai from supermarkets is usually already cleaned."]},
  "拌海螺面":{serves:"2–3",time:"20 min",
   ingT:[["Canned whelks (golbaengi)","1 can (about 230g)"],["Somen noodles","2 bundles (about 100g)"],["Japanese leek (negi)","1/2"],["Cucumber","1/2"],["Onion","1/4"],["Carrot","a little"]],
   sauceT:[["Gochujang","2 tbsp"],["Korean chili flakes","1 tbsp"],["Vinegar","2 tbsp"],["Sugar","1 tbsp"],["Grated garlic","1 tsp"],["Sesame oil","1 tbsp"],["White sesame","1 tsp"]],
   steps:["Drain the whelks (add 1 tbsp of the can liquid to the sauce if you like) and halve large ones.","Finely shred the leek and soak in cold water. Julienne the cucumber, onion and carrot.","Mix the gochujang, chili flakes, vinegar, sugar, garlic, sesame oil and sesame into a sauce.","Cook the somen, rinse in cold water, squeeze dry and twist into small bundles on a plate.","Toss the whelks and vegetables with the sauce, pile next to the noodles and mix together as you eat."],
   tips:["Golbaengi-muchim is a classic drinking snack at Korean beer halls.","Canned whelks are sold at Korean grocers or online.","It's sweet, sour and spicy. Adjust the chili to taste."]}}},
 baigai:{d:{
  "白灼花螺":{serves:"2",time:"20 min",
   ingT:[["Japanese babylon (bai-gai)","400g"],["Ginger","1 piece"],["Scallions","2"]],
   sauceT:[["Shaoxing or cooking wine","1 tbsp"],["Salt","1 tsp"],["Wasabi soy sauce","as needed"],["Ginger-scallion soy sauce (optional)","as needed"]],
   steps:["Scrub the shells and soak in clean water for 30 minutes.","Bring water with ginger slices, scallions, wine and salt to a boil.","Add the snails, and when it returns to a boil, cook on medium 5 minutes.","Lift out, stick in a toothpick and twist to pull out the meat.","Dip in wasabi soy sauce or ginger-scallion soy sauce."],
   tips:["Don't overcook or the meat toughens.","Called bai-gai in Japan, where the Hokuriku region often simmers them sweet and savory.","The innards at the tip are edible and slightly sweet."]},
  "煮东风螺":{serves:"3",time:"25 min",
   ingT:[["Japanese babylon (bai-gai)","500g"],["Ginger","1 piece"]],
   sauceT:[["Water","200ml"],["Sake","100ml"],["Soy sauce","3 tbsp"],["Mirin","2 tbsp"],["Sugar","1 tbsp"]],
   steps:["Scrub the shells with a brush and soak in water for 30 minutes.","Blanch in boiling water for 1 minute and drain (removes odor and slime).","Bring the water, sake, soy sauce, mirin, sugar and sliced ginger to a boil and add the snails.","Simmer on medium-low 10 minutes, turn off the heat and let them cool in the liquid to absorb the flavor.","Twist out the meat with a toothpick to eat."],
   tips:["A drinking snack (umani) common in Hokuriku and San'in.","Cooling in the liquid lets the flavor soak in.","Longer cooking toughens the meat. 10 minutes is enough."]}}},
 mategai:{d:{
  "辣炒蛏子":{serves:"2",time:"20 min (plus 2 hours purging)",
   ingT:[["Razor clams (or agemaki from Chinese grocers)","400g"],["Garlic","4 cloves"],["Dried red chilies","4"],["Ginger","3 slices"],["Scallions","2"]],
   sauceT:[["Pixian doubanjiang","1 tbsp"],["Shaoxing or cooking wine","1 tbsp"],["Light soy sauce","1 tsp"],["Sugar","1/2 tsp"],["Cooking oil","2 tbsp"]],
   steps:["Purge the clams in 3% salt water for 2 hours and gently scrub the shells.","Blanch in boiling water for 30 seconds until the shells open, lift out and pull off the black line (grit sac) around the meat. You can leave them in the shell.","Fry the doubanjiang in oil on low until the oil turns red, then add the ginger, garlic and chilies.","Turn the heat to high, add the clams, splash in the wine, add the soy sauce and sugar and toss quickly for 1 minute.","Scatter with scallions to finish."],
   tips:["Blanching first means they won't release water when stir-fried, and the grit is easy to remove.","Fast, high-heat cooking keeps them tender.","Agemaki from the Ariake Sea is the closest Japanese match to Chinese razor clams."]},
  "西班牙铁板蛏子":{serves:"2",time:"15 min (plus purging)",
   ingT:[["Razor clams","10"],["Garlic","2 cloves"],["Parsley","a little"],["Lemon","1/2"]],
   sauceT:[["Olive oil","3 tbsp"],["Coarse salt","a little"]],
   steps:["Stand the clams upright in 3% salt water for 1–2 hours to purge, then rinse.","Mince the garlic and parsley and mix with the olive oil.","Heat a griddle or frying pan very hot on high, brush with a little oil and lay the clams flat.","When they open after 1–2 minutes, flip and cook 30 seconds more.","Plate, spoon over the garlic-parsley oil, sprinkle with coarse salt and squeeze over lemon."],
   tips:["Navajas are a Galician classic. Navaja means folding knife.","Hot and fast keeps them tender.","Standing them upright while purging helps them expel the sand."]},
  "黄油酱油蛏":{serves:"2",time:"15 min (plus purging)",
   ingT:[["Razor clams","300g"],["Garlic","1 clove"],["Scallion","1"]],
   sauceT:[["Butter","15g"],["Sake","2 tbsp"],["Soy sauce","1 tbsp"]],
   steps:["Purge the clams and rinse.","Melt the butter with minced garlic in a frying pan on low until fragrant.","Add the clams, splash in the sake, cover and steam on medium for 2 minutes until open.","Pour the soy sauce around the pan edge and toss.","Plate and scatter with scallion."],
   tips:["Butter and soy sauce is Japan's favorite way to season shellfish.","Spoon the juices over rice or mop them up with bread.","Agemaki from Kyushu's Ariake Sea can be cooked the same way."]}}},
 tairagi:{d:{
  "XO 酱炒带子":{serves:"2",time:"15 min",
   ingT:[["Pen shell adductors (or scallops)","200g"],["Asparagus","4 spears"],["Garlic","2 cloves"],["Red bell pepper (optional)","1/4"]],
   sauceT:[["XO sauce","2 tbsp"],["Shaoxing or cooking wine","1 tbsp"],["Salt","a little"],["Potato starch","1 tsp"],["Cooking oil","2 tbsp"]],
   steps:["Halve the adductors horizontally, pat dry and toss with a pinch of salt and the starch.","Trim the woody ends of the asparagus and cut diagonally. Slice the pepper.","In boiling water with a little oil and salt, blanch the asparagus 30 seconds and lift out, then the scallops for 10 seconds.","Fry the minced garlic and XO sauce in oil for 20 seconds until fragrant.","Add the asparagus, pepper and scallops, splash in the wine and toss on high for 30 seconds."],
   tips:["Blanching the scallops first keeps them from releasing water and keeps them silky.","XO sauce is salty, so you hardly need extra salt.","Pen shell adductors appear in winter. Scallops work as a substitute."]},
  "江珧刺身":{serves:"2",time:"15 min",
   ingT:[["Sashimi-grade pen shell adductors","2"],["Shiso and shredded daikon","as needed"],["Lemon or sudachi","1/2"]],
   sauceT:[["Soy sauce and wasabi","as needed"],["Salt","a little"]],
   steps:["Peel off the thin membrane on the surface with your fingers or a small knife.","Rinse briefly in cold water and pat dry with paper towel.","Cut crosswise into 5mm rounds or into cubes.","Arrange on shiso and daikon.","Eat with wasabi soy sauce, or with a sprinkle of salt and a squeeze of lemon."],
   tips:["Pen shell adductors are crunchier than scallops, with a delicate sweetness.","Salt and lemon bring out the sweetness best.","In season from winter to spring, from the Ariake Sea and Seto Inland Sea."]}}},
 honbinosu:{d:{
  "辣炒白蛤":{serves:"2–3",time:"20 min",
   ingT:[["Northern quahog clams (honbinosu)","500g"],["Ginger","3 slices"],["Garlic","4 cloves"],["Dried or fresh red chilies","4"],["Scallions","2"]],
   sauceT:[["Shaoxing or cooking wine","1 tbsp"],["Light soy sauce","1 tbsp"],["Oyster sauce","1 tsp"],["Sugar","1/2 tsp"],["Cooking oil","2 tbsp"]],
   steps:["Scrub the clams and soak in salt water for 1 hour (they usually hold little sand).","Fry the ginger, garlic and chilies in oil.","Add the clams, splash in the wine, cover and steam on medium-high for 3–4 minutes.","When most have opened, add the soy sauce, oyster sauce and sugar and toss 30 seconds.","Finish with scallions and discard any that didn't open."],
   tips:["Quahogs have thick shells, so steam them 1–2 minutes longer than regular clams.","The juices are delicious tossed with noodles.","Tokyo Bay quahogs are cheap and large, perfect for stir-frying."]},
  "酒蒸美国帘蛤":{serves:"2",time:"15 min",
   ingT:[["Northern quahog clams (honbinosu)","500g"],["Garlic","1 clove"],["Scallions","2"]],
   sauceT:[["Sake","100ml"],["Butter","10g"],["Soy sauce (optional)","a few drops"]],
   steps:["Scrub the shells (they hold little sand, so 30 minutes in salt water is enough).","Put the clams, sliced garlic and sake in a frying pan or deep pot and cover.","Steam on medium-high 4–5 minutes until all are open.","Melt in the butter, add a few drops of soy sauce and scatter with scallions.","Eat with the broth, which is great over rice or for cooking udon."],
   tips:["A large North American clam that has spread widely in Tokyo Bay and is cheap.","The shells are thick, so steam a bit longer than regular clams.","Meaty and chewy, with a very savory broth."]}}}
});
