window.ADD_I18N("ja", {
 honbinosu:{d:{
  "烤馅蛤":{serves:"8個分",time:"50分",
   ingT:[["ホンビノス貝（大）","8個"],["チョリソー","50g"],["玉ねぎ","1/2個"],["セロリ","1/3本"],["にんにく","1かけ"],["パン粉","カップ1"],["パセリ","少々"]],
   sauceT:[["バター","30g"],["白ワインか水","100ml"],["パプリカ","少々"],["レモン","1/2個"],["タバスコ","数滴"]],
   steps:["鍋に白ワインと貝を入れ、ふたをして口が開くまで蒸し、身を取り出して刻む。蒸し汁は取っておき、殻は洗って16枚残す。","バターでチョリソーの角切り・玉ねぎ・セロリ・にんにくのみじん切りを5分炒める。","貝の身・パン粉・パセリ・蒸し汁大さじ3〜4を加えてしっとりした具にし、タバスコを加える。","具を殻にこんもり詰め、パプリカをふる。","200°Cのオーブンで15分、表面がきつね色になるまで焼き、レモンを搾る。"],
   tips:["アメリカ・ロードアイランドの名物「スタッフィーズ」で、海辺の家庭料理。","具はしっとりさせる。乾いていたら蒸し汁を足す。","作って冷凍しておき、食べるときにそのまま焼ける。"]}}},
 tanishi:{d:{
  "螺蛳粉":{serves:"2",time:"40分",
   ingT:[["螺螄粉（袋麺・中華食材店）","2袋"],["青梗菜か小松菜","2株"],["卵（お好みで）","2個"],["湯葉（干し、お好みで）","1本"]],
   sauceT:[["付属のスープ・酸筍・ラー油・ピーナッツ・きくらげ","袋の表示どおり"],["水","1L"],["サラダ油（目玉焼き用）","大さじ3"]],
   steps:["乾燥米麺を冷水に20分つける（袋の表示に従う。つけなくてよいものもある）。","鍋に水とスープの素を入れて煮立て、米麺を入れて中火で8〜10分、芯がなくなるまで煮る。","別の鍋に油を熱し、ふちがカリッとした目玉焼きを作る。湯葉はもどして切り、揚げてもよい。","麺がゆで上がる直前に青菜を入れて1分煮る。","大きな器に盛り、酸筍・きくらげ・ピーナッツ・湯葉・目玉焼きをのせ、好みでラー油を加える。"],
   tips:["タニシのスープを一から作るのは大変なので、家では袋麺がいちばん現実的。日本でも中華食材店や通販で買える。","酸筍はにおいが強いので、窓を開けるか換気扇を回す。","揚げ卵をのせるのが柳州の定番の食べ方。"]},
  "越南田螺粉":{serves:"3",time:"1時間",
   ingT:[["タニシ（冷凍むき身）かつぶ貝缶","200g"],["トマト","3個"],["ブン（細い米麺）","300g"],["厚揚げ（お好みで）","1枚"],["しそ・パクチー・レタス","各ひとつかみ"],["小ねぎ","2本"]],
   sauceT:[["鶏ガラスープか豚骨スープ","1.5L"],["米酢","大さじ2"],["ナンプラー","大さじ3"],["砂糖","小さじ1"],["エシャロット","3個"],["サラダ油","大さじ2"],["唐辛子・ライム","適量"]],
   steps:["タニシの身を塩と酢でもみ洗いし、1分下ゆでする。","トマトをくし形に切る。鍋に油を熱してエシャロットの薄切りをきつね色に炒め、トマトを加えて3分、やわらかくなるまで炒める。","スープ・酢・ナンプラー・砂糖を加えて20分煮ると、オレンジ色の酸っぱいスープになる。","タニシと厚揚げを加えてさらに5分煮て、酸味と塩気を味見して調える。","器にゆでたブンを入れ、スープとタニシを注ぎ、ハーブと小ねぎをたっぷりのせ、唐辛子とライムを添える。"],
   tips:["ハノイの朝ごはん「ブン・オック」。酸っぱいスープが命。","日本ではタニシは手に入りにくいので、冷凍の貝の身やつぶ貝缶で代用。","しそ（ベトナムではティアトー）がタニシとよく合う。"]}}},
 hiogi:{d:{
  "蒜蓉粉丝扇贝":{serves:"2〜3",time:"30分",
   ingT:[["ひおうぎ貝（殻付き）","8個"],["緑豆春雨","1束（約30g）"],["にんにく","1玉"],["小ねぎ","2本"]],
   sauceT:[["サラダ油","大さじ4"],["醤油","大さじ2"],["オイスターソース","小さじ1"],["砂糖","小さじ1/2"]],
   steps:["春雨をぬるま湯でもどし、はさみで切る。","貝の殻を開けて片方の殻を残し、黒いわたを取って洗う。","にんにくをみじん切りにし、半量を油大さじ3で弱火できつね色に炒め、火を止めて生のにんにく・醤油・オイスターソース・砂糖を混ぜる。","殻に春雨、貝柱の順にのせ、にんにくだれをスプーン1杯ずつのせる。","湯が沸いた蒸し器で5分蒸し、小ねぎを散らし、熱した油大さじ1をかける。"],
   tips:["ひおうぎ貝の殻は赤・黄・紫などの色があり、盛り付けが華やか。","蒸し時間は6分を超えないように。","帆立の作り方と同じ。「帆立」の項も参考に。"]},
  "焗扇贝":{serves:"8個分",time:"25分",
   ingT:[["ひおうぎ貝（殻付き）","8個"],["にんにく","2かけ"],["パン粉","大さじ4"],["パセリ","少々"],["粉チーズ","大さじ2"]],
   sauceT:[["バター（やわらかくする）","30g"],["塩・黒こしょう","少々"],["レモン","1/2個"],["白ワイン（お好みで）","大さじ1"]],
   steps:["貝の殻を開けて片方の殻を残し、わたを取って身は殻にのせたままにする。","やわらかいバターに、にんにくとパセリのみじん切り・塩・こしょうを混ぜてガーリックバターを作る。","パン粉と粉チーズを混ぜる。","貝に白ワインを数滴たらし、ガーリックバターを少しのせ、パン粉をふる。","230°Cのオーブンか魚焼きグリルで6分、表面がきつね色になりバターが泡立つまで焼き、レモンを搾る。"],
   tips:["色とりどりのひおうぎ貝は、焼いても色がきれい。","ガーリックバターは多めに作って冷凍しておけば、きのこやバゲットにも使える。","焼きすぎると身が縮む。"]}}},
 amaebi:{d:{
  "芥末北极虾":{serves:"2",time:"10分（解凍別）",
   ingT:[["ボイル甘えび・ボイル北極えび","300g"],["レモン（お好みで）","1/4個"]],
   sauceT:[["醤油","大さじ2"],["わさび","小さじ1"],["酢（お好みで）","小さじ1"]],
   steps:["冷蔵庫で3〜4時間かけて解凍するか、袋ごと冷水に20分つける。","水気をきって皿に盛る。","醤油とわさびを混ぜる（好みで酢を少し）。","殻をむいてつけて食べる。頭のみそは吸って食べられる。"],
   tips:["中国のスーパーの「北極甜えび」は船上でゆでて冷凍したもので、解凍すればそのまま食べられる。","日本の「甘えび」は生の刺身用が多いので、パッケージの「ボイル」表示で見分ける。","お湯で解凍すると身がやわらかくくずれる。"]},
  "甜虾刺身":{serves:"2",time:"15分",
   ingT:[["刺身用甘えび","12尾"],["大葉","2枚"]],
   sauceT:[["醤油・わさび","適量"],["頭の味噌汁用：味噌・だし（お好みで）","各適量"]],
   steps:["冷凍なら冷蔵庫で解凍する。","頭を取り（取っておく）、胴の殻をむいて尾を残す。","大葉とわさびを添えて盛り、醤油で食べる。","頭と殻をだしで5分煮て味噌を溶けば、うまみたっぷりの味噌汁に。または頭に片栗粉をまぶして1分揚げ、塩をふる。"],
   tips:["甘えびは生のほうが加熱するより甘く、ねっとりする。","青い卵もきれいで、食べられる。","頭は捨てずに、汁物か揚げ物に。"]},
  "酱虾":{serves:"4",time:"30分（漬け1〜2日）",
   ingT:[["刺身用えび（甘えびなど）","500g"],["玉ねぎ","1/2個"],["青唐辛子・赤唐辛子","各1本"],["にんにく","4かけ"],["生姜","1かけ"],["レモン（お好みで）","1/2個"]],
   sauceT:[["醤油","200ml"],["水","300ml"],["砂糖","大さじ4"],["酒か焼酎","50ml"],["昆布","5cm 1枚"]],
   steps:["醤油・水・砂糖・酒・昆布・にんにくと生姜の薄切りを鍋に入れて5分煮立て、完全に冷ます（必ずしっかり冷ます）。","えびのひげととがった部分をはさみで切り、つまようじで背わたを取り、洗って水気をふく。","清潔な密閉容器にえびを入れ、玉ねぎの薄切り・唐辛子の輪切り・レモンの薄切りを加える。","冷ましたたれをえびがかぶるまで注ぎ、冷蔵庫で1日漬ける。","翌日、たれだけを取り出して再び煮立てて冷まし、戻す（より安全で日持ちもよくなる）。さらに1日漬ければ食べられる。"],
   tips:["韓国の「セウジャン」。「ご飯泥棒（パプドドゥク）」と呼ばれる。","必ず新鮮な刺身用えびを使い、漬けてから3〜4日で食べきる。","殻をむいて温かいご飯にのせ、たれを少しかけて生卵黄を落とすとおいしい。"]}}},
 botanebi:{d:{
  "牡丹虾味噌汤":{serves:"2",time:"15分",
   ingT:[["ボタンエビの頭・殻（刺身の残り）","4〜6尾分"],["小ねぎ","1本"],["豆腐（お好みで）","1/4丁"]],
   sauceT:[["水","400ml"],["酒","大さじ1"],["味噌","大さじ1.5"]],
   steps:["頭の先のとがった角を取り、殻と一緒に洗う。","鍋に油を少し入れ（お好みで）、頭と殻を中火で1分、赤くなって香りが出るまで炒める。","水と酒を加えて煮立て、アクを取り、弱火で5分煮る。スプーンで頭を押してみそを出す。","豆腐を入れ、弱火にして味噌を溶き入れる。","小ねぎを散らす。頭は器に残して、吸って食べてもよい。"],
   tips:["刺身を食べたあとの頭は、汁物にするのがいちばんの活用法。","先に頭を炒めると、汁がきれいなオレンジ色になる。","甘えびの頭でも同じように作れる。"]},
  "加拿大烤斑点虾":{serves:"2",time:"15分",
   ingT:[["ボタンエビか有頭えび（殻付き）","8尾"],["にんにく","2かけ"],["レモン","1/2個"],["パセリ","少々"]],
   sauceT:[["バター","30g"],["塩・黒こしょう","少々"],["チリフレーク（お好みで）","少々"]],
   steps:["えびの背の殻をはさみで切り開き、背わたを取る（殻は残す）。","バターを溶かし、にんにくのみじん切り・パセリ・塩・こしょう・チリフレークを混ぜてガーリックバターを作る。","えびの切り口にガーリックバターを塗る。","焼き網かフライパンを強火で熱し、片面1分ずつ、赤くなるまで焼く。","もう一度ガーリックバターを塗り、レモンを搾る。"],
   tips:["カナダ・ブリティッシュコロンビア州のスポットプローンは5月が解禁で、地元のお祭りになる。","強火で短時間焼くと、身が甘くやわらかい。","背を切り開くと、ガーリックバターが身にしみ込む。"]}}},
 kurumaebi:{d:{
  "盐水大明虾":{serves:"2〜3",time:"20分",
   ingT:[["車えびか大正えび","10尾（約400g）"],["生姜","4枚"],["小ねぎ","2本"]],
   sauceT:[["塩","大さじ1.5"],["花椒","小さじ1"],["料理酒","大さじ2"],["水","1L"],["しょうが酢（お好みで）","適量"]],
   steps:["えびのひげと頭の先のとげを切り、つまようじで背の2節目から背わたを取る。","鍋に水・塩・花椒・生姜・ねぎ・料理酒を入れ、2分煮立てて香りを出す。","えびを入れ、再び沸騰したら1〜2分、赤くなって丸まるまでゆでる。","火を止め、塩水につけたまま5分置いて味をしみ込ませる。","取り出して皿に盛る。冷たいままでも、しょうが酢をつけても。"],
   tips:["火を止めてからつけておくのがポイント。味がしみて身もかたくならない。","塩水はスープより塩辛く、約4%に。","車えびは高価なので、ブラックタイガーやバナメイえびでもよい。"]},
  "车虾天妇罗":{serves:"2",time:"30分",
   ingT:[["車えび","6尾"],["大根おろし","適量"]],
   sauceT:[["薄力粉","60g＋打ち粉少々"],["卵","1/2個"],["冷水","100ml"],["揚げ油","鍋底から4cm"],["天つゆ（だし4：醤油1：みりん1）","適量"],["塩","少々"]],
   steps:["車えびの頭を取り（取っておく）、尾を残して殻をむき、背わたを取る。尾の先を包丁でしごいて水分を出す。","腹側に斜めに4本切り込みを入れ、裏返して押さえ、まっすぐにのばす。","卵と冷水を混ぜ、薄力粉を加えてざっくり混ぜ、ゆるい衣を作る（混ぜすぎない）。","えびに打ち粉をして尾を持って衣をつけ、175°Cの油で1.5〜2分、薄いきつね色に揚げる。","頭は口先のとげを取り、粉をまぶしてそのまま1分揚げる。カリッとして丸ごと食べられる。","大根おろしと天つゆで、または塩で食べる。"],
   tips:["衣は冷たく、ざっくり混ぜると、軽くサクッと揚がる。","頭の唐揚げは天ぷら屋の隠れた名物。","車えびは天ぷらの最高級の種。"]}}}
});
window.ADD_I18N("en", {
 honbinosu:{d:{
  "烤馅蛤":{serves:"8 pieces",time:"50 min",
   ingT:[["Large quahog clams","8"],["Chorizo or spicy Italian sausage","50g"],["Onion","1/2"],["Celery","1/3 stalk"],["Garlic","1 clove"],["Breadcrumbs","1 cup"],["Parsley","a little"]],
   sauceT:[["Butter","30g"],["White wine or water","100ml"],["Paprika","a little"],["Lemon","1/2"],["Hot sauce","a few drops"]],
   steps:["Steam the clams in the wine, covered, until they open. Chop the meat, keep the liquid, and clean and keep 16 half-shells.","Fry the diced sausage, onion, celery and minced garlic in butter for 5 minutes.","Add the clam meat, breadcrumbs, parsley and 3–4 tbsp of the clam liquid to make a moist stuffing. Add hot sauce.","Pile the stuffing into the shells and sprinkle with paprika.","Bake at 200°C for 15 minutes until golden and squeeze over lemon."],
   tips:["Stuffies are a Rhode Island specialty and a seaside home dish.","Keep the stuffing moist. Add more clam liquid if it's dry.","Make ahead and freeze, then bake straight from frozen."]}}},
 tanishi:{d:{
  "螺蛳粉":{serves:"2",time:"40 min",
   ingT:[["Packaged luosifen (rice noodles plus sauce packets)","2 packs"],["Greens (bok choy or komatsuna)","2"],["Eggs (optional)","2"],["Dried tofu skin (optional)","1 stick"]],
   sauceT:[["Included soup base, pickled bamboo, chili oil, peanuts and wood ear packets","per package"],["Water","1 liter"],["Cooking oil (for frying eggs)","3 tbsp"]],
   steps:["Soak the dried noodles in cold water for 20 minutes (follow the package; some don't need soaking).","Boil the water with the soup base, add the noodles and cook on medium 8–10 minutes until no hard core remains.","In another pan, fry the eggs in oil until crispy at the edges. Optionally soak, cut and fry the tofu skin.","Add the greens to the noodles for the last minute.","Pour into large bowls and top with the pickled bamboo, wood ear, peanuts, tofu skin and fried egg. Add chili oil to taste."],
   tips:["Making snail broth from scratch is a lot of work, so packaged kits are the practical choice. They're sold at Chinese grocers and online in Japan.","The pickled bamboo smells strong, so open a window or run the fan.","A crispy fried egg on top is the Liuzhou standard."]},
  "越南田螺粉":{serves:"3",time:"1 hour",
   ingT:[["River snail meat (frozen) or canned whelks","200g"],["Tomatoes","3"],["Thin rice vermicelli (bun)","300g"],["Fried tofu (optional)","1 block"],["Perilla, cilantro and lettuce","1 handful each"],["Scallions","2"]],
   sauceT:[["Chicken or pork stock","1.5 liters"],["Rice vinegar","2 tbsp"],["Fish sauce","3 tbsp"],["Sugar","1 tsp"],["Shallots","3"],["Cooking oil","2 tbsp"],["Chili and lime","as needed"]],
   steps:["Rub the snail meat with salt and vinegar, rinse and blanch 1 minute.","Cut the tomatoes into wedges. Fry sliced shallots in oil until golden, then the tomatoes for 3 minutes until soft.","Add the stock, vinegar, fish sauce and sugar and simmer 20 minutes into an orange-red sour broth.","Add the snails and tofu for 5 more minutes. Taste and adjust the sour and salty balance.","Put cooked noodles in bowls, ladle over the broth and snails, pile on herbs and scallions and serve with chili and lime."],
   tips:["Bún ốc is a Hanoi breakfast, and the sour broth is its soul.","River snails are hard to find in Japan, so use frozen shellfish meat or canned whelks.","Perilla (tía tô in Vietnamese) pairs especially well with snails."]}}},
 hiogi:{d:{
  "蒜蓉粉丝扇贝":{serves:"2–3",time:"30 min",
   ingT:[["Noble scallops (hiogi), in the shell","8"],["Mung bean glass noodles","1 small bundle (about 30g)"],["Garlic","1 whole head"],["Scallions","2"]],
   sauceT:[["Cooking oil","4 tbsp"],["Light soy sauce","2 tbsp"],["Oyster sauce","1 tsp"],["Sugar","1/2 tsp"]],
   steps:["Soak the glass noodles in warm water until soft and cut with scissors.","Pry the scallops open, keep one half-shell, remove the dark innards and rinse.","Mince the garlic. Fry half in 3 tbsp oil on low until golden, turn off the heat and mix in the raw garlic, soy sauce, oyster sauce and sugar.","Put noodles in each shell, then the scallop, then a spoonful of garlic sauce.","Steam over boiling water for 5 minutes, scatter with scallions and pour over 1 tbsp hot oil."],
   tips:["Noble scallop shells come in red, yellow and purple, making a colorful platter.","Don't steam more than 6 minutes.","Same method as regular scallops. See the scallop entry."]},
  "焗扇贝":{serves:"8 pieces",time:"25 min",
   ingT:[["Noble scallops (hiogi), in the shell","8"],["Garlic","2 cloves"],["Breadcrumbs","4 tbsp"],["Parsley","a little"],["Grated Parmesan","2 tbsp"]],
   sauceT:[["Butter (softened)","30g"],["Salt and black pepper","a little"],["Lemon","1/2"],["White wine (optional)","1 tbsp"]],
   steps:["Open the scallops, keep one half-shell, remove the innards and leave the meat in the shell.","Mix the soft butter with minced garlic, chopped parsley, salt and pepper to make garlic butter.","Mix the breadcrumbs and Parmesan.","Add a few drops of wine to each scallop, top with a little garlic butter and sprinkle with crumbs.","Bake at 230°C or under a fish grill for 6 minutes until golden and bubbling. Squeeze over lemon."],
   tips:["Colorful noble scallops keep their pretty colors after baking.","Make extra garlic butter and freeze it for mushrooms or baguette.","Don't overbake or the scallops shrink."]}}},
 amaebi:{d:{
  "芥末北极虾":{serves:"2",time:"10 min (plus thawing)",
   ingT:[["Cooked frozen sweet shrimp (northern shrimp)","300g"],["Lemon (optional)","1/4"]],
   sauceT:[["Soy sauce","2 tbsp"],["Wasabi","1 tsp"],["Rice vinegar (optional)","1 tsp"]],
   steps:["Thaw in the fridge for 3–4 hours, or soak the sealed bag in cold water for 20 minutes.","Drain and arrange on a plate.","Mix the soy sauce and wasabi (with a little vinegar if you like).","Peel and dip. You can suck the rich roe and tomalley from the heads."],
   tips:["The 'arctic sweet shrimp' in Chinese supermarkets is cooked on board and frozen, so it's ready once thawed.","Japanese amaebi is mostly raw sashimi grade. Check the package for ボイル (cooked).","Don't thaw in hot water or the meat turns mushy."]},
  "甜虾刺身":{serves:"2",time:"15 min",
   ingT:[["Sashimi-grade sweet shrimp (amaebi)","12"],["Shiso","2 leaves"]],
   sauceT:[["Soy sauce and wasabi","as needed"],["For head miso soup (optional): miso and dashi","as needed"]],
   steps:["Thaw in the fridge if frozen.","Pull off the heads (keep them) and peel the bodies, leaving the tails.","Arrange with shiso and wasabi and dip in soy sauce.","Simmer the heads and shells in dashi for 5 minutes and dissolve in miso for a rich miso soup. Or coat the heads in starch, fry 1 minute and salt."],
   tips:["Raw sweet shrimp is sweeter and stickier than cooked.","The blue-green roe is pretty and edible.","Don't throw out the heads. Use them in soup or fry them."]},
  "酱虾":{serves:"4",time:"30 min (plus 1–2 days marinating)",
   ingT:[["Sashimi-grade raw shrimp (sweet shrimp etc.)","500g"],["Onion","1/2"],["Green and red chilies","1 each"],["Garlic","4 cloves"],["Ginger","1 piece"],["Lemon (optional)","1/2"]],
   sauceT:[["Soy sauce","200ml"],["Water","300ml"],["Sugar","4 tbsp"],["Sake or soju","50ml"],["Kombu","1 piece, 5cm"]],
   steps:["Boil the soy sauce, water, sugar, sake, kombu and sliced garlic and ginger for 5 minutes and cool completely (it must be fully cold).","Snip off the shrimp's feelers and spikes, remove the veins with a toothpick, rinse and pat dry.","Put the shrimp in a clean airtight container with sliced onion, chilies and lemon.","Pour over the cold sauce to cover and refrigerate 1 day.","The next day, drain the sauce, boil it again, cool and pour it back (safer and keeps longer). After another day it's ready."],
   tips:["Korean saeu-jang, nicknamed 'rice thief' (bap-doduk).","Use fresh sashimi-grade shrimp and eat within 3–4 days.","Peel onto hot rice with a little sauce and a raw egg yolk."]}}},
 botanebi:{d:{
  "牡丹虾味噌汤":{serves:"2",time:"15 min",
   ingT:[["Botan shrimp heads and shells (left from sashimi)","from 4–6 shrimp"],["Scallion","1"],["Tofu (optional)","1/4 block"]],
   sauceT:[["Water","400ml"],["Sake","1 tbsp"],["Miso","1.5 tbsp"]],
   steps:["Snip off the sharp spike at the front of each head and rinse with the shells.","Fry the heads and shells in a little oil (optional) on medium for 1 minute until red and fragrant.","Add the water and sake, bring to a boil, skim and simmer on low 5 minutes, pressing the heads with a spoon to release the tomalley.","Add the tofu, lower the heat and dissolve in the miso.","Scatter with scallion. Leave the heads in the bowl to suck on."],
   tips:["Soup is the best use for heads left over from sashimi.","Frying the heads first turns the soup a lovely orange-red.","Sweet shrimp heads work the same way."]},
  "加拿大烤斑点虾":{serves:"2",time:"15 min",
   ingT:[["Large shell-on prawns (botan or spot prawns)","8"],["Garlic","2 cloves"],["Lemon","1/2"],["Parsley","a little"]],
   sauceT:[["Butter","30g"],["Salt and black pepper","a little"],["Chili flakes (optional)","a little"]],
   steps:["Cut the shells open along the back with scissors and remove the veins (leave the shells on).","Melt the butter with minced garlic, chopped parsley, salt, pepper and chili flakes to make garlic butter.","Brush garlic butter into the cuts.","Grill on a rack or in a pan on high for 1 minute per side until red.","Brush with more garlic butter and squeeze over lemon."],
   tips:["British Columbia's spot prawn season opens in May with local festivals.","High heat and a short cook keep them sweet and tender.","Splitting the back lets the garlic butter soak in."]}}},
 kurumaebi:{d:{
  "盐水大明虾":{serves:"2–3",time:"20 min",
   ingT:[["Large prawns (kuruma or fleshy prawns)","10 (about 400g)"],["Ginger","4 slices"],["Scallions","2"]],
   sauceT:[["Salt","1.5 tbsp"],["Sichuan peppercorns","1 tsp"],["Shaoxing or cooking wine","2 tbsp"],["Water","1 liter"],["Ginger vinegar (optional)","as needed"]],
   steps:["Snip off the feelers and head spike and remove the vein with a toothpick from the second segment of the back.","Boil the water with salt, peppercorns, ginger, scallions and wine for 2 minutes to infuse.","Add the prawns, and when it returns to a boil, cook 1–2 minutes until red and curled.","Turn off the heat and leave the prawns in the brine for 5 minutes to absorb flavor.","Lift out and plate. Eat cold or with ginger vinegar."],
   tips:["Steeping after turning off the heat seasons the prawns without overcooking them.","The brine should be saltier than soup, about 4%.","Kuruma prawns are pricey, so black tiger or whiteleg shrimp also work."]},
  "车虾天妇罗":{serves:"2",time:"30 min",
   ingT:[["Kuruma prawns","6"],["Grated daikon","as needed"]],
   sauceT:[["Cake flour","60g plus a little for dusting"],["Egg","1/2"],["Ice water","100ml"],["Oil for frying","4cm deep"],["Tempura dipping sauce (dashi 4: soy 1: mirin 1)","as needed"],["Salt","a little"]],
   steps:["Pull off the heads (keep them), peel leaving the tails and devein. Scrape the tail tip with a knife to squeeze out water.","Make 4 diagonal cuts on the belly, flip and press to straighten.","Mix the egg and ice water, add the flour and stir roughly into a thin batter (don't overmix).","Dust the prawns with flour, dip by the tail into the batter and fry at 175°C for 1.5–2 minutes until pale golden.","Snip the spike off each head, dust with flour and fry 1 minute. They turn crisp and can be eaten whole.","Serve with grated daikon and dipping sauce, or with salt."],
   tips:["Cold, lightly mixed batter fries up light and crisp.","Fried heads are a hidden treat at tempura restaurants.","Kuruma prawns are the most prized tempura ingredient."]}}}
});
