window.ADD_I18N("ja", {
 kegani:{d:{
  "蟹壳烧":{serves:"2",time:"20分",
   ingT:[["茹で毛ガニ","1杯"],["長ねぎ","1/4本"],["卵（お好みで）","1個"]],
   sauceT:[["日本酒","大さじ1"],["味噌（お好みで）","小さじ1"]],
   steps:["毛ガニを解体し、甲羅の中のカニ味噌を取り出し、身をほぐす。","甲羅を洗って水気をふき、カニ味噌と身の一部を戻し、日本酒と味噌少々を加えて混ぜる。","小ねぎを散らし、卵黄を落としてもよい。","甲羅をそのまま焼き網か魚焼きグリルにのせ、中火で5〜7分、ぐつぐつするまで焼く。","混ぜながら食べ、残りはご飯にのせても。"],
   tips:["北海道の居酒屋の名物。残った甲羅を器にする。","ゆでたカニなので、ぐつぐつするまで温めれば十分。","日本酒を少し加えると、臭みが消えて香りが立つ。"]},
  "螃蟹味噌汤":{serves:"4",time:"25分",
   ingT:[["カニ（毛ガニ・ワタリガニなど、生かゆで）","1〜2杯"],["長ねぎ","1/2本"],["大根","5cm"],["豆腐（お好みで）","1/2丁"]],
   sauceT:[["水","800ml"],["酒","大さじ2"],["味噌","大さじ3"]],
   steps:["カニをこすり洗いしてえらを取り、殻ごと4〜6つに切り、はさみは包丁の背でたたいて割る。","大根をいちょう切りにする。","鍋に水・カニ・大根を入れて煮立て、アクを取り、酒を加えて弱火で10分煮る。","豆腐を入れ、弱火にして味噌を溶き入れ、ねぎを加える。","器に盛り、カニを食べながら汁を飲む。"],
   tips:["「鉄砲汁」の名は、カニのはさみが鉄砲の筒のようだから。","水からゆっくり煮ると、うまみがよく出る。","はさみを割っておくと、味がしみて身も取りやすい。"]}}},
 tarabagani:{d:{
  "芝士焗帝王蟹":{serves:"2〜3",time:"25分",
   ingT:[["ボイルたらばがに（脚）","500g"],["ピザ用チーズ","100g"],["にんにく","2かけ"],["パセリ（お好みで）","少々"]],
   sauceT:[["バター","20g"],["マヨネーズ","大さじ2"],["黒こしょう","少々"],["レモン","1/4個"]],
   steps:["脚を冷蔵庫で半日かけて解凍する。","キッチンばさみで脚のやわらかい側の殻を切り、殻を半分はがして身を出す。","やわらかくしたバターに、にんにくのみじん切りと黒こしょうを混ぜて身に塗り、マヨネーズを絞る。","チーズをたっぷりのせる。","220°Cに予熱したオーブンで8分、チーズがきつね色にふつふつするまで焼く。","パセリを散らし、レモンを搾る。"],
   tips:["市販のたらばがにの脚はほとんどがボイル冷凍品なので、温めて焼き色をつけるだけ。","焼きすぎると身がぱさつく。","殻にとげがあるので、はさみで切るときは手袋をする。"]},
  "螃蟹火锅":{serves:"3〜4",time:"40分",
   ingT:[["タラバガニかズワイガニ（生・カット済み）","600g"],["白菜","1/4株"],["豆腐","1丁"],["長ねぎ","1本"],["えのき・しいたけ","各1パック"],["春菊","1束"],["ご飯・卵（雑炊用）","1杯・2個"]],
   sauceT:[["昆布","10cm 1枚"],["水","1.2L"],["酒","50ml"],["薄口醤油","大さじ2"],["みりん","大さじ1"],["塩","小さじ1/2"],["ポン酢","適量"]],
   steps:["昆布を水に30分つけて火にかけ、沸騰直前に取り出し、酒・薄口醤油・みりん・塩を加える。","野菜と豆腐を切り、冷凍のカニは冷蔵庫で半解凍する。","鍋に白菜の芯・ねぎ・きのこを入れて5分煮る。","カニを入れて2〜3分、身が白くなるまで煮てポン酢で食べ、豆腐・白菜の葉・春菊を加える。","最後に水で洗ったご飯をスープに入れ、煮立ったら溶き卵を回し入れ、ふたをして30秒蒸らし、ねぎを散らしてカニ雑炊に。"],
   tips:["関西の冬の名物「かにすき」。","カニは煮すぎず、白くなったら食べる。","最後の雑炊がうまみをすべて吸って、いちばんのごちそう。"]},
  "阿拉斯加蟹脚":{serves:"2",time:"15分",
   ingT:[["ボイルタラバガニ（冷凍）","500g"],["レモン","1個"]],
   sauceT:[["バター","60g"],["にんにく（お好みで）","1かけ"],["パセリ","少々"]],
   steps:["脚を冷蔵庫で一晩かけて解凍する（水につけない）。","キッチンばさみで殻に切れ目を入れ、身を取り出しやすくする。","湯が沸いた蒸し器で5分蒸す（すでにゆでてあるので温めるだけ）。","小鍋でバターを溶かし、好みでにんにくのみじん切りを加えて1分煮て、パセリを散らす。","カニの身を溶かしバターにつけ、レモンを搾って食べる。"],
   tips:["アメリカのシーフードレストランの定番。いちばんシンプルで、たらばがにの甘さがよくわかる。","市販の脚はほとんどがゆでてあるので、再びゆでず温めるだけ。","ゆっくり解凍すると、身から水が出ずぱさつかない。"]}}},
 zuwaigani:{d:{
  "蒜蓉粉丝蒸雪蟹腿":{n:"ずわいがにの脚のにんにく春雨蒸し",h:"殻を半分切った脚を春雨にのせ、にんにくだれをかけて6分蒸し、熱した油と小ねぎをかける。",serves:"2〜3",time:"30分",
   ingT:[["ずわいがに（脚）かボイル紅ずわい","400g"],["緑豆春雨","1束（約30g）"],["にんにく","1玉"],["小ねぎ","2本"]],
   sauceT:[["サラダ油","大さじ4"],["醤油","大さじ2"],["オイスターソース","小さじ1"],["砂糖","小さじ1/2"],["料理酒","大さじ1"]],
   steps:["脚を冷蔵庫で解凍し、キッチンばさみで片面の殻を切り取って身を出し、6〜8cmに切る。","春雨をぬるま湯でもどし、切って皿に敷き、カニの身を上にして並べる。","にんにくをみじん切りにし、半量を油大さじ3で弱火できつね色に炒め、火を止めて生のにんにく・醤油・オイスターソース・砂糖を混ぜ、身にのせる。","料理酒をふり、湯が沸いた蒸し器で強火6分（ボイル冷凍なら4分）蒸す。","小ねぎを散らし、熱した油大さじ1をかける。"],
   tips:["ボイル済みの脚は温めて味をなじませるだけなので、蒸しすぎない。","カニの汁を吸った春雨がとてもおいしい。","中国の「カナダ産スノークラブ」と日本のずわいがには近縁で、作り方は同じ。"]},
  "香箱蟹":{serves:"2",time:"40分",
   ingT:[["香箱ガニ（セイコガニ、活か生）","2杯"]],
   sauceT:[["塩","水の量の3%"],["カニ酢（酢2：醤油1：だし1）","適量"]],
   steps:["大鍋にたっぷりの水と3%の塩を入れて煮立てる。","カニを腹を上にして入れ（みそが流れ出ない）、再び沸騰したら中火で15分ゆでる。","取り出し、腹を下にして冷ます。","ふんどしをはずして甲羅をはがし、外子（腹のつぶつぶの卵）と甲羅の中の内子（オレンジ色）、みそを取り出す。","脚と胴の身をほぐし、内子・外子・みそと一緒に甲羅に詰め、カニ酢を添える。"],
   tips:["北陸の冬（11〜12月）限定。メスは小さいが、2種類の卵が楽しめる。","腹を上にしてゆでると、みそが流れない。","石川では「香箱ガニ」、福井では「セイコガニ」と呼ぶ。"]},
  "螃蟹杂炊":{serves:"2〜3",time:"15分",
   ingT:[["かに鍋の残りのスープ","600ml"],["ご飯","1杯"],["卵","2個"],["カニの身（お好みで）","少々"],["小ねぎ","2本"]],
   sauceT:[["塩か薄口醤油","少々（味見して）"]],
   steps:["鍋に残った具をきれいにすくい、アクを取ってスープを残す。","ご飯を水でさっと洗ってぬめりを取る（スープがさらりと仕上がる）。","ご飯とカニの身をスープに入れ、中火で3分煮る。","味見して、塩か薄口醤油で調える。","溶き卵を回し入れ、ふたをして火を止め、30秒蒸らして小ねぎを散らす。"],
   tips:["日本の鍋の定番のしめ。","ご飯を洗うと、雑炊がさらりとしてべたつかない。","卵を入れたらすぐ火を止め、半熟がいちばんおいしい。"]}}},
 gazami:{d:{
  "酱蟹":{serves:"4",time:"40分（漬け3日）",
   ingT:[["活ワタリガニ（メス、内子入り）","2杯"],["にんにく","6かけ"],["生姜","1かけ"],["青唐辛子・赤唐辛子","各2本"],["玉ねぎ","1/2個"]],
   sauceT:[["醤油","500ml"],["水","700ml"],["砂糖","大さじ4"],["酒か焼酎","100ml"],["昆布","10cm"],["干ししいたけ","3枚"]],
   steps:["醤油・水・砂糖・酒・昆布・しいたけ・にんにく・生姜・玉ねぎを鍋に入れて煮立て、弱火で15分煮て、こして完全に冷ます。","活きたカニを冷凍庫に1〜2時間入れて眠らせ、ブラシで洗い、脚の先を切る。","清潔な容器にカニを腹を上にして入れ、冷ましたたれをかぶるまで注ぎ、唐辛子の輪切りを加えてふたをし、冷蔵する。","2日目にたれだけを取り出して再び煮立てて冷まし、戻す（安全と日持ちのため）。","3日目から食べられる。切り分けて、甲羅の中で内子と温かいご飯を混ぜて食べる。"],
   tips:["韓国の名物「カンジャンケジャン」。「ご飯泥棒」と呼ばれる。","必ず活きたカニを使い、漬けてから1週間以内に食べきる。","生食にはリスクがあるので、妊娠中や免疫力の弱い人にはすすめない。"]},
  "意式梭子蟹面":{serves:"2",time:"40分",
   ingT:[["ワタリガニ","1杯（約400g）"],["パスタ（リングイネ）","180g"],["トマト缶","1/2缶"],["にんにく","2かけ"],["鷹の爪","1本"],["パセリ","少々"]],
   sauceT:[["オリーブオイル","大さじ3"],["白ワイン","80ml"],["塩","適量"]],
   steps:["カニをこすり洗いしてえらを取り、4つに切り、はさみは包丁の背でたたいて割る。","フライパンにオリーブオイル・にんにくの薄切り・鷹の爪を入れて弱火で香りを出し、カニを入れて中火で2分、赤くなるまで焼く。","白ワインを注いで1分煮て、つぶしたトマト缶と水100mlを加え、ふたをして弱火で15分煮る。","同時にパスタを袋の表示より1分短くゆでる。","パスタをカニのソースに入れ、ゆで汁を少し加えて強火で1分あえてソースを吸わせ、パセリを散らし、カニを上に盛る。"],
   tips:["イタリア・ヴェネツィアや南部の海辺の家庭料理。","殻のうまみがトマトソースに溶け出すのがポイント。","手でカニをむきながら食べると、ソースがさらにおいしい。"]},
  "梭子蟹味噌汤":{serves:"4",time:"25分",
   ingT:[["ワタリガニ","1杯"],["長ねぎ","1/2本"]],
   sauceT:[["水","800ml"],["酒","大さじ2"],["味噌","大さじ3"]],
   steps:["カニをこすり洗いし、甲羅をはずしてえらを取り、4〜6つに切る。","鍋に水とカニを入れて中火にかけ、沸騰したらアクを取る。","酒を加えて弱火で10分煮ると、汁がオレンジ色になる。","弱火にして味噌を溶き入れる。","ねぎを入れ、30秒煮て火を止める。"],
   tips:["ワタリガニの汁は赤くてうまみが濃く、西日本でよく作られる家庭の汁物。","水から煮ると、うまみがよく出る。","味噌を入れたら煮立たせない。"]}}},
 "mitten-crab":{d:{
  "蟹粉豆腐":{serves:"2〜3",time:"50分",
   ingT:[["上海蟹（またはずわいがにのほぐし身）","2杯（または身100g）"],["絹ごし豆腐","1丁"],["生姜","1かけ"],["小ねぎ","1本"]],
   sauceT:[["ラードかサラダ油","大さじ2"],["紹興酒","大さじ1"],["鶏ガラスープ","200ml"],["塩","少々"],["白こしょう","少々"],["黒酢","小さじ1"],["水溶き片栗粉","片栗粉大さじ1＋水大さじ3"]],
   steps:["上海蟹をこすり洗いし、湯が沸いた蒸し器で15分蒸す。冷めたら、みそと身を取り出す（これが「蟹粉」）。","豆腐を1.5cm角に切り、塩を入れた湯に5分つけて取り出す。","鍋にラードを入れ、弱火で生姜のみじん切りを炒め、蟹粉を加えて1分炒め、紹興酒と黒酢少々をふってカニの油を出す。","スープを加えて煮立て、豆腐をそっと入れて弱火で3分煮る。","塩と白こしょうで調え、水溶き片栗粉を回し入れ、混ぜずにへらで前に押すようにして、とろみがつくまで煮る。","小ねぎを散らす。"],
   tips:["カニをむくのは時間がかかるので、市販のカニ缶や「かにのほぐし身」で代用できる。","豆腐を塩湯につけるとくずれにくい。","酢は臭みを消し、カニの香りを引き立てる。"]}}}
});
window.ADD_I18N("en", {
 kegani:{d:{
  "蟹壳烧":{serves:"2",time:"20 min",
   ingT:[["Boiled horsehair crab","1"],["Japanese leek (negi)","1/4"],["Egg (optional)","1"]],
   sauceT:[["Sake","1 tbsp"],["Miso (optional)","1 tsp"]],
   steps:["Take the crab apart, scoop the tomalley (kani miso) from the shell and pick out the meat.","Wash and dry the top shell, return the tomalley and some of the meat, add the sake and a little miso and mix.","Scatter with chopped leek, and drop in an egg yolk if you like.","Set the shell directly on a grill rack or under a fish grill and cook on medium 5–7 minutes until bubbling.","Stir as you eat, and spoon the rest over rice."],
   tips:["A Hokkaido izakaya favorite that uses the crab shell as a bowl.","The crab is already cooked, so just heat until bubbling.","A little sake removes odor and adds aroma."]},
  "螃蟹味噌汤":{serves:"4",time:"25 min",
   ingT:[["Crab (horsehair, swimming crab, etc., raw or cooked)","1–2"],["Japanese leek (negi)","1/2"],["Daikon","5cm"],["Tofu (optional)","1/2 block"]],
   sauceT:[["Water","800ml"],["Sake","2 tbsp"],["Miso","3 tbsp"]],
   steps:["Scrub the crab, remove the gills and chop it in the shell into 4–6 pieces. Crack the claws with the back of a knife.","Cut the daikon into quarter rounds.","Bring the water, crab and daikon to a boil, skim, add the sake and simmer on low 10 minutes.","Add the tofu, lower the heat, dissolve in the miso and add the leek.","Serve and drink the broth as you eat the crab."],
   tips:["Called teppo-jiru (gun soup) because the claws look like gun barrels.","Starting in cold water draws out more flavor.","Cracking the claws lets flavor in and makes the meat easier to get out."]}}},
 tarabagani:{d:{
  "芝士焗帝王蟹":{serves:"2–3",time:"25 min",
   ingT:[["Cooked frozen king crab legs","500g"],["Shredded mozzarella","100g"],["Garlic","2 cloves"],["Parsley (optional)","a little"]],
   sauceT:[["Butter","20g"],["Mayonnaise","2 tbsp"],["Black pepper","a little"],["Lemon","1/4"]],
   steps:["Thaw the legs in the fridge for half a day.","Cut along the softer side of each leg with kitchen scissors and lift off half the shell to expose the meat.","Mix the soft butter with minced garlic and pepper, brush over the meat and pipe on mayonnaise.","Cover with cheese.","Bake at 220°C for 8 minutes until golden and bubbling.","Sprinkle with parsley and squeeze over lemon."],
   tips:["King crab legs on the market are almost always cooked and frozen, so they only need heating and browning.","Don't overbake or the meat dries out.","Wear gloves when cutting, as the shell is spiny."]},
  "螃蟹火锅":{serves:"3–4",time:"40 min",
   ingT:[["Raw king or snow crab legs, cut","600g"],["Napa cabbage","1/4 head"],["Tofu","1 block"],["Japanese leek (negi)","1"],["Enoki and shiitake","1 pack each"],["Shungiku (edible chrysanthemum)","1 bunch"],["Rice and eggs (for porridge)","1 bowl and 2"]],
   sauceT:[["Kombu","1 piece, 10cm"],["Water","1.2 liters"],["Sake","50ml"],["Light (usukuchi) soy sauce","2 tbsp"],["Mirin","1 tbsp"],["Salt","1/2 tsp"],["Ponzu","as needed"]],
   steps:["Soak the kombu for 30 minutes, heat and remove just before boiling, then add the sake, soy sauce, mirin and salt.","Cut the vegetables and tofu. Half-thaw frozen crab in the fridge.","Simmer the cabbage stems, leek and mushrooms for 5 minutes.","Add the crab for 2–3 minutes until the meat turns white and eat with ponzu, then add the tofu, cabbage leaves and shungiku.","Finally add rinsed rice to the broth, bring to a boil, drizzle in beaten egg, cover for 30 seconds and scatter with scallion for crab porridge."],
   tips:["Kani-suki is a winter specialty of the Kansai region.","Don't overcook the crab. Eat it once it turns white.","The final porridge soaks up all the flavor and is the highlight of the meal."]},
  "阿拉斯加蟹脚":{serves:"2",time:"15 min",
   ingT:[["Cooked frozen king crab legs","500g"],["Lemon","1"]],
   sauceT:[["Butter","60g"],["Garlic (optional)","1 clove"],["Parsley","a little"]],
   steps:["Thaw the legs in the fridge overnight (don't soak in water).","Cut a slit in the shells with kitchen scissors to make the meat easy to remove.","Steam over boiling water for 5 minutes (they're already cooked, so this just heats them).","Melt the butter in a small pan, add minced garlic for 1 minute if you like and sprinkle with parsley.","Dip the crab meat in melted butter and squeeze over lemon."],
   tips:["The classic American seafood-restaurant way, the simplest way to taste king crab's sweetness.","Most legs on sale are already cooked, so just heat them. Don't boil again.","Slow thawing keeps the meat from leaking water and drying out."]}}},
 zuwaigani:{d:{
  "蒜蓉粉丝蒸雪蟹腿":{n:"Steamed snow crab legs with garlic and glass noodles",h:"Cut away half the shell, lay the legs on glass noodles with garlic sauce, steam 6 minutes and finish with hot oil and scallions.",serves:"2–3",time:"30 min",
   ingT:[["Snow crab legs (cooked frozen or raw)","400g"],["Mung bean glass noodles","1 small bundle (about 30g)"],["Garlic","1 whole head"],["Scallions","2"]],
   sauceT:[["Cooking oil","4 tbsp"],["Light soy sauce","2 tbsp"],["Oyster sauce","1 tsp"],["Sugar","1/2 tsp"],["Shaoxing or cooking wine","1 tbsp"]],
   steps:["Thaw the legs in the fridge, cut away the shell on one side with kitchen scissors to expose the meat and cut into 6–8cm lengths.","Soak the noodles in warm water until soft, cut and spread on a plate, then lay the crab on top meat side up.","Mince the garlic. Fry half in 3 tbsp oil on low until golden, turn off the heat and mix in the raw garlic, soy sauce, oyster sauce and sugar. Spoon over the crab.","Splash with wine and steam on high for 6 minutes (4 minutes for cooked frozen legs).","Scatter with scallions and pour over 1 tbsp hot oil."],
   tips:["Pre-cooked legs only need heating through, so don't oversteam.","The noodles soak up the crab juices and are delicious.","Canadian snow crab in China and Japanese zuwaigani are close relatives and cook the same way."]},
  "香箱蟹":{serves:"2",time:"40 min",
   ingT:[["Female snow crabs (kobako or seiko), live or raw","2"]],
   sauceT:[["Salt","3% of the water"],["Crab vinegar (vinegar 2: soy 1: dashi 1)","as needed"]],
   steps:["Bring a large pot of water with 3% salt to a boil.","Put the crabs in belly up (so the tomalley doesn't run out), return to a boil and cook on medium 15 minutes.","Lift out and cool belly down.","Remove the belly flap and pull off the top shell. Take out the outer roe (the beaded eggs on the belly), the orange inner roe and the tomalley from the shell.","Pick the meat from the legs and body and pack it back into the shell with both roes and the tomalley. Serve with crab vinegar."],
   tips:["Only available in Hokuriku in winter (November–December). Females are small but carry two kinds of roe.","Boiling belly up keeps the tomalley in.","Called kobako-gani in Ishikawa and seiko-gani in Fukui."]},
  "螃蟹杂炊":{serves:"2–3",time:"15 min",
   ingT:[["Leftover crab hot pot broth","600ml"],["Cooked rice","1 bowl"],["Eggs","2"],["Crab meat (optional)","a little"],["Scallions","2"]],
   sauceT:[["Salt or light soy sauce","a little (to taste)"]],
   steps:["Clear out the leftover solids from the pot and skim, keeping the broth.","Rinse the rice in water to remove the starch (for a clean broth).","Add the rice and crab meat to the broth and simmer on medium 3 minutes.","Taste and adjust with salt or light soy sauce.","Drizzle in the beaten eggs, cover, turn off the heat and rest 30 seconds. Scatter with scallions."],
   tips:["The standard finish (shime) to a Japanese hot pot.","Rinsing the rice keeps the porridge light, not gluey.","Turn off the heat right after adding the egg. Half-set is best."]}}},
 gazami:{d:{
  "酱蟹":{serves:"4",time:"40 min (plus 3 days marinating)",
   ingT:[["Live female swimming crabs with roe","2"],["Garlic","6 cloves"],["Ginger","1 piece"],["Green and red chilies","2 each"],["Onion","1/2"]],
   sauceT:[["Soy sauce","500ml"],["Water","700ml"],["Sugar","4 tbsp"],["Sake or soju","100ml"],["Kombu","10cm"],["Dried shiitake","3"]],
   steps:["Boil the soy sauce, water, sugar, sake, kombu, shiitake, garlic, ginger and onion, simmer on low 15 minutes, strain and cool completely.","Put the live crabs in the freezer for 1–2 hours to make them dormant, scrub with a brush and snip off the leg tips.","Lay the crabs belly up in a clean container, pour over the cold sauce to cover, add sliced chilies, cover and refrigerate.","On day 2, drain the sauce, boil it again, cool and pour it back (for safety and longer keeping).","Ready on day 3. Cut into pieces and mix the roe with hot rice in the shell."],
   tips:["Ganjang-gejang is a famous Korean dish nicknamed 'rice thief'.","Always use live crabs and eat within a week.","Eating raw crab carries risk. Not recommended during pregnancy or for anyone with weak immunity."]},
  "意式梭子蟹面":{serves:"2",time:"40 min",
   ingT:[["Swimming crab","1 (about 400g)"],["Pasta (linguine or spaghetti)","180g"],["Canned tomatoes","1/2 can"],["Garlic","2 cloves"],["Dried red chili","1"],["Parsley","a little"]],
   sauceT:[["Olive oil","3 tbsp"],["White wine","80ml"],["Salt","as needed"]],
   steps:["Scrub the crab, remove the gills, cut into 4 pieces and crack the claws with the back of a knife.","Heat olive oil with sliced garlic and chili on low until fragrant, add the crab and cook on medium 2 minutes until red.","Add the wine for 1 minute, then the crushed tomatoes and 100ml water. Cover and simmer on low 15 minutes.","Meanwhile cook the pasta 1 minute less than the package says.","Add the pasta to the crab sauce with a little pasta water, toss on high for 1 minute to absorb, sprinkle with parsley and arrange the crab on top."],
   tips:["A home-style dish from Venice and Italy's southern coast.","The flavor from the shells infusing the tomato sauce is the key.","Peeling the crab by hand as you eat makes the sauce even better."]},
  "梭子蟹味噌汤":{serves:"4",time:"25 min",
   ingT:[["Swimming crab","1"],["Japanese leek (negi)","1/2"]],
   sauceT:[["Water","800ml"],["Sake","2 tbsp"],["Miso","3 tbsp"]],
   steps:["Scrub the crab, lift off the top shell, remove the gills and cut into 4–6 pieces.","Put the water and crab in a pot on medium, and skim when it boils.","Add the sake and simmer on low 10 minutes. The broth turns orange-red.","Lower the heat and dissolve in the miso.","Add the leek, cook 30 seconds and turn off the heat."],
   tips:["Swimming crab makes a red, savory broth, a common home soup in western Japan.","Starting in cold water brings out more flavor.","Don't boil after adding the miso."]}}},
 "mitten-crab":{d:{
  "蟹粉豆腐":{serves:"2–3",time:"50 min",
   ingT:[["Chinese mitten crabs (or snow crab meat)","2 (or 100g meat)"],["Silken tofu","1 block"],["Ginger","1 piece"],["Scallion","1"]],
   sauceT:[["Lard or cooking oil","2 tbsp"],["Shaoxing wine","1 tbsp"],["Chicken stock","200ml"],["Salt","a little"],["White pepper","a little"],["Black vinegar","1 tsp"],["Starch slurry","1 tbsp starch + 3 tbsp water"]],
   steps:["Scrub the crabs and steam over boiling water for 15 minutes. When cool, pick out the roe and meat (this is 'crab powder').","Cut the tofu into 1.5cm cubes, soak in salted hot water for 5 minutes and drain.","Fry the minced ginger in lard on low, add the crab and fry 1 minute, then splash in the wine and a little vinegar to release the crab oil.","Add the stock, bring to a boil, gently add the tofu and simmer on low 3 minutes.","Season with salt and white pepper, drizzle in the slurry and push gently with a spatula (don't stir) until thickened.","Scatter with scallion."],
   tips:["Picking crab takes time, so canned crab or ready-picked crab meat works.","Soaking tofu in salted water keeps it from breaking.","Vinegar removes odor and lifts the crab flavor."]}}}
});
// 详细菜谱翻译 29
window.ADD_I18N("ja", {
 "mitten-crab":{d:{
  "醉蟹":{serves:"4",time:"30分（漬け3〜5日）",
   ingT:[["活上海蟹（小さめ）","4杯"],["生姜","1かけ"],["長ねぎ","1本"]],
   sauceT:[["紹興酒（花雕）","500ml"],["醤油","200ml"],["氷砂糖","50g"],["花椒","大さじ1"],["八角","2個"],["焼酎（35度以上）","50ml"],["水","200ml"]],
   steps:["小鍋に水・醤油・氷砂糖・花椒・八角・生姜・ねぎを入れて5分煮立て、完全に冷ましてから紹興酒と焼酎を加えて漬け汁を作る。","活きたカニをブラシでよく洗い、きれいな水に半日入れて汚れを吐かせる。","冷蔵庫に1時間入れて動かなくし、腹のふんどしの部分に包丁の先で切れ目を入れる（汁がしみ込みやすい）。","清潔な密閉容器に腹を上にして入れ、漬け汁を完全にかぶるまで注ぎ、皿で重しをする。","冷蔵庫で3〜5日漬け、切り分けて冷たいまま食べる。"],
   tips:["生で食べる料理なので、寄生虫や細菌のリスクがある。信頼できる活きたカニだけを使い、妊婦・子ども・高齢者にはすすめない。","死んだカニは絶対に使わない。","漬けてから1週間以内に食べきる。"]}}},
 "mud-crab":{d:{
  "避风塘炒蟹":{serves:"3",time:"45分",
   ingT:[["ノコギリガザミかワタリガニ","1〜2杯（約800g）"],["にんにく","2玉（約20かけ）"],["豆豉","大さじ1"],["鷹の爪","5本"],["小ねぎ","2本"]],
   sauceT:[["片栗粉","大さじ4"],["揚げ油","鍋底から3cm"],["砂糖","小さじ1"],["塩","少々"],["パン粉（お好みで）","大さじ2"]],
   steps:["カニをこすり洗いしてえらと胃を取り、6〜8つに切り、はさみはたたいて割り、切り口に片栗粉をまぶす。","にんにくを細かいみじん切りにし、水でさっと洗って絞る（焦げにくくなる）。","油を180°Cに熱し、カニを3〜4分、赤くなるまで揚げて取り出す。","油温を140°Cに下げ、にんにくを入れて弱火で5〜8分、混ぜ続けながらきつね色にカリッと揚げ、すぐ取り出して油をきる。","鍋に油大さじ1を残して豆豉・鷹の爪・パン粉を炒め、カニ・揚げにんにく・砂糖・塩・小ねぎを加えて強火で混ぜる。"],
   tips:["にんにくの揚げ加減が決め手。きつね色になったらすぐ取り出す。余熱でさらに色づく。","香港の避風塘の船上料理。にんにくはたっぷり使う。","活きたカニの下処理は魚屋に頼んでもよい。"]},
  "膏蟹蒸饭":{serves:"4",time:"1.5時間（米の浸水2時間）",
   ingT:[["ワタリガニ（メス）かノコギリガザミのメス","1杯（約500g）"],["もち米","2合（300g）"],["干ししいたけ","4枚"],["干しえび","大さじ2"],["豚バラ肉","100g"],["エシャロット","3個"]],
   sauceT:[["ラードかサラダ油","大さじ3"],["醤油","大さじ2"],["米酒か酒","大さじ2"],["砂糖","小さじ1"],["白こしょう","少々"],["しいたけの戻し汁","150ml"]],
   steps:["もち米を2時間水につけて水気をきる。しいたけと干しえびをもどし、しいたけは細切りにし、戻し汁は取っておく。","豚バラを細切り、エシャロットを薄切りにする。","鍋にラードを熱してエシャロットをきつね色に炒め、豚バラ・しいたけ・干しえびを加えて香りを出す。","もち米を加えて炒め、醤油・米酒・砂糖・こしょう・戻し汁を加え、水分がなくなるまで炒める。","もち米を皿かせいろに広げ、湯が沸いた蒸し器で強火25分蒸す。","カニを洗って切り（甲羅も残す）、もち米の上にのせてさらに15分蒸し、カニの汁をご飯にしみ込ませる。"],
   tips:["台湾・閩南の宴席料理「紅蟳米糕」。","メスのかにみそがいちばん香ばしく、秋冬が旬。","もち米を炒めてから蒸すと、もっちりと歯ごたえが出る。"]},
  "黑胡椒蟹":{serves:"2〜3",time:"40分",
   ingT:[["ノコギリガザミ（マッドクラブ、活）","1杯（約800g）"],["にんにく","4かけ"],["エシャロット","3個"],["カレーリーフ","1枝"],["赤唐辛子","2本"]],
   sauceT:[["粗挽き黒こしょう","大さじ2"],["バター","40g"],["オイスターソース","大さじ1"],["醤油","大さじ1"],["老抽（中国のたまり醤油）","小さじ1"],["砂糖","小さじ1"],["片栗粉","大さじ2"],["揚げ油","鍋底から3cm"]],
   steps:["カニを30分冷凍して眠らせ、こすり洗いし、甲羅をはずしてえらを取り、6つに切り、はさみをたたいて割る。","切り口に片栗粉をつけ、180°Cの油で3〜4分、殻が赤くなるまで揚げて取り出す。","黒こしょうを油をひかない鍋で弱火30秒から炒りして香りを出す。","中華鍋にバターを溶かし、にんにく・エシャロット・カレーリーフ・唐辛子を1分炒め、黒こしょう・オイスターソース・醤油・老抽・砂糖・水大さじ3を加える。","カニを入れ、強火で2分炒めてソースをからめる。"],
   tips:["シンガポールでチリクラブと並ぶ看板料理。","黒こしょうを先にから炒りすると香りが倍増する。","日本ではノコギリガザミが手に入りにくいので、ワタリガニで代用。"]}}},
 dungeness:{d:{
  "旧金山蒜香烤蟹":{serves:"2",time:"40分",
   ingT:[["ダンジネスクラブなど大きなカニ（ボイル）","1杯（約1kg）"],["にんにく","1玉"],["パセリ","少々"],["レモン","1個"],["バゲット","1本"]],
   sauceT:[["バター","80g"],["オリーブオイル","大さじ2"],["白ワイン（お好みで）","大さじ2"],["こしょう・塩","少々"]],
   steps:["ゆでたカニの甲羅とえらを取り、4つに切り、はさみと脚を包丁の背でたたいて割る。","鍋にバターとオリーブオイルを入れて弱火で溶かし、にんにくのみじん切りをたっぷり加えて2分炒め（焦がさない）、白ワインとこしょうを加える。","天板にカニを並べ、ガーリックバターをかけて全体にからめる。","220°Cのオーブンで10〜12分、途中で一度返して焼く。","パセリを散らし、レモンを搾り、天板のガーリックバターをバゲットにつけて食べる。"],
   tips:["サンフランシスコ・フィッシャーマンズワーフの名物。ベトナム系レストランの「ローストガーリッククラブ」が有名。","ゆでたカニなので、温めて味をなじませるだけ。焼きすぎるとぱさつく。","日本では毛ガニやたらばがにで代用できる。"]},
  "海鲜炖菜":{serves:"4",time:"1時間",
   ingT:[["カニ（切ったもの）","1杯"],["あさり","300g"],["えび","8尾"],["白身魚","300g"],["玉ねぎ","1個"],["にんにく","3かけ"],["セロリ","1本"],["トマト缶","1缶"],["サワードウブレッド","適量"]],
   sauceT:[["オリーブオイル","大さじ3"],["白ワイン","200ml"],["魚のスープか水","500ml"],["トマトペースト","大さじ1"],["オレガノ・チリフレーク","各小さじ1/2"],["ローリエ","1枚"],["塩","適量"]],
   steps:["大鍋にオリーブオイルを熱し、玉ねぎ・セロリ・にんにくのみじん切りを5分、しんなりするまで炒める。","トマトペースト・オレガノ・チリフレークを加えて1分炒め、白ワインを注いで2分煮る。","トマト缶・スープ・ローリエを加え、弱火で20分煮てトマトスープのベースにし、塩で調える。","先にカニを入れて5分煮て、白身魚とあさりを加え、ふたをして3分煮る。","最後にえびを入れ、2分、えびが赤くなりあさりがすべて開くまで煮る。","大きな器に盛り、トーストしたサワードウを添える。"],
   tips:["サンフランシスコのイタリア系漁師が生んだ煮込み「チョッピーノ」。","魚介は火の通りやすさの順に入れると、かたくならない。","サワードウをスープにつけて食べるのが必須。"]}}},
 kouika:{d:{
  "花枝丸":{serves:"約20個",time:"40分",
   ingT:[["もんごういかかいか（むき身）","300g"],["豚の背脂（お好みで）","50g"],["卵白","1個分"],["くわいか玉ねぎ（お好みで）","3個"]],
   sauceT:[["塩","小さじ1/2"],["砂糖","小さじ1"],["白こしょう","少々"],["片栗粉","大さじ2"],["ごま油","小さじ1"],["揚げ油","鍋底から3cm"]],
   steps:["いかの皮を取り、水気をふく。3分の2はフードプロセッサーですり身にし、3分の1は小さな角切りにする（つぶつぶ感が出る）。","背脂とくわいを小さな角切りにする。","すり身に塩を加え、一方向に5分しっかり練って粘りを出し、卵白・砂糖・こしょう・片栗粉・ごま油を混ぜる。","いかの角切り・背脂・くわいを混ぜ、冷蔵庫で20分休ませる。","手を水でぬらし、親指と人さし指の間から丸く絞り出し、スプーンで160°Cの油に落とし、4〜5分、浮いてきつね色になるまで揚げる。","スイートチリソースにつけて食べる。スープに入れて煮ても。"],
   tips:["塩を入れてからしっかり練ると、ぷりぷりの団子になる。","台湾の夜市の定番。スイートチリソースがいちばん合う。","揚げた団子は冷凍保存できる。"]},
  "威尼斯墨鱼面":{serves:"2",time:"40分",
   ingT:[["スミイカかコウイカ（墨袋付き）","1杯（約400g）"],["スパゲッティ","180g"],["玉ねぎ","1/4個"],["にんにく","1かけ"],["トマト缶","1/4缶"],["パセリ","少々"]],
   sauceT:[["オリーブオイル","大さじ3"],["白ワイン","50ml"],["イカスミ（墨袋か市販品）","1個（または1袋4g）"],["塩","適量"]],
   steps:["いかの甲を取り、墨袋（銀色の小さな袋）をやぶらないように取り出して小皿に入れ、内臓と皮を取って胴を細切りにする。","フライパンにオリーブオイルを熱し、玉ねぎとにんにくのみじん切りを3分炒め、いかを1分炒める。","白ワインを注いで1分煮て、トマトと水少々を加え、弱火で15分、いかがやわらかくなるまで煮る。","墨袋をつぶして墨を水大さじ2で溶き、鍋に加えるとソースが黒くなる。","ゆでたパスタを入れ、ゆで汁を少し加えて強火で1分あえ、塩で調えてパセリを散らす。"],
   tips:["イタリア・ヴェネツィアの名物「スパゲッティ・アル・ネーロ・ディ・セッピア」。","いかは弱火でじっくり煮ると、かたい状態からやわらかくなる。","イカスミは色がつくので、濃い色の服を着て、まな板はすぐ洗う。"]},
  "墨鱼刺身":{serves:"2",time:"25分",
   ingT:[["スミイカ（刺身用）","1杯"],["大葉・大根のつま","適量"]],
   sauceT:[["醤油・わさび","適量"],["塩・すだち（お好みで）","少々"]],
   steps:["背から切り開いて甲を取り、墨袋をやぶらないように注意して内臓を取る。","胴のふちから外皮をむき、さらにキッチンペーパーで内側の薄皮をむく（きれいにむかないとかたくなる）。","胴の水気をふき、5mm幅の細切りにする（または表面に細かい格子の切り目を入れてそぎ切り）。","大葉と大根のつまの上に盛る。","わさび醤油で、または塩をふってすだちを搾って食べる。"],
   tips:["スミイカは身が厚く甘く、やりいかより弾力があり、寿司屋の冬から春の看板。","薄皮はしっかりむくと、食感がやわらかくなる。","墨はイカスミパスタに使える。"]}}},
 yariika:{d:{
  "活乌贼刺身":{serves:"2",time:"20分",
   ingT:[["活ヤリイカか活イカ（信頼できる店のもの）","1〜2杯"],["生姜","1かけ"],["大葉・大根のつま","適量"]],
   sauceT:[["醤油","適量"],["天ぷら衣（ゲソ・エンペラ用）","適量"]],
   steps:["活きたいかの頭と胴を持ち、頭と内臓を一緒に引き抜く。","透明な軟骨を抜き、胴の皮をむいてキッチンペーパーで水気をふく。","3mmのごく細切りにして透き通った姿に盛り、頭と脚を横に添える（まだ動いている）。","おろし生姜と醤油ですぐに食べる。","刺身を食べ終わったら、残りのゲソとエンペラを天ぷら衣をつけて1分揚げる（店なら頼めばしてくれる）。"],
   tips:["佐賀県呼子の名物。透き通ったいかは新鮮な証拠。","家庭では活いかは手に入りにくいので、刺身用のいかを同じように切ってもおいしい。","細く切るほど甘く感じる。"]},
  "希腊烤鱿鱼":{serves:"2",time:"30分",
   ingT:[["ヤリイカ（丸ごと）","2杯"],["にんにく","1かけ"],["レモン","1個"],["パセリ","少々"]],
   sauceT:[["エキストラバージンオリーブオイル","大さじ4"],["オレガノ（乾燥）","小さじ1"],["塩・こしょう","適量"]],
   steps:["いかの頭と内臓を引き抜き、軟骨を抜いて洗い、胴は丸ごとのまま水気をふく。","オリーブオイル・レモン汁（半個分）・にんにくのみじん切り・オレガノ・塩・こしょうを混ぜ、いかを15分漬ける。","焼き網か鋳鉄の鍋を強火で煙が出るまで熱し、胴と脚をのせ、片面1.5〜2分ずつ、焦げ目がつくまで焼く。","輪切りにし、残りのマリネ液と新しいオリーブオイルをかける。","パセリを散らし、くし形のレモンを添える。"],
   tips:["ギリシャの海辺の居酒屋（タベルナ）の看板料理。","強火で短時間焼くと、かたくならない。","胴に浅く切り目を入れると丸まりにくい。"]}}},
 hotaruika:{d:{
  "萤火鱿沖漬":{serves:"2〜3",time:"10分（漬け一晩）",
   ingT:[["生ホタルイカ（冷凍処理済み・生食用）","100g"],["生姜","少々"]],
   sauceT:[["醤油","大さじ3"],["酒","大さじ2"],["みりん","大さじ1"]],
   steps:["酒とみりんを小鍋で30秒煮立ててアルコールを飛ばし、醤油を加えて冷ます。","ホタルイカを冷蔵庫で解凍し、ピンセットで目と口を取る（食感がよくなる）。","密閉容器に入れ、冷ました漬け汁を注ぎ、生姜の薄切りを加える。","冷蔵庫で一晩漬ける。","温かいご飯にのせるか、酒の肴に。"],
   tips:["生のホタルイカには寄生虫のリスクがあるので、必ず「冷凍処理済み・生食用」を買う。","富山湾の名物。漁船の上でそのまま漬けたことから「沖漬け」と呼ぶ。","漬けてから2〜3日で食べきる。"]}}}
});
window.ADD_I18N("en", {
 "mitten-crab":{d:{
  "醉蟹":{serves:"4",time:"30 min (plus 3–5 days marinating)",
   ingT:[["Live Chinese mitten crabs (smallish)","4"],["Ginger","1 piece"],["Japanese leek (negi)","1"]],
   sauceT:[["Huadiao or Shaoxing wine","500ml"],["Light soy sauce","200ml"],["Rock sugar","50g"],["Sichuan peppercorns","1 tbsp"],["Star anise","2"],["Strong spirit (35% or more)","50ml"],["Water","200ml"]],
   steps:["Boil the water, soy sauce, rock sugar, peppercorns, star anise, ginger and leek for 5 minutes. Cool completely, then add the wine and spirit.","Scrub the live crabs well and keep them in clean water for half a day to purge.","Chill in the fridge for 1 hour so they stop moving, then nick the belly flap with the tip of a knife (helps the brine soak in).","Pack them belly up in a clean airtight container, pour in the brine to cover completely and weigh down with a plate.","Refrigerate 3–5 days. Cut into pieces and eat cold."],
   tips:["This dish is eaten raw and carries a risk of parasites and bacteria. Use only live crabs from a reliable source, and it's not recommended for pregnant women, children or the elderly.","Never use dead crabs.","Eat within a week."]}}},
 "mud-crab":{d:{
  "避风塘炒蟹":{serves:"3",time:"45 min",
   ingT:[["Mud crab or swimming crab","1–2 (about 800g)"],["Garlic","2 whole heads (about 20 cloves)"],["Fermented black beans","1 tbsp"],["Dried red chilies","5"],["Scallions","2"]],
   sauceT:[["Potato starch","4 tbsp"],["Oil for frying","3cm deep"],["Sugar","1 tsp"],["Salt","a little"],["Breadcrumbs (optional)","2 tbsp"]],
   steps:["Scrub the crab, remove the gills and stomach, cut into 6–8 pieces, crack the claws and dust the cut surfaces with starch.","Mince the garlic finely, rinse briefly and squeeze dry (it burns less easily).","Heat oil to 180°C and fry the crab 3–4 minutes until red. Lift out.","Lower the oil to 140°C and fry the garlic on low for 5–8 minutes, stirring constantly, until golden and crisp. Lift out immediately and drain.","Leave 1 tbsp oil and fry the black beans, chilies and breadcrumbs, add the crab, fried garlic, sugar, salt and scallions and toss on high."],
   tips:["Timing the garlic is key: remove it the moment it turns golden, as residual heat darkens it.","A boat people's dish from Hong Kong's typhoon shelters. Use lots of garlic.","Have the fishmonger prepare live crabs if you prefer."]},
  "膏蟹蒸饭":{serves:"4",time:"1.5 hours (plus 2 hours soaking)",
   ingT:[["Female mud crab or swimming crab with roe","1 (about 500g)"],["Glutinous rice","2 rice-cooker cups (300g)"],["Dried shiitake","4"],["Dried shrimp","2 tbsp"],["Pork belly","100g"],["Shallots","3"]],
   sauceT:[["Lard or cooking oil","3 tbsp"],["Soy sauce","2 tbsp"],["Rice wine or sake","2 tbsp"],["Sugar","1 tsp"],["White pepper","a little"],["Shiitake soaking water","150ml"]],
   steps:["Soak the glutinous rice 2 hours and drain. Soak the shiitake and dried shrimp until soft, slice the shiitake and keep the soaking water.","Slice the pork into strips and the shallots thinly.","Fry the shallots in lard until golden, then add the pork, shiitake and shrimp until fragrant.","Add the rice and stir-fry, then the soy sauce, rice wine, sugar, pepper and shiitake water, and stir until absorbed.","Spread the rice on a plate or in a steamer and steam on high 25 minutes.","Scrub and cut the crab (keep the top shell), lay it on the rice and steam 15 more minutes so the crab juices soak in."],
   tips:["A Taiwanese Minnan banquet dish called red crab rice cake.","The roe of female crabs is the most fragrant, best in autumn and winter.","Stir-frying the rice before steaming gives it more chew."]},
  "黑胡椒蟹":{serves:"2–3",time:"40 min",
   ingT:[["Live mud crab","1 (about 800g)"],["Garlic","4 cloves"],["Shallots","3"],["Curry leaves","1 sprig"],["Bird's eye chilies","2"]],
   sauceT:[["Coarse black pepper","2 tbsp"],["Butter","40g"],["Oyster sauce","1 tbsp"],["Light soy sauce","1 tbsp"],["Dark soy sauce","1 tsp"],["Sugar","1 tsp"],["Potato starch","2 tbsp"],["Oil for frying","3cm deep"]],
   steps:["Freeze the crab 30 minutes to make it dormant, scrub, lift off the shell, remove the gills, cut into 6 pieces and crack the claws.","Dip the cut surfaces in starch and fry at 180°C for 3–4 minutes until the shells turn red. Lift out.","Toast the pepper in a dry pan on low for 30 seconds until fragrant.","Melt the butter in a wok and fry the garlic, shallots, curry leaves and chilies for 1 minute, then add the pepper, oyster sauce, both soy sauces, sugar and 3 tbsp water.","Add the crab and toss on high for 2 minutes to coat in sauce."],
   tips:["Singapore's signature dish alongside chili crab.","Toasting the pepper first doubles the aroma.","Mud crab is hard to find in Japan, so swimming crab works instead."]}}},
 dungeness:{d:{
  "旧金山蒜香烤蟹":{serves:"2",time:"40 min",
   ingT:[["Cooked Dungeness or other large crab","1 (about 1kg)"],["Garlic","1 head"],["Parsley","a little"],["Lemon","1"],["Baguette","1"]],
   sauceT:[["Butter","80g"],["Olive oil","2 tbsp"],["White wine (optional)","2 tbsp"],["Black pepper and salt","a little"]],
   steps:["Remove the top shell and gills from the cooked crab, cut into 4 and crack the claws and legs with the back of a knife.","Melt the butter and olive oil on low, add plenty of minced garlic and cook 2 minutes until fragrant (don't burn it), then add the wine and pepper.","Put the crab in a roasting pan, pour over the garlic butter and toss.","Roast at 220°C for 10–12 minutes, turning once.","Sprinkle with parsley, squeeze over lemon and mop up the garlic butter with baguette."],
   tips:["A Fisherman's Wharf specialty, made famous by Vietnamese-American restaurants' roasted garlic crab.","The crab is already cooked, so just heat it through. Overroasting dries it out.","In Japan, use horsehair or king crab."]},
  "海鲜炖菜":{serves:"4",time:"1 hour",
   ingT:[["Crab, cut in pieces","1"],["Clams","300g"],["Shrimp","8"],["White fish","300g"],["Onion","1"],["Garlic","3 cloves"],["Celery","1 stalk"],["Canned tomatoes","1 can"],["Sourdough bread","as needed"]],
   sauceT:[["Olive oil","3 tbsp"],["White wine","200ml"],["Fish stock or water","500ml"],["Tomato paste","1 tbsp"],["Dried oregano and chili flakes","1/2 tsp each"],["Bay leaf","1"],["Salt","as needed"]],
   steps:["Fry the chopped onion, celery and garlic in olive oil in a large pot for 5 minutes until soft.","Add the tomato paste, oregano and chili flakes for 1 minute, then the wine for 2 minutes.","Add the tomatoes, stock and bay leaf and simmer on low 20 minutes for the tomato base. Season with salt.","Add the crab first for 5 minutes, then the fish and clams, covered, for 3 minutes.","Add the shrimp last and cook 2 minutes until pink and all the clams open.","Serve in large bowls with toasted sourdough."],
   tips:["Cioppino was created by Italian fishermen in San Francisco.","Adding the seafood in order of cooking time keeps everything tender.","Dipping sourdough in the broth is a must."]}}},
 kouika:{d:{
  "花枝丸":{serves:"about 20",time:"40 min",
   ingT:[["Cuttlefish (or squid) meat","300g"],["Pork back fat (optional)","50g"],["Egg white","1"],["Water chestnuts or onion (optional)","3"]],
   sauceT:[["Salt","1/2 tsp"],["Sugar","1 tsp"],["White pepper","a little"],["Potato starch","2 tbsp"],["Sesame oil","1 tsp"],["Oil for frying","3cm deep"]],
   steps:["Skin and pat dry the cuttlefish. Blend two-thirds into a paste and dice the rest small (for texture).","Dice the fat and water chestnuts small.","Add salt to the paste and beat hard in one direction for 5 minutes until sticky, then mix in the egg white, sugar, pepper, starch and sesame oil.","Fold in the diced cuttlefish, fat and water chestnuts and chill 20 minutes.","With wet hands, squeeze balls out between thumb and forefinger, scoop them into 160°C oil with a spoon and fry 4–5 minutes until floating and golden.","Dip in sweet chili sauce, or simmer in soup."],
   tips:["Beating hard after adding salt makes the balls bouncy.","A Taiwanese night-market classic, best with sweet chili sauce.","Fried balls freeze well."]},
  "威尼斯墨鱼面":{serves:"2",time:"40 min",
   ingT:[["Cuttlefish with ink sac","1 (about 400g)"],["Spaghetti","180g"],["Onion","1/4"],["Garlic","1 clove"],["Canned tomatoes","1/4 can"],["Parsley","a little"]],
   sauceT:[["Olive oil","3 tbsp"],["White wine","50ml"],["Cuttlefish ink (sac or store-bought)","1 sac (or 1 packet, 4g)"],["Salt","as needed"]],
   steps:["Remove the cuttlebone, carefully take out the ink sac (a small silvery pouch) into a small bowl, discard the innards and skin and cut the body into thin strips.","Fry the minced onion and garlic in olive oil for 3 minutes, then the cuttlefish for 1 minute.","Add the wine for 1 minute, then the tomatoes and a little water, and simmer on low 15 minutes until tender.","Burst the ink sac, dilute the ink with 2 tbsp water and stir into the pan. The sauce turns black.","Add the cooked pasta with a little pasta water, toss on high for 1 minute, season and sprinkle with parsley."],
   tips:["Spaghetti al nero di seppia is a famous Venetian dish.","Slow simmering turns cuttlefish from tough to tender.","Ink stains, so wear dark clothes and wash the board right away."]},
  "墨鱼刺身":{serves:"2",time:"25 min",
   ingT:[["Sashimi-grade cuttlefish","1"],["Shiso and shredded daikon","as needed"]],
   sauceT:[["Soy sauce and wasabi","as needed"],["Salt and sudachi (optional)","a little"]],
   steps:["Cut open along the back and remove the cuttlebone and innards, taking care not to burst the ink sac.","Peel the outer skin from the edge, then peel off the thin inner membrane with paper towel (it must all come off or the meat is tough).","Pat the body dry and cut into 5mm strips (or score finely and slice).","Arrange on shiso and daikon.","Dip in wasabi soy sauce, or sprinkle with salt and squeeze over sudachi."],
   tips:["Cuttlefish is thick, sweet and springier than squid, a winter-to-spring star at sushi bars.","Peeling the membrane completely keeps it tender.","Save the ink for squid-ink pasta."]}}},
 yariika:{d:{
  "活乌贼刺身":{serves:"2",time:"20 min",
   ingT:[["Live spear squid (from a trusted source)","1–2"],["Ginger","1 piece"],["Shiso and shredded daikon","as needed"]],
   sauceT:[["Soy sauce","as needed"],["Tempura batter (for the leftovers)","as needed"]],
   steps:["Hold the head in one hand and the body in the other and pull the head and innards out together.","Pull out the clear quill, peel the body and pat dry with paper towel.","Cut into very fine 3mm strips, arrange so they look translucent, and set the head and tentacles alongside (still moving).","Eat right away with grated ginger and soy sauce.","After the sashimi, dip the tentacles and fins in tempura batter and fry for 1 minute (restaurants will do this on request)."],
   tips:["A specialty of Yobuko in Saga. Translucent squid is proof of freshness.","Live squid is hard to buy at home, but sashimi-grade squid cut the same way is delicious.","The finer you cut it, the sweeter it tastes."]},
  "希腊烤鱿鱼":{serves:"2",time:"30 min",
   ingT:[["Whole squid","2"],["Garlic","1 clove"],["Lemon","1"],["Parsley","a little"]],
   sauceT:[["Extra virgin olive oil","4 tbsp"],["Dried oregano","1 tsp"],["Salt and black pepper","as needed"]],
   steps:["Pull out the head and innards, remove the quill, rinse and pat dry, keeping the body whole.","Mix the olive oil, juice of half the lemon, minced garlic, oregano, salt and pepper and marinate the squid 15 minutes.","Heat a grill or cast-iron pan on high until smoking and cook the bodies and tentacles 1.5–2 minutes per side until charred.","Slice into rings and drizzle with the remaining marinade and fresh olive oil.","Sprinkle with parsley and serve with lemon wedges."],
   tips:["A signature dish of Greek seaside tavernas.","High heat and a short cook keep squid from turning rubbery.","Lightly scoring the body stops it from curling."]}}},
 hotaruika:{d:{
  "萤火鱿沖漬":{serves:"2–3",time:"10 min (plus marinating overnight)",
   ingT:[["Raw firefly squid, frozen-treated and safe to eat raw","100g"],["Ginger","a little"]],
   sauceT:[["Soy sauce","3 tbsp"],["Sake","2 tbsp"],["Mirin","1 tbsp"]],
   steps:["Boil the sake and mirin for 30 seconds to cook off the alcohol, add the soy sauce and cool.","Thaw the squid in the fridge. Pull out the eyes and beaks with tweezers (better texture).","Put the squid in an airtight container, pour over the cold marinade and add a few slices of ginger.","Marinate overnight in the fridge.","Serve with hot rice or as a drinking snack."],
   tips:["Raw firefly squid can carry parasites, so always buy ones labeled frozen-treated and safe to eat raw.","A Toyama Bay specialty, named okizuke because it was marinated right on the fishing boat.","Eat within 2–3 days."]}}}
});
