window.ADD_I18N("ja", {
 hotaruika:{d:{
  "萤火鱿意面":{serves:"2",time:"20分",
   ingT:[["ボイルホタルイカ","100g"],["スパゲッティ","160g"],["菜の花","1/2束"],["にんにく","2かけ"],["鷹の爪","1本"]],
   sauceT:[["オリーブオイル","大さじ3"],["塩","適量"],["醤油（お好みで）","数滴"]],
   steps:["ホタルイカの目と口を取る。菜の花はざく切りにする。","パスタを塩を入れた湯でゆで、ゆで上がり1分前に菜の花も入れて一緒にゆでる。","フライパンにオリーブオイル・にんにくの薄切り・鷹の爪を入れ、弱火で香りを出す。","ホタルイカの半量を入れ、木べらでつぶしてわたをソースにする。","パスタ・菜の花・残りのホタルイカ・ゆで汁少々を入れて強火であえ、醤油を数滴たらし、塩で調える。"],
   tips:["春（3〜5月）の季節のパスタ。ホタルイカも菜の花も春の味。","つぶしたホタルイカのわたが濃厚なソースになる。","スーパーの「ボイルホタルイカ」は火が通っているので、最後に入れて煮すぎない。"]}}},
 aoriika:{d:{
  "软丝刺身":{serves:"2",time:"25分",
   ingT:[["アオリイカ（刺身用）","1杯（約500g）"],["大葉","2枚"],["ゆずかすだち","1/2個"]],
   sauceT:[["塩","少々"],["醤油・わさび","適量"]],
   steps:["頭と内臓を引き抜き、軟骨を抜いて、胴の外側の厚い皮をむく。","さらにキッチンペーパーで内側と外側の薄皮をむく（何層もあり、きれいにむくほどやわらかい）。","胴をキッチンペーパーで包み、冷蔵庫で1日寝かせる（お好みで。甘みが増す）。","細切り（麺のように）にするか、表面に細かい格子の切り目を入れてそぎ切りにする。","大葉の上に盛り、塩をふってゆずを搾るか、わさび醤油で。"],
   tips:["アオリイカは「イカの王様」と呼ばれ、甘みがいちばん強い。","冷蔵庫で1日寝かせると、うまみ（アミノ酸）が増える。","ゲソとエンペラは天ぷらに。"]},
  "软丝天妇罗":{serves:"2",time:"25分",
   ingT:[["アオリイカ（胴）","200g"],["大葉","4枚"]],
   sauceT:[["薄力粉","50g＋打ち粉少々"],["冷水","80ml"],["卵黄","1/2個"],["揚げ油","鍋底から4cm"],["塩","少々"],["レモン","1/4個"]],
   steps:["いかの皮と薄皮をむき、幅1.5cm・長さ5cmの太い棒状に切り、キッチンペーパーでしっかり水気をふく。","卵黄に冷水を混ぜ、薄力粉を加えてざっくり混ぜる。","いかに打ち粉をして（油はね防止）、衣をつける。","180°Cの油で1分、表面がカリッとしたら引き上げ、中心は半生に仕上げる。","大葉で1本巻いて一緒に揚げてもよい。塩をふり、レモンを搾って食べる。"],
   tips:["アオリイカは身が厚いので、半生に揚げるといちばん甘くやわらかい。","水気は必ずしっかりふく。残ると油がはねる。","揚げすぎるとかたくなる。"]}}},
 ikura:{d:{
  "亲子盖饭":{serves:"2",time:"20分",
   ingT:[["いくら醤油漬け","80g"],["塩鮭","1切れ"],["温かいご飯か酢飯","2杯"],["大葉","4枚"],["刻みのり","少々"]],
   sauceT:[["わさび","少々"],["醤油（お好みで）","少々"]],
   steps:["塩鮭を魚焼きグリルで焼き、皮と骨を取ってほぐす（鮭フレーク）。","器にご飯を盛り、刻みのりを散らして大葉を敷く。","半分に鮭フレークをのせる。","もう半分にいくらをたっぷりのせる。","わさびを添え、好みで醤油を少したらす。"],
   tips:["「親子」は鮭といくらのこと。北海道の名物丼。","いくらには味がついているので、醤油は控えめに。","いくらの醤油漬けを自分で作るなら、いくらのおすすめ料理を参照。"]},
  "俄式布林饼配鱼子":{serves:"3〜4",time:"1時間（発酵含む）",
   ingT:[["いくら","100g"],["サワークリーム","100g"],["ディル","少々"],["そば粉","60g"],["強力粉か中力粉","60g"],["牛乳","200ml"],["卵","1個"]],
   sauceT:[["ドライイースト","3g"],["砂糖","小さじ1"],["塩","小さじ1/3"],["バター（溶かす）","20g"]],
   steps:["牛乳を35°Cに温め、イーストと砂糖を混ぜて5分置く。","そば粉・小麦粉・卵黄・塩・溶かしバターの半量を加えてゆるい生地にし、ラップをして温かい場所で40分、泡立つまで発酵させる。","卵白を角が軽く立つまで泡立て、生地にさっくり混ぜる。","フライパンにバターを塗り、お玉で直径7cmの小さな円に流し、弱火で表面に小さな穴があくまで焼き、返して30秒焼く。","少し冷ましてサワークリームを塗り、いくらをスプーン1杯のせ、ディルを添える。"],
   tips:["ロシアのマースレニツァ（冬送りの祭り）の伝統食。","ブリヌイは前もって焼いておき、食べる前にフライパンで軽く温めればよい。","そば粉がなければ、全部小麦粉でもよい。"]}}},
 tarako:{d:{
  "烤明太子":{serves:"2",time:"10分",
   ingT:[["辛子明太子","1腹（約60g）"],["長ねぎか小ねぎ","少々"],["温かいご飯","2杯"]],
   sauceT:[["マヨネーズ（お好みで）","適量"]],
   steps:["魚焼きグリルかフライパンを中火で予熱する。","明太子を丸ごとのせる（フライパンならアルミホイルを敷いてもよい）。","片面1〜2分ずつ、そっと返しながら、表面が白くなって少し焦げ目がつくまで焼き、中は半生に保つ。","斜めに2cm幅に切る。","ご飯と一緒に、またはマヨネーズをつけて酒の肴に。"],
   tips:["表面に火が通り、中が半生のときがいちばんおいしい。","焼きすぎるとぱさぱさになる。","食べきれなければおにぎりの具に。"]},
  "明太鱼子酱":{serves:"3〜4",time:"10分",
   ingT:[["明太子かたらこ","2腹（約120g）"],["小ねぎ","2本"],["温かいご飯","適量"],["のり（お好みで）","少々"]],
   sauceT:[["ごま油","大さじ1"],["白ごま","小さじ1"],["韓国唐辛子粉（お好みで）","小さじ1/2"],["おろしにんにく","少々"]],
   steps:["明太子を1cm幅に切る（薄皮を切って中の卵をしごき出してもよい）。","小ねぎを小口切りにする。","ボウルに明太子を入れ、ごま油・にんにく・唐辛子粉・小ねぎを加えてそっと混ぜる。","白ごまをふる。","温かいご飯にのせるか、のりでご飯と一緒に巻いて食べる。"],
   tips:["明太子は韓国が起源で、福岡に伝わって日本の名産になった。","ごま油で卵の香りがよくなるのが、韓国式のポイント。","生卵黄を加えてご飯に混ぜても。"]}}},
 kazunoko:{d:{
  "芥末鲱鱼子":{serves:"2〜3",time:"10分（解凍別）",
   ingT:[["味付け数の子","1パック（約150g）"],["きゅうりか大葉（お好みで）","少々"]],
   sauceT:[["醤油","大さじ1"],["わさび","小さじ1/2"]],
   steps:["冷凍なら、冷蔵庫で2〜3時間かけて解凍する。","キッチンペーパーで余分な汁を軽く吸い取る。","1.5cm幅に切って皿に盛り、きゅうりの薄切りか大葉を添える。","わさびと醤油を混ぜ、つけて食べる。"],
   tips:["中国のスーパーでは「黄金魚子」「希鯪魚子」と呼ばれ、味付け済みでそのまま食べられる。","日本のスーパーの「味付け数の子」も同じように食べられる。","塩気が強ければ、わさびだけでもよい。"]},
  "高汤腌鲱鱼子":{serves:"4",time:"30分（塩抜き半日・漬け1日）",
   ingT:[["塩数の子","4本"],["切り昆布（松前漬けの素）","20g"],["するめ（細切り）","20g"],["にんじん","1/3本"]],
   sauceT:[["醤油","50ml"],["酒","50ml"],["みりん","50ml"],["塩（塩抜き用）","少々"]],
   steps:["塩数の子を薄い塩水（水1L＋塩小さじ1）につけ、冷蔵庫で6〜8時間置き、途中で2回水をかえる。ほんのり塩気が残る程度になればよい。","指で表面の薄皮をむき、食べやすい大きさに割る。","酒とみりんを煮立ててアルコールを飛ばし、醤油を加えて冷ます。","にんじんを細いせん切りにする。切り昆布・するめ・にんじん・数の子を容器に入れ、たれを注いで混ぜる。","冷蔵庫で1日漬け、昆布からぬめりが出れば味がなじんだ合図。"],
   tips:["北海道・松前の名物で、日本の正月のおせち料理によく入る。","塩抜きは真水ではなく薄い塩水で。数の子が苦くならない。","年末のスーパーには、昆布とするめがセットの「松前漬けの素」がある。"]},
  "鲱鱼子海藻":{serves:"2〜3",time:"10分（塩抜き別）",
   ingT:[["子持ち昆布（塩漬け）","100g"],["かつお節","少々"]],
   sauceT:[["薄い塩水（塩抜き用）","水1L＋塩小さじ1"],["醤油か白だし","適量"]],
   steps:["子持ち昆布を薄い塩水につけ、冷蔵庫で3〜4時間置いて塩抜きする（途中で1回水をかえる）。","味見して、ほんのり塩気が残る程度になったらキッチンペーパーで水気をふく。","1cm幅に切る。","器に盛り、かつお節をふる。","醤油を少しかけるか、白だしに1時間つけるとさらに味がしみる。"],
   tips:["にしんが昆布に卵を産みつけたもので、「プチプチ」とした食感が独特。","アラスカやカナダが主な産地。","寿司種にもなる。"]}}},
 tobiko:{d:{
  "蟹子炒饭":{serves:"2",time:"15分",
   ingT:[["とびこ","40g"],["冷やご飯","2杯"],["卵","2個"],["小ねぎ","2本"],["むきえび（お好みで）","50g"]],
   sauceT:[["サラダ油","大さじ2"],["塩","小さじ1/2"],["白こしょう","少々"]],
   steps:["とびこを冷蔵庫で解凍する。卵を溶き、小ねぎを小口切りにする。","鍋をよく熱して油を入れ、溶き卵を半熟まで炒める。","ご飯を入れ、強火で卵とほぐしながら炒め合わせる（えびを入れるならここで）。","塩・白こしょう・小ねぎを加えて混ぜ、火を止める。","火を止めてからとびこの大半を混ぜ、盛り付けて残りのとびこを上にのせる。"],
   tips:["とびこは火を止めてから入れると、プチプチ感が残る。","中華料理店の「蟹子」は多くがカラフトシシャモの卵（マサゴ）で、使い方は同じ。","冷やご飯を使うとパラパラになる。"]},
  "飞鱼子军舰卷":{serves:"2",time:"25分",
   ingT:[["とびこ","60g"],["米","1合"],["焼きのり","2枚"],["うずらの卵黄（お好みで）","2個"]],
   sauceT:[["すし酢","大さじ1.5"],["醤油","少々"]],
   steps:["酢飯を作り、あおいで冷ます。","のりを3cm×18cmの帯状に切る。","手に手酢をつけ、15gくらいの俵形に軽く握る。","のりを酢飯の周りに一周巻き、端をご飯粒でとめ、上に1cmのすき間を残す。","すき間にとびこをたっぷりのせ、中央にうずらの卵黄をのせてもよい。"],
   tips:["とびこのプチプチした食感は子どもに大人気。","のりは食べる直前に巻かないとしんなりする。","スーパーのとびこにはオレンジ色や緑色（わさび味）などがある。"]}}}
});
window.ADD_I18N("en", {
 hotaruika:{d:{
  "萤火鱿意面":{serves:"2",time:"20 min",
   ingT:[["Boiled firefly squid","100g"],["Spaghetti","160g"],["Nanohana (rapini)","1/2 bunch"],["Garlic","2 cloves"],["Dried red chili","1"]],
   sauceT:[["Olive oil","3 tbsp"],["Salt","as needed"],["Soy sauce (optional)","a few drops"]],
   steps:["Remove the eyes and beaks from the squid. Cut the nanohana into lengths.","Cook the pasta in salted water, adding the nanohana for the last minute.","Heat olive oil with sliced garlic and chili on low until fragrant.","Add half the squid and crush with a wooden spatula so the livers turn into sauce.","Add the pasta, nanohana, remaining squid and a little pasta water, toss on high, add a few drops of soy sauce and season with salt."],
   tips:["A seasonal spring pasta (March–May). Firefly squid and nanohana are both tastes of spring.","The crushed squid livers make a rich sauce.","Supermarket boiled firefly squid is already cooked, so add it last and don't overcook."]}}},
 aoriika:{d:{
  "软丝刺身":{serves:"2",time:"25 min",
   ingT:[["Sashimi-grade bigfin reef squid","1 (about 500g)"],["Shiso","2 leaves"],["Yuzu or sudachi","1/2"]],
   sauceT:[["Salt","a little"],["Soy sauce and wasabi","as needed"]],
   steps:["Pull out the head and innards, remove the quill and peel the thick outer skin from the body.","Then peel off the thin inner and outer membranes with paper towel (there are several layers, and the cleaner, the more tender).","Wrap the body in paper towel and refrigerate 1 day (optional, it gets sweeter).","Cut into fine noodle-like strips, or score the surface in a fine grid and slice.","Arrange on shiso and sprinkle with salt and yuzu juice, or serve with wasabi soy sauce."],
   tips:["Bigfin reef squid is called the king of squid and is the sweetest.","Resting a day in the fridge increases its savory amino acids.","Use the tentacles and fins for tempura."]},
  "软丝天妇罗":{serves:"2",time:"25 min",
   ingT:[["Bigfin reef squid body","200g"],["Shiso","4 leaves"]],
   sauceT:[["Cake flour","50g plus a little for dusting"],["Ice water","80ml"],["Egg yolk","1/2"],["Oil for frying","4cm deep"],["Salt","a little"],["Lemon","1/4"]],
   steps:["Peel off the skin and membranes and cut into thick sticks 1.5cm wide and 5cm long. Dry thoroughly with paper towel.","Mix the yolk with the ice water and stir in the flour roughly.","Dust the squid with flour (prevents spatter) and dip in batter.","Fry at 180°C for 1 minute until the outside is crisp, keeping the center half-raw.","You can wrap a stick in shiso and fry it together. Eat with salt and lemon."],
   tips:["The squid is thick, so frying it half-raw keeps it sweetest and most tender.","Dry it well or the oil will spatter.","Overfrying makes it tough."]}}},
 ikura:{d:{
  "亲子盖饭":{serves:"2",time:"20 min",
   ingT:[["Soy-marinated salmon roe","80g"],["Salted salmon","1 piece"],["Hot rice or sushi rice","2 bowls"],["Shiso","4 leaves"],["Shredded nori","a little"]],
   sauceT:[["Wasabi","a little"],["Soy sauce (optional)","a little"]],
   steps:["Grill the salted salmon, remove skin and bones and flake it.","Fill bowls with rice, scatter with nori and lay shiso on top.","Cover half with the salmon flakes.","Pile the other half with salmon roe.","Add wasabi and a little soy sauce to taste."],
   tips:["'Parent and child' means salmon and its roe, a famous Hokkaido rice bowl.","The roe is already seasoned, so go easy on the soy sauce.","To marinate your own roe, see the salmon roe featured recipe."]},
  "俄式布林饼配鱼子":{serves:"3–4",time:"1 hour (including rising)",
   ingT:[["Salmon roe","100g"],["Sour cream","100g"],["Dill","a little"],["Buckwheat flour","60g"],["Bread or all-purpose flour","60g"],["Milk","200ml"],["Egg","1"]],
   sauceT:[["Dry yeast","3g"],["Sugar","1 tsp"],["Salt","1/3 tsp"],["Butter (melted)","20g"]],
   steps:["Warm the milk to 35°C, stir in the yeast and sugar and rest 5 minutes.","Add both flours, the egg yolk, salt and half the butter to make a thin batter. Cover and rise somewhere warm for 40 minutes until bubbly.","Whip the egg white to soft peaks and fold gently into the batter.","Brush a pan with butter, ladle in 7cm rounds and cook on low until small holes appear, then flip for 30 seconds.","Cool slightly, spread with sour cream, top with a spoonful of roe and garnish with dill."],
   tips:["A traditional food of Maslenitsa, Russia's farewell-to-winter festival.","The blini can be made ahead and warmed briefly in a pan before serving.","Without buckwheat flour, use all wheat flour."]}}},
 tarako:{d:{
  "烤明太子":{serves:"2",time:"10 min",
   ingT:[["Spicy pollock roe (karashi mentaiko)","1 sac (about 60g)"],["Leek or scallion","a little"],["Hot rice","2 bowls"]],
   sauceT:[["Mayonnaise (optional)","as needed"]],
   steps:["Preheat a fish grill or frying pan on medium.","Lay the whole roe sac on it (line the pan with foil if you like).","Cook 1–2 minutes per side, turning gently, until the outside turns white with a little char while the center stays half-raw.","Cut diagonally into 2cm pieces.","Eat with rice, or dip in mayonnaise as a drinking snack."],
   tips:["Cooked outside and half-raw inside is the best texture.","Overcooking makes it dry and crumbly.","Leftovers make a great onigiri filling."]},
  "明太鱼子酱":{serves:"3–4",time:"10 min",
   ingT:[["Mentaiko or tarako (pollock roe)","2 sacs (about 120g)"],["Scallions","2"],["Hot rice","as needed"],["Nori (optional)","a little"]],
   sauceT:[["Sesame oil","1 tbsp"],["White sesame","1 tsp"],["Korean chili flakes (optional)","1/2 tsp"],["Grated garlic","a little"]],
   steps:["Cut the roe into 1cm pieces (or slit the membrane and scrape out the eggs).","Chop the scallions.","Put the roe in a bowl with the sesame oil, garlic, chili flakes and scallions and mix gently.","Sprinkle with sesame seeds.","Spoon onto hot rice, or wrap with rice in nori."],
   tips:["Mentaiko originated in Korea and became a Japanese specialty after reaching Fukuoka.","Sesame oil makes the roe more fragrant and is the key to the Korean style.","Add a raw egg yolk and mix into the rice."]}}},
 kazunoko:{d:{
  "芥末鲱鱼子":{serves:"2–3",time:"10 min (plus thawing)",
   ingT:[["Seasoned herring roe","1 pack (about 150g)"],["Cucumber or shiso (optional)","a little"]],
   sauceT:[["Soy sauce","1 tbsp"],["Wasabi","1/2 tsp"]],
   steps:["If frozen, thaw in the fridge for 2–3 hours.","Gently blot off excess liquid with paper towel.","Cut into 1.5cm pieces and plate with cucumber slices or shiso.","Mix the wasabi and soy sauce and dip."],
   tips:["Chinese supermarkets sell it pre-seasoned as 'golden roe' and it's ready to eat.","Japanese supermarket ajitsuke kazunoko is eaten the same way.","If it's salty, dip in wasabi alone."]},
  "高汤腌鲱鱼子":{serves:"4",time:"30 min (plus half a day desalting and 1 day marinating)",
   ingT:[["Salted herring roe","4 pieces"],["Shredded kombu (for matsumaezuke)","20g"],["Shredded dried squid","20g"],["Carrot","1/3"]],
   sauceT:[["Soy sauce","50ml"],["Sake","50ml"],["Mirin","50ml"],["Salt (for desalting)","a little"]],
   steps:["Soak the salted roe in light salt water (1 liter water + 1 tsp salt) in the fridge for 6–8 hours, changing the water twice. It's ready when only a faint saltiness remains.","Peel off the thin membrane with your fingers and break into bite-size pieces.","Boil the sake and mirin to cook off the alcohol, add the soy sauce and cool.","Julienne the carrot finely. Put the kombu, squid, carrot and roe in a container, pour over the sauce and mix.","Marinate 1 day in the fridge. When the kombu turns slippery, it's ready."],
   tips:["A specialty of Matsumae in Hokkaido, often in Japanese New Year osechi.","Desalt in light salt water, not plain water, or the roe turns bitter.","At year's end, supermarkets sell matsumaezuke kits of kombu and dried squid."]},
  "鲱鱼子海藻":{serves:"2–3",time:"10 min (plus desalting)",
   ingT:[["Salted herring roe on kelp","100g"],["Bonito flakes","a little"]],
   sauceT:[["Light salt water (for desalting)","1 liter water + 1 tsp salt"],["Soy sauce or white dashi","as needed"]],
   steps:["Soak the roe on kelp in light salt water in the fridge for 3–4 hours to desalt, changing the water once.","Taste, and when only a faint saltiness remains, pat dry with paper towel.","Cut into 1cm slices.","Plate and scatter with bonito flakes.","Drizzle with a little soy sauce, or soak in white dashi for 1 hour for more flavor."],
   tips:["Herring lay their eggs on kelp, giving a unique crunchy pop.","Alaska and Canada are the main sources.","It's also used as a sushi topping."]}}},
 tobiko:{d:{
  "蟹子炒饭":{serves:"2",time:"15 min",
   ingT:[["Flying fish roe (tobiko)","40g"],["Day-old cooked rice","2 bowls"],["Eggs","2"],["Scallions","2"],["Peeled shrimp (optional)","50g"]],
   sauceT:[["Cooking oil","2 tbsp"],["Salt","1/2 tsp"],["White pepper","a little"]],
   steps:["Thaw the roe in the fridge. Beat the eggs and chop the scallions.","Heat the wok, add oil and scramble the eggs until half set.","Add the rice and stir-fry on high, breaking it up with the egg (add shrimp now if using).","Add the salt, white pepper and scallions, toss and turn off the heat.","Off the heat, mix in most of the roe, plate and top with the rest."],
   tips:["Add the roe after turning off the heat to keep its pop.","Much of the 'crab roe' in Chinese restaurants is capelin roe (masago), used the same way.","Day-old rice keeps the grains separate."]},
  "飞鱼子军舰卷":{serves:"2",time:"25 min",
   ingT:[["Flying fish roe (tobiko)","60g"],["Rice","1 rice-cooker cup"],["Toasted nori","2 sheets"],["Quail egg yolks (optional)","2"]],
   sauceT:[["Sushi vinegar","1.5 tbsp"],["Soy sauce","a little"]],
   steps:["Make sushi rice and fan it cool.","Cut the nori into strips 3cm × 18cm.","With vinegared hands, shape about 15g of rice into an oval.","Wrap a nori strip around the rice, seal the end with a grain of rice and leave 1cm of space at the top.","Fill the space with roe and place a quail yolk in the middle if you like."],
   tips:["Kids love tobiko's popping texture.","Wrap the nori just before eating or it goes soft.","Supermarket tobiko comes in orange, green (wasabi flavored) and more."]}}}
});
// 详细菜谱翻译 31
window.ADD_I18N("ja", {
 tobiko:{d:{
  "加州卷":{serves:"2本",time:"40分",
   ingT:[["米","2合"],["焼きのり","2枚"],["カニカマ","4本"],["アボカド","1個"],["きゅうり","1/2本"],["とびこ","40g"]],
   sauceT:[["すし酢","大さじ3"],["マヨネーズ","大さじ2"],["白ごま（お好みで）","少々"]],
   steps:["酢飯を作る。アボカドは棒状、きゅうりは細切りにし、カニカマはほぐす。","巻きすにラップをかぶせ、のりを1枚のせ、酢飯を全面に広げる。","全体を裏返し、のりを上、ご飯を下にする。","のりの中央にカニカマ・アボカド・きゅうりをのせ、マヨネーズを絞る。","巻きすで巻いて、しっかり押さえて形を整える。","外側のご飯にとびこ（またはごま）をまぶし、ぬらした包丁で8つに切る。"],
   tips:["アメリカで生まれた「裏巻き」（ご飯が外側）で、多くの人が最初に食べる寿司。","ラップを使うとご飯が巻きすにくっつかない。","一回切るごとに包丁をふく。"]}}},
 karasumi:{d:{
  "烤乌鱼子":{serves:"2〜4（酒の肴）",time:"15分",
   ingT:[["からすみ","1腹（約100g）"],["葉にんにく","1本"],["大根","少々"],["りんごか梨（お好みで）","1/4個"]],
   sauceT:[["焼酎か米酒","大さじ2"]],
   steps:["小さなナイフでからすみの表面の薄皮をそっとはがす（先に酒につけるとはがしやすい）。","両面に酒をたっぷり塗り、5分置く。","油をひかないフライパンで（またはバーナーで）、弱火で片面30秒〜1分ずつ、表面に小さな泡が出てオレンジ色になるまであぶり、中はやわらかく保つ。","斜めに3mmの薄切りにする。","大根とりんごを薄切り、葉にんにくを斜め切りにし、からすみと一緒に挟んで食べる。"],
   tips:["弱火でじっくりあぶる。強火だと焦げて苦く、かたくなる。","台湾ではからすみ1枚＋大根1枚＋葉にんにく1枚で食べる。","台湾と長崎が有名な産地で、台湾産のほうが安い。"]},
  "乌鱼子年糕":{serves:"4",time:"15分",
   ingT:[["からすみ","1/4腹（約30g）"],["切り餅","2個"],["大根（お好みで）","少々"]],
   sauceT:[["酒（お好みで）","少々"]],
   steps:["からすみの薄皮をはがし、2mmの薄切りにする。","餅を小さく切り（1個を4等分）、焼き網かオーブンでふくらんで少し焦げ目がつくまで焼く。","熱いうちに餅に切り込みを入れ、からすみをはさむ。","からすみは先に酒を塗るか、軽くあぶると香りがよくなる。","大根の薄切りを一緒にはさんでもよい。"],
   tips:["京都の料亭の冬の前菜。からすみの塩気と餅のもちもち感がよく合う。","からすみは高価なので、できるだけ薄く切る。","日本三大珍味の一つ（長崎産が最も有名）。"]}}},
 caviar:{d:{
  "俄式经典吃法":{serves:"4",time:"10分（ブリヌイ別）",
   ingT:[["キャビア","30g"],["ブリヌイ（いくらのブリヌイの作り方参照）","12枚"],["サワークリーム","100g"],["チャイブ（お好みで）","少々"],["クラッシュアイス","適量"]],
   sauceT:[["ウォッカ（冷やしたもの）","適量"]],
   steps:["キャビアの缶をクラッシュアイスの上に置き、食べる直前まで冷やしておく。","ブリヌイを軽く温めて皿に並べる。","ブリヌイにサワークリームを少し塗る。","貝・骨・プラスチックの小さなスプーンでキャビアをすくい、サワークリームの上にのせる（金属のスプーンは金属臭がつくので使わない）。","チャイブを散らし、冷やしたウォッカを添える。"],
   tips:["ロシアの伝統的な食べ方。キャビアは氷の上で鮮度を保つ。","金属のスプーンはキャビアに嫌なにおいをつけるので、専用の貝のスプーンを使う。","キャビアはかき混ぜず、そっとすくって粒をつぶさない。"]},
  "鱼子酱冷荞麦":{serves:"2",time:"15分",
   ingT:[["そば（乾麺）","160g"],["キャビア","10〜20g"],["小ねぎ","2本"],["わさび","少々"]],
   sauceT:[["めんつゆ（濃縮タイプ、表示どおり希釈）","300ml"],["氷","適量"]],
   steps:["めんつゆを表示どおり「かけ用」に薄め、冷蔵庫でよく冷やす。","そばを表示時間どおりにゆで、すぐ冷水でもみ洗いしてぬめりを取り、氷水でしめて水気をきる。","器にそばを入れ、冷たいつゆをかける。","中央にキャビアをスプーン1杯のせ、小ねぎを散らす。","わさびを少し添え、混ぜながら食べる。"],
   tips:["日本の高級そば店の夏の創作料理。","そばは氷水でしっかりしめるとコシが出る。","キャビアの塩気とつゆのバランスを考え、つゆは薄めにしてもよい。"]}}},
 uni:{d:{
  "海胆蒸蛋":{serves:"2",time:"20分",
   ingT:[["生うに","60g"],["卵","2個"],["小ねぎ","少々"]],
   sauceT:[["ぬるま湯","約180ml（卵液の1.5倍）"],["塩","少々"],["醤油","小さじ1"],["ごま油","数滴"]],
   steps:["卵を溶き、ぬるま湯と塩を加えて混ぜ、こして泡を取る。","うにの半量を器の底に入れ、卵液を注いでラップをする。","湯が沸いた蒸し器に入れ、中弱火で8〜10分、表面が固まるまで蒸す。","ラップをはずし、残りのうにを上にのせてさらに1分蒸す。","醤油とごま油をかけ、小ねぎを散らす。"],
   tips:["中弱火でラップをすると、表面がなめらかで気泡ができない。","うにの一部を最後にのせると、甘みが残る。","大連や山東の沿岸でよく作られる。日本では手ごろな「塩水うに」でよい。"]},
  "海胆意面":{serves:"2",time:"20分",
   ingT:[["生うに","80〜100g"],["スパゲッティ","160g"],["にんにく","1かけ"],["鷹の爪","1/2本"],["パセリ","少々"]],
   sauceT:[["エキストラバージンオリーブオイル","大さじ3"],["白ワイン","大さじ2"],["塩","適量"],["生クリーム（お好みで）","大さじ2"]],
   steps:["うにの半量をボウルでつぶし、オリーブオイル大さじ1を混ぜてソースにする。","パスタを塩を入れた湯で、表示より1分短くゆでる。","フライパンにオリーブオイル・にんにくの薄切り・鷹の爪を入れて弱火で香りを出し、白ワインを注いで30秒煮る（生クリームを使うならここで）。","パスタとゆで汁大さじ2を入れてあえたら火を止め、うにソースを混ぜる（余熱で。火はつけない）。","皿に盛り、残りのうにをのせ、パセリを散らし、オリーブオイルを少しかける。"],
   tips:["イタリア・シチリアやプーリアの定番パスタ。","うには必ず火を止めてから混ぜる。加熱しすぎると生臭くなり、固まる。","ソースには手ごろな輸入うにや冷凍うにを使い、上に良い生うにをのせるとよい。"]},
  "海胆海带汤":{serves:"3",time:"30分",
   ingT:[["生うに","50g"],["乾燥わかめ","10g"],["にんにく","1かけ"]],
   sauceT:[["ごま油","大さじ1"],["水","800ml"],["韓国醤油（クッカンジャン）か薄口醤油","大さじ1.5"],["塩","少々"]],
   steps:["わかめを水に10分つけてもどし、絞って食べやすく切る。","鍋にごま油を熱し、わかめとにんにくのみじん切りを中火で2〜3分炒める。","水を加えて煮立て、弱火で15分煮る。","うにを入れてそっとほぐし、2分煮る。","韓国醤油と塩で味を調える。"],
   tips:["済州島の名物スープ「ソンゲミヨックク」。","わかめを先にごま油で炒めると、スープが香ばしく濃くなる。","うにを入れるとスープが淡い黄色になり、うまみがとても強い。"]},
  "加州海胆吐司":{serves:"2",time:"10分",
   ingT:[["生うに","60g"],["バゲットか食パン","4枚"],["レモン","1/2個"],["チャイブか大葉","少々"]],
   sauceT:[["バター","20g"],["マルドンの塩（フレーク塩）","少々"],["エキストラバージンオリーブオイル","少々"]],
   steps:["パンを1.5cm厚さに切り、表面がきつね色にカリッとするまで焼く。","熱いうちにバターを塗る。","うにをのせる。","フレーク塩とレモンの皮のすりおろしを散らし、オリーブオイルを数滴たらす。","チャイブを散らし、すぐに食べる。"],
   tips:["アメリカ・カリフォルニア州サンタバーバラのうにレストランの人気メニュー。","パンは熱く、うには冷たく。温度差がおいしさのポイント。","バターをアボカドのペーストに替えても。"]}}},
 shirako:{d:{
  "白子天妇罗":{serves:"2",time:"25分",
   ingT:[["たらの白子","150g"],["大根おろし","適量"],["すだちかレモン","1/2個"]],
   sauceT:[["塩（洗う用）","小さじ1"],["薄力粉","40g＋打ち粉少々"],["冷水","70ml"],["揚げ油","鍋底から3cm"],["抹茶塩か塩","少々"]],
   steps:["白子に塩をふってそっともみ洗いしてぬめりを取り、洗い流して太い血管を切り、一口大に切る。","塩少々を入れた熱湯で白子を30秒、表面が白くなるまでゆで、氷水にとってキッチンペーパーでしっかり水気をふく。","薄力粉に冷水を加えてざっくり混ぜ、衣を作る。","白子に打ち粉をして衣をつけ、180°Cの油で1分、表面がカリッとするまで揚げる。","大根おろしとすだちを添えるか、抹茶塩で。"],
   tips:["外はカリッと、中はクリームのようにとろける冬の珍味。","下ゆですると表面が固まり、揚げても破れない。","水気は必ずしっかりふく。残ると油がはねる。"]},
  "鳕鱼白子汤":{serves:"3",time:"30分",
   ingT:[["たらの白子","200g"],["大根","5cm"],["もやし","1/2袋"],["春菊","1/2束"],["長ねぎ","1/2本"],["青唐辛子・赤唐辛子","各1本"]],
   sauceT:[["煮干し昆布だし","800ml"],["韓国唐辛子粉（澄ましなら入れない）","大さじ1"],["おろしにんにく","小さじ1"],["韓国醤油","大さじ1"],["塩","少々"],["酒","大さじ1"]],
   steps:["白子を塩でそっともみ洗いし、洗い流して一口大に切る。","大根を薄い色紙切りにし、だしで10分煮る。","唐辛子粉（辛口にするなら）・にんにく・韓国醤油・酒を加える。","白子ともやしを入れ、中火で4〜5分煮る（混ぜると白子がくずれるので混ぜない）。","塩で調え、春菊・ねぎ・唐辛子を加えて30秒煮て火を止める。"],
   tips:["韓国の冬の「コニタン」。辛いものは「コニメウンタン」と呼ぶ。","白子はやわらかいので、入れたらお玉でかき混ぜない。","たらの切り身と一緒に煮てたら鍋にしてもよい。"]}}},
 namako:{d:{
  "葱烧海参":{serves:"2〜3",time:"40分（もどし時間別）",
   ingT:[["戻しなまこか即食なまこ","4本（約300g）"],["長ねぎ（白い部分のみ）","3本"],["生姜","3枚"]],
   sauceT:[["サラダ油","大さじ4"],["料理酒","大さじ1"],["醤油","大さじ1"],["たまり醤油","小さじ1"],["オイスターソース","大さじ1"],["砂糖","大さじ1"],["鶏ガラスープ","200ml"],["水溶き片栗粉","片栗粉大さじ1＋水大さじ3"]],
   steps:["なまこを縦に切り開き、腹の中のすじを取り、大きめに切って、生姜と料理酒を入れた熱湯で2分下ゆでして取り出す。","長ねぎは白い部分だけを6cm長さに切る。","鍋に油を入れ、中弱火でねぎを5〜8分じっくり揚げてきつね色に香ばしくし、ねぎを取り出す。残った油がねぎ油。","ねぎ油に醤油・たまり醤油・オイスターソース・砂糖・スープを入れて煮立て、なまこを入れて弱火で10分煮る。","ねぎを戻してさらに5分煮て、水溶き片栗粉を回し入れ、鍋をゆすってなまこにからめ、ねぎ油を少したらして仕上げる。"],
   tips:["乾燥なまこをもどすには3〜5日かかり、油に触れてもいけないので、初心者はもどしたものか即食なまこを買うとよい。","ねぎ油がこの山東料理の命。ねぎはきつね色になるまで揚げる。","なまこ自体には味がなく、煮汁で味をしみ込ませるので、少し長めに煮る。"]}}}
});
window.ADD_I18N("en", {
 tobiko:{d:{
  "加州卷":{serves:"2 rolls",time:"40 min",
   ingT:[["Rice","2 rice-cooker cups"],["Toasted nori","2 sheets"],["Imitation crab sticks","4"],["Avocado","1"],["Cucumber","1/2"],["Flying fish roe (tobiko)","40g"]],
   sauceT:[["Sushi vinegar","3 tbsp"],["Mayonnaise","2 tbsp"],["White sesame (optional)","a little"]],
   steps:["Make sushi rice. Cut the avocado into strips and the cucumber into thin sticks, and shred the crab sticks.","Cover a bamboo mat with plastic wrap, lay on a sheet of nori and spread rice over the whole sheet.","Flip it over so the nori is on top and the rice underneath.","Lay the crab, avocado and cucumber along the middle of the nori and pipe on mayonnaise.","Roll up with the mat and press firmly into shape.","Roll the outside in roe (or sesame) and cut into 8 pieces with a wet knife."],
   tips:["An American-born inside-out roll (rice outside), the first sushi many people try.","Plastic wrap keeps the rice from sticking to the mat.","Wipe the knife after every cut."]}}},
 karasumi:{d:{
  "烤乌鱼子":{serves:"2–4 (with drinks)",time:"15 min",
   ingT:[["Dried mullet roe (karasumi)","1 piece (about 100g)"],["Green garlic","1 stalk"],["Daikon","a small piece"],["Apple or pear (optional)","1/4"]],
   sauceT:[["Kaoliang, shochu or rice wine","2 tbsp"]],
   steps:["Gently peel off the thin membrane with a small knife (soaking in liquor first makes it easier).","Brush both sides generously with the liquor and rest 5 minutes.","In a dry pan (or with a torch), toast on low for 30 seconds to 1 minute per side until small bubbles form and it turns golden orange, keeping the center soft.","Slice diagonally 3mm thin.","Thinly slice the daikon and apple, cut the green garlic diagonally and eat sandwiched together with the roe."],
   tips:["Toast slowly on low. High heat makes it bitter and hard.","The Taiwanese way: one slice each of roe, daikon and green garlic.","Taiwan and Nagasaki are famous sources, and Taiwanese is cheaper."]},
  "乌鱼子年糕":{serves:"4",time:"15 min",
   ingT:[["Dried mullet roe (karasumi)","1/4 piece (about 30g)"],["Square rice cakes (kirimochi)","2"],["Daikon (optional)","a little"]],
   sauceT:[["Sake (optional)","a little"]],
   steps:["Peel the membrane from the roe and slice 2mm thin.","Cut each rice cake into 4 and grill or toast until puffed and lightly charred.","While hot, slit each piece and tuck in a slice of roe.","Brushing the roe with sake or lightly searing it first makes it more fragrant.","You can also add a thin slice of daikon."],
   tips:["A winter appetizer at Kyoto ryotei. The salty roe pairs beautifully with chewy mochi.","Karasumi is expensive, so slice it as thin as possible.","One of Japan's three great delicacies, with Nagasaki's the most famous."]}}},
 caviar:{d:{
  "俄式经典吃法":{serves:"4",time:"10 min (plus blini)",
   ingT:[["Caviar","30g"],["Blini (see the salmon roe blini recipe)","12"],["Sour cream","100g"],["Chives (optional)","a little"],["Crushed ice","as needed"]],
   sauceT:[["Vodka (chilled)","as needed"]],
   steps:["Set the caviar tin on crushed ice and keep it cold until serving.","Warm the blini slightly and arrange on a plate.","Spread a little sour cream on each.","Use a mother-of-pearl, bone or plastic spoon to place a small spoonful of caviar on the sour cream (metal spoons leave a metallic taste).","Scatter with chives and serve with chilled vodka."],
   tips:["The traditional Russian way. Caviar stays fresh on ice.","Metal spoons give caviar an off taste, so use a mother-of-pearl spoon.","Don't stir the caviar. Lift it gently to keep the eggs whole."]},
  "鱼子酱冷荞麦":{serves:"2",time:"15 min",
   ingT:[["Dried soba noodles","160g"],["Caviar","10–20g"],["Scallions","2"],["Wasabi","a little"]],
   sauceT:[["Noodle sauce (concentrated mentsuyu, diluted per package)","300ml"],["Ice","as needed"]],
   steps:["Dilute the mentsuyu to pouring strength per the package and chill well.","Cook the soba per the package, immediately rinse and rub in cold water to remove the starch, then chill in ice water and drain.","Put the soba in bowls and pour over the cold sauce.","Place a spoonful of caviar in the center and scatter with scallions.","Add a little wasabi and mix as you eat."],
   tips:["A summer creation at upscale Japanese soba restaurants.","Chilling the soba in ice water gives it a firm bite.","Balance the caviar's saltiness by making the sauce a little lighter."]}}},
 uni:{d:{
  "海胆蒸蛋":{serves:"2",time:"20 min",
   ingT:[["Fresh sea urchin","60g"],["Eggs","2"],["Scallion","a little"]],
   sauceT:[["Warm water","about 180ml (1.5× the egg)"],["Salt","a little"],["Light soy sauce","1 tsp"],["Sesame oil","a few drops"]],
   steps:["Beat the eggs with the warm water and salt, strain and skim off the foam.","Put half the urchin in the bottom of a bowl, pour in the egg and cover with plastic wrap.","Steam over boiling water on medium-low 8–10 minutes until set.","Remove the wrap, arrange the remaining urchin on top and steam 1 minute more.","Drizzle with soy sauce and sesame oil and scatter with scallion."],
   tips:["Medium-low heat and plastic wrap give a smooth, bubble-free surface.","Adding some urchin at the end keeps its sweetness.","Common along the coasts of Dalian and Shandong. In Japan, affordable salt-water-packed uni works."]},
  "海胆意面":{serves:"2",time:"20 min",
   ingT:[["Fresh sea urchin","80–100g"],["Spaghetti","160g"],["Garlic","1 clove"],["Dried red chili","1/2"],["Parsley","a little"]],
   sauceT:[["Extra virgin olive oil","3 tbsp"],["White wine","2 tbsp"],["Salt","as needed"],["Heavy cream (optional)","2 tbsp"]],
   steps:["Mash half the urchin in a bowl with 1 tbsp olive oil into a sauce.","Cook the pasta in salted water 1 minute less than the package says.","Heat olive oil with sliced garlic and chili on low until fragrant, add the wine for 30 seconds (and the cream now if using).","Add the pasta and 2 tbsp pasta water, toss, then turn off the heat and stir in the urchin sauce (use residual heat only).","Plate, top with the remaining urchin, sprinkle with parsley and drizzle with a little olive oil."],
   tips:["A classic pasta of Sicily and Puglia.","Always add the urchin off the heat. Too much heat makes it fishy and lumpy.","Use cheaper imported or frozen urchin for the sauce and top with good fresh urchin."]},
  "海胆海带汤":{serves:"3",time:"30 min",
   ingT:[["Fresh sea urchin","50g"],["Dried wakame","10g"],["Garlic","1 clove"]],
   sauceT:[["Sesame oil","1 tbsp"],["Water","800ml"],["Korean soup soy sauce (or light soy sauce)","1.5 tbsp"],["Salt","a little"]],
   steps:["Soak the wakame in water for 10 minutes, squeeze dry and cut into bite-size lengths.","Fry the wakame and minced garlic in sesame oil on medium for 2–3 minutes.","Add the water, bring to a boil and simmer on low 15 minutes.","Add the urchin, gently break it up and simmer 2 minutes.","Season with soup soy sauce and salt."],
   tips:["Seongge miyeokguk is a Jeju Island specialty.","Frying the wakame in sesame oil first makes the soup rich and fragrant.","The urchin tints the soup pale yellow and makes it intensely savory."]},
  "加州海胆吐司":{serves:"2",time:"10 min",
   ingT:[["Fresh sea urchin","60g"],["Baguette or bread","4 slices"],["Lemon","1/2"],["Chives or shiso","a little"]],
   sauceT:[["Butter","20g"],["Flaky sea salt","a little"],["Extra virgin olive oil","a little"]],
   steps:["Cut the bread 1.5cm thick and toast until golden and crisp.","Butter it while hot.","Top with the urchin.","Sprinkle with flaky salt and lemon zest and add a few drops of olive oil.","Scatter with chives and eat right away."],
   tips:["A favorite at sea urchin restaurants in Santa Barbara, California.","Hot bread and cold urchin: the contrast is what makes it.","Swap the butter for mashed avocado if you like."]}}},
 shirako:{d:{
  "白子天妇罗":{serves:"2",time:"25 min",
   ingT:[["Cod milt (shirako)","150g"],["Grated daikon","as needed"],["Sudachi or lemon","1/2"]],
   sauceT:[["Salt (for cleaning)","1 tsp"],["Cake flour","40g plus a little for dusting"],["Ice water","70ml"],["Oil for frying","3cm deep"],["Matcha salt or salt","a little"]],
   steps:["Sprinkle the milt with salt and gently rub to remove the slime, rinse, snip off the thick blood vessels and cut into bite-size pieces.","Blanch in lightly salted boiling water for 30 seconds until the surface turns white, chill in ice water and dry thoroughly with paper towel.","Mix the flour and ice water roughly into a batter.","Dust the milt with flour, dip in batter and fry at 180°C for 1 minute until crisp.","Serve with grated daikon and sudachi, or matcha salt."],
   tips:["Crisp outside and creamy, flowing inside, a winter delicacy.","Blanching firms the surface so it doesn't burst while frying.","Dry it well or the oil will spatter."]},
  "鳕鱼白子汤":{serves:"3",time:"30 min",
   ingT:[["Cod milt (shirako)","200g"],["Daikon","5cm"],["Bean sprouts","1/2 bag"],["Shungiku (edible chrysanthemum)","1/2 bunch"],["Japanese leek (negi)","1/2"],["Green and red chilies","1 each"]],
   sauceT:[["Anchovy-kelp stock","800ml"],["Korean chili flakes (omit for clear soup)","1 tbsp"],["Grated garlic","1 tsp"],["Korean soup soy sauce","1 tbsp"],["Salt","a little"],["Sake","1 tbsp"]],
   steps:["Gently rub the milt with salt, rinse and cut into bite-size pieces.","Cut the daikon into thin squares and simmer in the stock for 10 minutes.","Add the chili flakes (for the spicy version), garlic, soup soy sauce and sake.","Add the milt and sprouts and simmer on medium 4–5 minutes (don't stir or the milt breaks apart).","Season with salt, add the shungiku, leek and chilies, cook 30 seconds and turn off the heat."],
   tips:["Goni-tang is a Korean winter soup, and the spicy version is goni-maeuntang.","The milt is delicate, so don't stir with a ladle once it's in.","Add cod pieces to make it a full cod stew."]}}},
 namako:{d:{
  "葱烧海参":{serves:"2–3",time:"40 min (not counting rehydration)",
   ingT:[["Rehydrated or ready-to-eat sea cucumber","4 (about 300g)"],["Japanese leeks (white parts only)","3"],["Ginger","3 slices"]],
   sauceT:[["Cooking oil","4 tbsp"],["Shaoxing or cooking wine","1 tbsp"],["Light soy sauce","1 tbsp"],["Dark soy sauce","1 tsp"],["Oyster sauce","1 tbsp"],["Sugar","1 tbsp"],["Chicken stock","200ml"],["Starch slurry","1 tbsp starch + 3 tbsp water"]],
   steps:["Split the sea cucumbers lengthwise, remove the inner sinews, cut into large strips and blanch for 2 minutes in boiling water with ginger and wine. Lift out.","Cut only the white parts of the leeks into 6cm lengths.","Slowly fry the leeks in oil on medium-low for 5–8 minutes until golden and fragrant, then lift them out. The oil left behind is scallion oil.","Add both soy sauces, oyster sauce, sugar and stock to the scallion oil, bring to a boil, add the sea cucumber and simmer on low 10 minutes.","Return the leeks and simmer 5 more minutes, drizzle in the slurry, shake the pan to coat and finish with a little scallion oil."],
   tips:["Rehydrating dried sea cucumber takes 3–5 days and it must never touch oil, so beginners should buy rehydrated or ready-to-eat ones.","Scallion oil is the soul of this Shandong dish. Fry the leeks until golden.","Sea cucumber has no flavor of its own and absorbs it from the sauce, so simmer a bit longer."]}}}
});
// 详细菜谱翻译 32
window.ADD_I18N("ja", {
 namako:{d:{
  "海参小米粥":{serves:"2",time:"40分",
   ingT:[["あわ（雑穀）","1/2カップ（約80g）"],["戻しなまこか即食なまこ","1〜2本"],["生姜","2枚"],["小ねぎ","1本"],["クコの実（お好みで）","少々"]],
   sauceT:[["水","1L"],["鶏ガラスープ（お好みで、水の半量を置き換え）","500ml"],["塩","少々"],["白こしょう","少々"]],
   steps:["あわを一度洗って水気をきる。なまこは小さな角切りにし、生姜を入れた熱湯で1分下ゆでする。","鍋に水（または水と鶏ガラスープ半々）を沸かし、あわを入れ、再び沸いたら弱火にする。","ふたを少しずらして弱火で25分煮る。数分ごとに混ぜ、とろみがついて表面に米の膜ができるまで煮る。","なまことクコの実を入れ、さらに5分煮る。","塩と白こしょう少々で調え、小ねぎを散らす。"],
   tips:["中国北方の滋養朝ごはん。なまこは少しでよい。","あわは日本のスーパーの雑穀コーナーで買える。","弱火でじっくり煮ると、とろりとした膜ができる。"]}}},
 hoya:{d:{
  "海鞘刺身":{serves:"2",time:"20分",
   ingT:[["活ほや","2個"],["きゅうり","1/2本"]],
   sauceT:[["酢","大さじ2"],["醤油","小さじ1"],["砂糖（お好みで）","少々"]],
   steps:["ほやの上には突起が2つある。「＋」形が入水孔、「−」形が出水孔。両方を切り落とし、中の海水を出す（身を洗うのに取っておく）。","殻を縦に切り開き、指でオレンジ色の身をはがす。","身を開いて黒い内臓を取り、取っておいた海水で洗う（真水より風味がよい）。","1cm幅に切る。","薄切りのきゅうりとあわせ、酢と醤油少々（三杯酢）をかける。"],
   tips:["宮城・岩手など東北の夏の名物で、「海のパイナップル」と呼ばれる。","甘・塩・苦・酸・うまみの五味があり、初めてだと慣れないことも。","新鮮なほどくせがない。その日の活ほやを買う。"]},
  "海鞘拌饭":{serves:"2",time:"20分",
   ingT:[["ほや（刺身用むき身）","100g"],["温かいご飯","2杯"],["レタスか大葉","4枚"],["きゅうり","1/3本"],["韓国のり","2枚"]],
   sauceT:[["ごま油","大さじ1"],["白ごま","小さじ1"],["コチュジャン（お好みで）","小さじ1"],["酢","小さじ1"]],
   steps:["ほやを小さな角切りにし、冷蔵庫で冷やしておく（先に30分冷凍すると切りやすく、くせも減る）。","レタスときゅうりを細切りにし、のりはちぎる。","器にご飯を盛り、野菜をのせる。","ほやをのせ、のりとごまを散らす。","ごま油をかけ（辛いのが好きならコチュジャンを酢でのばして）、全体を混ぜて食べる。"],
   tips:["韓国・統営（トンヨン）の名物「モンゲビビンバ」。","ごま油がほやの独特の風味をやわらげる。","少し凍らせてから切ると、食感がよりコリコリする。"]}}},
 kurage:{d:{
  "中华风海蜇":{serves:"3",time:"20分（塩抜き別）",
   ingT:[["塩くらげ","150g"],["きゅうり","1本"],["にんじん（お好みで）","少々"]],
   sauceT:[["醤油","大さじ1.5"],["酢","大さじ2"],["砂糖","大さじ1"],["ごま油","大さじ1"],["白ごま","小さじ1"],["ラー油（お好みで）","少々"]],
   steps:["塩くらげを洗い、1〜2時間水につけ、途中で数回水を替えて塩抜きする。","80°Cくらいの湯（小さな泡が出る程度）を用意し、くらげを5秒くぐらせてすぐ冷水にとる。くらげが縮んでコリコリになる。","さらに1時間冷水につけ、しっかり水気を絞る。","きゅうりとにんじんを細切りにする。","醤油・酢・砂糖・ごま油を混ぜ、くらげときゅうりとあえ、ごまをふって冷蔵庫で30分置く。"],
   tips:["日本の中華料理店や居酒屋で人気のおつまみ。","沸騰した湯は使わない。くらげが縮みすぎてかたくなる。","スーパーには味付き「中華くらげ」もある。"]},
  "芥末拌海蜇":{serves:"4",time:"30分（塩抜き別）",
   ingT:[["塩くらげ","150g"],["きゅうり","1本"],["梨","1/4個"],["ボイルえび","8尾"],["にんじん","少々"],["カニカマ（お好みで）","2本"]],
   sauceT:[["練りからし（韓国か日本）","小さじ1〜2"],["酢","大さじ3"],["砂糖","大さじ1.5"],["塩","小さじ1/2"],["おろしにんにく","少々"],["水","大さじ1"]],
   steps:["くらげは「中華風くらげ」と同じく塩抜き・湯通し・冷水・水気絞りをする。","きゅうり・梨・にんじんを細切りにし、えびは半分に切り、カニカマはほぐす。","からし・酢・砂糖・塩・にんにく・水を混ぜてからし酢を作り、味見して酸・甘・辛のバランスを整える。","くらげをソースの半量であえ、冷蔵庫で20分なじませる。","大皿にくらげと他の具を並べ、残りのソースをかけ、食べる前に混ぜる。"],
   tips:["韓国の宴席や祝日の冷菜「ヘパリネンチェ」。","からしのツンとした辛さとくらげの食感が特徴。","梨でさっぱりする。なければりんごで。"]}}},
 kombu:{d:{
  "海带炖排骨":{serves:"3〜4",time:"1.5時間",
   ingT:[["豚スペアリブ","500g"],["結び昆布か早煮昆布","150g（乾燥なら30g）"],["生姜","4枚"],["小ねぎ","1本"]],
   sauceT:[["料理酒","大さじ1"],["塩","小さじ1"],["白こしょう","少々"],["水","2L"]],
   steps:["乾燥昆布は30分水につけて砂を洗い、太めの帯に切って結ぶ（市販の結び昆布でも）。","スペアリブを水から入れ、料理酒を加えて沸かし、アクを取ってから取り出して洗う。","鍋に水・スペアリブ・生姜を入れ、強火で沸かしてから弱火で40分煮込む。","昆布を入れ、やわらかくなるまでさらに30分煮る。","塩と白こしょうで調え、小ねぎを散らす。"],
   tips:["中国の昆布は厚い養殖ものなので、日本では「早煮昆布」や「結び昆布」を。","塩は最後に入れる。","昆布がスープを吸ってとてもおいしい。"]},
  "凉拌海带丝":{serves:"2〜3",time:"15分",
   ingT:[["刻み昆布（生）か早煮昆布","200g"],["にんにく","3かけ"],["パクチー","1本"],["赤唐辛子（お好みで）","1本"],["にんじんの細切り（お好みで）","少々"]],
   sauceT:[["米酢か黒酢","大さじ2"],["醤油","大さじ1"],["砂糖","小さじ1"],["塩","少々"],["ごま油","小さじ1"],["ラー油","大さじ1"]],
   steps:["昆布を数回洗い、熱湯で2分ゆでて冷水にとり、水気をきる。","にんにくはみじん切り、唐辛子は輪切り、パクチーはざく切りにする。","酢・醤油・砂糖・塩・ごま油・ラー油を混ぜてたれを作る。","大きなボウルに昆布・にんにく・唐辛子・にんじんを入れ、たれを加えてあえる。","冷蔵庫で15分なじませ、パクチーを散らす。"],
   tips:["ゆでると昆布のぬめりと磯臭さが取れる。","日本の「刻み昆布」は細いので、30秒ゆでれば十分。","冷蔵庫で2日もつ。"]},
  "佃煮昆布":{serves:"1びん分",time:"40分",
   ingT:[["だしを取った後の昆布","100g（ぬれた状態）"],["白ごま","大さじ1"],["かつお節（お好みで）","小袋1つ"]],
   sauceT:[["水","200ml"],["酢","大さじ1"],["醤油","大さじ3"],["砂糖","大さじ1.5"],["みりん","大さじ2"],["酒","大さじ2"]],
   steps:["だしを取った後の昆布を長さ3cm、幅3mmの細切りにする（角切りでもよい）。","鍋に昆布・水・酢を入れ、中火で10分煮る（酢で昆布がやわらかくなる）。","醤油・砂糖・みりん・酒を加え、ときどき混ぜながら弱火で20分煮る。","煮汁が少なくなったらかつお節とごまを入れ、混ぜながら汁気がなくなるまで煮詰める。","冷まして清潔な容器に入れる。冷蔵で1週間もつ。"],
   tips:["無駄を出さない日本の家庭の知恵。だしがらを冷凍してためておき、たまったら作る。","酢を入れると昆布がやわらかく煮える。","最後は混ぜ続けないと焦げやすい。"]}}},
 nori:{d:{
  "紫菜蛋花汤":{serves:"2",time:"10分",
   ingT:[["乾燥岩のりか焼きのり","5g（小1枚）"],["卵","1個"],["干しえび（小）","大さじ1"],["小ねぎ","1本"]],
   sauceT:[["水","500ml"],["塩","小さじ1/2"],["白こしょう","少々"],["ごま油","数滴"]],
   steps:["のりを小さくちぎり、卵を溶き、ねぎを小口切りにする。","鍋に水と干しえびを入れて沸かす。","のりを入れて30秒煮る。","中火にし、溶き卵を鍋のふちに沿って回し入れ、10秒待ってから箸でそっと広げるときれいなかき玉になる。","塩・白こしょうで調えて火を止め、ごま油をたらしてねぎを散らす。"],
   tips:["卵を入れる前はスープを軽く沸いた状態に保つと、卵がふわっと広がる。","日本の焼きのりでもよい。ちぎって入れれば溶ける。","干しえびに塩気があるので、味見してから塩を足す。"]}}}
});
window.ADD_I18N("en", {
 namako:{d:{
  "海参小米粥":{serves:"2",time:"40 min",
   ingT:[["Foxtail millet","1/2 cup (about 80g)"],["Rehydrated or ready-to-eat sea cucumber","1–2"],["Ginger","2 slices"],["Scallion","1"],["Goji berries (optional)","a few"]],
   sauceT:[["Water","1L"],["Chicken stock (optional, replaces half the water)","500ml"],["Salt","a little"],["White pepper","a little"]],
   steps:["Rinse the millet once and drain. Dice the sea cucumber small and blanch 1 minute in boiling water with ginger.","Bring the water (or half water, half stock) to a boil, add the millet and turn to low once it boils again.","Simmer on low, lid ajar, for 25 minutes, stirring every few minutes, until thick with a silky film on top.","Add the sea cucumber and goji and simmer 5 more minutes.","Season with a little salt and white pepper and scatter with scallion."],
   tips:["A nourishing northern Chinese breakfast. A little sea cucumber goes a long way.","Japanese supermarkets sell millet as awa in the grains section.","Slow simmering on low gives the porridge its silky film."]}}},
 hoya:{d:{
  "海鞘刺身":{serves:"2",time:"20 min",
   ingT:[["Live sea pineapple (hoya)","2"],["Cucumber","1/2"]],
   sauceT:[["Vinegar","2 tbsp"],["Soy sauce","1 tsp"],["Sugar (optional)","a pinch"]],
   steps:["The top has two nubs: the +-shaped one takes water in, the −-shaped one lets it out. Cut both off and pour out the seawater inside (save it for rinsing).","Slit the shell lengthwise and peel out the orange flesh with your fingers.","Open the flesh, remove the black innards and rinse in the saved seawater (it keeps more flavor than tap water).","Cut into 1cm strips.","Toss with sliced cucumber and dress with vinegar and a little soy sauce (sanbaizu)."],
   tips:["A summer specialty of Miyagi and Iwate in northeast Japan, nicknamed the pineapple of the sea.","It has sweet, salty, bitter, sour and savory notes all at once, which can take getting used to.","The fresher, the milder. Buy it live on the day."]},
  "海鞘拌饭":{serves:"2",time:"20 min",
   ingT:[["Sea pineapple flesh (sashimi grade)","100g"],["Hot cooked rice","2 bowls"],["Lettuce or perilla leaves","4"],["Cucumber","1/3"],["Korean seasoned laver","2 sheets"]],
   sauceT:[["Sesame oil","1 tbsp"],["White sesame","1 tsp"],["Gochujang (optional)","1 tsp"],["Vinegar","1 tsp"]],
   steps:["Dice the sea pineapple small and keep it chilled (freezing 30 minutes first makes it easier to cut and milder).","Shred the lettuce and cucumber and tear the laver.","Put rice in bowls and top with the vegetables.","Add the sea pineapple and scatter with laver and sesame.","Drizzle with sesame oil (and gochujang thinned with vinegar if you like it spicy) and mix everything before eating."],
   tips:["Meongge bibimbap is a specialty of Tongyeong, Korea.","Sesame oil softens the sea pineapple's distinctive taste.","Partly frozen before cutting, it's crunchier."]}}},
 kurage:{d:{
  "中华风海蜇":{serves:"3",time:"20 min (plus desalting)",
   ingT:[["Salted jellyfish strips","150g"],["Cucumber","1"],["Carrot (optional)","a little"]],
   sauceT:[["Soy sauce","1.5 tbsp"],["Vinegar","2 tbsp"],["Sugar","1 tbsp"],["Sesame oil","1 tbsp"],["White sesame","1 tsp"],["Chili oil (optional)","a little"]],
   steps:["Rinse the jellyfish and soak in water 1–2 hours, changing the water a few times to remove the salt.","Heat water to about 80°C (small bubbles), dip the jellyfish for 5 seconds and move straight to cold water. It curls up and turns crunchy.","Soak in cold water another hour, then squeeze very dry.","Julienne the cucumber and carrot.","Mix the soy sauce, vinegar, sugar and sesame oil, toss with the jellyfish and cucumber, sprinkle with sesame and chill 30 minutes."],
   tips:["A popular side at Japanese Chinese restaurants and izakaya.","Don't use boiling water or the jellyfish shrinks and goes tough.","Supermarkets also sell ready-seasoned chuka kurage."]},
  "芥末拌海蜇":{serves:"4",time:"30 min (plus desalting)",
   ingT:[["Salted jellyfish strips","150g"],["Cucumber","1"],["Asian pear","1/4"],["Cooked shrimp","8"],["Carrot","a little"],["Imitation crab sticks (optional)","2"]],
   sauceT:[["Hot mustard (Korean or Japanese)","1–2 tsp"],["Vinegar","3 tbsp"],["Sugar","1.5 tbsp"],["Salt","1/2 tsp"],["Grated garlic","a little"],["Water","1 tbsp"]],
   steps:["Desalt, blanch, soak and squeeze the jellyfish as for the Chinese-style jellyfish.","Julienne the cucumber, pear and carrot, halve the shrimp and shred the crab sticks.","Mix the mustard, vinegar, sugar, salt, garlic and water into a mustard dressing. Taste and balance the sour, sweet and heat.","Toss the jellyfish with half the dressing and chill 20 minutes.","Arrange the jellyfish and other ingredients on a large platter, pour over the rest of the dressing and toss before eating."],
   tips:["Haepari naengchae is a cold dish for Korean banquets and holidays.","The mustard's nose-tingling heat and the crunchy jellyfish define it.","Pear keeps it fresh. Use apple if you don't have pear."]}}},
 kombu:{d:{
  "海带炖排骨":{serves:"3–4",time:"1.5 hr",
   ingT:[["Pork spare ribs","500g"],["Kelp knots or quick-cooking kombu","150g (30g if dried)"],["Ginger","4 slices"],["Scallion","1"]],
   sauceT:[["Cooking wine","1 tbsp"],["Salt","1 tsp"],["White pepper","a little"],["Water","2L"]],
   steps:["Soak dried kelp 30 minutes, rinse off any grit, cut into wide strips and tie into knots (or buy ready-made kelp knots).","Put the ribs in cold water with the wine, bring to a boil, skim, then drain and rinse.","Put the water, ribs and ginger in a pot, bring to a boil on high and simmer on low 40 minutes.","Add the kelp and simmer 30 more minutes until soft.","Season with salt and white pepper and scatter with scallion."],
   tips:["Chinese kelp is thick farmed kelp. In Japan, look for hayani kombu or musubi kombu.","Add salt at the end.","The kelp soaks up the rib broth and is delicious."]},
  "凉拌海带丝":{serves:"2–3",time:"15 min",
   ingT:[["Kelp strips (fresh or rehydrated)","200g"],["Garlic","3 cloves"],["Cilantro","1 sprig"],["Red chili (optional)","1"],["Julienned carrot (optional)","a little"]],
   sauceT:[["Rice vinegar or black vinegar","2 tbsp"],["Light soy sauce","1 tbsp"],["Sugar","1 tsp"],["Salt","a little"],["Sesame oil","1 tsp"],["Chili oil","1 tbsp"]],
   steps:["Rinse the kelp a few times, blanch 2 minutes in boiling water, cool in cold water and drain.","Mince the garlic, slice the chili into rings and cut the cilantro into lengths.","Mix the vinegar, soy sauce, sugar, salt, sesame oil and chili oil into a dressing.","Put the kelp in a large bowl with the garlic, chili and carrot and toss with the dressing.","Chill 15 minutes and scatter with cilantro."],
   tips:["Blanching removes the kelp's slime and sea smell.","Japanese kizami kombu is thinner and needs only 30 seconds.","Keeps 2 days in the fridge."]},
  "佃煮昆布":{serves:"1 jar",time:"40 min",
   ingT:[["Kombu left over from making dashi","100g (wet weight)"],["White sesame","1 tbsp"],["Bonito flakes (optional)","1 small pack"]],
   sauceT:[["Water","200ml"],["Vinegar","1 tbsp"],["Soy sauce","3 tbsp"],["Sugar","1.5 tbsp"],["Mirin","2 tbsp"],["Sake","2 tbsp"]],
   steps:["Cut the leftover kombu into thin strips 3cm long and 3mm wide (or small squares).","Simmer the kombu with the water and vinegar on medium for 10 minutes (the vinegar softens it).","Add the soy sauce, sugar, mirin and sake and simmer on low 20 minutes, stirring now and then.","When the liquid is nearly gone, add the bonito flakes and sesame and keep stirring until completely dry.","Cool and pack into a clean container. Keeps 1 week in the fridge."],
   tips:["A no-waste Japanese home habit: freeze spent dashi kombu and make this once you have enough.","Vinegar helps the kombu cook soft.","Stir constantly at the end or it scorches."]}}},
 nori:{d:{
  "紫菜蛋花汤":{serves:"2",time:"10 min",
   ingT:[["Dried laver (zicai) or toasted nori","5g (1 small sheet)"],["Egg","1"],["Small dried shrimp","1 tbsp"],["Scallion","1"]],
   sauceT:[["Water","500ml"],["Salt","1/2 tsp"],["White pepper","a little"],["Sesame oil","a few drops"]],
   steps:["Tear the laver into small pieces, beat the egg and slice the scallion.","Bring the water and dried shrimp to a boil.","Add the laver and cook 30 seconds.","On medium, pour the egg in a circle around the edge of the pot, wait 10 seconds, then gently push with chopsticks to get pretty egg ribbons.","Season with salt and white pepper, turn off the heat, add sesame oil and scatter with scallion."],
   tips:["Keep the soup at a gentle boil before adding the egg so it forms ribbons.","Japanese toasted nori works too. Torn up, it melts into the soup.","The dried shrimp is salty, so taste before adding salt."]}}}
});
