window.ADD_I18N("ja", {
 umibudo:{d:{
  "海葡萄盖饭":{serves:"2",time:"15分",
   ingT:[["海ぶどう","50g"],["刺身（まぐろ・サーモン・鯛など）","150g"],["温かい酢飯かご飯","2杯"],["大葉","4枚"],["刻みのり","少々"]],
   sauceT:[["醤油","適量"],["わさび","少々"],["ポン酢（お好みで）","適量"]],
   steps:["海ぶどうは食べる直前に冷水に3〜5分つけると粒がぷりっとする。水気をきる。","刺身を切る。","器にご飯を盛り、刻みのりを散らし、大葉を敷く。","刺身を並べ、中央に海ぶどうを盛る。","醤油かポン酢をかけ、わさびを添える。"],
   tips:["沖縄の名物。口の中で海ぶどうがぷちぷちはじける。","海ぶどうは冷蔵庫に入れない（しぼむ）。常温で保存し、食べる前に水につける。","醤油を海ぶどうに長くかけておくと粒がしぼむので、食べる直前にかける。"]},
  "菲律宾海葡萄沙拉":{serves:"2〜3",time:"15分",
   ingT:[["海ぶどう","80g"],["トマト","1個"],["紫玉ねぎ","1/4個"],["ライム","1個"],["赤唐辛子（お好みで）","1本"]],
   sauceT:[["ココナッツビネガーか米酢","大さじ2"],["ナンプラー","小さじ1"],["砂糖","小さじ1"],["こしょう","少々"]],
   steps:["海ぶどうを冷水に3〜5分つけ、水気をきる。","トマトは種を取って角切り、紫玉ねぎはみじん切りにして5分水にさらし、水気をきる。","酢・ナンプラー・砂糖・ライム果汁・こしょうを混ぜてドレッシングにする。","トマト・玉ねぎ・唐辛子をドレッシングであえる。","食べる直前に海ぶどうを加え、さっと混ぜてすぐ食べる。"],
   tips:["フィリピンの海辺の家庭サラダ「エンサラダン・ラト」。","海ぶどうはドレッシングに長く触れるとしぼむので、直前にあえる。","焼き魚や焼き肉に合わせるとさっぱりする。"]}}},
 tengusa:{d:{
  "凉拌石花菜":{serves:"2〜3",time:"30分（もどし2時間別）",
   ingT:[["乾燥天草（または糸寒天）","20g"],["にんにく","3かけ"],["パクチー","1本"],["きゅうり（お好みで）","1/2本"]],
   sauceT:[["米酢","大さじ2"],["醤油","大さじ1"],["砂糖","小さじ1"],["ごま油","小さじ1"],["ラー油","大さじ1"]],
   steps:["乾燥天草を冷水に2時間（または一晩）つけてやわらかくし、砂を洗い流す。","5cm長さに切り、熱湯に10秒くぐらせてすぐ冷水にとる（長くゆでると溶ける）。","にんにくはみじん切り、パクチーはざく切り、きゅうりは細切りにする。","酢・醤油・砂糖・ごま油・ラー油・にんにくを混ぜる。","大きなボウルに天草ときゅうりを入れ、たれであえてパクチーを散らす。"],
   tips:["ゆでるのは数秒だけ。長く煮ると溶けて寒天になる。","日本ではあえもの用の天草はあまり売っていないので、糸寒天を水でもどして使ってもよい（ゆでなくてよい）。","青島や福建沿岸の夏の冷菜。"]},
  "心太凉粉":{serves:"4",time:"1時間（固める時間2時間別）",
   ingT:[["天草（乾燥）","20g"],["水","1.5L"],["酢","大さじ1"],["刻みのり・白ごま（関東風）","少々"]],
   sauceT:[["関東風：酢大さじ2＋醤油大さじ2＋だし大さじ2＋からし少々","適量"],["関西風：黒蜜","適量"]],
   steps:["天草を洗って1時間水につけ、取り出す。","鍋に水・天草・酢を入れて沸かし、弱火にしてふたをせず40分煮る（煮汁にとろみが出る）。","さらしか目の細かいこし器でこし、煮汁をすべて絞り出す。","流し缶に注ぎ、冷ましてから冷蔵庫で2時間固める。","天突きに入る大きさの棒状に切り、突いて麺状にする。道具がなければ包丁で細く切る。","関東風は酢醤油をかけてからしと刻みのりを添え、関西風は黒蜜をかけて甘味にする。"],
   tips:["日本の夏の伝統的な涼味で、カロリーはほぼゼロ。","関東はおかず（酸っぱい）、関西は甘味（甘い）として食べる違いが面白い。","スーパーにはたれ付きの「ところてん」も売っている。"]}}},
 aosa:{d:{
  "海白菜豆腐汤":{serves:"2〜3",time:"15分",
   ingT:[["乾燥あおさ","5g"],["絹ごし豆腐","1丁"],["干しえび（小）","大さじ1"],["生姜","2枚"],["小ねぎ","1本"]],
   sauceT:[["水","600ml"],["塩","小さじ1/2"],["白こしょう","少々"],["ごま油","数滴"]],
   steps:["豆腐を小さく切る。","鍋に水・生姜・干しえびを入れ、沸騰させて2分煮る。","豆腐を入れ、中火で3分煮る。","塩と白こしょうを加え、あおさを入れてすぐ火を止める（あおさはすぐ広がる）。","ごま油をたらし、小ねぎを散らす。"],
   tips:["あおさは最後に入れる。煮すぎると色がくすみ、香りが飛ぶ。","福建や山東の沿岸では「海白菜」「海青菜」と呼ぶ。","干しえびに塩気があるので、味見してから塩を足す。"]},
  "大阪烧":{serves:"2枚",time:"40分",
   ingT:[["キャベツ","1/4個（約300g）"],["豚バラ薄切り","6枚"],["卵","2個"],["長芋のすりおろし（お好みで）","大さじ3"],["天かす","大さじ2"],["青のりかあおさ粉","適量"],["かつお節","適量"],["紅しょうが","少々"]],
   sauceT:[["薄力粉かお好み焼き粉","100g"],["だし","120ml"],["お好みソース","適量"],["マヨネーズ","適量"],["サラダ油","大さじ1"]],
   steps:["キャベツを1cm角に切る。","粉とだしを混ぜ、長芋・卵・キャベツ・天かす・紅しょうがを加えてざっくり混ぜる（混ぜすぎない）。","フライパンに油をひいて中火にし、生地の半量を流して直径18cm・厚さ2cmの丸に整える。","上に豚バラを3枚のせ、ふたをして中弱火で5分、底がきつね色になるまで焼く。","裏返して（豚肉が下）ふたをせずに5分焼き、もう一度返して2分焼く。","ソースを塗り、マヨネーズを絞り、青のりとかつお節をかける。"],
   tips:["大阪の家庭料理。青のり（あおさ）が香りの決め手。","返したときにへらで押さえないと、ふっくら焼ける。","長芋を入れるとふわっとするが、なくてもよい。"]},
  "石莼天妇罗":{serves:"2",time:"20分",
   ingT:[["乾燥あおさ","5g"],["ちくわ（お好みで）","4本"],["小えび（お好みで）","50g"]],
   sauceT:[["薄力粉","60g"],["冷水","90ml"],["揚げ油","鍋底から2cm"],["塩","少々"]],
   steps:["薄力粉と冷水をざっくり混ぜて衣を作り、乾燥あおさを混ぜる（あおさが水を吸って緑色になる）。","かき揚げにする場合：小えびを加え、スプーン1杯ずつ170°Cの油に落として平らにし、2分揚げて返し、両面カリッとさせる。","ちくわにする場合（磯辺揚げ）：ちくわを斜め半分に切り、あおさ衣をたっぷりつけて1〜2分、表面がカリッとするまで揚げる。","油をきって塩をふる。","ご飯のおかずにも酒の肴にもよい。"],
   tips:["あおさは香りが強く、揚げると部屋中に磯の香りが広がる。","「磯辺揚げ」は日本のお弁当の定番おかず。","乾燥あおさはみそ汁に入れてもおいしい。"]}}}
});
window.ADD_I18N("en", {
 umibudo:{d:{
  "海葡萄盖饭":{serves:"2",time:"15 min",
   ingT:[["Sea grapes (umibudo)","50g"],["Sashimi (tuna, salmon, sea bream, etc.)","150g"],["Hot sushi rice or plain rice","2 bowls"],["Shiso leaves","4"],["Shredded nori","a little"]],
   sauceT:[["Soy sauce","as needed"],["Wasabi","a little"],["Ponzu (optional)","as needed"]],
   steps:["Just before eating, soak the sea grapes in cold water 3–5 minutes so the beads plump up. Drain.","Slice the sashimi.","Put rice in bowls, scatter with nori and lay on the shiso.","Arrange the sashimi and pile the sea grapes in the middle.","Pour over soy sauce or ponzu and add wasabi."],
   tips:["An Okinawan specialty. The sea grapes pop in your mouth.","Never refrigerate sea grapes (they shrivel). Keep them at room temperature and soak just before eating.","Soy sauce left on sea grapes shrivels them, so pour it on right before eating."]},
  "菲律宾海葡萄沙拉":{serves:"2–3",time:"15 min",
   ingT:[["Sea grapes","80g"],["Tomato","1"],["Red onion","1/4"],["Lime","1"],["Bird's eye chili (optional)","1"]],
   sauceT:[["Coconut vinegar or rice vinegar","2 tbsp"],["Fish sauce","1 tsp"],["Sugar","1 tsp"],["Black pepper","a little"]],
   steps:["Soak the sea grapes in cold water 3–5 minutes and drain.","Seed and dice the tomato. Finely dice the red onion, soak 5 minutes in water to tame it and drain.","Mix the vinegar, fish sauce, sugar, lime juice and pepper into a dressing.","Toss the tomato, onion and chili with the dressing.","Add the sea grapes just before eating, toss lightly and serve at once."],
   tips:["Ensaladang lato is a home-style seaside salad from the Philippines.","Sea grapes shrivel if they sit in dressing, so add them last.","A refreshing side for grilled fish or meat."]}}},
 tengusa:{d:{
  "凉拌石花菜":{serves:"2–3",time:"30 min (plus 2 hr soaking)",
   ingT:[["Dried agar seaweed (tengusa) or agar strands","20g"],["Garlic","3 cloves"],["Cilantro","1 sprig"],["Cucumber (optional)","1/2"]],
   sauceT:[["Rice vinegar","2 tbsp"],["Light soy sauce","1 tbsp"],["Sugar","1 tsp"],["Sesame oil","1 tsp"],["Chili oil","1 tbsp"]],
   steps:["Soak the dried seaweed in cold water 2 hours (or overnight) until soft and rinse off any sand.","Cut into 5cm lengths, dip in boiling water for 10 seconds and move straight to cold water (longer and it dissolves).","Mince the garlic, cut the cilantro into lengths and julienne the cucumber.","Mix the vinegar, soy sauce, sugar, sesame oil, chili oil and garlic.","Put the seaweed and cucumber in a large bowl, toss with the dressing and scatter with cilantro."],
   tips:["Blanch only a few seconds. Cooked longer, it melts into agar jelly.","Salad-style tengusa is rare in Japan. Soaked agar strands (ito kanten) work instead, with no blanching.","A summer cold dish of Qingdao and coastal Fujian."]},
  "心太凉粉":{serves:"4",time:"1 hr (plus 2 hr setting)",
   ingT:[["Dried agar seaweed (tengusa)","20g"],["Water","1.5L"],["Vinegar","1 tbsp"],["Shredded nori and white sesame (Kanto style)","a little"]],
   sauceT:[["Kanto style: 2 tbsp vinegar + 2 tbsp soy sauce + 2 tbsp dashi + a little hot mustard","as needed"],["Kansai style: kuromitsu (black sugar syrup)","as needed"]],
   steps:["Wash the tengusa, soak 1 hour and drain.","Bring the water, tengusa and vinegar to a boil, then simmer uncovered on low 40 minutes (the liquid turns thick).","Strain through cotton cloth or a fine sieve, squeezing out all the liquid.","Pour into a square container, cool, and chill 2 hours to set.","Cut into bars that fit a tokoroten pusher and push into noodles. Without one, cut thin strips with a knife.","Kanto style: dress with vinegar-soy sauce, mustard and nori. Kansai style: pour over kuromitsu as a dessert."],
   tips:["A traditional Japanese summer cooler with almost no calories.","Kanto eats it as a sour side dish and Kansai as a sweet dessert, a fun regional difference.","Supermarkets sell ready-made tokoroten with sauce included."]}}},
 aosa:{d:{
  "海白菜豆腐汤":{serves:"2–3",time:"15 min",
   ingT:[["Dried sea lettuce (aosa)","5g"],["Silken tofu","1 block"],["Small dried shrimp","1 tbsp"],["Ginger","2 slices"],["Scallion","1"]],
   sauceT:[["Water","600ml"],["Salt","1/2 tsp"],["White pepper","a little"],["Sesame oil","a few drops"]],
   steps:["Cut the tofu into small cubes.","Boil the water with the ginger and dried shrimp for 2 minutes.","Add the tofu and simmer on medium 3 minutes.","Add salt and white pepper, drop in the sea lettuce and turn off the heat at once (it spreads out immediately).","Add a few drops of sesame oil and scatter with scallion."],
   tips:["Add the sea lettuce last. Overcooked, it dulls in color and loses aroma.","Coastal Fujian and Shandong call it sea cabbage or sea greens.","The dried shrimp is salty, so taste before adding salt."]},
  "大阪烧":{serves:"2 pancakes",time:"40 min",
   ingT:[["Cabbage","1/4 head (about 300g)"],["Thin-sliced pork belly","6 slices"],["Eggs","2"],["Grated nagaimo yam (optional)","3 tbsp"],["Tempura bits (tenkasu)","2 tbsp"],["Aonori or sea lettuce powder","as needed"],["Bonito flakes","as needed"],["Red pickled ginger","a little"]],
   sauceT:[["Cake flour or okonomiyaki flour","100g"],["Dashi","120ml"],["Okonomiyaki sauce","as needed"],["Mayonnaise","as needed"],["Cooking oil","1 tbsp"]],
   steps:["Cut the cabbage into 1cm pieces.","Mix the flour and dashi, then add the yam, eggs, cabbage, tempura bits and pickled ginger and fold roughly (don't overmix).","Heat oil in a pan on medium, pour in half the batter and shape a round 18cm wide and 2cm thick.","Lay 3 slices of pork on top, cover and cook on medium-low 5 minutes until golden underneath.","Flip (pork side down) and cook uncovered 5 minutes, then flip back for 2 minutes.","Brush with sauce, squeeze over mayonnaise and sprinkle with aonori and bonito flakes."],
   tips:["Osaka home cooking. The aonori (sea lettuce) is what makes it so fragrant.","Don't press down with the spatula after flipping, so it stays fluffy.","Grated yam makes it lighter but can be skipped."]},
  "石莼天妇罗":{serves:"2",time:"20 min",
   ingT:[["Dried sea lettuce (aosa)","5g"],["Chikuwa fish cake tubes (optional)","4"],["Small shrimp (optional)","50g"]],
   sauceT:[["Cake flour","60g"],["Ice water","90ml"],["Oil for frying","2cm deep"],["Salt","a little"]],
   steps:["Mix the flour and ice water roughly into a batter and stir in the dried sea lettuce (it absorbs water and turns green).","Fritter version: add the shrimp, drop spoonfuls into 170°C oil, flatten, fry 2 minutes, flip and crisp both sides.","Chikuwa version (isobe-age): halve the chikuwa diagonally, coat thickly in the batter and fry 1–2 minutes until crisp.","Drain and sprinkle with salt.","Great with rice or as a drinking snack."],
   tips:["Sea lettuce is so aromatic the whole kitchen smells of the sea when you fry it.","Isobe-age is a Japanese bento staple.","Dried sea lettuce is also lovely in miso soup."]}}}
});
